#[derive(Debug, Error)]
pub enum NativeCorrectionError {
    #[error("filesystem error: {0}")]
    Io(#[from] std::io::Error),
    #[error("JSON error: {0}")]
    Json(#[from] serde_json::Error),
    #[error(transparent)]
    Execution(#[from] NativeExecutionError),
    #[error("invalid native correction data: {0}")]
    Invalid(String),
}

pub type NativeCorrectionResult<T> = Result<T, NativeCorrectionError>;

/// JSON value decoder that rejects duplicate keys at every object depth. `serde_json::Value`
/// normally keeps only the last duplicate, which would let an apparently exact object conceal a
/// contradictory earlier authority or scope field.
struct DuplicateRejectingJson(Value);

impl<'de> Deserialize<'de> for DuplicateRejectingJson {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        deserializer.deserialize_any(DuplicateRejectingJsonVisitor)
    }
}

struct DuplicateRejectingJsonVisitor;

impl<'de> Visitor<'de> for DuplicateRejectingJsonVisitor {
    type Value = DuplicateRejectingJson;

    fn expecting(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("a JSON value without duplicate object keys")
    }

    fn visit_bool<E>(self, value: bool) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::Bool(value)))
    }

    fn visit_i64<E>(self, value: i64) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::Number(Number::from(value))))
    }

    fn visit_u64<E>(self, value: u64) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::Number(Number::from(value))))
    }

    fn visit_f64<E>(self, value: f64) -> Result<Self::Value, E>
    where
        E: serde::de::Error,
    {
        Number::from_f64(value)
            .map(Value::Number)
            .map(DuplicateRejectingJson)
            .ok_or_else(|| E::custom("JSON number was not finite"))
    }

    fn visit_str<E>(self, value: &str) -> Result<Self::Value, E>
    where
        E: serde::de::Error,
    {
        self.visit_string(value.to_string())
    }

    fn visit_string<E>(self, value: String) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::String(value)))
    }

    fn visit_none<E>(self) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::Null))
    }

    fn visit_unit<E>(self) -> Result<Self::Value, E> {
        Ok(DuplicateRejectingJson(Value::Null))
    }

    fn visit_some<D>(self, deserializer: D) -> Result<Self::Value, D::Error>
    where
        D: Deserializer<'de>,
    {
        DuplicateRejectingJson::deserialize(deserializer)
    }

    fn visit_seq<A>(self, mut sequence: A) -> Result<Self::Value, A::Error>
    where
        A: SeqAccess<'de>,
    {
        let mut values = Vec::new();
        while let Some(DuplicateRejectingJson(value)) = sequence.next_element()? {
            values.push(value);
        }
        Ok(DuplicateRejectingJson(Value::Array(values)))
    }

    fn visit_map<A>(self, mut object: A) -> Result<Self::Value, A::Error>
    where
        A: MapAccess<'de>,
    {
        let mut values = Map::new();
        while let Some(key) = object.next_key::<String>()? {
            if values.contains_key(&key) {
                return Err(serde::de::Error::custom(format!(
                    "duplicate JSON object key: {key}"
                )));
            }
            let DuplicateRejectingJson(value) = object.next_value()?;
            values.insert(key, value);
        }
        Ok(DuplicateRejectingJson(Value::Object(values)))
    }
}

fn strict_json_value_from_slice(bytes: &[u8]) -> NativeCorrectionResult<Value> {
    let mut deserializer = serde_json::Deserializer::from_slice(bytes);
    let DuplicateRejectingJson(value) = DuplicateRejectingJson::deserialize(&mut deserializer)?;
    deserializer.end()?;
    Ok(value)
}

fn strict_json_value_from_str(text: &str) -> NativeCorrectionResult<Value> {
    strict_json_value_from_slice(text.as_bytes())
}

fn strict_json_from_slice<T: DeserializeOwned>(bytes: &[u8]) -> NativeCorrectionResult<T> {
    serde_json::from_value(strict_json_value_from_slice(bytes)?).map_err(Into::into)
}

fn strict_json_from_str<T: DeserializeOwned>(text: &str) -> NativeCorrectionResult<T> {
    strict_json_from_slice(text.as_bytes())
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "snake_case")]
pub enum NativeCorrectionHost {
    Codex,
    ClaudeCode,
}

impl NativeCorrectionHost {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Codex => "codex",
            Self::ClaudeCode => "claude_code",
        }
    }

    fn writer(self) -> (&'static str, &'static str) {
        match self {
            Self::Codex => ("codex", "openai"),
            Self::ClaudeCode => ("claude_code", "anthropic"),
        }
    }
}

