#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionProtocol {
    pub schema_version: u32,
    pub family: String,
    pub pilot_id: String,
    /// Public, non-secret nonce used only to make every marker unique.
    pub nonce: String,
    pub requires_explicit_provider_execution: bool,
    pub lanes: Vec<NativeCorrectionLaneSpec>,
    pub claude: NativeCorrectionClaudeBudget,
    pub resources: NativeCorrectionResourceBudgets,
    pub burden: NativeCorrectionBurdenContract,
}

pub fn validate_native_correction_protocol(
    protocol: &NativeCorrectionProtocol,
) -> NativeCorrectionResult<()> {
    if protocol.schema_version != NATIVE_CORRECTION_PROTOCOL_SCHEMA_VERSION
        || protocol.family != NATIVE_CORRECTION_FAMILY
        || !protocol.pilot_id.starts_with("native-correction-")
        || !protocol.requires_explicit_provider_execution
    {
        return invalid("protocol family, schema, pilot ID, or execution-approval gate drifted");
    }
    if !(12..=48).contains(&protocol.nonce.len())
        || !protocol
            .nonce
            .bytes()
            .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit())
    {
        return invalid("nonce must be 12-48 lowercase ASCII letters or digits");
    }
    let expected_hosts = [
        NativeCorrectionHost::Codex,
        NativeCorrectionHost::ClaudeCode,
    ];
    if protocol.lanes.len() != expected_hosts.len() {
        return invalid("native correction requires exactly two lanes");
    }
    let mut labels = BTreeSet::new();
    for (index, (lane, host)) in protocol.lanes.iter().zip(expected_hosts).enumerate() {
        if lane.order != (index + 1) as u32 || lane.host != host || lane.repetition != 1 {
            return invalid("lane order must be Codex then Claude Code, each exactly once");
        }
        if lane.opaque_path_label.len() != 24
            || !lane
                .opaque_path_label
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
            || !labels.insert(lane.opaque_path_label.clone())
            || lane.opaque_path_label.contains(lane.host.label())
        {
            return invalid("lane path labels must be distinct opaque 24-character lowercase hex");
        }
    }
    let claude = &protocol.claude;
    if claude.model.trim().is_empty()
        || claude.proposal_max_turns != 10
        || claude.proposal_budget_cents != 10
        || claude.retrieval_max_turns != 6
        || claude.retrieval_budget_cents != 10
        || claude.aggregate_budget_cents != 20
        || claude.proposal_budget_cents + claude.retrieval_budget_cents
            != claude.aggregate_budget_cents
    {
        return invalid("Claude budget must be 10 turns/$0.10 + 6 turns/$0.10 = $0.20");
    }
    let resources = &protocol.resources;
    if resources.provider_calls != 4
        || resources.codex_max_tokens_per_call != 50_000
        || resources.host_timeout_ms != 600_000
        || resources.max_trace_bytes != 8 * 1024 * 1024
        || resources.max_stderr_bytes != 1024 * 1024
        || resources.max_engram_result_bytes_per_call != 8 * 1024
        || resources.max_engram_result_bytes_per_lane != 32 * 1024
    {
        return invalid("native correction resource budget contract drifted");
    }
    let burden = &protocol.burden;
    if burden.operator_action_definition != NATIVE_CORRECTION_OPERATOR_ACTION_DEFINITION
        || burden.operator_actions_per_lane != NATIVE_CORRECTION_OPERATOR_ACTIONS_PER_LANE
        || burden.cleanup_action_definition != NATIVE_CORRECTION_CLEANUP_ACTION_DEFINITION
        || burden.cleanup_actions_per_lane != NATIVE_CORRECTION_CLEANUP_ACTIONS_PER_LANE
        || burden.model_turn_definition != NATIVE_CORRECTION_MODEL_TURN_DEFINITION
        || burden.max_model_turns_total != NATIVE_CORRECTION_MAX_MODEL_TURNS_TOTAL
        || burden.harness_retry_definition != NATIVE_CORRECTION_HARNESS_RETRY_DEFINITION
        || burden.required_harness_retry_count != 0
        || burden.same_phase_replay_definition != NATIVE_CORRECTION_SAME_PHASE_REPLAY_DEFINITION
        || burden.required_same_phase_replay_count != 0
        || burden.provider_internal_retry_count != NativeCorrectionUnavailableCount::Unavailable
        || burden.elapsed_definition != NATIVE_CORRECTION_ELAPSED_DEFINITION
        || burden.elapsed_unit != "milliseconds"
        || burden.max_active_elapsed_ms_total != NATIVE_CORRECTION_MAX_ACTIVE_ELAPSED_MS_TOTAL
        || burden.stale_reappearance_definition != NATIVE_CORRECTION_STALE_REAPPEARANCE_DEFINITION
        || burden.required_stale_reappearance_count != 0
    {
        return invalid("native correction burden contract drifted");
    }
    Ok(())
}

pub fn validate_native_correction_protocol_file(
    protocol_path: &Path,
) -> NativeCorrectionResult<NativeCorrectionProtocol> {
    validate_absolute_normal_path(protocol_path, "protocol source")?;
    validate_existing_path_identity(protocol_path, protocol_path, "protocol source")?;
    let protocol_metadata = fs::symlink_metadata(protocol_path)?;
    if !protocol_metadata.is_file()
        || protocol_metadata.len() == 0
        || protocol_metadata.len() > 1024 * 1024
    {
        return invalid("protocol source exceeded its regular-file byte boundary");
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if protocol_metadata.uid() != unsafe { libc::geteuid() } || protocol_metadata.nlink() != 1 {
            return invalid("protocol source ownership or link count drifted");
        }
    }
    let protocol: NativeCorrectionProtocol = strict_json_from_slice(&read_bounded_attested_file(
        protocol_path,
        1024 * 1024,
        "protocol source",
    )?)?;
    validate_native_correction_protocol(&protocol)?;
    Ok(protocol)
}

