pub fn validate_native_correction_runtime(
    runtime: &NativeCorrectionRuntimeAttestation,
) -> NativeCorrectionResult<()> {
    validate_native_correction_runtime_claims(runtime)?;

    // Unit fixtures exercise the schema gates without pretending that `/frozen/*` exists. This
    // branch is not compiled into the evaluator binary; every production call below re-attests
    // the exact regular files and derives both contracts from executable output.
    #[cfg(test)]
    if runtime
        .binaries
        .values()
        .all(|binary| binary.path.starts_with("/frozen/"))
    {
        return Ok(());
    }

    let paths = runtime_paths_from_attestation(runtime)?;
    let observed = attest_native_correction_runtime(&paths)?;
    if &observed != runtime {
        return invalid("runtime attestation differs from fresh binary/stdio observations");
    }
    Ok(())
}

fn validate_native_correction_runtime_claims(
    runtime: &NativeCorrectionRuntimeAttestation,
) -> NativeCorrectionResult<()> {
    let required = [
        (
            "engram",
            EXPECTED_ENGRAM_SHA256,
            Some(EXPECTED_ENGRAM_VERSION),
        ),
        (
            "codex",
            EXPECTED_CODEX_SHA256,
            Some(EXPECTED_CODEX_VERSION_FRAGMENT),
        ),
        (
            "codex_code_mode_host",
            EXPECTED_CODEX_CODE_MODE_HOST_SHA256,
            Some(EXPECTED_CODE_MODE_HOST_PROBE),
        ),
        (
            "claude_code",
            EXPECTED_CLAUDE_SHA256,
            Some(EXPECTED_CLAUDE_VERSION_FRAGMENT),
        ),
    ];
    if runtime.binaries.len() != required.len() {
        return invalid("runtime must contain exactly four frozen binary attestations");
    }
    for (name, digest, version) in required {
        let binary = runtime
            .binaries
            .get(name)
            .ok_or_else(|| NativeCorrectionError::Invalid(format!("missing {name} binary")))?;
        if binary.sha256 != digest
            || binary.path.trim().is_empty()
            || version.is_some_and(|fragment| !binary.version.contains(fragment))
        {
            return invalid(format!("frozen {name} binary identity drifted"));
        }
    }
    if runtime.libraries.len() != 1 {
        return invalid("runtime must contain exactly one frozen Engram library attestation");
    }
    let onnxruntime = runtime
        .libraries
        .get("onnxruntime")
        .ok_or_else(|| NativeCorrectionError::Invalid("missing onnxruntime library".into()))?;
    if onnxruntime.sha256 != EXPECTED_ONNXRUNTIME_SHA256 {
        return invalid("frozen onnxruntime library identity drifted");
    }
    let engram_path = Path::new(&runtime.binaries["engram"].path);
    let frozen_root = engram_path.parent().and_then(Path::parent).ok_or_else(|| {
        NativeCorrectionError::Invalid("Engram candidate has no frozen root".into())
    })?;
    if engram_path
        .parent()
        .and_then(Path::file_name)
        .and_then(|name| name.to_str())
        != Some("bin")
        || Path::new(&onnxruntime.path) != frozen_root.join("lib").join(ONNXRUNTIME_DYLIB_NAME)
    {
        return invalid("Engram candidate is not the exact frozen bin/lib bundle");
    }
    let codex_path = Path::new(&runtime.binaries["codex"].path);
    let expected_code_mode_host = codex_path
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("Codex binary has no parent".to_string()))?
        .join("codex-code-mode-host");
    if Path::new(&runtime.binaries["codex_code_mode_host"].path) != expected_code_mode_host {
        return invalid("code-mode host is not the exact sibling launched by frozen Codex");
    }
    let agent = &runtime.agent_contract;
    if agent.schema_version != 4
        || agent.mcp_contract_version != 5
        || agent.mcp_protocol_version != NATIVE_CORRECTION_MCP_PROTOCOL
        || agent.profile != "agent"
        || agent.mcp_tool_count != 6
        || agent.mcp_tools_sha256 != EXPECTED_AGENT_TOOLS_SHA256
        || agent.profile_instructions_sha256 != EXPECTED_AGENT_INSTRUCTIONS_SHA256
        || !agent.runtime_verified
        || !agent.restricted_tool_rejected
        || !agent.review_authority_rejected
        || !agent.correction_proposal_path_verified
        || !agent.direct_correction_unavailable
        || !agent.correction_apply_unavailable
        || !agent.correction_inspection_unavailable
        || !agent.correction_verification_unavailable
    {
        return invalid("agent-profile schema-v4/MCP-v5 contract drifted");
    }
    let full = &runtime.full_profile;
    let actions = full
        .memory_actions
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    if !full.fresh_process
        || !full.initialized
        || full.profile != "full"
        || full.mcp_protocol_version != NATIVE_CORRECTION_MCP_PROTOCOL
        || full.mcp_tool_count != EXPECTED_FULL_TOOL_COUNT
        || full.mcp_tools_sha256 != EXPECTED_FULL_TOOLS_SHA256
        || !full.memory_tool_present
        || !full.daemon_stopped
        || !REQUIRED_FULL_MEMORY_ACTIONS
            .iter()
            .all(|action| actions.contains(action))
    {
        return invalid("full-profile fresh stdio handshake contract drifted");
    }
    Ok(())
}

fn runtime_paths_from_attestation(
    runtime: &NativeCorrectionRuntimeAttestation,
) -> NativeCorrectionResult<NativeCorrectionRuntimePaths> {
    let path = |name: &str| {
        runtime
            .binaries
            .get(name)
            .map(|binary| PathBuf::from(&binary.path))
            .ok_or_else(|| NativeCorrectionError::Invalid(format!("missing {name} binary")))
    };
    Ok(NativeCorrectionRuntimePaths {
        engram: path("engram")?,
        codex: path("codex")?,
        codex_code_mode_host: path("codex_code_mode_host")?,
        claude_code: path("claude_code")?,
    })
}

fn native_correction_candidate_library_path(engram: &Path) -> NativeCorrectionResult<PathBuf> {
    let frozen_root = engram
        .parent()
        .filter(|parent| parent.file_name().and_then(|name| name.to_str()) == Some("bin"))
        .and_then(Path::parent)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "Engram candidate path must end in frozen/bin/engram".into(),
            )
        })?;
    Ok(frozen_root.join("lib").join(ONNXRUNTIME_DYLIB_NAME))
}

fn validate_native_correction_candidate_bundle(
    engram: &Path,
) -> NativeCorrectionResult<NativeCorrectionLibraryAttestation> {
    validate_absolute_normal_path(engram, "Engram candidate binary")?;
    if engram.file_name().and_then(|name| name.to_str()) != Some("engram")
        || path_has_symlink_component(engram)?
        || engram.canonicalize()? != engram
    {
        return invalid("Engram candidate binary path was not canonical or exact");
    }
    let bin = engram.parent().expect("validated candidate bin");
    let root = bin.parent().expect("validated candidate root");
    let library = native_correction_candidate_library_path(engram)?;
    let lib = library.parent().expect("validated candidate lib");
    for directory in [root, bin, lib] {
        validate_owned_directory(directory, 0o700)?;
        if path_has_symlink_component(directory)? || directory.canonicalize()? != directory {
            return invalid("Engram candidate bundle directory was symlinked or non-canonical");
        }
    }
    validate_owned_regular_file(engram, 0o700)?;
    validate_owned_regular_file(&library, 0o600)?;
    let engram_metadata = fs::symlink_metadata(engram)?;
    let library_metadata = fs::symlink_metadata(&library)?;
    if engram_metadata.len() == 0
        || engram_metadata.len() > 512 * 1024 * 1024
        || library_metadata.len() == 0
        || library_metadata.len() > 256 * 1024 * 1024
        || path_has_symlink_component(&library)?
        || library.canonicalize()? != library
        || sha256_file(engram)? != EXPECTED_ENGRAM_SHA256
        || sha256_file(&library)? != EXPECTED_ONNXRUNTIME_SHA256
    {
        return invalid("Engram candidate binary or onnxruntime library identity drifted");
    }
    validate_native_correction_candidate_loader(engram)?;
    Ok(NativeCorrectionLibraryAttestation {
        path: library.display().to_string(),
        sha256: EXPECTED_ONNXRUNTIME_SHA256.to_string(),
    })
}

fn validate_native_correction_candidate_loader(engram: &Path) -> NativeCorrectionResult<()> {
    let environment = BTreeMap::from([(
        "PATH".to_string(),
        "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
    )]);
    let engram_text = engram.to_str().ok_or_else(|| {
        NativeCorrectionError::Invalid("Engram candidate path was not UTF-8".into())
    })?;
    let (linked_status, linked_stdout, linked_stderr) = run_bounded_native_correction_command(
        Path::new("/usr/bin/otool"),
        &["-L", engram_text],
        engram.parent().expect("validated candidate parent"),
        &environment,
        Duration::from_secs(5),
        256 * 1024,
    )?;
    let (load_status, load_stdout, load_stderr) = run_bounded_native_correction_command(
        Path::new("/usr/bin/otool"),
        &["-l", engram_text],
        engram.parent().expect("validated candidate parent"),
        &environment,
        Duration::from_secs(5),
        2 * 1024 * 1024,
    )?;
    if linked_status != 0
        || load_status != 0
        || !linked_stderr.is_empty()
        || !load_stderr.is_empty()
    {
        return invalid("Engram candidate Mach-O inspection failed");
    }
    let linked = String::from_utf8(linked_stdout).map_err(|_| {
        NativeCorrectionError::Invalid("Engram candidate dependency output was not UTF-8".into())
    })?;
    let load = String::from_utf8(load_stdout).map_err(|_| {
        NativeCorrectionError::Invalid("Engram candidate load-command output was not UTF-8".into())
    })?;
    let expected_dependency = format!("@rpath/{ONNXRUNTIME_DYLIB_NAME}");
    if linked.matches(&expected_dependency).count() != 1
        || linked
            .lines()
            .filter(|line| line.contains("onnxruntime"))
            .any(|line| !line.trim_start().starts_with(&expected_dependency))
        || load.matches("cmd LC_RPATH").count() != 1
        || load.matches("path @loader_path/../lib (offset ").count() != 1
    {
        return invalid("Engram candidate did not bind exactly one loader-relative ONNX runtime");
    }
    Ok(())
}

/// Derive every runtime fact used by this family from the exact executable bytes and a fresh
/// full-profile stdio session. No provider process or credential is consulted.
pub fn attest_native_correction_runtime(
    paths: &NativeCorrectionRuntimePaths,
) -> NativeCorrectionResult<NativeCorrectionRuntimeAttestation> {
    let onnxruntime = validate_native_correction_candidate_bundle(&paths.engram)?;
    let binaries = BTreeMap::from([
        (
            "engram".to_string(),
            attest_native_correction_binary("engram", &paths.engram, EXPECTED_ENGRAM_SHA256)?,
        ),
        (
            "codex".to_string(),
            attest_native_correction_binary("codex", &paths.codex, EXPECTED_CODEX_SHA256)?,
        ),
        (
            "codex_code_mode_host".to_string(),
            attest_native_correction_binary(
                "codex_code_mode_host",
                &paths.codex_code_mode_host,
                EXPECTED_CODEX_CODE_MODE_HOST_SHA256,
            )?,
        ),
        (
            "claude_code".to_string(),
            attest_native_correction_binary(
                "claude_code",
                &paths.claude_code,
                EXPECTED_CLAUDE_SHA256,
            )?,
        ),
    ]);
    let libraries = BTreeMap::from([("onnxruntime".to_string(), onnxruntime)]);
    let engram = Path::new(&binaries["engram"].path);
    let agent_contract = derive_agent_runtime_contract(engram)?;
    let full_profile = derive_full_profile_handshake(engram)?;
    let runtime = NativeCorrectionRuntimeAttestation {
        binaries,
        libraries,
        agent_contract,
        full_profile,
    };
    validate_native_correction_runtime_claims(&runtime)?;
    Ok(runtime)
}

fn attest_native_correction_binary(
    name: &str,
    supplied_path: &Path,
    expected_sha256: &str,
) -> NativeCorrectionResult<NativeCorrectionBinaryAttestation> {
    let supplied = fs::symlink_metadata(supplied_path)?;
    if !supplied.is_file() && !supplied.file_type().is_symlink() {
        return invalid(format!(
            "{name} path is neither a regular file nor a file symlink"
        ));
    }
    let path = supplied_path.canonicalize()?;
    let metadata = fs::symlink_metadata(&path)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return invalid(format!("resolved {name} binary is not a regular file"));
    }
    if metadata.len() == 0 || metadata.len() > 512 * 1024 * 1024 {
        return invalid(format!("resolved {name} binary exceeded its size boundary"));
    }
    let sha256 = sha256_file(&path)?;
    if sha256 != expected_sha256 {
        return invalid(format!("frozen {name} executable SHA-256 drifted"));
    }
    let probe_argument = if name == "codex_code_mode_host" {
        "--help"
    } else {
        "--version"
    };
    let (status, stdout, stderr) = run_bounded_native_correction_command(
        &path,
        &[probe_argument],
        path.parent().ok_or_else(|| {
            NativeCorrectionError::Invalid(format!("resolved {name} binary has no parent"))
        })?,
        &BTreeMap::from([
            (
                "PATH".to_string(),
                "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
            ),
            ("DISABLE_TELEMETRY".to_string(), "1".to_string()),
        ]),
        Duration::from_secs(5),
        64 * 1024,
    )?;
    if status != 0 {
        return invalid(format!(
            "{name} version probe failed or exceeded its byte cap"
        ));
    }
    let combined = format!(
        "{}{}",
        String::from_utf8_lossy(&stdout),
        String::from_utf8_lossy(&stderr)
    );
    let version = combined
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{name} version probe was empty")))?
        .to_string();
    Ok(NativeCorrectionBinaryAttestation {
        path: path.display().to_string(),
        version,
        sha256,
    })
}

fn derive_agent_runtime_contract(
    engram: &Path,
) -> NativeCorrectionResult<NativeCorrectionAgentRuntimeContract> {
    let root = create_runtime_probe_root()?;
    let home = root.join("home");
    create_new_private_dir(&home)?;
    let result = run_bounded_native_correction_command(
        engram,
        &[
            "contract",
            "--profile",
            "agent",
            "--verify-runtime",
            "--json",
        ],
        &root,
        &BTreeMap::from([
            ("ENGRAM_HOME".to_string(), home.display().to_string()),
            ("DISABLE_TELEMETRY".to_string(), "1".to_string()),
            (
                "PATH".to_string(),
                "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
            ),
        ]),
        Duration::from_millis(RUNTIME_PROBE_TIMEOUT_MS),
        1024 * 1024,
    );
    let cleanup = fs::remove_dir_all(&root).map_err(NativeCorrectionError::from);
    let (status, stdout, stderr) =
        combine_native_correction_cleanup(result, cleanup, "agent runtime probe-root cleanup")?;
    if status != 0 || !stderr.is_empty() {
        return invalid("Engram agent contract probe failed or exceeded its byte cap");
    }
    let value = strict_json_value_from_slice(&stdout)?;
    if value.get("executable_path").and_then(Value::as_str)
        != Some(engram.to_string_lossy().as_ref())
        || value.get("executable_sha256").and_then(Value::as_str) != Some(EXPECTED_ENGRAM_SHA256)
    {
        return invalid("Engram contract probe did not identify the executed frozen binary");
    }
    let required_bool = |pointer: &str| {
        value
            .pointer(pointer)
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(format!(
                    "Engram contract probe omitted boolean {pointer}"
                ))
            })
    };
    let required_u64 = |pointer: &str| {
        value
            .pointer(pointer)
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(format!(
                    "Engram contract probe omitted integer {pointer}"
                ))
            })
    };
    let required_string = |pointer: &str| {
        value
            .pointer(pointer)
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(format!(
                    "Engram contract probe omitted string {pointer}"
                ))
            })
    };
    Ok(NativeCorrectionAgentRuntimeContract {
        schema_version: u32::try_from(required_u64("/schema_version")?)
            .map_err(|_| NativeCorrectionError::Invalid("schema version overflow".to_string()))?,
        mcp_contract_version: u32::try_from(required_u64("/mcp_contract_version")?)
            .map_err(|_| NativeCorrectionError::Invalid("contract version overflow".to_string()))?,
        mcp_protocol_version: required_string("/mcp_protocol_version")?,
        profile: required_string("/profile")?,
        mcp_tool_count: usize::try_from(required_u64("/mcp_tool_count")?)
            .map_err(|_| NativeCorrectionError::Invalid("tool count overflow".to_string()))?,
        mcp_tools_sha256: required_string("/mcp_tools_sha256")?,
        profile_instructions_sha256: required_string("/profile_instructions_sha256")?,
        runtime_verified: required_bool("/effective_runtime/verified")?,
        restricted_tool_rejected: required_bool("/effective_runtime/restricted_tool_rejected")?,
        review_authority_rejected: required_bool("/effective_runtime/review_authority_rejected")?,
        correction_proposal_path_verified: required_bool(
            "/effective_runtime/correction_proposal_path_verified",
        )?,
        direct_correction_unavailable: required_bool(
            "/effective_runtime/direct_correction_unavailable",
        )?,
        correction_apply_unavailable: required_bool(
            "/effective_runtime/correction_apply_unavailable",
        )?,
        correction_inspection_unavailable: required_bool(
            "/effective_runtime/correction_inspection_unavailable",
        )?,
        correction_verification_unavailable: required_bool(
            "/effective_runtime/correction_verification_unavailable",
        )?,
    })
}

#[derive(Debug)]
struct NativeCorrectionMcpResponse {
    raw: Value,
    content: Option<Value>,
}

#[derive(Debug)]
struct NativeCorrectionPreparedRequest {
    id: u64,
    method: String,
    message: Value,
    json_line: Vec<u8>,
}

fn native_correction_deadlines(timeout: Duration) -> NativeCorrectionResult<(Instant, Instant)> {
    let started = Instant::now();
    let terminal_deadline = started.checked_add(timeout).ok_or_else(|| {
        NativeCorrectionError::Invalid("native correction deadline overflowed".into())
    })?;
    let cleanup_reserve = (timeout / 4).min(NATIVE_CORRECTION_CLEANUP_RESERVE_MAX);
    let response_deadline = terminal_deadline
        .checked_sub(cleanup_reserve)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("native correction cleanup reserve underflowed".into())
        })?;
    Ok((response_deadline, terminal_deadline))
}

fn native_correction_spawned_guard(
    outcome: NativeExecutionSpawnOutcome,
) -> NativeCorrectionResult<NativeCorrectionChildGuard> {
    match outcome {
        NativeExecutionSpawnOutcome::Spawned(guard) => Ok(guard),
        NativeExecutionSpawnOutcome::NotSpawned(error)
        | NativeExecutionSpawnOutcome::PostSpawnTerminal { error, .. } => Err(error.into()),
        NativeExecutionSpawnOutcome::PostSpawnCleanupUnproven {
            error, quarantine, ..
        } => {
            // Correction has no terminal-receipt shortcut at this boundary. Keep the owner-bound
            // quarantine alive through error classification; its Drop performs only another
            // deadline-bounded cleanup attempt and the operation remains non-authorizing.
            let _quarantine = quarantine;
            Err(error.into())
        }
    }
}

fn native_correction_cleanup_result(
    outcome: NativeExecutionCleanupOutcome,
) -> NativeCorrectionResult<ExitStatus> {
    match outcome {
        NativeExecutionCleanupOutcome::ProvenTerminal(status) => Ok(status),
        NativeExecutionCleanupOutcome::CleanupUnproven(error) => Err(error.into()),
    }
}

#[cfg(unix)]
fn configure_native_correction_stdin_nonblocking(
    stdin: &NativeCorrectionChildStdin,
) -> NativeCorrectionResult<()> {
    Ok(stdin.configure_nonblocking()?)
}

#[cfg(not(unix))]
fn configure_native_correction_stdin_nonblocking(
    _stdin: &NativeCorrectionChildStdin,
) -> NativeCorrectionResult<()> {
    invalid("bounded Engram stdio request delivery requires a Unix nonblocking pipe")
}

#[cfg(unix)]
fn write_native_correction_stdin_until(
    stdin: &mut NativeCorrectionChildStdin,
    bytes: &[u8],
    deadline: Instant,
) -> NativeCorrectionResult<usize> {
    let mut delivered = 0usize;
    while delivered < bytes.len() {
        if Instant::now() >= deadline {
            return invalid(format!(
                "Engram stdin delivery exceeded the absolute response deadline after delivering {delivered} of {} bytes",
                bytes.len()
            ));
        }
        match stdin.write(&bytes[delivered..]) {
            Ok(0) => {
                return invalid(format!(
                    "Engram stdin accepted zero bytes after delivering {delivered} of {} bytes",
                    bytes.len()
                ));
            }
            Ok(written) => {
                delivered = delivered.checked_add(written).ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "Engram stdin delivery byte count overflowed".to_string(),
                    )
                })?;
                if Instant::now() >= deadline {
                    return invalid(format!(
                        "Engram stdin delivery crossed the absolute response deadline after delivering {delivered} of {} bytes",
                        bytes.len()
                    ));
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
                    return invalid(format!(
                        "Engram stdin delivery exceeded the absolute response deadline after delivering {delivered} of {} bytes",
                        bytes.len()
                    ));
                };
                let timeout_ms = remaining
                    .as_millis()
                    .saturating_add(u128::from(remaining.subsec_nanos() % 1_000_000 != 0))
                    .clamp(1, i32::MAX as u128) as i32;
                let events = match stdin.poll_writable(timeout_ms) {
                    Ok(Some(events)) => events,
                    Ok(None) => {
                        return invalid(format!(
                            "Engram stdin delivery exceeded the absolute response deadline after delivering {delivered} of {} bytes",
                            bytes.len()
                        ));
                    }
                    Err(error) if error.kind() == std::io::ErrorKind::Interrupted => continue,
                    Err(error) => return Err(error.into()),
                };
                if events == 0 {
                    return invalid(format!(
                        "Engram stdin poll returned no writable event after delivering {delivered} of {} bytes",
                        bytes.len()
                    ));
                }
                let terminal_events = libc::POLLERR | libc::POLLHUP | libc::POLLNVAL;
                if events & terminal_events != 0 {
                    return invalid(format!(
                        "Engram stdin became unavailable after delivering {delivered} of {} bytes (poll events {})",
                        bytes.len(),
                        events
                    ));
                }
                if events & libc::POLLOUT == 0 {
                    return invalid(format!(
                        "Engram stdin poll returned no writable event after delivering {delivered} of {} bytes",
                        bytes.len()
                    ));
                }
            }
            Err(error) => {
                return invalid(format!(
                    "Engram stdin delivery failed after delivering {delivered} of {} bytes: {error}",
                    bytes.len()
                ));
            }
        }
    }
    Ok(delivered)
}

#[cfg(not(unix))]
fn write_native_correction_stdin_until(
    _stdin: &mut NativeCorrectionChildStdin,
    bytes: &[u8],
    _deadline: Instant,
) -> NativeCorrectionResult<usize> {
    invalid(format!(
        "bounded Engram stdio request delivery is unsupported on this host for {} bytes",
        bytes.len()
    ))
}

#[derive(Debug)]
struct NativeCorrectionStdioSession {
    child: NativeCorrectionChildGuard,
    daemon_cleanup: Option<(PathBuf, PathBuf, String)>,
    stdin: Option<NativeCorrectionChildStdin>,
    stdout_rx: Receiver<Result<String, String>>,
    stdout_thread: Option<JoinHandle<()>>,
    stderr_rx: Receiver<Result<Vec<u8>, String>>,
    stderr_thread: Option<JoinHandle<()>>,
    response_deadline: Instant,
    terminal_deadline: Instant,
    next_id: u64,
    transcript: Vec<u8>,
    terminal_failure: Option<String>,
}

impl NativeCorrectionStdioSession {
    fn process_id(&self) -> NativeCorrectionResult<u32> {
        Ok(self.child.process_id()?)
    }

    #[cfg(test)]
    fn start(
        engram: &Path,
        engram_home: &Path,
        partition: &str,
        timeout: Duration,
    ) -> NativeCorrectionResult<Self> {
        let (response_deadline, terminal_deadline) = native_correction_deadlines(timeout)?;
        Self::start_with_deadlines(
            engram,
            engram_home,
            partition,
            response_deadline,
            terminal_deadline,
        )
    }

    fn start_with_deadlines(
        engram: &Path,
        engram_home: &Path,
        partition: &str,
        response_deadline: Instant,
        terminal_deadline: Instant,
    ) -> NativeCorrectionResult<Self> {
        if partition.trim().is_empty() || !engram_home.is_dir() {
            return invalid("stdio session requires a non-empty partition and existing home");
        }
        validate_native_correction_candidate_bundle(engram)?;
        let mut command = Command::new(engram);
        command
            .args(["serve", "--project", partition, "--profile", "full"])
            .env_clear()
            .env("ENGRAM_HOME", engram_home)
            .env("DISABLE_TELEMETRY", "1")
            .env("PATH", "/usr/bin:/bin:/usr/sbin:/sbin")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        Self::from_spawned_child_with_deadlines(
            native_correction_spawned_guard(NativeCorrectionChildGuard::spawn(
                command,
                terminal_deadline,
            ))?,
            response_deadline,
            terminal_deadline,
            Some((
                engram.to_path_buf(),
                engram_home.to_path_buf(),
                partition.to_string(),
            )),
        )
    }

    #[cfg(test)]
    fn from_spawned_child(
        child: Child,
        timeout: Duration,
        daemon_cleanup: Option<(PathBuf, PathBuf, String)>,
    ) -> NativeCorrectionResult<Self> {
        let (response_deadline, terminal_deadline) = native_correction_deadlines(timeout)?;
        Self::from_spawned_child_with_deadlines(
            NativeCorrectionChildGuard::adopt_spawned_group_for_test(child, terminal_deadline)?,
            response_deadline,
            terminal_deadline,
            daemon_cleanup,
        )
    }

    fn from_spawned_child_with_deadlines(
        mut child: NativeCorrectionChildGuard,
        response_deadline: Instant,
        terminal_deadline: Instant,
        daemon_cleanup: Option<(PathBuf, PathBuf, String)>,
    ) -> NativeCorrectionResult<Self> {
        let stdin = child.take_stdin()?.ok_or_else(|| {
            NativeCorrectionError::Invalid("Engram stdio stdin unavailable".to_string())
        });
        let stdout = child.take_stdout()?.ok_or_else(|| {
            NativeCorrectionError::Invalid("Engram stdio stdout unavailable".to_string())
        });
        let stderr = child.take_stderr()?.ok_or_else(|| {
            NativeCorrectionError::Invalid("Engram stdio stderr unavailable".to_string())
        });
        let (stdin, stdout, stderr) = match (stdin, stdout, stderr) {
            (Ok(stdin), Ok(stdout), Ok(stderr)) => (stdin, stdout, stderr),
            (stdin, stdout, stderr) => {
                let mut failures = Vec::new();
                if let Err(error) = stdin {
                    failures.push(error.to_string());
                }
                if let Err(error) = stdout {
                    failures.push(error.to_string());
                }
                if let Err(error) = stderr {
                    failures.push(error.to_string());
                }
                if let Err(error) = native_correction_cleanup_result(
                    child.terminate_group_and_reap_with_status_until(terminal_deadline),
                ) {
                    failures.push(format!("Engram stdio construction cleanup failed: {error}"));
                    if let Some(abandonment) =
                        child.abandon_after_cleanup_failure("Engram stdio construction cleanup")
                    {
                        failures.push(abandonment);
                    }
                }
                return invalid(failures.join("; "));
            }
        };
        if let Err(primary) = configure_native_correction_stdin_nonblocking(&stdin) {
            drop(stdin);
            drop(stdout);
            drop(stderr);
            let cleanup = native_correction_cleanup_result(
                child.terminate_group_and_reap_with_status_until(terminal_deadline),
            );
            let abandonment = cleanup.as_ref().err().and_then(|_| {
                child.abandon_after_cleanup_failure("Engram stdio nonblocking setup cleanup")
            });
            let mut failures = vec![format!(
                "cannot configure bounded Engram stdin delivery: {primary}"
            )];
            if let Err(error) = cleanup {
                failures.push(format!(
                    "Engram stdio nonblocking setup cleanup failed: {error}"
                ));
            }
            if let Some(abandonment) = abandonment {
                failures.push(abandonment);
            }
            return invalid(failures.join("; "));
        }
        let (stdout_tx, stdout_rx) = mpsc::channel();
        let stdout_thread =
            thread::spawn(move || {
                let mut reader = BufReader::new(stdout);
                let mut total_bytes = 0usize;
                loop {
                    let mut bytes = Vec::new();
                    match reader
                        .by_ref()
                        .take((MAX_RUNTIME_PROBE_BYTES + 1) as u64)
                        .read_until(b'\n', &mut bytes)
                    {
                        Ok(0) => break,
                        Ok(_) if bytes.len() <= MAX_RUNTIME_PROBE_BYTES => {
                            if bytes.last() != Some(&b'\n') {
                                let _ = stdout_tx
                                    .send(Err("Engram stdio response omitted its JSONL newline"
                                        .to_string()));
                                break;
                            }
                            total_bytes = total_bytes.saturating_add(bytes.len());
                            if total_bytes > MAX_RUNTIME_PROBE_BYTES {
                                let _ = stdout_tx
                                    .send(Err("Engram stdio stream exceeded the runtime byte cap"
                                        .to_string()));
                                break;
                            }
                            let line = match String::from_utf8(bytes) {
                                Ok(line) => line,
                                Err(_) => {
                                    let _ = stdout_tx.send(Err(
                                        "Engram stdio response was not UTF-8".to_string(),
                                    ));
                                    break;
                                }
                            };
                            if stdout_tx.send(Ok(line)).is_err() {
                                break;
                            }
                        }
                        Ok(_) => {
                            let _ = stdout_tx
                                .send(Err("Engram stdio response exceeded the runtime byte cap"
                                    .to_string()));
                            break;
                        }
                        Err(error) => {
                            let _ = stdout_tx
                                .send(Err(format!("cannot read Engram stdio response: {error}")));
                            break;
                        }
                    }
                }
            });
        let (stderr_tx, stderr_rx) = mpsc::channel();
        let stderr_thread = thread::spawn(move || {
            let mut bytes = Vec::new();
            let result = stderr
                .take((MAX_RUNTIME_PROBE_BYTES + 1) as u64)
                .read_to_end(&mut bytes);
            let observed = result
                .map(|_| bytes)
                .map_err(|error| format!("cannot read Engram stderr: {error}"));
            let _ = stderr_tx.send(observed);
        });
        Ok(Self {
            child,
            daemon_cleanup,
            stdin: Some(stdin),
            stdout_rx,
            stdout_thread: Some(stdout_thread),
            stderr_rx,
            stderr_thread: Some(stderr_thread),
            response_deadline,
            terminal_deadline,
            next_id: 1,
            transcript: Vec::new(),
            terminal_failure: None,
        })
    }

    fn initialize(&mut self) -> NativeCorrectionResult<Value> {
        let response = self.request(
            "initialize",
            json!({
                "protocolVersion": NATIVE_CORRECTION_MCP_PROTOCOL,
                "capabilities": {},
                "clientInfo": {"name":"engram-native-correction-eval","version":"1"}
            }),
        )?;
        self.notify("notifications/initialized", json!({}))?;
        Ok(response.raw)
    }

    fn tools_list(&mut self) -> NativeCorrectionResult<Value> {
        Ok(self.request("tools/list", json!({}))?.raw)
    }

    fn tool_call(
        &mut self,
        name: &str,
        arguments: Value,
    ) -> NativeCorrectionResult<NativeCorrectionMcpResponse> {
        let response = self.request("tools/call", json!({"name":name,"arguments":arguments}))?;
        Ok(response)
    }

    fn request(
        &mut self,
        method: &str,
        params: Value,
    ) -> NativeCorrectionResult<NativeCorrectionMcpResponse> {
        let prepared = self.prepare_request(method, params)?;
        self.send_prepared_request(prepared)
    }

    fn prepare_request(
        &mut self,
        method: &str,
        params: Value,
    ) -> NativeCorrectionResult<NativeCorrectionPreparedRequest> {
        let id = self.next_id;
        self.next_id = self
            .next_id
            .checked_add(1)
            .ok_or_else(|| NativeCorrectionError::Invalid("MCP request ID overflow".to_string()))?;
        let message = json!({"jsonrpc":"2.0","id":id,"method":method,"params":params});
        let mut json_line = serde_json::to_vec(&message)?;
        json_line.push(b'\n');
        Ok(NativeCorrectionPreparedRequest {
            id,
            method: method.to_string(),
            message,
            json_line,
        })
    }

    fn send_prepared_request(
        &mut self,
        prepared: NativeCorrectionPreparedRequest,
    ) -> NativeCorrectionResult<NativeCorrectionMcpResponse> {
        let NativeCorrectionPreparedRequest {
            id,
            method,
            message,
            json_line,
        } = prepared;
        if strict_json_value_from_slice(json_line.strip_suffix(b"\n").ok_or_else(|| {
            NativeCorrectionError::Invalid("prepared MCP request omitted newline".to_string())
        })?)?
            != message
        {
            return invalid("prepared MCP request bytes disagreed with its JSON value");
        }
        self.write_message_bytes(&json_line)?;
        let remaining = self
            .response_deadline
            .checked_duration_since(Instant::now())
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(format!(
                    "absolute Engram stdio session deadline elapsed before {method} response"
                ))
            })?;
        let line = self
            .stdout_rx
            .recv_timeout(remaining)
            .map_err(|error| {
                NativeCorrectionError::Invalid(format!(
                    "timed out waiting for Engram {method} response: {error}"
                ))
            })?
            .map_err(NativeCorrectionError::Invalid)?;
        if self.transcript.len().saturating_add(line.len()) > MAX_RUNTIME_PROBE_BYTES {
            return invalid("Engram stdio transcript exceeded its byte cap");
        }
        self.transcript.extend_from_slice(line.as_bytes());
        let raw = strict_json_value_from_str(line.trim())?;
        if raw.get("id").and_then(Value::as_u64) != Some(id)
            || raw.get("jsonrpc").and_then(Value::as_str) != Some("2.0")
        {
            return invalid(format!("Engram {method} returned an unrelated response"));
        }
        if let Some(error) = raw.get("error").filter(|value| !value.is_null()) {
            return invalid(format!("Engram {method} returned JSON-RPC error: {error}"));
        }
        let content = if method == "tools/call" {
            if raw.pointer("/result/isError").and_then(Value::as_bool) == Some(true) {
                None
            } else {
                let values = raw
                    .pointer("/result/content")
                    .and_then(Value::as_array)
                    .ok_or_else(|| {
                        NativeCorrectionError::Invalid(
                            "Engram tools/call omitted MCP content".to_string(),
                        )
                    })?;
                if values.len() != 1
                    || values[0].get("type").and_then(Value::as_str) != Some("text")
                {
                    return invalid("Engram tools/call returned a non-exact text envelope");
                }
                Some(strict_json_value_from_str(
                    values[0]
                        .get("text")
                        .and_then(Value::as_str)
                        .ok_or_else(|| {
                            NativeCorrectionError::Invalid(
                                "Engram MCP text content was absent".to_string(),
                            )
                        })?,
                )?)
            }
        } else {
            None
        };
        Ok(NativeCorrectionMcpResponse { raw, content })
    }

    fn notify(&mut self, method: &str, params: Value) -> NativeCorrectionResult<()> {
        self.write_message(&json!({"jsonrpc":"2.0","method":method,"params":params}))
    }

    fn write_message(&mut self, message: &Value) -> NativeCorrectionResult<()> {
        let mut bytes = serde_json::to_vec(message)?;
        bytes.push(b'\n');
        self.write_message_bytes(&bytes)
    }

    fn write_message_bytes(&mut self, bytes: &[u8]) -> NativeCorrectionResult<()> {
        if let Some(failure) = &self.terminal_failure {
            return invalid(format!(
                "Engram stdio session is already terminal after request-delivery failure: {failure}"
            ));
        }
        if self.transcript.len().saturating_add(bytes.len()) > MAX_RUNTIME_PROBE_BYTES {
            let primary = NativeCorrectionError::Invalid(
                "Engram stdio transcript exceeded its byte cap before request delivery".into(),
            );
            return Err(self.abort_after_request_delivery_failure(primary));
        }
        let delivery = match self.stdin.as_mut() {
            Some(stdin) => {
                write_native_correction_stdin_until(stdin, bytes, self.response_deadline)
            }
            None => invalid("Engram stdio session is closed before request delivery"),
        };
        if let Err(primary) = delivery {
            return Err(self.abort_after_request_delivery_failure(primary));
        }
        // Only a fully delivered JSONL frame belongs in the transcript. A partial nonblocking
        // write is reported by byte count in the failure, but never masquerades as sent evidence.
        self.transcript.extend_from_slice(bytes);
        Ok(())
    }

    fn abort_after_request_delivery_failure(
        &mut self,
        primary: NativeCorrectionError,
    ) -> NativeCorrectionError {
        let mut failures = vec![format!("Engram stdio request delivery failed: {primary}")];
        self.stdin.take();
        let reaped_status = native_correction_cleanup_result(
            self.child
                .terminate_group_and_reap_with_status_until(self.terminal_deadline),
        );
        if let Err(error) = &reaped_status {
            failures.push(format!(
                "Engram stdio delivery-failure group termination and direct-child reap failed: {error}"
            ));
            if let Some(abandonment) = self
                .child
                .abandon_after_cleanup_failure("Engram stdio request-delivery cleanup")
            {
                failures.push(abandonment);
            }
        }

        let stdout_joined = match self.stdout_thread.take() {
            Some(handle) => match join_native_correction_thread_until(
                handle,
                self.terminal_deadline,
                "Engram stdout collector after request-delivery failure",
            ) {
                Ok(()) => true,
                Err(error) => {
                    failures.push(error.to_string());
                    false
                }
            },
            None => {
                failures.push(
                    "Engram stdout collector handle was absent after request-delivery failure"
                        .to_string(),
                );
                false
            }
        };
        let stderr_joined = match self.stderr_thread.take() {
            Some(handle) => match join_native_correction_thread_until(
                handle,
                self.terminal_deadline,
                "Engram stderr collector after request-delivery failure",
            ) {
                Ok(()) => true,
                Err(error) => {
                    failures.push(error.to_string());
                    false
                }
            },
            None => {
                failures.push(
                    "Engram stderr collector handle was absent after request-delivery failure"
                        .to_string(),
                );
                false
            }
        };

        let mut drained_stdout_bytes = 0usize;
        loop {
            if Instant::now() >= self.terminal_deadline {
                failures.push(
                    "Engram stdout drain after request-delivery failure exhausted the absolute terminal deadline"
                        .to_string(),
                );
                break;
            }
            match self.stdout_rx.try_recv() {
                Ok(Ok(line)) => {
                    drained_stdout_bytes = drained_stdout_bytes.saturating_add(line.len());
                    if drained_stdout_bytes > MAX_RUNTIME_PROBE_BYTES
                        || self.transcript.len().saturating_add(line.len())
                            > MAX_RUNTIME_PROBE_BYTES
                    {
                        failures.push(
                            "Engram stdout after request-delivery failure exceeded the transcript byte cap"
                                .to_string(),
                        );
                        break;
                    } else {
                        self.transcript.extend_from_slice(line.as_bytes());
                        failures.push(
                            "Engram emitted unaccounted stdout after request-delivery failure"
                                .to_string(),
                        );
                    }
                }
                Ok(Err(error)) => failures.push(error),
                Err(TryRecvError::Disconnected) => break,
                Err(TryRecvError::Empty) => {
                    if stdout_joined {
                        failures.push(
                            "Engram stdout collector remained connected after request-delivery failure"
                                .to_string(),
                        );
                    }
                    break;
                }
            }
        }
        if stderr_joined {
            match self.stderr_rx.try_recv() {
                Ok(Ok(stderr)) => {
                    if stderr.len() > MAX_RUNTIME_PROBE_BYTES {
                        failures.push(
                            "Engram stderr after request-delivery failure exceeded its byte cap"
                                .to_string(),
                        );
                    }
                }
                Ok(Err(error)) => failures.push(error),
                Err(TryRecvError::Empty) => failures.push(
                    "Engram stderr collector remained connected after request-delivery failure"
                        .to_string(),
                ),
                Err(TryRecvError::Disconnected) => failures.push(
                    "Engram stderr collector omitted its request-delivery failure result"
                        .to_string(),
                ),
            }
            if self.stderr_rx.try_recv() != Err(TryRecvError::Disconnected) {
                failures.push(
                    "Engram stderr collector returned duplicate request-delivery failure output"
                        .to_string(),
                );
            }
        }

        if let Some((engram, home, partition)) = self.daemon_cleanup.take() {
            if let Err(error) = stop_native_correction_daemon_with_evidence_until(
                &engram,
                &home,
                &partition,
                self.terminal_deadline,
            ) {
                failures.push(format!(
                    "Engram detached daemon cleanup after request-delivery failure failed: {error}"
                ));
            }
        }
        let failure = failures.join("; ");
        self.terminal_failure = Some(failure.clone());
        NativeCorrectionError::Invalid(failure)
    }

    fn finish(mut self) -> NativeCorrectionResult<NativeCorrectionStdioFinish> {
        if let Some(failure) = self.terminal_failure.take() {
            return invalid(format!(
                "Engram stdio session already reached a safely disarmed terminal failure: {failure}"
            ));
        }
        if !self.child.is_armed() {
            return invalid(
                "Engram stdio session was unexpectedly disarmed without terminal failure evidence",
            );
        }
        self.stdin.take();
        let completion = loop {
            match self.child.exited_without_reap(self.response_deadline) {
                Ok(true) => break Ok(()),
                Ok(false) if Instant::now() < self.response_deadline => {
                    let remaining = self
                        .response_deadline
                        .saturating_duration_since(Instant::now());
                    thread::sleep(remaining.min(Duration::from_millis(10)));
                }
                Ok(false) => break invalid("Engram stdio proxy did not exit after EOF"),
                Err(error) => break Err(error.into()),
            }
        };
        let reaped_status = native_correction_cleanup_result(
            self.child
                .terminate_group_and_reap_with_status_until(self.terminal_deadline),
        );
        let abandonment = reaped_status.as_ref().err().and_then(|_| {
            self.child
                .abandon_after_cleanup_failure("Engram stdio cleanup")
        });
        let stdout_join = self.stdout_thread.take().map(|handle| {
            join_native_correction_thread_until(
                handle,
                self.terminal_deadline,
                "Engram stdout collector",
            )
        });
        let stderr_join = self.stderr_thread.take().map(|handle| {
            join_native_correction_thread_until(
                handle,
                self.terminal_deadline,
                "Engram stderr collector",
            )
        });
        let primary = (|| {
            let mut failures = Vec::new();
            if let Err(error) = completion {
                failures.push(format!(
                    "Engram stdio completion observation failed: {error}"
                ));
            }
            let status = match reaped_status {
                Ok(status) => Some(status),
                Err(error) => {
                    failures.push(format!(
                        "Engram stdio group termination and direct-child reap failed: {error}"
                    ));
                    None
                }
            };
            if let Some(abandonment) = abandonment {
                failures.push(abandonment);
            }
            let stdout_joined = match stdout_join {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    failures.push(error.to_string());
                    false
                }
                None => {
                    failures.push("Engram stdout collector handle was absent".to_string());
                    false
                }
            };
            let stderr_joined = match stderr_join {
                Some(Ok(())) => true,
                Some(Err(error)) => {
                    failures.push(error.to_string());
                    false
                }
                None => {
                    failures.push("Engram stderr collector handle was absent".to_string());
                    false
                }
            };
            loop {
                match self.stdout_rx.try_recv() {
                    Ok(Ok(line)) => {
                        if self.transcript.len().saturating_add(line.len())
                            > MAX_RUNTIME_PROBE_BYTES
                        {
                            failures.push(
                                "Engram stdio trailing output exceeded the runtime byte cap"
                                    .to_string(),
                            );
                        } else {
                            self.transcript.extend_from_slice(line.as_bytes());
                            failures.push(
                                "Engram stdio emitted an unaccounted trailing JSONL line"
                                    .to_string(),
                            );
                        }
                    }
                    Ok(Err(error)) => failures.push(error),
                    Err(TryRecvError::Disconnected) => break,
                    Err(TryRecvError::Empty) => {
                        if stdout_joined {
                            failures.push(
                                "Engram stdout collector remained connected after join".to_string(),
                            );
                        }
                        break;
                    }
                }
            }
            let mut stderr = None;
            if stderr_joined {
                match self.stderr_rx.try_recv() {
                    Ok(Ok(bytes)) => stderr = Some(bytes),
                    Ok(Err(error)) => failures.push(error),
                    Err(TryRecvError::Empty) => failures
                        .push("Engram stderr collector remained connected after join".to_string()),
                    Err(TryRecvError::Disconnected) => failures
                        .push("Engram stderr collector omitted its terminal result".to_string()),
                }
                if self.stderr_rx.try_recv() != Err(TryRecvError::Disconnected) {
                    failures.push("Engram stderr collector returned duplicate output".into());
                }
            }
            if let Some(stderr) = &stderr {
                if stderr.len() > MAX_RUNTIME_PROBE_BYTES {
                    failures.push("Engram stderr exceeded the runtime byte cap".to_string());
                }
            }
            if let Some(status) = status {
                if !status.success() {
                    failures.push(format!(
                        "Engram stdio proxy exited unsuccessfully: {status}"
                    ));
                }
            }
            if !failures.is_empty() {
                return invalid(failures.join("; "));
            }
            let stderr = stderr.expect("failure list proves stderr exists");
            Ok((std::mem::take(&mut self.transcript), stderr))
        })();
        let daemon_cleanup = if let Some((engram, home, partition)) = self.daemon_cleanup.take() {
            stop_native_correction_daemon_with_evidence_until(
                &engram,
                &home,
                &partition,
                self.terminal_deadline,
            )
            .map(Some)
        } else {
            Ok(None)
        };
        match (primary, daemon_cleanup) {
            (Ok((transcript, stderr)), Ok(daemon_stop)) => Ok(NativeCorrectionStdioFinish {
                transcript,
                stderr,
                daemon_stop,
            }),
            (Err(primary), Ok(_)) => Err(primary),
            (Ok(_), Err(cleanup)) => Err(cleanup),
            (Err(primary), Err(cleanup)) => invalid(format!(
                "{primary}; detached daemon cleanup also failed: {cleanup}"
            )),
        }
    }
}

fn join_native_correction_thread_until<T>(
    handle: JoinHandle<T>,
    deadline: Instant,
    label: &str,
) -> NativeCorrectionResult<T> {
    let handle = handle;
    loop {
        if handle.is_finished() {
            return handle
                .join()
                .map_err(|_| NativeCorrectionError::Invalid(format!("{label} panicked")));
        }
        let Some(remaining) = deadline.checked_duration_since(Instant::now()) else {
            drop(handle);
            return invalid(format!(
                "{label} did not finish before the absolute deadline and was detached; this result is non-authorizing"
            ));
        };
        thread::sleep(remaining.min(Duration::from_millis(5)));
    }
}

#[derive(Debug)]
struct NativeCorrectionStdioFinish {
    transcript: Vec<u8>,
    stderr: Vec<u8>,
    daemon_stop: Option<NativeCorrectionDaemonStopEvidence>,
}

impl NativeCorrectionStdioFinish {
    fn require_daemon_stop(
        self,
        label: &str,
    ) -> NativeCorrectionResult<(Vec<u8>, Vec<u8>, NativeCorrectionDaemonStopEvidence)> {
        let stop = self.daemon_stop.ok_or_else(|| {
            NativeCorrectionError::Invalid(format!("{label} omitted causal daemon-stop evidence"))
        })?;
        Ok((self.transcript, self.stderr, stop))
    }
}

impl Drop for NativeCorrectionStdioSession {
    fn drop(&mut self) {
        self.stdin.take();
        if self.child.is_armed() {
            if let Err(error) = native_correction_cleanup_result(
                self.child
                    .terminate_group_and_reap_with_status_until(self.terminal_deadline),
            ) {
                eprintln!("native correction stdio cleanup failed: {error}");
                if let Some(abandonment) = self
                    .child
                    .abandon_after_cleanup_failure("Engram stdio drop cleanup")
                {
                    eprintln!("{abandonment}");
                }
            }
        }
        if let Some(handle) = self.stdout_thread.take() {
            if handle.is_finished() {
                if handle.join().is_err() {
                    eprintln!("native correction stdout collector panicked during drop");
                }
            } else {
                drop(handle);
                eprintln!(
                    "native correction stdout collector was detached during drop; result is non-authorizing"
                );
            }
        }
        if let Some(handle) = self.stderr_thread.take() {
            if handle.is_finished() {
                if handle.join().is_err() {
                    eprintln!("native correction stderr collector panicked during drop");
                }
            } else {
                drop(handle);
                eprintln!(
                    "native correction stderr collector was detached during drop; result is non-authorizing"
                );
            }
        }
        if let Some((engram, home, partition)) = self.daemon_cleanup.take() {
            if let Err(error) = stop_native_correction_daemon_with_evidence_until(
                &engram,
                &home,
                &partition,
                self.terminal_deadline,
            ) {
                eprintln!("native correction detached daemon cleanup failed: {error}");
            }
        }
    }
}

fn combine_native_correction_process_cleanup<T>(
    primary: NativeCorrectionResult<T>,
    cleanup: NativeCorrectionResult<()>,
) -> NativeCorrectionResult<T> {
    combine_native_correction_cleanup(primary, cleanup, "child process cleanup")
}

fn combine_native_correction_cleanup<T>(
    primary: NativeCorrectionResult<T>,
    cleanup: NativeCorrectionResult<()>,
    cleanup_label: &str,
) -> NativeCorrectionResult<T> {
    match (primary, cleanup) {
        (Ok(value), Ok(())) => Ok(value),
        (Err(error), Ok(())) => Err(error),
        (Ok(_), Err(cleanup)) => Err(cleanup),
        (Err(primary), Err(cleanup)) => {
            invalid(format!("{primary}; {cleanup_label} also failed: {cleanup}"))
        }
    }
}

fn combine_native_correction_three<A, B, C>(
    first: NativeCorrectionResult<A>,
    second: NativeCorrectionResult<B>,
    third: NativeCorrectionResult<C>,
    labels: [&str; 3],
) -> NativeCorrectionResult<(A, B, C)> {
    let mut failures = Vec::new();
    let first = match first {
        Ok(value) => Some(value),
        Err(error) => {
            failures.push(format!("{} failed: {error}", labels[0]));
            None
        }
    };
    let second = match second {
        Ok(value) => Some(value),
        Err(error) => {
            failures.push(format!("{} failed: {error}", labels[1]));
            None
        }
    };
    let third = match third {
        Ok(value) => Some(value),
        Err(error) => {
            failures.push(format!("{} failed: {error}", labels[2]));
            None
        }
    };
    if !failures.is_empty() {
        return invalid(failures.join("; "));
    }
    Ok((
        first.expect("failure list proves first result exists"),
        second.expect("failure list proves second result exists"),
        third.expect("failure list proves third result exists"),
    ))
}

fn start_native_correction_stdio_session(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
    timeout: Duration,
) -> NativeCorrectionResult<NativeCorrectionStdioSession> {
    let (response_deadline, terminal_deadline) = native_correction_deadlines(timeout)?;
    match NativeCorrectionStdioSession::start_with_deadlines(
        engram,
        engram_home,
        partition,
        response_deadline,
        terminal_deadline,
    ) {
        Ok(session) => Ok(session),
        Err(primary) => {
            let daemon_root = engram_home.join("projects").join(partition);
            let controls_absent = ["daemon.pid", "daemon.port", "daemon.meta.json"]
                .iter()
                .all(|name| !path_entry_exists(&daemon_root.join(name)));
            finish_native_correction_stdio_start_failure(
                primary,
                controls_absent,
                terminal_deadline,
                |deadline| {
                    stop_native_correction_daemon_with_evidence_until(
                        engram,
                        engram_home,
                        partition,
                        deadline,
                    )
                    .map(|_| ())
                },
            )
        }
    }
}

fn finish_native_correction_stdio_start_failure(
    primary: NativeCorrectionError,
    controls_absent: bool,
    terminal_deadline: Instant,
    cleanup: impl FnOnce(Instant) -> NativeCorrectionResult<()>,
) -> NativeCorrectionResult<NativeCorrectionStdioSession> {
    let cleanup = if controls_absent {
        invalid(
            "stdio startup failed without daemon controls; detached-child absence cannot be proven",
        )
    } else {
        cleanup(terminal_deadline)
    };
    combine_native_correction_process_cleanup(Err(primary), cleanup)
}

fn derive_full_profile_handshake(
    engram: &Path,
) -> NativeCorrectionResult<NativeCorrectionFullProfileHandshake> {
    let root = create_runtime_probe_root()?;
    derive_full_profile_handshake_in_root_with_cleanup(engram, &root, |path| {
        fs::remove_dir_all(path).map_err(NativeCorrectionError::from)
    })
}

fn derive_full_profile_handshake_in_root_with_cleanup(
    engram: &Path,
    root: &Path,
    cleanup_root: impl FnOnce(&Path) -> NativeCorrectionResult<()>,
) -> NativeCorrectionResult<NativeCorrectionFullProfileHandshake> {
    derive_full_profile_handshake_in_root_with_cleanup_and_start(
        engram,
        root,
        cleanup_root,
        start_native_correction_stdio_session,
    )
}

fn derive_full_profile_handshake_in_root_with_cleanup_and_start(
    engram: &Path,
    root: &Path,
    cleanup_root: impl FnOnce(&Path) -> NativeCorrectionResult<()>,
    start_session: impl FnOnce(
        &Path,
        &Path,
        &str,
        Duration,
    ) -> NativeCorrectionResult<NativeCorrectionStdioSession>,
) -> NativeCorrectionResult<NativeCorrectionFullProfileHandshake> {
    let primary = (|| {
        let home = root.join("home");
        create_new_private_dir(&home)?;
        let partition = format!("correction-runtime-{}", std::process::id());
        let mut session = start_session(
            engram,
            &home,
            &partition,
            Duration::from_millis(RUNTIME_PROBE_TIMEOUT_MS),
        )?;
        let observed: NativeCorrectionResult<NativeCorrectionFullProfileHandshake> = (|| {
            let initialize = session.initialize()?;
            let tools_response = session.tools_list()?;
            let tools = tools_response
                .pointer("/result/tools")
                .and_then(Value::as_array)
                .ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "full-profile tools/list omitted tools".to_string(),
                    )
                })?;
            let memory = tools
                .iter()
                .find(|tool| tool.get("name").and_then(Value::as_str) == Some("memory"))
                .ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "full-profile tools/list omitted memory".to_string(),
                    )
                })?;
            let action_text = memory
                .pointer("/inputSchema/properties/action/description")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let memory_actions = REQUIRED_FULL_MEMORY_ACTIONS
                .iter()
                .filter(|action| action_text.contains(**action))
                .map(|action| (*action).to_string())
                .collect::<Vec<_>>();
            let initialized = initialize
                .pointer("/result/protocolVersion")
                .and_then(Value::as_str)
                == Some(NATIVE_CORRECTION_MCP_PROTOCOL)
                && initialize
                    .pointer("/result/instructions")
                    .and_then(Value::as_str)
                    .is_some_and(|instructions| instructions.contains("full tool profile"));
            let tools_sha256 = sorted_json_array_sha256(tools)?;
            Ok(NativeCorrectionFullProfileHandshake {
                fresh_process: true,
                initialized,
                profile: "full".to_string(),
                mcp_protocol_version: NATIVE_CORRECTION_MCP_PROTOCOL.to_string(),
                mcp_tool_count: tools.len(),
                mcp_tools_sha256: tools_sha256,
                memory_tool_present: true,
                memory_actions,
                daemon_stopped: true,
            })
        })();
        let finished = session
            .finish()
            .and_then(|finish| finish.require_daemon_stop("full-profile handshake"));
        let (handshake, (_, stderr, _), ()) = combine_native_correction_three(
            observed,
            finished,
            Ok(()),
            [
                "full-profile handshake observation",
                "full-profile stdio finish",
                "full-profile terminal gate",
            ],
        )?;
        if !stderr.is_empty() {
            return invalid("full-profile handshake proxy emitted stderr");
        }
        Ok(handshake)
    })();
    let cleanup = cleanup_root(root);
    combine_native_correction_cleanup(primary, cleanup, "full-profile probe-root cleanup")
}

fn sorted_json_array_sha256(values: &[Value]) -> NativeCorrectionResult<String> {
    let mut values = values.to_vec();
    values.sort_by(|left, right| {
        left.get("name")
            .and_then(Value::as_str)
            .cmp(&right.get("name").and_then(Value::as_str))
    });
    Ok(format!(
        "{:x}",
        Sha256::digest(serde_json::to_vec(&values)?)
    ))
}

fn create_runtime_probe_root() -> NativeCorrectionResult<PathBuf> {
    create_runtime_probe_root_under(&std::env::temp_dir())
}

fn create_runtime_probe_root_under(base: &Path) -> NativeCorrectionResult<PathBuf> {
    let base = base.canonicalize()?;
    let now = unix_ms(SystemTime::now())?;
    for attempt in 0..32u32 {
        let path = base.join(format!(
            "engram-native-correction-runtime-{}-{now}-{attempt}",
            std::process::id()
        ));
        match create_new_private_dir(&path) {
            Ok(()) => return Ok(path),
            Err(NativeCorrectionError::Io(error))
                if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(error) => return Err(error),
        }
    }
    invalid("could not allocate an exclusive runtime probe directory")
}

fn stop_native_correction_daemon(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
) -> NativeCorrectionResult<()> {
    stop_native_correction_daemon_with_evidence(engram, engram_home, partition).map(|_| ())
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct NativeCorrectionDaemonStopEvidence {
    started_unix_ms: u64,
    completed_unix_ms: u64,
    engram_path: String,
    engram_sha256: String,
    engram_home: String,
    partition: String,
    daemon_root: String,
    termination_method: String,
    signal_issued: bool,
    signal_number: Option<i32>,
    control_files_absent: bool,
    controls_absent_only: bool,
    live_observations: Vec<NativeCorrectionDaemonLiveObservation>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
struct NativeCorrectionDaemonLiveObservation {
    pid: u32,
    port: u16,
    controls_complete: bool,
    executable_verified: bool,
    argv_verified: bool,
    environment_verified: bool,
    daemon_token_matched: bool,
    health_verified: bool,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeCorrectionDaemonSpawnMetadata {
    schema_version: u32,
    executable_path: String,
    executable_version: String,
    executable_sha256: Option<String>,
    pid: u32,
    port: u16,
}

fn stop_native_correction_daemon_with_evidence(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
) -> NativeCorrectionResult<NativeCorrectionDaemonStopEvidence> {
    run_native_correction_standalone_stop_with_budget(
        NATIVE_CORRECTION_STANDALONE_STOP_TIMEOUT,
        |deadline| {
            stop_native_correction_daemon_with_evidence_until(
                engram,
                engram_home,
                partition,
                deadline,
            )
        },
    )
}

fn run_native_correction_standalone_stop_with_budget<T>(
    timeout: Duration,
    stop: impl FnOnce(Instant) -> NativeCorrectionResult<T>,
) -> NativeCorrectionResult<T> {
    run_native_correction_standalone_stop_with_budget_from(Instant::now(), timeout, stop)
}

fn run_native_correction_standalone_stop_with_budget_from<T>(
    started: Instant,
    timeout: Duration,
    stop: impl FnOnce(Instant) -> NativeCorrectionResult<T>,
) -> NativeCorrectionResult<T> {
    let deadline = started.checked_add(timeout).ok_or_else(|| {
        NativeCorrectionError::Invalid("standalone daemon-stop deadline overflowed".into())
    })?;
    stop(deadline).map_err(|error| {
        NativeCorrectionError::Invalid(format!(
            "standalone daemon stop failed after {} ms of its {} ms absolute budget: {error}",
            started.elapsed().as_millis(),
            timeout.as_millis(),
        ))
    })
}

fn stop_native_correction_daemon_with_evidence_until(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
    deadline: Instant,
) -> NativeCorrectionResult<NativeCorrectionDaemonStopEvidence> {
    if Instant::now() >= deadline {
        return invalid("Engram daemon cleanup deadline elapsed before attestation");
    }
    let daemon_root = engram_home.join("projects").join(partition);
    let port_file = daemon_root.join("daemon.port");
    let pid_file = daemon_root.join("daemon.pid");
    let metadata_file = daemon_root.join("daemon.meta.json");
    let started_unix_ms = unix_ms(SystemTime::now())?;
    let expected_token = validate_native_correction_daemon_stop_inputs(
        engram,
        engram_home,
        partition,
        &daemon_root,
    )?;
    // `engram daemon stop` reports a missing port file as an error. For this create-new isolated
    // family, absence of both control files is the exact already-stopped state and is intentionally
    // idempotent so a durable operator intent can be retried before or after a clean stop.
    let pid_control_present = path_entry_exists(&pid_file);
    let port_control_present = path_entry_exists(&port_file);
    let metadata_control_present = path_entry_exists(&metadata_file);
    if !pid_control_present && !port_control_present && !metadata_control_present {
        require_native_correction_cleanup_before(
            deadline,
            "Engram daemon cleanup crossed its deadline while proving absent controls",
        )?;
        let completed_unix_ms = unix_ms(SystemTime::now())?;
        return Ok(NativeCorrectionDaemonStopEvidence {
            started_unix_ms,
            completed_unix_ms,
            engram_path: engram.display().to_string(),
            engram_sha256: EXPECTED_ENGRAM_SHA256.to_string(),
            engram_home: engram_home.display().to_string(),
            partition: partition.to_string(),
            daemon_root: daemon_root.display().to_string(),
            termination_method: "already_absent".to_string(),
            signal_issued: false,
            signal_number: None,
            control_files_absent: true,
            controls_absent_only: true,
            live_observations: Vec::new(),
        });
    }
    validate_native_correction_daemon_control_presence(
        pid_control_present,
        port_control_present,
        metadata_control_present,
    )?;
    let first_observation = attest_native_correction_daemon_before_stop(
        engram,
        engram_home,
        partition,
        &daemon_root,
        &pid_file,
        &port_file,
        &metadata_file,
        &expected_token,
        deadline,
    )?;
    let second_observation = attest_native_correction_daemon_before_stop(
        engram,
        engram_home,
        partition,
        &daemon_root,
        &pid_file,
        &port_file,
        &metadata_file,
        &expected_token,
        deadline,
    )?;
    if first_observation != second_observation {
        return invalid("Engram daemon live identity changed immediately before stop");
    }
    if Instant::now() >= deadline {
        return invalid("Engram daemon cleanup deadline elapsed before the attested signal");
    }
    let daemon_pid = first_observation.pid;
    let daemon_port = first_observation.port;
    #[cfg(unix)]
    {
        // SAFETY: two consecutive attestations bound this live PID to the exact frozen binary,
        // isolated home, partition, argv, metadata, and health response. Signaling the PID
        // directly avoids asking the CLI to re-read attacker-mutable control files.
        if unsafe { libc::kill(daemon_pid as i32, libc::SIGTERM) } != 0 {
            return Err(std::io::Error::last_os_error().into());
        }
    }
    while native_correction_pid_exists(daemon_pid)? {
        if Instant::now() >= deadline {
            return invalid(format!(
                "attested Engram daemon PID {daemon_pid} remained live after stop on port {daemon_port}"
            ));
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        thread::sleep(remaining.min(Duration::from_millis(10)));
    }
    for path in [&pid_file, &port_file, &metadata_file] {
        if path_entry_exists(path) {
            if path == &pid_file {
                validate_existing_path_identity(path, path, "Engram daemon control cleanup")?;
                validate_owned_regular_file(path, 0o600)?;
            } else if fs::symlink_metadata(path)?.is_dir() {
                return invalid("Engram daemon control residue became a directory");
            }
            fs::remove_file(path)?;
        }
    }
    sync_parent_directory(&pid_file)?;
    if path_entry_exists(&port_file)
        || path_entry_exists(&pid_file)
        || path_entry_exists(&metadata_file)
    {
        return invalid("Engram daemon stop retained a live control file");
    }
    if !first_observation.controls_complete {
        return invalid(
            "Engram daemon was safely terminated but its spawn metadata was missing or invalid",
        );
    }
    require_native_correction_cleanup_before(
        deadline,
        "Engram daemon cleanup crossed its deadline before recording evidence",
    )?;
    let completed_unix_ms = unix_ms(SystemTime::now())?;
    Ok(NativeCorrectionDaemonStopEvidence {
        started_unix_ms,
        completed_unix_ms,
        engram_path: engram.display().to_string(),
        engram_sha256: EXPECTED_ENGRAM_SHA256.to_string(),
        engram_home: engram_home.display().to_string(),
        partition: partition.to_string(),
        daemon_root: daemon_root.display().to_string(),
        termination_method: "direct_sigterm".to_string(),
        signal_issued: true,
        signal_number: Some(libc::SIGTERM),
        control_files_absent: true,
        controls_absent_only: false,
        live_observations: vec![first_observation, second_observation],
    })
}

fn require_native_correction_cleanup_before(
    deadline: Instant,
    error: &str,
) -> NativeCorrectionResult<()> {
    if Instant::now() >= deadline {
        return invalid(error);
    }
    Ok(())
}

fn validate_native_correction_daemon_stop_inputs(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
    daemon_root: &Path,
) -> NativeCorrectionResult<Zeroizing<String>> {
    validate_absolute_normal_path(engram, "Engram daemon executable")?;
    validate_existing_path_identity(engram, engram, "Engram daemon executable")?;
    if sha256_file(engram)? != EXPECTED_ENGRAM_SHA256 {
        return invalid("Engram daemon stop executable did not match the frozen binary");
    }
    validate_absolute_normal_path(engram_home, "Engram daemon home")?;
    validate_existing_path_identity(engram_home, engram_home, "Engram daemon home")?;
    validate_owned_directory(engram_home, 0o700)?;
    if partition.is_empty()
        || !partition
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        || daemon_root != engram_home.join("projects").join(partition)
    {
        return invalid("Engram daemon partition escaped its frozen path grammar");
    }
    validate_existing_path_identity(daemon_root, daemon_root, "Engram daemon root")?;
    validate_owned_directory(daemon_root, 0o700)?;
    let token_path = daemon_root.join("daemon.token");
    validate_existing_path_identity(&token_path, &token_path, "Engram daemon token")?;
    validate_owned_regular_file_size(&token_path, 0o600, 64, 64, "Engram daemon token")?;
    let token_bytes = Zeroizing::new(read_bounded_attested_file(
        &token_path,
        64,
        "Engram daemon token",
    )?);
    let token = std::str::from_utf8(&token_bytes)
        .map_err(|_| NativeCorrectionError::Invalid("Engram daemon token was not UTF-8".into()))?;
    if token.len() != 64
        || !token
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
    {
        return invalid("Engram daemon token did not match its exact lowercase-hex grammar");
    }
    Ok(Zeroizing::new(token.to_string()))
}

fn validate_native_correction_daemon_control_presence(
    pid_present: bool,
    port_present: bool,
    metadata_present: bool,
) -> NativeCorrectionResult<()> {
    if !pid_present && (port_present || metadata_present) {
        return invalid("daemon control residue omitted the write-order-leading PID file");
    }
    if !pid_present && !port_present && !metadata_present {
        return invalid("daemon control presence validator received the absent state");
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn attest_native_correction_daemon_before_stop(
    engram: &Path,
    engram_home: &Path,
    partition: &str,
    _daemon_root: &Path,
    pid_file: &Path,
    port_file: &Path,
    metadata_file: &Path,
    expected_token: &str,
    deadline: Instant,
) -> NativeCorrectionResult<NativeCorrectionDaemonLiveObservation> {
    if Instant::now() >= deadline {
        return invalid("Engram daemon attestation began after its cleanup deadline");
    }
    validate_existing_path_identity(pid_file, pid_file, "Engram daemon PID file")?;
    validate_owned_regular_file_size(pid_file, 0o600, 2, 16, "Engram daemon PID file")?;
    let pid_text = std::str::from_utf8(&read_bounded_attested_file(
        pid_file,
        16,
        "Engram daemon PID file",
    )?)
    .map_err(|_| NativeCorrectionError::Invalid("Engram daemon PID was not UTF-8".into()))?
    .to_string();
    let pid: u32 = pid_text
        .strip_suffix('\n')
        .ok_or_else(|| NativeCorrectionError::Invalid("daemon PID omitted newline".into()))?
        .parse()
        .map_err(|_| NativeCorrectionError::Invalid("daemon PID was not decimal".into()))?;
    if pid <= 1 || pid > i32::MAX as u32 || pid_text != format!("{pid}\n") {
        return invalid("Engram daemon PID was outside its canonical numeric boundary");
    }
    let port_control_present = path_entry_exists(port_file);
    let metadata_control_present = path_entry_exists(metadata_file);
    let parsed_port = port_control_present
        .then(|| {
            (|| {
                validate_existing_path_identity(port_file, port_file, "Engram daemon port file")?;
                validate_owned_regular_file_size(
                    port_file,
                    0o600,
                    2,
                    8,
                    "Engram daemon port file",
                )?;
                let port_text = std::str::from_utf8(&read_bounded_attested_file(
                    port_file,
                    8,
                    "Engram daemon port file",
                )?)
                .map_err(|_| {
                    NativeCorrectionError::Invalid("Engram daemon port was not UTF-8".into())
                })?
                .to_string();
                let port: u16 = port_text
                    .strip_suffix('\n')
                    .ok_or_else(|| {
                        NativeCorrectionError::Invalid("daemon port omitted newline".into())
                    })?
                    .parse()
                    .map_err(|_| {
                        NativeCorrectionError::Invalid("daemon port was not decimal".into())
                    })?;
                if port == 0 || port_text != format!("{port}\n") {
                    return invalid(
                        "Engram daemon port was outside its canonical numeric boundary",
                    );
                }
                Ok(port)
            })()
        })
        .transpose()
        .ok()
        .flatten();
    let port_control_valid = parsed_port.is_some();
    let port = match parsed_port {
        Some(port) => port,
        None => derive_native_correction_daemon_port(
            pid,
            engram,
            engram_home,
            partition,
            expected_token,
        )?,
    };
    let metadata_valid = if metadata_control_present {
        (|| {
            validate_existing_path_identity(
                metadata_file,
                metadata_file,
                "Engram daemon metadata file",
            )?;
            validate_owned_regular_file_size(
                metadata_file,
                0o600,
                2,
                4096,
                "Engram daemon metadata file",
            )?;
            read_bounded_attested_file(metadata_file, 4096, "Engram daemon metadata file")
        })()
        .ok()
        .and_then(|bytes| {
            strict_json_from_slice::<NativeCorrectionDaemonSpawnMetadata>(&bytes).ok()
        })
        .is_some_and(|metadata| {
            metadata.schema_version == 1
                && metadata.executable_path == engram.display().to_string()
                && metadata.executable_version
                    == EXPECTED_ENGRAM_VERSION.trim_start_matches("engram ")
                && metadata.executable_sha256.as_deref() == Some(EXPECTED_ENGRAM_SHA256)
                && metadata.pid == pid
                && metadata.port == port
        })
    } else {
        false
    };
    let live_executable = native_correction_live_executable(pid)?;
    if live_executable != engram {
        return invalid("Engram daemon PID did not execute the frozen Engram binary");
    }
    validate_native_correction_daemon_arguments(
        pid,
        engram,
        engram_home,
        port,
        partition,
        expected_token,
    )?;
    #[cfg(unix)]
    {
        let process_group = unsafe { libc::getpgid(pid as i32) };
        if process_group != pid as i32 || unsafe { libc::kill(pid as i32, 0) } != 0 {
            return invalid("Engram daemon PID was not a live self-led process group");
        }
    }
    let health_verified = match validate_native_correction_daemon_health(port, pid, deadline) {
        Ok(()) => true,
        Err(NativeCorrectionError::Io(error))
            if (!port_control_valid || !metadata_valid)
                && matches!(
                    error.kind(),
                    std::io::ErrorKind::ConnectionRefused | std::io::ErrorKind::TimedOut
                ) =>
        {
            false
        }
        Err(error) => return Err(error),
    };
    Ok(NativeCorrectionDaemonLiveObservation {
        pid,
        port,
        controls_complete: port_control_valid && metadata_valid,
        executable_verified: true,
        argv_verified: true,
        environment_verified: true,
        daemon_token_matched: true,
        health_verified,
    })
}

fn validate_native_correction_daemon_arguments(
    pid: u32,
    engram: &Path,
    engram_home: &Path,
    port: u16,
    partition: &str,
    expected_token: &str,
) -> NativeCorrectionResult<()> {
    let (arguments, environment) = native_correction_daemon_process_arguments(pid)?;
    validate_native_correction_daemon_process_surfaces(
        &arguments,
        &environment,
        engram,
        engram_home,
        port,
        partition,
        expected_token,
    )
}

fn derive_native_correction_daemon_port(
    pid: u32,
    engram: &Path,
    engram_home: &Path,
    partition: &str,
    expected_token: &str,
) -> NativeCorrectionResult<u16> {
    let (arguments, environment) = native_correction_daemon_process_arguments(pid)?;
    if arguments.len() != 7
        || arguments[0] != engram.display().to_string()
        || arguments[1] != "serve"
        || arguments[2] != "--http"
        || arguments[3] != "--port"
        || arguments[5] != "--project"
        || arguments[6] != partition
    {
        return invalid("live Engram daemon argv could not derive a safe isolated port");
    }
    let port: u16 = arguments[4]
        .parse()
        .map_err(|_| NativeCorrectionError::Invalid("daemon argv port was not decimal".into()))?;
    if port == 0 || arguments[4] != port.to_string() {
        return invalid("daemon argv port was outside its canonical numeric boundary");
    }
    validate_native_correction_daemon_process_surfaces(
        &arguments,
        &environment,
        engram,
        engram_home,
        port,
        partition,
        expected_token,
    )?;
    Ok(port)
}

fn validate_native_correction_daemon_process_surfaces(
    arguments: &[String],
    environment: &[String],
    engram: &Path,
    engram_home: &Path,
    port: u16,
    partition: &str,
    expected_token: &str,
) -> NativeCorrectionResult<()> {
    let expected = vec![
        engram.display().to_string(),
        "serve".to_string(),
        "--http".to_string(),
        "--port".to_string(),
        port.to_string(),
        "--project".to_string(),
        partition.to_string(),
    ];
    let expected_home = format!("ENGRAM_HOME={}", engram_home.display());
    let expected_telemetry = "DISABLE_TELEMETRY=1";
    let mut observed = BTreeMap::new();
    for entry in environment {
        let (name, value) = entry.split_once('=').ok_or_else(|| {
            NativeCorrectionError::Invalid("live Engram daemon environment was malformed".into())
        })?;
        if observed.insert(name, value).is_some() {
            return invalid("live Engram daemon environment repeated one variable");
        }
    }
    let daemon_token_valid = observed.get("ENGRAM_DAEMON_TOKEN").copied() == Some(expected_token);
    if arguments != expected.as_slice() {
        return invalid("live Engram daemon argv did not bind the exact isolated partition");
    }
    let common_environment_valid = observed.get("ENGRAM_HOME").copied()
        == expected_home.strip_prefix("ENGRAM_HOME=")
        && observed.get("DISABLE_TELEMETRY").copied()
            == expected_telemetry.strip_prefix("DISABLE_TELEMETRY=")
        && observed.get("PATH").copied() == Some("/usr/bin:/bin:/usr/sbin:/sbin")
        && daemon_token_valid;
    #[cfg(target_os = "macos")]
    let platform_environment_valid = {
        // macOS inserts this CoreFoundation variable at exec even after Command::env_clear. Bind
        // the only admitted injected variable to the effective UID and its exact system spelling.
        // SAFETY: geteuid only reads the effective identity of this evaluator process.
        let expected_text_encoding = format!("0x{:X}:0x0:0x0", unsafe { libc::geteuid() });
        environment.len() == 5
            && observed.get("__CF_USER_TEXT_ENCODING").copied()
                == Some(expected_text_encoding.as_str())
    };
    #[cfg(not(target_os = "macos"))]
    let platform_environment_valid = environment.len() == 4;
    if !common_environment_valid || !platform_environment_valid {
        return invalid("live Engram daemon environment left its exact isolated allowlist");
    }
    Ok(())
}

#[cfg(target_os = "macos")]
fn native_correction_daemon_process_arguments(
    pid: u32,
) -> NativeCorrectionResult<(Vec<String>, Vec<String>)> {
    let mut mib = [libc::CTL_KERN, libc::KERN_PROCARGS2, pid as i32];
    let mut size = 0usize;
    // SAFETY: this first sysctl call asks the kernel only for the bounded buffer size.
    if unsafe {
        libc::sysctl(
            mib.as_mut_ptr(),
            mib.len() as u32,
            std::ptr::null_mut(),
            &mut size,
            std::ptr::null_mut(),
            0,
        )
    } != 0
        || size < std::mem::size_of::<i32>()
        || size > 1024 * 1024
    {
        return invalid("live Engram daemon process arguments exceeded their kernel boundary");
    }
    let mut bytes = vec![0u8; size];
    // SAFETY: the buffer is allocated to the kernel-reported size and the call is read-only.
    if unsafe {
        libc::sysctl(
            mib.as_mut_ptr(),
            mib.len() as u32,
            bytes.as_mut_ptr().cast(),
            &mut size,
            std::ptr::null_mut(),
            0,
        )
    } != 0
        || size > bytes.len()
    {
        return Err(std::io::Error::last_os_error().into());
    }
    bytes.truncate(size);
    let argc = i32::from_ne_bytes(
        bytes[..std::mem::size_of::<i32>()]
            .try_into()
            .expect("kernel argument count has i32 width"),
    );
    if argc <= 0 || argc > 32 {
        return invalid("live Engram daemon argc left its frozen boundary");
    }
    let mut cursor = std::mem::size_of::<i32>();
    cursor = bytes[cursor..]
        .iter()
        .position(|byte| *byte == 0)
        .map(|offset| cursor + offset + 1)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("kernel argv omitted exec path NUL".into())
        })?;
    while cursor < bytes.len() && bytes[cursor] == 0 {
        cursor += 1;
    }
    let mut values = Vec::new();
    while cursor < bytes.len() {
        let end = bytes[cursor..]
            .iter()
            .position(|byte| *byte == 0)
            .map(|offset| cursor + offset)
            .ok_or_else(|| NativeCorrectionError::Invalid("kernel argv/env omitted NUL".into()))?;
        if end == cursor {
            break;
        }
        values.push(
            std::str::from_utf8(&bytes[cursor..end])
                .map_err(|_| {
                    NativeCorrectionError::Invalid("kernel argv/env was not UTF-8".into())
                })?
                .to_string(),
        );
        cursor = end + 1;
    }
    let argc = argc as usize;
    if values.len() < argc {
        return invalid("kernel process arguments were truncated");
    }
    let environment = values.split_off(argc);
    Ok((values, environment))
}

#[cfg(not(target_os = "macos"))]
fn native_correction_daemon_process_arguments(
    pid: u32,
) -> NativeCorrectionResult<(Vec<String>, Vec<String>)> {
    let mut arguments = Vec::new();
    File::open(format!("/proc/{pid}/cmdline"))?
        .take(16 * 1024 + 1)
        .read_to_end(&mut arguments)?;
    if arguments.len() > 16 * 1024 {
        return invalid("live Engram daemon argv exceeded its byte boundary");
    }
    let mut environment = Vec::new();
    File::open(format!("/proc/{pid}/environ"))?
        .take(64 * 1024 + 1)
        .read_to_end(&mut environment)?;
    if environment.len() > 64 * 1024 {
        return invalid("live Engram daemon environment exceeded its byte boundary");
    }
    let arguments = arguments
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
        .map(|value| {
            std::str::from_utf8(value)
                .map(str::to_string)
                .map_err(|_| NativeCorrectionError::Invalid("daemon argv was not UTF-8".into()))
        })
        .collect::<NativeCorrectionResult<Vec<_>>>()?;
    let environment = environment
        .split(|byte| *byte == 0)
        .filter(|value| !value.is_empty())
        .map(|value| {
            std::str::from_utf8(value).map(str::to_string).map_err(|_| {
                NativeCorrectionError::Invalid("daemon environment was not UTF-8".into())
            })
        })
        .collect::<NativeCorrectionResult<Vec<_>>>()?;
    Ok((arguments, environment))
}

#[cfg(target_os = "macos")]
fn native_correction_live_executable(pid: u32) -> NativeCorrectionResult<PathBuf> {
    use std::os::unix::ffi::OsStringExt;
    let mut buffer = vec![0u8; libc::PROC_PIDPATHINFO_MAXSIZE as usize];
    let length =
        unsafe { libc::proc_pidpath(pid as i32, buffer.as_mut_ptr().cast(), buffer.len() as u32) };
    if length <= 0 {
        return invalid("could not attest the live Engram daemon executable path");
    }
    buffer.truncate(length as usize);
    let path = PathBuf::from(std::ffi::OsString::from_vec(buffer));
    validate_absolute_normal_path(&path, "live Engram daemon executable")?;
    Ok(path.canonicalize()?)
}

#[cfg(not(target_os = "macos"))]
fn native_correction_live_executable(pid: u32) -> NativeCorrectionResult<PathBuf> {
    let path = fs::read_link(format!("/proc/{pid}/exe"))?;
    validate_absolute_normal_path(&path, "live Engram daemon executable")?;
    Ok(path.canonicalize()?)
}

fn native_correction_pid_exists(pid: u32) -> NativeCorrectionResult<bool> {
    #[cfg(unix)]
    {
        let result = unsafe { libc::kill(pid as i32, 0) };
        if result == 0 {
            return Ok(true);
        }
        let error = std::io::Error::last_os_error();
        match error.raw_os_error() {
            Some(libc::ESRCH) => Ok(false),
            Some(libc::EPERM) => Ok(true),
            _ => Err(error.into()),
        }
    }
    #[cfg(not(unix))]
    {
        let _ = pid;
        invalid("Engram daemon process identity requires Unix semantics")
    }
}

fn native_correction_remaining_io_timeout(deadline: Instant) -> NativeCorrectionResult<Duration> {
    deadline
        .checked_duration_since(Instant::now())
        .filter(|remaining| !remaining.is_zero())
        .map(|remaining| remaining.min(Duration::from_millis(750)))
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "Engram daemon health I/O exhausted its absolute cleanup deadline".into(),
            )
        })
}

fn validate_native_correction_daemon_health(
    port: u16,
    pid: u32,
    deadline: Instant,
) -> NativeCorrectionResult<()> {
    let timeout = native_correction_remaining_io_timeout(deadline)?;
    let address = SocketAddr::from(([127, 0, 0, 1], port));
    let mut stream = TcpStream::connect_timeout(&address, timeout)?;
    let request = b"GET /health HTTP/1.1\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n";
    let mut written = 0usize;
    while written < request.len() {
        stream.set_write_timeout(Some(native_correction_remaining_io_timeout(deadline)?))?;
        let count = stream.write(&request[written..])?;
        if count == 0 {
            return invalid("Engram daemon health request made no write progress");
        }
        written += count;
    }
    let mut response = Vec::new();
    let mut chunk = [0_u8; 8 * 1024];
    loop {
        stream.set_read_timeout(Some(native_correction_remaining_io_timeout(deadline)?))?;
        let remaining_capacity = (64_usize * 1024 + 1).saturating_sub(response.len());
        if remaining_capacity == 0 {
            break;
        }
        let read_capacity = chunk.len().min(remaining_capacity);
        let count = stream.read(&mut chunk[..read_capacity])?;
        if count == 0 {
            break;
        }
        response.extend_from_slice(&chunk[..count]);
    }
    validate_native_correction_daemon_health_response(&response, pid)
}

fn validate_native_correction_daemon_health_response(
    response: &[u8],
    pid: u32,
) -> NativeCorrectionResult<()> {
    if response.len() > 64 * 1024 {
        return invalid("Engram daemon health response exceeded its byte boundary");
    }
    let boundary = response
        .windows(4)
        .position(|window| window == b"\r\n\r\n")
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("daemon health HTTP framing failed".into())
        })?;
    let headers = std::str::from_utf8(&response[..boundary]).map_err(|_| {
        NativeCorrectionError::Invalid("daemon health HTTP headers were not UTF-8".into())
    })?;
    let header_lines = headers.split("\r\n").collect::<Vec<_>>();
    if header_lines.first().copied() != Some("HTTP/1.1 200 OK") {
        return invalid("Engram daemon health endpoint was not exactly ready");
    }
    if header_lines.len() != 5
        || header_lines[1] != "content-type: application/json"
        || header_lines[3] != "connection: close"
        || !header_lines[4].starts_with("date: ")
    {
        return invalid("Engram daemon health headers left the exact installed framing");
    }
    let date = &header_lines[4]["date: ".len()..];
    if date.len() != 29
        || !date.ends_with(" GMT")
        || !date
            .bytes()
            .all(|byte| byte == b' ' || byte.is_ascii_graphic())
    {
        return invalid("Engram daemon health Date header left its bounded IMF-fixdate shape");
    }
    let content_length_text = header_lines[2]
        .strip_prefix("content-length: ")
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "Engram daemon health omitted its exact Content-Length header".into(),
            )
        })?;
    if content_length_text.is_empty()
        || !content_length_text
            .bytes()
            .all(|byte| byte.is_ascii_digit())
        || (content_length_text.len() > 1 && content_length_text.starts_with('0'))
    {
        return invalid("Engram daemon health Content-Length was not canonical decimal");
    }
    let content_length = content_length_text.parse::<usize>().map_err(|_| {
        NativeCorrectionError::Invalid(
            "Engram daemon health Content-Length exceeded its numeric boundary".into(),
        )
    })?;
    if content_length == 0 || content_length > 64 * 1024 {
        return invalid("Engram daemon health Content-Length exceeded its byte boundary");
    }
    let body = &response[boundary + 4..];
    if body.len() != content_length {
        return invalid("Engram daemon health body length drifted");
    }
    let health = strict_json_value_from_slice(body)?;
    if !exact_object_keys(
        &health,
        &[
            "status",
            "service",
            "version",
            "build_sha",
            "pid",
            "health_schema_version",
            "mcp_contract_version",
            "mcp_tools_sha256",
            "mcp_protocol_version",
            "auth_required",
            "storage_status",
            "storage_ready",
            "storage_available_bytes",
            "storage_required_bytes",
        ],
    ) || health.get("status").and_then(Value::as_str) != Some("ok")
        || health.get("service").and_then(Value::as_str) != Some("engram")
        || health.get("version").and_then(Value::as_str)
            != Some(EXPECTED_ENGRAM_VERSION.trim_start_matches("engram "))
        || health.get("pid").and_then(Value::as_u64) != Some(pid as u64)
        || health.get("health_schema_version").and_then(Value::as_u64) != Some(3)
        || health.get("mcp_contract_version").and_then(Value::as_u64) != Some(5)
        || health.get("mcp_tools_sha256").and_then(Value::as_str)
            != Some(EXPECTED_FULL_TOOLS_SHA256)
        || health.get("mcp_protocol_version").and_then(Value::as_str)
            != Some(NATIVE_CORRECTION_MCP_PROTOCOL)
        || health.get("auth_required").and_then(Value::as_bool) != Some(true)
        || health.get("storage_status").and_then(Value::as_str) != Some("ready")
        || health.get("storage_ready").and_then(Value::as_bool) != Some(true)
        || !(health.get("build_sha").is_some_and(Value::is_null)
            || health.get("build_sha").is_some_and(Value::is_string))
        || !(health
            .get("storage_available_bytes")
            .is_some_and(Value::is_null)
            || health
                .get("storage_available_bytes")
                .is_some_and(Value::is_u64))
        || !(health
            .get("storage_required_bytes")
            .is_some_and(Value::is_null)
            || health
                .get("storage_required_bytes")
                .is_some_and(Value::is_u64))
    {
        return invalid("Engram daemon live health identity drifted");
    }
    Ok(())
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum NativeCorrectionMemoryStatus {
    Active,
    NeedsReview,
    Superseded,
    Archived,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum NativeCorrectionOrigin {
    ToolResult,
    AgentInferred,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionMemorySnapshot {
    pub id: String,
    pub kind: String,
    pub title: String,
    pub content: String,
    pub origin: NativeCorrectionOrigin,
    pub status: NativeCorrectionMemoryStatus,
    pub scope: Value,
    pub scope_project: String,
    pub scope_project_id: Option<String>,
    pub writer: Value,
    pub evidence: Vec<Value>,
    pub tags: Vec<String>,
    pub confidence_millis: u16,
    pub confidence_bits: u32,
    pub supersedes_ids: Vec<String>,
    pub supersedes_id: Option<String>,
    pub superseded_by_id: Option<String>,
    pub correction_proposal_id: Option<String>,
    pub pending_correction_proposal_id: Option<String>,
    pub manual_review_evidence_count: u32,
    pub created_at: String,
    pub updated_at: String,
    pub last_used_at: Option<String>,
    pub review_after: Option<String>,
    pub archive: Option<Value>,
    pub procedure: Option<Value>,
    pub canonical_item_sha256: String,
}

#[derive(Serialize)]
struct NativeCorrectionDigestItem<'a> {
    id: &'a Id,
    kind: &'a MemoryKind,
    title: &'a str,
    content: &'a str,
    scope: &'a MemoryScope,
    origin: &'a ClaimOrigin,
    writer: &'a WriterProvenance,
    evidence: &'a [EvidenceRef],
    confidence: f32,
    status: MemoryStatus,
    supersedes: &'a [Id],
    tags: &'a [String],
    review_after: Option<OffsetDateTime>,
    archive: &'a Option<ArchiveMetadata>,
    procedure: &'a Option<ProcedureCard>,
    correction_proposal_id: Option<Id>,
    pending_correction_proposal_id: Option<Id>,
}

impl<'a> From<&'a MemoryItem> for NativeCorrectionDigestItem<'a> {
    fn from(item: &'a MemoryItem) -> Self {
        Self {
            id: &item.id,
            kind: &item.kind,
            title: &item.title,
            content: &item.content,
            scope: &item.scope,
            origin: &item.origin,
            writer: &item.writer,
            evidence: &item.evidence,
            confidence: item.confidence.value(),
            status: item.status,
            supersedes: &item.supersedes,
            tags: &item.tags,
            review_after: item.review_after,
            archive: &item.archive,
            procedure: &item.procedure,
            correction_proposal_id: item.correction_proposal_id,
            pending_correction_proposal_id: item.pending_correction_proposal_id,
        }
    }
}

#[derive(Serialize)]
struct NativeCorrectionDigestPayload<'a> {
    schema_version: u32,
    proposal_id: &'a Id,
    obsolete_id: &'a Id,
    replacement_id: &'a Id,
    memory_kind: &'a MemoryKind,
    scope: &'a MemoryScope,
    obsolete: NativeCorrectionDigestItem<'a>,
    replacement: NativeCorrectionDigestItem<'a>,
}

fn recompute_native_correction_digest(
    proposal: &CorrectionProposal,
    obsolete: &MemoryItem,
    replacement: &MemoryItem,
) -> NativeCorrectionResult<String> {
    if proposal.digest_schema_version != 1
        || proposal.obsolete_id != obsolete.id
        || proposal.replacement_id != replacement.id
        || proposal.memory_kind != obsolete.kind
        || proposal.memory_kind != replacement.kind
        || proposal.scope != obsolete.scope
        || proposal.scope != replacement.scope
    {
        return invalid("correction proposal lost its exact ID/kind/scope pair");
    }
    let payload = NativeCorrectionDigestPayload {
        schema_version: proposal.digest_schema_version,
        proposal_id: &proposal.id,
        obsolete_id: &proposal.obsolete_id,
        replacement_id: &proposal.replacement_id,
        memory_kind: &proposal.memory_kind,
        scope: &proposal.scope,
        obsolete: obsolete.into(),
        replacement: replacement.into(),
    };
    sha256_json(&payload)
}

fn native_correction_memory_snapshot(
    item: &MemoryItem,
    superseded_by_id: Option<String>,
) -> NativeCorrectionResult<NativeCorrectionMemorySnapshot> {
    let (scope_project, scope_project_id) = match &item.scope {
        MemoryScope::Project {
            project_id,
            project_name,
        } => (
            project_name.clone(),
            project_id.as_ref().map(ToString::to_string),
        ),
        _ => return invalid("native correction memory must have project scope"),
    };
    let origin = match item.origin {
        ClaimOrigin::ToolResult => NativeCorrectionOrigin::ToolResult,
        ClaimOrigin::AgentInferred => NativeCorrectionOrigin::AgentInferred,
        _ => return invalid("native correction memory has an unexpected claim origin"),
    };
    let status = match item.status {
        MemoryStatus::Active => NativeCorrectionMemoryStatus::Active,
        MemoryStatus::NeedsReview => NativeCorrectionMemoryStatus::NeedsReview,
        MemoryStatus::Superseded => NativeCorrectionMemoryStatus::Superseded,
        MemoryStatus::Archived => NativeCorrectionMemoryStatus::Archived,
        _ => return invalid("native correction memory has an unexpected lifecycle status"),
    };
    if item.supersedes.len() > 1 {
        return invalid("native correction memory supersedes more than one item");
    }
    let confidence = f64::from(item.confidence.value()) * 1000.0;
    if !confidence.is_finite() || !(0.0..=1000.0).contains(&confidence) {
        return invalid("native correction memory confidence is outside 0..=1");
    }
    let serialized = serde_json::to_value(item)?;
    let evidence = serialized
        .get("evidence")
        .and_then(Value::as_array)
        .cloned()
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("memory serialization omitted evidence".to_string())
        })?;
    Ok(NativeCorrectionMemorySnapshot {
        id: item.id.to_string(),
        kind: item.kind.to_string(),
        title: item.title.clone(),
        content: item.content.clone(),
        origin,
        status,
        scope: serialized
            .get("scope")
            .cloned()
            .ok_or_else(|| NativeCorrectionError::Invalid("memory scope missing".to_string()))?,
        scope_project,
        scope_project_id,
        writer: serialized
            .get("writer")
            .cloned()
            .ok_or_else(|| NativeCorrectionError::Invalid("memory writer missing".to_string()))?,
        evidence,
        tags: item.tags.clone(),
        confidence_millis: confidence.round() as u16,
        confidence_bits: item.confidence.value().to_bits(),
        supersedes_ids: item.supersedes.iter().map(ToString::to_string).collect(),
        supersedes_id: item.supersedes.first().map(ToString::to_string),
        superseded_by_id,
        correction_proposal_id: item.correction_proposal_id.map(|id| id.to_string()),
        pending_correction_proposal_id: item
            .pending_correction_proposal_id
            .map(|id| id.to_string()),
        manual_review_evidence_count: u32::try_from(
            item.evidence
                .iter()
                .filter(|evidence| matches!(evidence.kind, EvidenceKind::ManualReview))
                .count(),
        )
        .map_err(|_| {
            NativeCorrectionError::Invalid("manual-review evidence count overflow".to_string())
        })?,
        created_at: required_json_string(&serialized, "created_at", "memory")?,
        updated_at: required_json_string(&serialized, "updated_at", "memory")?,
        last_used_at: optional_json_string(&serialized, "last_used_at", "memory")?,
        review_after: optional_json_string(&serialized, "review_after", "memory")?,
        archive: serialized
            .get("archive")
            .cloned()
            .filter(|value| !value.is_null()),
        procedure: serialized
            .get("procedure")
            .cloned()
            .filter(|value| !value.is_null()),
        canonical_item_sha256: sha256_json(&serialized)?,
    })
}

fn native_correction_proposal_snapshot(
    proposal: &CorrectionProposal,
) -> NativeCorrectionResult<NativeCorrectionProposalSnapshot> {
    let serialized = serde_json::to_value(proposal)?;
    Ok(NativeCorrectionProposalSnapshot {
        proposal_id: proposal.id.to_string(),
        obsolete_id: proposal.obsolete_id.to_string(),
        replacement_id: proposal.replacement_id.to_string(),
        memory_kind: proposal.memory_kind.to_string(),
        scope: serialized
            .get("scope")
            .cloned()
            .ok_or_else(|| NativeCorrectionError::Invalid("proposal scope missing".to_string()))?,
        canonical_digest: proposal.canonical_digest.clone(),
        digest_schema_version: proposal.digest_schema_version,
        applied_digest: proposal.applied_digest.clone(),
        status: proposal.status.to_string(),
        proposer: serialized.get("proposer").cloned().ok_or_else(|| {
            NativeCorrectionError::Invalid("proposal proposer missing".to_string())
        })?,
        created_at: required_json_string(&serialized, "created_at", "proposal")?,
        applied_at: optional_json_string(&serialized, "applied_at", "proposal")?,
        reviewer_authority_conferred: false,
        intent_verified: false,
        scope_selector_authenticated: false,
    })
}

