#[derive(Debug)]
struct NativeCorrectionSeedOutcome {
    receipt: NativeCorrectionSeedReceipt,
    transcript: Vec<u8>,
    stderr: Vec<u8>,
}

/// Provider-free control plane used only behind the production exact-stdio entry point and local
/// tests. Keeping this trait private prevents callers from substituting asserted seed state.
trait NativeCorrectionSeedBackend {
    fn seed_lane(
        &mut self,
        request: &NativeCorrectionSeedRequest,
    ) -> NativeCorrectionResult<NativeCorrectionSeedOutcome>;
}

/// Exact-binary, provider-free implementation of the deterministic seed control plane.
///
/// Each call starts one fresh full-profile Engram stdio process against the caller-supplied
/// isolated home/partition, derives every receipt field from JSON-RPC results, closes the proxy,
/// and stops that exact partition daemon before returning. Provider executables and credential
/// files are never consulted.
#[derive(Debug, Clone)]
struct NativeCorrectionStdioSeedBackend {
    engram: PathBuf,
    full_profile_handshake_sha256: String,
    timeout: Duration,
}

impl NativeCorrectionStdioSeedBackend {
    pub fn new(runtime: &NativeCorrectionRuntimeAttestation) -> NativeCorrectionResult<Self> {
        validate_native_correction_runtime(runtime)?;
        let engram = PathBuf::from(
            &runtime
                .binaries
                .get("engram")
                .ok_or_else(|| {
                    NativeCorrectionError::Invalid("runtime omitted Engram binary".to_string())
                })?
                .path,
        );
        Ok(Self {
            engram,
            full_profile_handshake_sha256: sha256_json(&runtime.full_profile)?,
            timeout: Duration::from_millis(RUNTIME_PROBE_TIMEOUT_MS),
        })
    }
}

impl NativeCorrectionSeedBackend for NativeCorrectionStdioSeedBackend {
    fn seed_lane(
        &mut self,
        request: &NativeCorrectionSeedRequest,
    ) -> NativeCorrectionResult<NativeCorrectionSeedOutcome> {
        if request.schema_version != 1
            || request.project_name != "atlas"
            || request.repository_remote != "git@github.com:acme/atlas.git"
            || !Path::new(&request.engram_home).is_dir()
        {
            return invalid("stdio seed request identity or filesystem boundary drifted");
        }
        let home = Path::new(&request.engram_home);
        let mut session = start_native_correction_stdio_session(
            &self.engram,
            home,
            &request.opaque_partition,
            self.timeout,
        )?;
        let seeded = seed_native_correction_stdio(&mut session, request);
        let finished = session
            .finish()
            .and_then(|finish| finish.require_daemon_stop("seed session"));
        let (derived, (transcript, stderr, _), ()) = combine_native_correction_three(
            seeded,
            finished,
            Ok(()),
            [
                "seed-state observation",
                "seed stdio finish",
                "seed terminal gate",
            ],
        )?;
        if !stderr.is_empty() {
            return invalid("Engram seed stdio proxy emitted stderr");
        }
        let receipt = NativeCorrectionSeedReceipt {
            schema_version: 1,
            host: request.host,
            request_sha256: sha256_json(request)?,
            full_profile_handshake_sha256: self.full_profile_handshake_sha256.clone(),
            fresh_process: true,
            daemon_stopped: true,
            identity: derived.identity,
            old: derived.old,
            other_scope: derived.other_scope,
            active_atlas_ids: derived.active_atlas_ids,
            active_orbit_ids: derived.active_orbit_ids,
            all_memory_ids: derived.all_memory_ids,
            replacement_count: derived.replacement_count,
            proposal_count: derived.proposal_count,
            projection_commit_id: derived.projection_commit_id,
            projection_trace_id: derived.projection_trace_id,
            projection_feedback_id: derived.projection_feedback_id,
            stdio_call_count: derived.stdio_call_count,
            stdio_transcript_sha256: format!("{:x}", Sha256::digest(&transcript)),
            stdio_transcript_bytes: transcript.len() as u64,
            stdio_stderr_sha256: format!("{:x}", Sha256::digest(&stderr)),
            stdio_stderr_bytes: stderr.len() as u64,
            reviewer_authority_conferred: false,
            intent_verified: false,
            scope_selector_authenticated: false,
        };
        Ok(NativeCorrectionSeedOutcome {
            receipt,
            transcript,
            stderr,
        })
    }
}

#[derive(Debug)]
struct DerivedNativeCorrectionSeed {
    identity: NativeCorrectionIdentitySnapshot,
    old: NativeCorrectionMemorySnapshot,
    other_scope: NativeCorrectionMemorySnapshot,
    active_atlas_ids: Vec<String>,
    active_orbit_ids: Vec<String>,
    all_memory_ids: Vec<String>,
    replacement_count: u32,
    proposal_count: u32,
    projection_commit_id: String,
    projection_trace_id: String,
    projection_feedback_id: String,
    stdio_call_count: u32,
}

fn seed_native_correction_stdio(
    session: &mut NativeCorrectionStdioSession,
    request: &NativeCorrectionSeedRequest,
) -> NativeCorrectionResult<DerivedNativeCorrectionSeed> {
    let initialize = session.initialize()?;
    if initialize
        .pointer("/result/protocolVersion")
        .and_then(Value::as_str)
        != Some(NATIVE_CORRECTION_MCP_PROTOCOL)
    {
        return invalid("Engram seed handshake protocol drifted");
    }
    let tools = session.tools_list()?;
    let tool_values = tools
        .pointer("/result/tools")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("Engram seed tools/list omitted tools".to_string())
        })?;
    if sorted_json_array_sha256(tool_values)? != EXPECTED_FULL_TOOLS_SHA256 {
        return invalid("Engram seed full-profile tools drifted");
    }

    let atlas_project = exact_mcp_content(
        session.tool_call(
            "work_project",
            json!({"action":"create","name":"atlas","description":"native correction fixture"}),
        )?,
        "create Atlas project",
    )?;
    let orbit_project = exact_mcp_content(
        session.tool_call(
            "work_project",
            json!({"action":"create","name":"orbit","description":"native correction scope canary"}),
        )?,
        "create Orbit project",
    )?;
    if atlas_project.get("name").and_then(Value::as_str) != Some("atlas")
        || atlas_project.get("status").and_then(Value::as_str) != Some("active")
        || orbit_project.get("name").and_then(Value::as_str) != Some("orbit")
        || orbit_project.get("status").and_then(Value::as_str) != Some("active")
    {
        return invalid("Engram seed project creation results drifted");
    }

    let detection = exact_mcp_content(
        session.tool_call("repo", json!({"action":"detect","cwd":request.orient_cwd}))?,
        "detect Atlas checkout",
    )?;
    let repository = detection
        .pointer("/detection/context/repository")
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "Engram repository detection omitted repository".to_string(),
            )
        })?;
    let repository_id = required_json_string(repository, "id", "detected repository")?;
    let detected_checkout_id = required_json_pointer_string(
        &detection,
        "/detection/context/checkout/id",
        "detected checkout ID",
    )?;
    let detected_head_sha = required_json_pointer_string(
        &detection,
        "/detection/context/checkout/head_sha",
        "detected checkout HEAD",
    )?;
    if repository.get("remote_url").and_then(Value::as_str)
        != Some(request.repository_remote.as_str())
        || detection
            .pointer("/detection/context/checkout/repository_id")
            .and_then(Value::as_str)
            != Some(repository_id.as_str())
        || detection
            .pointer("/detection/context/checkout/local_path")
            .and_then(Value::as_str)
            != Some(request.orient_cwd.as_str())
    {
        return invalid("Engram seed repository detection did not bind the fixture checkout");
    }
    let link = exact_mcp_content(
        session.tool_call(
            "repo",
            json!({
                "action":"link_project",
                "repository_id":repository_id,
                "project_name":"atlas",
                "role":"primary"
            }),
        )?,
        "link Atlas project",
    )?;
    if link.pointer("/link/project_name").and_then(Value::as_str) != Some("atlas")
        || link.pointer("/link/repository_id").and_then(Value::as_str)
            != Some(repository_id.as_str())
    {
        return invalid("Engram seed project/repository link drifted");
    }

    let old_candidate_value = exact_mcp_content(
        session.tool_call(
            "memory",
            seed_procedure_arguments(
                "atlas",
                &request.old_title,
                &request.old_content,
                &request.tag,
            ),
        )?,
        "seed Atlas memory",
    )?;
    let old_candidate_id = required_json_pointer_string(
        &old_candidate_value,
        "/item/id",
        "Atlas procedure candidate ID",
    )?;
    let old_value = exact_mcp_content(
        session.tool_call(
            "memory",
            json!({
                "action":"promote",
                "id":old_candidate_id,
                "reviewer":"engram-eval-seed",
                "rationale":"Activate the isolated obsolete procedure fixture; this label is not verified reviewer authority."
            }),
        )?,
        "activate Atlas procedure fixture",
    )?;
    let other_value = exact_mcp_content(
        session.tool_call(
            "memory",
            seed_decision_arguments(
                "orbit",
                &request.other_title,
                &request.other_content,
                &request.tag,
                &old_candidate_id,
            ),
        )?,
        "seed Orbit memory",
    )?;
    let old_item = parse_exact_domain(
        old_value
            .get("item")
            .ok_or_else(|| NativeCorrectionError::Invalid("Atlas add omitted item".to_string()))?,
        "Atlas seed memory",
    )?;
    let other_item = parse_exact_domain(
        other_value
            .get("item")
            .ok_or_else(|| NativeCorrectionError::Invalid("Orbit add omitted item".to_string()))?,
        "Orbit seed memory",
    )?;
    let projection_commit = exact_mcp_content(
        session.tool_call("memory", seed_projection_commit_arguments(&old_item))?,
        "seed cleanup knowledge-commit projection",
    )?;
    let projection_commit_id = required_json_pointer_string(
        &projection_commit,
        "/commit/id",
        "cleanup projection commit ID",
    )?;
    let projection_trace = exact_mcp_content(
        session.tool_call("telemetry", seed_projection_trace_arguments(&old_item))?,
        "seed cleanup retrieval-trace projection",
    )?;
    let projection_trace_id = required_json_pointer_string(
        &projection_trace,
        "/trace/id",
        "cleanup projection trace ID",
    )?;
    let projection_feedback = exact_mcp_content(
        session.tool_call(
            "telemetry",
            seed_projection_feedback_arguments(&old_item, &projection_trace_id),
        )?,
        "seed cleanup feedback projection",
    )?;
    let projection_feedback_id = required_json_pointer_string(
        &projection_feedback,
        "/feedback/id",
        "cleanup projection feedback ID",
    )?;

    let orient = exact_mcp_content(
        session.tool_call(
            "orient",
            json!({
                "project":"atlas",
                "cwd":request.orient_cwd,
                "agent":"engram_eval",
                "response_shape":"lean"
            }),
        )?,
        "orient Atlas fixture",
    )?;
    let identity = NativeCorrectionIdentitySnapshot {
        repository_id: required_json_pointer_string(
            &orient,
            "/identity/repository/repository_id",
            "orientation repository ID",
        )?,
        normalized_remote: required_json_pointer_string(
            &orient,
            "/identity/repository/normalized_remote",
            "orientation normalized remote",
        )?,
        checkout_id: required_json_pointer_string(
            &orient,
            "/identity/repository/checkout_id",
            "orientation checkout ID",
        )?,
        checkout_root: required_json_pointer_string(
            &orient,
            "/identity/repository/checkout_root",
            "orientation checkout root",
        )?,
        head_sha: required_json_pointer_string(
            &orient,
            "/identity/repository/head_sha",
            "orientation checkout HEAD",
        )?,
        project_name: required_json_pointer_string(
            &orient,
            "/identity/project/name",
            "orientation project name",
        )?,
        project_status: required_json_pointer_string(
            &orient,
            "/identity/project/status",
            "orientation project status",
        )?,
        resolution_source: required_json_pointer_string(
            &orient,
            "/resolution/source",
            "orientation resolution source",
        )?,
        // The explicit-project orientation source deliberately does not expose repository-link
        // IDs. The preceding exact `repo(link_project)` result is the source of this fact.
        project_linked: true,
        requires_confirmation: orient
            .pointer("/resolution/requires_confirmation")
            .and_then(Value::as_bool)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "orientation omitted confirmation status".to_string(),
                )
            })?,
    };
    if identity.repository_id != repository_id
        || identity.checkout_id != detected_checkout_id
        || identity.head_sha != detected_head_sha
    {
        return invalid("orientation identity did not match the exact detected fixture checkout");
    }
    let old_snapshot = native_correction_memory_snapshot(&old_item, None)?;
    validate_exact_lean_orient_shape(
        &orient,
        &request.project_name,
        &request.orient_cwd,
        "engram_eval",
        &identity,
        &old_snapshot,
    )?;

    let atlas_list = exact_mcp_content(
        session.tool_call(
            "memory",
            exact_memory_list_arguments("atlas", request, "active"),
        )?,
        "list Atlas memory",
    )?;
    let orbit_list = exact_mcp_content(
        session.tool_call(
            "memory",
            exact_memory_list_arguments("orbit", request, "active"),
        )?,
        "list Orbit memory",
    )?;
    let all_list = exact_mcp_content(
        session.tool_call(
            "memory",
            json!({
                "action":"list",
                "status_filter":"active",
                "tags":[request.tag],
                "limit":3,
                "scope":{"relevance_mode":"global"}
            }),
        )?,
        "list all seeded memory",
    )?;
    let replacement_list = exact_mcp_content(
        session.tool_call(
            "memory",
            exact_memory_list_arguments("atlas", request, "needs_review"),
        )?,
        "list inactive replacements",
    )?;
    let proposals = exact_mcp_content(
        session.tool_call(
            "memory",
            json!({
                "action":"list_correction_proposals",
                "limit":2,
                "scope":exact_local_scope_value("atlas", &request.orient_cwd)
            }),
        )?,
        "list seed correction proposals",
    )?;
    if !validate_normal_scope_result_shape(&atlas_list, &["count", "items"], "atlas")
        || !validate_normal_scope_result_shape(&orbit_list, &["count", "items"], "orbit")
        || !validate_global_memory_result_shape(&all_list, &["count", "items"])
        || !validate_normal_scope_result_shape(&replacement_list, &["count", "items"], "atlas")
        || !validate_selector_result_shape(&proposals, &["count", "proposals"], "atlas")
    {
        return invalid("seed list scope wrapper drifted");
    }
    require_exact_empty_collection(&replacement_list, "items", "replacement list")?;
    require_exact_empty_collection(&proposals, "proposals", "proposal list")?;

    Ok(DerivedNativeCorrectionSeed {
        identity,
        old: old_snapshot,
        other_scope: native_correction_memory_snapshot(&other_item, None)?,
        active_atlas_ids: exact_memory_ids(&atlas_list, 1, "Atlas active list")?,
        active_orbit_ids: exact_memory_ids(&orbit_list, 1, "Orbit active list")?,
        all_memory_ids: exact_memory_ids(&all_list, 2, "global active list")?,
        replacement_count: 0,
        proposal_count: 0,
        projection_commit_id,
        projection_trace_id,
        projection_feedback_id,
        // initialize/tools-list are protocol calls; this counts the sixteen full-profile tools/call
        // observations above, all of which are preserved in the transcript digest.
        stdio_call_count: 16,
    })
}

fn seed_procedure_arguments(project: &str, title: &str, content: &str, tag: &str) -> Value {
    json!({
        "action":"add",
        "kind":"procedure",
        "title":title,
        "content":content,
        "origin":"tool_result",
        "status":"active",
        "confidence":1.0,
        "tags":[tag],
        "scope_type":"project",
        "project_name":project,
        "writer_harness":"custom",
        "model_provider":"engram_eval",
        "model":"provider_free_seed",
        "actor":"importer"
        ,"evidence":[{"kind":"tool_call","target":"engram-eval:provider-free-seed"}],
        "procedure":{
            "task":"Configure the queue worker using Redis Streams",
            "commands":["configure queue.backend=redis_streams"],
            "prerequisites":{},
            "prerequisite_sources":{},
            "failure_signatures":["NATS JetStream unavailable"],
            "verification_command":"/usr/bin/true",
            "verification_exit_code":0,
            "verification_output_contains":"obsolete fixture"
        }
    })
}

fn seed_decision_arguments(
    project: &str,
    title: &str,
    content: &str,
    tag: &str,
    referenced_memory_id: &str,
) -> Value {
    json!({
        "action":"add",
        "kind":"decision",
        "title":title,
        "content":content,
        "origin":"tool_result",
        "status":"active",
        "confidence":1.0,
        "tags":[tag],
        "scope_type":"project",
        "project_name":project,
        "writer_harness":"custom",
        "model_provider":"engram_eval",
        "model":"provider_free_seed",
        "actor":"importer",
        "evidence":[
            {"kind":"tool_call","target":"engram-eval:provider-free-seed"},
            {"kind":"observation","target":referenced_memory_id,"summary":"Synthetic graph projection for exact forget validation"}
        ]
    })
}

fn seed_projection_commit_arguments(item: &MemoryItem) -> Value {
    json!({
        "action":"commit",
        "message":"native-correction cleanup projection seed",
        "writer_harness":"custom",
        "model_provider":"engram_eval",
        "model":"provider_free_seed",
        "actor":"importer",
        "changes":[{
            "change_type":"added",
            "item_id":item.id.to_string(),
            "title":"Native correction cleanup projection",
            "summary":"Synthetic exact-ID projection exercised for irreversible cleanup validation"
        }]
    })
}

fn seed_projection_trace_arguments(item: &MemoryItem) -> Value {
    json!({
        "action":"record_trace",
        "operation":"search",
        "intent":"review_memory",
        "scenario_id":"native-correction-cleanup-projection",
        "arm":"provider-free",
        "query":"synthetic cleanup projection",
        "project":"atlas",
        "agent":"engram_eval",
        "returned_memory_ids":[item.id.to_string()],
        "latency_ms":1
    })
}

fn seed_projection_feedback_arguments(item: &MemoryItem, trace_id: &str) -> Value {
    json!({
        "action":"submit_feedback",
        "trace_id":trace_id,
        "agent":"engram_eval",
        "used_memory_ids":[item.id.to_string()],
        "task_success":true
    })
}

fn obsolete_seed_procedure() -> ProcedureCard {
    ProcedureCard::new(
        "Configure the queue worker using Redis Streams",
        vec!["configure queue.backend=redis_streams".to_string()],
        ProcedureVerification::new("/usr/bin/true", 0, "obsolete fixture"),
    )
    .with_failure_signature("NATS JetStream unavailable")
}

fn expected_replacement_procedure() -> ProcedureCard {
    ProcedureCard::new(
        EXPECTED_PROCEDURE_TASK,
        vec![EXPECTED_PROCEDURE_COMMAND.to_string()],
        ProcedureVerification::new(EXPECTED_PROCEDURE_COMMAND, 0, EXPECTED_PROCEDURE_OUTPUT),
    )
    .with_failure_signature(EXPECTED_PROCEDURE_FAILURE)
}

fn replacement_procedure_arguments() -> Value {
    json!({
        "task":EXPECTED_PROCEDURE_TASK,
        "commands":[EXPECTED_PROCEDURE_COMMAND],
        "prerequisites":{},
        "prerequisite_sources":{},
        "failure_signatures":[EXPECTED_PROCEDURE_FAILURE],
        "verification_command":EXPECTED_PROCEDURE_COMMAND,
        "verification_exit_code":0,
        "verification_output_contains":EXPECTED_PROCEDURE_OUTPUT
    })
}

fn exact_memory_list_arguments(
    project: &str,
    request: &NativeCorrectionSeedRequest,
    status: &str,
) -> Value {
    json!({
        "action":"list",
        "status_filter":status,
        "tags":[request.tag],
        "limit":2,
        "scope":exact_local_scope_value(project, &request.orient_cwd)
    })
}

fn exact_local_scope_value(project: &str, cwd: &str) -> Value {
    json!({"relevance_mode":"local","project":project,"cwd":cwd})
}

fn exact_mcp_content(
    response: NativeCorrectionMcpResponse,
    label: &str,
) -> NativeCorrectionResult<Value> {
    response.content.ok_or_else(|| {
        NativeCorrectionError::Invalid(format!(
            "Engram {label} returned an MCP error: {}",
            response.raw
        ))
    })
}

fn required_json_string(value: &Value, key: &str, label: &str) -> NativeCorrectionResult<String> {
    value
        .get(key)
        .and_then(Value::as_str)
        .map(ToOwned::to_owned)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(format!("{label} omitted string field {key}"))
        })
}

fn required_json_pointer_string(
    value: &Value,
    pointer: &str,
    label: &str,
) -> NativeCorrectionResult<String> {
    value
        .pointer(pointer)
        .and_then(Value::as_str)
        .map(ToOwned::to_owned)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} was absent")))
}

fn optional_json_string(
    value: &Value,
    key: &str,
    label: &str,
) -> NativeCorrectionResult<Option<String>> {
    match value.get(key) {
        Some(Value::Null) | None => Ok(None),
        Some(Value::String(value)) => Ok(Some(value.clone())),
        Some(_) => invalid(format!("{label} field {key} was not a string or null")),
    }
}

fn parse_exact_domain<T>(value: &Value, label: &str) -> NativeCorrectionResult<T>
where
    T: DeserializeOwned + Serialize,
{
    let parsed: T = serde_json::from_value(value.clone())?;
    if serde_json::to_value(&parsed)? != *value {
        return invalid(format!(
            "{label} contained unknown, omitted, or non-canonical domain fields"
        ));
    }
    Ok(parsed)
}

fn exact_json_count(value: &Value, label: &str) -> NativeCorrectionResult<u32> {
    let count = value
        .get("count")
        .and_then(Value::as_u64)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} omitted count")))?;
    u32::try_from(count)
        .map_err(|_| NativeCorrectionError::Invalid(format!("{label} count overflow")))
}

fn require_exact_empty_collection(
    value: &Value,
    collection: &str,
    label: &str,
) -> NativeCorrectionResult<()> {
    let values = value
        .get(collection)
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} omitted {collection}")))?;
    if exact_json_count(value, label)? != 0 || !values.is_empty() {
        return invalid(format!(
            "{label} must have count zero and an empty {collection} array"
        ));
    }
    Ok(())
}

fn exact_memory_ids(
    value: &Value,
    expected_count: usize,
    label: &str,
) -> NativeCorrectionResult<Vec<String>> {
    let items = value
        .get("items")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} omitted items")))?;
    if exact_json_count(value, label)? as usize != expected_count || items.len() != expected_count {
        return invalid(format!(
            "{label} did not contain exactly {expected_count} items: {value}"
        ));
    }
    items
        .iter()
        .map(|item| required_json_string(item, "id", label))
        .collect()
}

