fn operator_verification_arguments(
    lane: &PreparedNativeCorrectionLane,
    proposal_id: &str,
    p0_digest: &str,
) -> Value {
    json!({
        "action":"verify_correction_procedure",
        "proposal_id":proposal_id,
        "expected_digest":p0_digest,
        "receipt":lane.procedure_verification_receipt,
        "expires_at":lane.procedure_verification_expires_at,
        "scope":exact_local_scope_value("atlas", &lane.cwd)
    })
}

fn persist_native_correction_operator_verification_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
    process_id: u32,
    prepared: &NativeCorrectionPreparedRequest,
) -> NativeCorrectionResult<NativeCorrectionOperatorVerificationDispatchJournal> {
    let path = Path::new(&lane.operator_verification_dispatch);
    let digest_path = receipt_digest_path(path);
    if path_entry_exists(path) || path_entry_exists(&digest_path) {
        return invalid("refusing to overwrite or replay a procedure-verification dispatch");
    }
    let request_json_line = String::from_utf8(prepared.json_line.clone()).map_err(|_| {
        NativeCorrectionError::Invalid(
            "operator procedure-verification request was not UTF-8".to_string(),
        )
    })?;
    let journal = NativeCorrectionOperatorVerificationDispatchJournal {
        schema_version: 1,
        family: NATIVE_CORRECTION_FAMILY.to_string(),
        pilot_id: plan.pilot_id.clone(),
        run_plan: intent.run_plan.clone(),
        run_plan_sha256: intent.run_plan_sha256.clone(),
        lane_order: lane.order,
        host: lane.host,
        operator_intent_sha256: sha256_file(Path::new(&lane.operator_intent))?,
        proposal_id: intent.proposal.proposal_id.clone(),
        p0_digest: intent.proposal.canonical_digest.clone(),
        receipt_path: lane.procedure_verification_receipt.clone(),
        receipt_sha256: lane.procedure_verification_receipt_sha256.clone(),
        expires_at: lane.procedure_verification_expires_at.clone(),
        process_id,
        jsonrpc_id: prepared.id,
        request_sha256: format!("{:x}", Sha256::digest(&prepared.json_line)),
        request_bytes: prepared.json_line.len() as u64,
        request_json_line,
        created_unix_ms: unix_ms(SystemTime::now())?,
    };
    validate_native_correction_operator_verification_dispatch(plan, lane, intent, &journal, true)?;
    write_private_json(path, &journal)?;
    write_private_text(&digest_path, &(sha256_file(path)? + "\n"))?;
    validate_receipt_digest(path)?;
    Ok(journal)
}

fn validate_native_correction_operator_verification_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
    journal: &NativeCorrectionOperatorVerificationDispatchJournal,
    require_current_unexpired: bool,
) -> NativeCorrectionResult<()> {
    let request_bytes = journal.request_json_line.as_bytes();
    let request: Value =
        strict_json_value_from_slice(request_bytes.strip_suffix(b"\n").ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "operator procedure-verification dispatch omitted one terminal newline".to_string(),
            )
        })?)?;
    let expected_request = json!({
        "jsonrpc":"2.0",
        "id":journal.jsonrpc_id,
        "method":"tools/call",
        "params":{
            "name":"memory",
            "arguments":operator_verification_arguments(
                lane,
                &intent.proposal.proposal_id,
                &intent.proposal.canonical_digest,
            )
        }
    });
    let expected_plan = Path::new(&plan.protocol)
        .with_file_name("run-plan.json")
        .canonicalize()?;
    let (observed_plan, observed_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            &expected_plan,
            &expected_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "operator verification-dispatch run plan",
        )?;
    let intent_path = Path::new(&lane.operator_intent);
    let (observed_intent, observed_intent_sha256): (NativeCorrectionOperatorIntent, _) =
        read_digest_bound_strict_json(
            intent_path,
            &receipt_digest_path(intent_path),
            1024 * 1024,
            "operator verification-dispatch intent",
        )?;
    let receipt_bytes = read_bounded_attested_file(
        Path::new(&lane.procedure_verification_receipt),
        64 * 1024,
        "operator procedure-verification receipt",
    )?;
    let receipt: ProcedureVerificationReceipt = strict_json_from_slice(&receipt_bytes)?;
    let expires_at = OffsetDateTime::parse(&journal.expires_at, &Rfc3339).map_err(|error| {
        NativeCorrectionError::Invalid(format!(
            "operator procedure-verification expiry was not RFC3339: {error}"
        ))
    })?;
    let created_at =
        OffsetDateTime::from_unix_timestamp_nanos(i128::from(journal.created_unix_ms) * 1_000_000)
            .map_err(|error| {
                NativeCorrectionError::Invalid(format!(
                    "operator procedure-verification dispatch timestamp was invalid: {error}"
                ))
            })?;
    if journal.schema_version != 1
        || journal.family != NATIVE_CORRECTION_FAMILY
        || journal.pilot_id != plan.pilot_id
        || Path::new(&journal.run_plan) != expected_plan
        || observed_plan != *plan
        || journal.run_plan_sha256 != observed_plan_sha256
        || journal.lane_order != lane.order
        || journal.host != lane.host
        || observed_intent != *intent
        || journal.operator_intent_sha256 != observed_intent_sha256
        || journal.proposal_id != intent.proposal.proposal_id
        || journal.p0_digest != intent.proposal.canonical_digest
        || journal.receipt_path != lane.procedure_verification_receipt
        || journal.receipt_sha256 != lane.procedure_verification_receipt_sha256
        || journal.receipt_sha256 != format!("{:x}", Sha256::digest(&receipt_bytes))
        || receipt.command != EXPECTED_PROCEDURE_COMMAND
        || receipt.exit_code != 0
        || !receipt.output.contains(EXPECTED_PROCEDURE_OUTPUT)
        || !receipt.conditions.is_empty()
        || expires_at <= created_at
        || require_current_unexpired && expires_at <= OffsetDateTime::now_utc()
        || journal.expires_at != lane.procedure_verification_expires_at
        || journal.process_id == 0
        || journal.jsonrpc_id == 0
        || journal.request_bytes != request_bytes.len() as u64
        || journal.request_sha256 != format!("{:x}", Sha256::digest(request_bytes))
        || request != expected_request
        || journal.created_unix_ms < intent.created_unix_ms
    {
        return invalid(
            "operator procedure-verification dispatch lost its exact P0/receipt/expiry binding",
        );
    }
    Ok(())
}

#[cfg(test)]
fn load_native_correction_operator_verification_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
) -> NativeCorrectionResult<NativeCorrectionOperatorVerificationDispatchJournal> {
    let path = Path::new(&lane.operator_verification_dispatch);
    if receipt_presence(path) != ArtifactPresence::Complete {
        return invalid("operator procedure verification requires a complete dispatch journal");
    }
    let (journal, _): (NativeCorrectionOperatorVerificationDispatchJournal, _) =
        read_digest_bound_strict_json(
            path,
            &receipt_digest_path(path),
            1024 * 1024,
            "operator verification dispatch journal",
        )?;
    validate_native_correction_operator_verification_dispatch(plan, lane, intent, &journal, true)?;
    Ok(journal)
}

/// Durably records the exact pending tuple selected for the operator transition. This is written
/// with create-new semantics before any `apply_correction` request can be sent.
pub fn create_native_correction_operator_intent(
    run_plan: &Path,
    lane_order: u32,
) -> NativeCorrectionResult<NativeCorrectionOperatorIntent> {
    let (plan, plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_operator_turn(&plan, lane_order)?;
    let intent_path = Path::new(&lane.operator_intent);
    let digest_path = receipt_digest_path(intent_path);
    if path_entry_exists(intent_path) || path_entry_exists(&digest_path) {
        return invalid("refusing to overwrite or replay an operator intent");
    }
    let (proposal_receipt, proposal_receipt_sha256) =
        read_and_validate_provider_receipt_with_digest(
            &plan,
            lane,
            NativeCorrectionProviderPhase::Proposal,
        )?;
    let evidence: NativeCorrectionProposalEvidence =
        serde_json::from_value(proposal_receipt.normalized_evidence.clone())?;
    validate_native_correction_proposal_evidence(&protocol, lane, &evidence)?;
    let created_unix_ms = unix_ms(SystemTime::now())?;
    if created_unix_ms < proposal_receipt.completed_unix_ms {
        return invalid("operator intent predates proposal completion");
    }
    let intent = NativeCorrectionOperatorIntent {
        schema_version: 1,
        family: NATIVE_CORRECTION_FAMILY.to_string(),
        pilot_id: plan.pilot_id.clone(),
        run_plan: run_plan.canonicalize()?.display().to_string(),
        run_plan_sha256: plan_sha256,
        protocol_sha256: plan.protocol_sha256.clone(),
        lane_order,
        host: lane.host,
        proposal_receipt_sha256,
        proposal_evidence_sha256: proposal_receipt.normalized_evidence_sha256,
        proposal: evidence.proposal,
        old: evidence.old,
        replacement: evidence.replacement,
        created_unix_ms,
    };
    validate_native_correction_operator_intent(&plan, lane, &intent)?;
    write_private_json(intent_path, &intent)?;
    write_private_text(&digest_path, &(sha256_file(intent_path)? + "\n"))?;
    Ok(intent)
}

pub fn validate_native_correction_operator_intent(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
) -> NativeCorrectionResult<()> {
    let (proposal_receipt, proposal_receipt_sha256) =
        read_and_validate_provider_receipt_with_digest(
            plan,
            lane,
            NativeCorrectionProviderPhase::Proposal,
        )?;
    let evidence: NativeCorrectionProposalEvidence =
        serde_json::from_value(proposal_receipt.normalized_evidence.clone())?;
    let expected_run_plan = Path::new(&plan.protocol)
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("protocol has no parent".to_string()))?
        .join("run-plan.json")
        .canonicalize()?;
    let (observed_plan, observed_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            &expected_run_plan,
            &expected_run_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "operator-intent run plan",
        )?;
    if intent.schema_version != 1
        || intent.family != NATIVE_CORRECTION_FAMILY
        || intent.pilot_id != plan.pilot_id
        || intent.run_plan != expected_run_plan.display().to_string()
        || observed_plan != *plan
        || intent.run_plan_sha256 != observed_plan_sha256
        || intent.protocol_sha256 != plan.protocol_sha256
        || intent.lane_order != lane.order
        || intent.host != lane.host
        || intent.proposal_receipt_sha256 != proposal_receipt_sha256
        || intent.proposal_evidence_sha256 != proposal_receipt.normalized_evidence_sha256
        || intent.proposal != evidence.proposal
        || intent.old != evidence.old
        || intent.replacement != evidence.replacement
        || intent.created_unix_ms < proposal_receipt.completed_unix_ms
        || intent.proposal.status != "pending"
        || intent.old.status != NativeCorrectionMemoryStatus::Active
        || intent.replacement.status != NativeCorrectionMemoryStatus::NeedsReview
    {
        return invalid("operator intent lost its exact pending proposal binding");
    }
    Ok(())
}

fn load_or_create_native_correction_operator_intent(
    run_plan: &Path,
    lane_order: u32,
) -> NativeCorrectionResult<NativeCorrectionOperatorIntent> {
    let (plan, _, _) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    let path = Path::new(&lane.operator_intent);
    match receipt_presence(path) {
        ArtifactPresence::Absent => create_native_correction_operator_intent(run_plan, lane_order),
        ArtifactPresence::Partial => invalid("operator intent or its digest is orphaned"),
        ArtifactPresence::Complete => {
            let (intent, _): (NativeCorrectionOperatorIntent, _) = read_digest_bound_strict_json(
                path,
                &receipt_digest_path(path),
                1024 * 1024,
                "operator intent",
            )?;
            validate_native_correction_operator_intent(&plan, lane, &intent)?;
            Ok(intent)
        }
    }
}

fn persist_native_correction_operator_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
    p1_digest: &str,
    process_id: u32,
    prepared: &NativeCorrectionPreparedRequest,
) -> NativeCorrectionResult<NativeCorrectionOperatorDispatchJournal> {
    let path = Path::new(&lane.operator_dispatch);
    let digest_path = receipt_digest_path(path);
    if path_entry_exists(path) || path_entry_exists(&digest_path) {
        return invalid("refusing to overwrite an operator apply-dispatch journal");
    }
    let request_json_line = String::from_utf8(prepared.json_line.clone()).map_err(|_| {
        NativeCorrectionError::Invalid("operator apply request was not UTF-8".to_string())
    })?;
    let journal = NativeCorrectionOperatorDispatchJournal {
        schema_version: 1,
        family: NATIVE_CORRECTION_FAMILY.to_string(),
        pilot_id: plan.pilot_id.clone(),
        run_plan: intent.run_plan.clone(),
        run_plan_sha256: intent.run_plan_sha256.clone(),
        lane_order: lane.order,
        host: lane.host,
        operator_intent_sha256: sha256_file(Path::new(&lane.operator_intent))?,
        proposal_id: intent.proposal.proposal_id.clone(),
        canonical_digest: p1_digest.to_string(),
        process_id,
        jsonrpc_id: prepared.id,
        request_sha256: format!("{:x}", Sha256::digest(&prepared.json_line)),
        request_bytes: prepared.json_line.len() as u64,
        request_json_line,
        created_unix_ms: unix_ms(SystemTime::now())?,
    };
    validate_native_correction_operator_dispatch(plan, lane, intent, p1_digest, &journal)?;
    write_private_json(path, &journal)?;
    write_private_text(&digest_path, &(sha256_file(path)? + "\n"))?;
    validate_receipt_digest(path)?;
    Ok(journal)
}

fn validate_native_correction_operator_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
    p1_digest: &str,
    journal: &NativeCorrectionOperatorDispatchJournal,
) -> NativeCorrectionResult<()> {
    let request_bytes = journal.request_json_line.as_bytes();
    let request: Value =
        strict_json_value_from_slice(request_bytes.strip_suffix(b"\n").ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "operator dispatch request omitted one terminal newline".to_string(),
            )
        })?)?;
    let expected_arguments = json!({
        "action":"apply_correction",
        "proposal_id":intent.proposal.proposal_id,
        "expected_digest":p1_digest,
        "scope":exact_local_scope_value("atlas", &lane.cwd)
    });
    let expected_request = json!({
        "jsonrpc":"2.0",
        "id":journal.jsonrpc_id,
        "method":"tools/call",
        "params":{"name":"memory","arguments":expected_arguments}
    });
    let expected_plan = Path::new(&plan.protocol)
        .with_file_name("run-plan.json")
        .canonicalize()?;
    let (observed_plan, observed_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            &expected_plan,
            &expected_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "operator-dispatch run plan",
        )?;
    let intent_path = Path::new(&lane.operator_intent);
    let (observed_intent, observed_intent_sha256): (NativeCorrectionOperatorIntent, _) =
        read_digest_bound_strict_json(
            intent_path,
            &receipt_digest_path(intent_path),
            1024 * 1024,
            "operator-dispatch intent",
        )?;
    if journal.schema_version != 1
        || journal.family != NATIVE_CORRECTION_FAMILY
        || journal.pilot_id != plan.pilot_id
        || Path::new(&journal.run_plan) != expected_plan
        || observed_plan != *plan
        || journal.run_plan_sha256 != observed_plan_sha256
        || journal.lane_order != lane.order
        || journal.host != lane.host
        || observed_intent != *intent
        || journal.operator_intent_sha256 != observed_intent_sha256
        || journal.proposal_id != intent.proposal.proposal_id
        || journal.canonical_digest != p1_digest
        || journal.canonical_digest == intent.proposal.canonical_digest
        || journal.process_id == 0
        || journal.jsonrpc_id == 0
        || journal.request_bytes != request_bytes.len() as u64
        || journal.request_sha256 != format!("{:x}", Sha256::digest(request_bytes))
        || request != expected_request
        || journal.created_unix_ms < intent.created_unix_ms
    {
        return invalid("operator dispatch journal lost its exact fsynced apply-request binding");
    }
    Ok(())
}

fn load_native_correction_operator_dispatch(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionOperatorIntent,
    p1_digest: &str,
) -> NativeCorrectionResult<NativeCorrectionOperatorDispatchJournal> {
    let path = Path::new(&lane.operator_dispatch);
    if receipt_presence(path) != ArtifactPresence::Complete {
        return invalid("operator applied-state recovery requires a complete dispatch journal");
    }
    let (journal, _): (NativeCorrectionOperatorDispatchJournal, _) = read_digest_bound_strict_json(
        path,
        &receipt_digest_path(path),
        1024 * 1024,
        "operator dispatch journal",
    )?;
    validate_native_correction_operator_dispatch(plan, lane, intent, p1_digest, &journal)?;
    Ok(journal)
}

