fn exact_claude_model_usage(value: &Value) -> bool {
    exact_object_keys(
        value,
        &[
            "inputTokens",
            "outputTokens",
            "cacheReadInputTokens",
            "cacheCreationInputTokens",
            "webSearchRequests",
            "costUSD",
            "contextWindow",
            "maxOutputTokens",
            "thinkingTokens",
            "canonicalModel",
            "provider",
            "costBasis",
        ],
    ) && [
        "inputTokens",
        "outputTokens",
        "cacheReadInputTokens",
        "cacheCreationInputTokens",
        "webSearchRequests",
        "contextWindow",
        "maxOutputTokens",
        "thinkingTokens",
    ]
    .iter()
    .all(|key| value.get(*key).is_some_and(Value::is_u64))
        && value.get("webSearchRequests").and_then(Value::as_u64) == Some(0)
        && value.get("costUSD").is_some_and(Value::is_f64)
        && value.get("canonicalModel").and_then(Value::as_str)
            == Some(EXPECTED_CLAUDE_CANONICAL_MODEL)
        && value.get("provider").and_then(Value::as_str) == Some("firstParty")
        && value.get("costBasis").and_then(Value::as_str) == Some("list")
}

fn validate_claude_terminal_envelope(
    result: &Value,
    protocol: &NativeCorrectionProtocol,
    session_id: &str,
) -> NativeCorrectionResult<()> {
    if !exact_object_keys(
        result,
        &[
            "type",
            "subtype",
            "is_error",
            "duration_ms",
            "duration_api_ms",
            "num_turns",
            "result",
            "stop_reason",
            "session_id",
            "total_cost_usd",
            "usage",
            "modelUsage",
            "permission_denials",
            "uuid",
            "structured_output",
            "fast_mode_state",
            "fast_mode_disabled_reason",
            "terminal_reason",
            "first_content_frame_ms",
            "ttft_ms",
            "ttft_stream_ms",
            "time_to_request_ms",
            "subagent_stats",
            "queued_turn_count",
            "api_error_status",
        ],
    ) || result.get("type").and_then(Value::as_str) != Some("result")
        || result.get("session_id").and_then(Value::as_str) != Some(session_id)
        || !result
            .get("uuid")
            .and_then(Value::as_str)
            .is_some_and(looks_like_uuid)
        || ![
            "duration_ms",
            "duration_api_ms",
            "first_content_frame_ms",
            "ttft_ms",
            "ttft_stream_ms",
            "time_to_request_ms",
        ]
        .iter()
        .all(|key| result.get(*key).is_some_and(Value::is_u64))
        || result.get("fast_mode_state").and_then(Value::as_str) != Some("off")
        || result
            .get("fast_mode_disabled_reason")
            .and_then(Value::as_str)
            != Some("disabled_by_env")
        || !result.get("usage").is_some_and(exact_claude_terminal_usage)
        || !result
            .get("subagent_stats")
            .is_some_and(exact_claude_subagent_stats)
    {
        return invalid("Claude terminal envelope had unaccounted or contradictory fields");
    }
    let model_usage = result
        .get("modelUsage")
        .and_then(Value::as_object)
        .ok_or_else(|| NativeCorrectionError::Invalid("Claude modelUsage missing".into()))?;
    if model_usage.len() != 1
        || !model_usage
            .get(&protocol.claude.model)
            .is_some_and(exact_claude_model_usage)
    {
        return invalid("Claude modelUsage schema or canonical model drifted");
    }
    Ok(())
}

fn parse_claude_correction_trace(
    protocol: &NativeCorrectionProtocol,
    lane: &PreparedNativeCorrectionLane,
    phase: NativeCorrectionProviderPhase,
    lines: &[Value],
    output: Value,
) -> NativeCorrectionResult<NativeCorrectionParsedTrace> {
    let init = lines
        .first()
        .ok_or_else(|| NativeCorrectionError::Invalid("Claude trace omitted init".to_string()))?;
    if !exact_claude_init_shape(init, protocol, lane, phase) {
        return invalid("Claude init did not prove the exact fresh connected host envelope");
    }
    let process_identity = required_json_string(init, "session_id", "Claude init")?;
    let api_key_source = required_json_string(init, "apiKeySource", "Claude init")?;
    if !looks_like_uuid(&process_identity) {
        return invalid("Claude session identity was not UUID-shaped");
    }
    let mut pending = BTreeMap::<String, (String, Value)>::new();
    let mut all_ids = BTreeSet::new();
    let mut events = Vec::new();
    let mut terminal: Option<Value> = None;
    let mut structured_count = 0u32;
    let mut final_result: Option<&Value> = None;
    for (index, line) in lines.iter().enumerate().skip(1) {
        if terminal.is_some() && line.get("type").and_then(Value::as_str) != Some("result") {
            return invalid("Claude emitted an event after StructuredOutput completion");
        }
        let event_type = line.get("type").and_then(Value::as_str);
        if line.get("session_id").and_then(Value::as_str) != Some(&process_identity) {
            return invalid("Claude event escaped the one direct session");
        }
        if matches!(event_type, Some("assistant" | "user"))
            && line.get("parent_tool_use_id") != Some(&Value::Null)
        {
            return invalid("Claude assistant/user event had a parent tool use");
        }
        if matches!(event_type, Some("system" | "result"))
            && line.get("parent_tool_use_id").is_some()
        {
            return invalid("Claude system/result event unexpectedly had a parent tool use");
        }
        match event_type {
            Some("system") => {
                if line.get("subtype").and_then(Value::as_str) != Some("thinking_tokens")
                    || !exact_object_keys(
                        line,
                        &[
                            "type",
                            "subtype",
                            "estimated_tokens",
                            "estimated_tokens_delta",
                            "session_id",
                            "uuid",
                        ],
                    )
                    || line
                        .get("estimated_tokens")
                        .and_then(Value::as_u64)
                        .is_none()
                    || line
                        .get("estimated_tokens_delta")
                        .and_then(Value::as_u64)
                        .is_none()
                {
                    return invalid("Claude trace contained an unaccounted system event");
                }
            }
            Some("assistant") => {
                validate_claude_assistant_envelope(line, &process_identity)?;
                if terminal.is_some()
                    || line.pointer("/message/role").and_then(Value::as_str) != Some("assistant")
                {
                    return invalid("Claude emitted assistant activity outside the tool phase");
                }
                let content = line
                    .pointer("/message/content")
                    .and_then(Value::as_array)
                    .ok_or_else(|| {
                        NativeCorrectionError::Invalid(
                            "Claude assistant event omitted content".to_string(),
                        )
                    })?;
                for block in content {
                    match block.get("type").and_then(Value::as_str) {
                        Some("thinking")
                            if exact_object_keys(block, &["type", "thinking", "signature"])
                                && block
                                    .get("thinking")
                                    .and_then(Value::as_str)
                                    .is_some_and(|value| !value.is_empty())
                                && block
                                    .get("signature")
                                    .and_then(Value::as_str)
                                    .is_some_and(|value| !value.is_empty()) => {}
                        Some("text") => {
                            return invalid(
                                "Claude emitted assistant prose before StructuredOutput",
                            )
                        }
                        Some("tool_use") => {
                            if !exact_object_keys(block, &["type", "id", "name", "input", "caller"])
                                || !block
                                    .get("caller")
                                    .is_some_and(|caller| exact_object_keys(caller, &["type"]))
                            {
                                return invalid("Claude tool-use block had unaccounted fields");
                            }
                            let id = required_json_string(block, "id", "Claude tool use")?;
                            let name = required_json_string(block, "name", "Claude tool use")?;
                            let input = block.get("input").cloned().ok_or_else(|| {
                                NativeCorrectionError::Invalid(
                                    "Claude tool use omitted input".to_string(),
                                )
                            })?;
                            let allowed = match phase {
                                NativeCorrectionProviderPhase::Proposal => matches!(
                                    name.as_str(),
                                    "mcp__engram__orient"
                                        | "Read"
                                        | "mcp__engram__memory"
                                        | "StructuredOutput"
                                ),
                                NativeCorrectionProviderPhase::Retrieval => matches!(
                                    name.as_str(),
                                    "mcp__engram__orient"
                                        | "mcp__engram__memory"
                                        | "StructuredOutput"
                                ),
                            };
                            if !allowed
                                || block.pointer("/caller/type").and_then(Value::as_str)
                                    != Some("direct")
                            {
                                return invalid(
                                    "Claude attempted a non-direct or unaccounted tool",
                                );
                            }
                            if !all_ids.insert(id.clone())
                                || pending.insert(id, (name, input)).is_some()
                            {
                                return invalid("Claude reused a tool-use ID");
                            }
                        }
                        _ => {
                            return invalid("Claude assistant event contained an unaccounted block")
                        }
                    }
                }
            }
            Some("user") => {
                validate_claude_user_envelope(line, &process_identity)?;
                if terminal.is_some()
                    || line.pointer("/message/role").and_then(Value::as_str) != Some("user")
                {
                    return invalid("Claude emitted user activity outside the tool phase");
                }
                let content = line
                    .pointer("/message/content")
                    .and_then(Value::as_array)
                    .ok_or_else(|| {
                        NativeCorrectionError::Invalid(
                            "Claude user event omitted content".to_string(),
                        )
                    })?;
                if content.len() != 1
                    || content[0].get("type").and_then(Value::as_str) != Some("tool_result")
                {
                    return invalid("Claude user event was not exactly one tool result");
                }
                let block = &content[0];
                if !exact_object_keys(block, &["type", "tool_use_id", "content"]) {
                    return invalid("Claude tool-result block had unaccounted fields");
                }
                let id = required_json_string(block, "tool_use_id", "Claude tool result")?;
                let (name, arguments) = pending.remove(&id).ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "Claude result had no pending tool use".to_string(),
                    )
                })?;
                let top_result = line.get("tool_use_result").cloned().ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "Claude result omitted lossless tool_use_result".to_string(),
                    )
                })?;
                if name == "StructuredOutput" {
                    structured_count = structured_count.checked_add(1).ok_or_else(|| {
                        NativeCorrectionError::Invalid(
                            "structured output count overflow".to_string(),
                        )
                    })?;
                    if block.get("content").and_then(Value::as_str)
                        != Some("Structured output provided successfully")
                        || top_result.as_str() != Some("Structured output provided successfully")
                    {
                        return invalid(
                            "Claude structured-output tool did not complete successfully",
                        );
                    }
                    terminal = Some(arguments);
                    continue;
                }
                let (tool_name, result) = match name.as_str() {
                    "mcp__engram__orient" | "mcp__engram__memory" => {
                        let raw_content = block.get("content").ok_or_else(|| {
                            NativeCorrectionError::Invalid(
                                "Claude MCP result omitted content".to_string(),
                            )
                        })?;
                        if &top_result != raw_content {
                            return invalid("Claude MCP result surfaces disagreed");
                        }
                        (name, parse_claude_mcp_text_result(raw_content)?)
                    }
                    "Read" if phase == NativeCorrectionProviderPhase::Proposal => {
                        validate_owned_regular_file_size(
                            Path::new(&lane.fixture_adr),
                            0o644,
                            1,
                            64 * 1024,
                            "fixture ADR",
                        )?;
                        let expected_content = read_bounded_regular_text(
                            Path::new(&lane.fixture_adr),
                            64 * 1024,
                            "fixture ADR",
                        )?;
                        let expected_rendered = claude_rendered_read_result(&expected_content);
                        if block.get("content").and_then(Value::as_str)
                            != Some(expected_rendered.as_str())
                            || top_result.get("type").and_then(Value::as_str) != Some("text")
                            || !exact_object_keys(&top_result, &["type", "file"])
                            || !top_result.pointer("/file").is_some_and(|file| {
                                exact_object_keys(
                                    file,
                                    &["filePath", "content", "numLines", "startLine", "totalLines"],
                                )
                            })
                            || top_result.pointer("/file/filePath").and_then(Value::as_str)
                                != Some(&lane.fixture_adr)
                            || top_result.pointer("/file/content").and_then(Value::as_str)
                                != Some(expected_content.as_str())
                            || top_result
                                .pointer("/file/startLine")
                                .and_then(Value::as_u64)
                                != Some(1)
                            || top_result.pointer("/file/numLines").and_then(Value::as_u64)
                                != Some(expected_content.lines().count() as u64)
                            || top_result
                                .pointer("/file/totalLines")
                                .and_then(Value::as_u64)
                                != Some(expected_content.lines().count() as u64)
                        {
                            return invalid(
                                "Claude Read result omitted the accepted ADR paragraph",
                            );
                        }
                        (name, top_result)
                    }
                    _ => return invalid("Claude invoked an unaccounted tool"),
                };
                events.push(observed_event(
                    events.len(),
                    &tool_name,
                    id,
                    arguments,
                    result,
                )?);
            }
            Some("result") => {
                if index != lines.len() - 1 || final_result.is_some() {
                    return invalid("Claude result was not the one final event");
                }
                final_result = Some(line);
            }
            _ => return invalid("Claude trace contained an unaccounted top-level event"),
        }
    }
    let result = final_result.ok_or_else(|| {
        NativeCorrectionError::Invalid("Claude trace omitted final result".to_string())
    })?;
    validate_claude_terminal_envelope(result, protocol, &process_identity)?;
    let result_output =
        strict_json_value_from_str(result.get("result").and_then(Value::as_str).ok_or_else(
            || {
                NativeCorrectionError::Invalid(
                    "Claude final result omitted JSON string".to_string(),
                )
            },
        )?)?;
    if !pending.is_empty()
        || structured_count != 1
        || terminal.as_ref() != Some(&output)
        || result.get("structured_output") != Some(&output)
        || result_output != output
        || result.get("subtype").and_then(Value::as_str) != Some("success")
        || result.get("is_error").and_then(Value::as_bool) != Some(false)
        || result.get("permission_denials").and_then(Value::as_array) != Some(&Vec::new())
        || result.get("queued_turn_count").and_then(Value::as_u64) != Some(0)
        || !result.get("api_error_status").is_some_and(Value::is_null)
        || result
            .get("subagent_stats")
            .map_or(true, |value| !exact_claude_subagent_stats(value))
    {
        return invalid("Claude trace was incomplete or terminal surfaces disagreed");
    }
    if result.get("terminal_reason").and_then(Value::as_str) != Some("completed")
        || !result.get("usage").is_some_and(Value::is_object)
    {
        return invalid("Claude final result omitted its completed usage envelope");
    }
    let model_usage = result
        .get("modelUsage")
        .and_then(Value::as_object)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("Claude result omitted modelUsage".to_string())
        })?;
    if model_usage.len() != 1 || !model_usage.contains_key(&protocol.claude.model) {
        return invalid("Claude modelUsage did not bind the one frozen model");
    }
    let mut total_tokens = 0u64;
    let mut summed_cost = 0.0f64;
    for usage in model_usage.values() {
        for key in [
            "inputTokens",
            "outputTokens",
            "cacheReadInputTokens",
            "cacheCreationInputTokens",
        ] {
            let value = usage.get(key).and_then(Value::as_u64).ok_or_else(|| {
                NativeCorrectionError::Invalid(format!("Claude modelUsage omitted {key}"))
            })?;
            total_tokens = total_tokens.checked_add(value).ok_or_else(|| {
                NativeCorrectionError::Invalid("Claude token count overflow".to_string())
            })?;
        }
        let model_cost = usage
            .get("costUSD")
            .and_then(Value::as_f64)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("Claude modelUsage omitted costUSD".to_string())
            })?;
        if !model_cost.is_finite() || model_cost < 0.0 {
            return invalid("Claude modelUsage cost was invalid");
        }
        summed_cost += model_cost;
    }
    let cost = result
        .get("total_cost_usd")
        .and_then(Value::as_f64)
        .ok_or_else(|| NativeCorrectionError::Invalid("Claude result omitted cost".to_string()))?;
    if !cost.is_finite()
        || cost < 0.0
        || cost * 1_000_000.0 > u64::MAX as f64
        || (cost - summed_cost).abs() > 0.000_000_5
    {
        return invalid("Claude cost was invalid");
    }
    let turns = u32::try_from(result.get("num_turns").and_then(Value::as_u64).ok_or_else(
        || NativeCorrectionError::Invalid("Claude result omitted turn count".to_string()),
    )?)
    .map_err(|_| NativeCorrectionError::Invalid("Claude turn count overflow".to_string()))?;
    Ok(NativeCorrectionParsedTrace {
        model: init
            .get("model")
            .and_then(Value::as_str)
            .unwrap()
            .to_string(),
        events,
        output,
        process_identity,
        codex_turn_completed: None,
        codex_total_tokens: None,
        claude_turns: Some(turns),
        claude_total_tokens: Some(total_tokens),
        claude_cost_microusd: Some((cost * 1_000_000.0).ceil() as u64),
        claude_stop_reason: result
            .get("stop_reason")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned),
        claude_unique_tool_ids: Some(true),
        claude_structured_output_count: Some(structured_count),
        claude_api_key_source: Some(api_key_source),
    })
}

fn expected_claude_tool_inventory(phase: NativeCorrectionProviderPhase) -> Vec<Value> {
    let mut tools = Vec::new();
    if phase == NativeCorrectionProviderPhase::Proposal {
        tools.push("Read");
    }
    tools.extend([
        "StructuredOutput",
        "mcp__engram__harness",
        "mcp__engram__memory",
        "mcp__engram__obligations",
        "mcp__engram__orient",
        "mcp__engram__repo",
        "mcp__engram__search",
    ]);
    tools
        .into_iter()
        .map(|value| Value::String(value.to_string()))
        .collect()
}

fn claude_rendered_read_result(content: &str) -> String {
    let mut rendered = content
        .lines()
        .enumerate()
        .map(|(index, line)| format!("{}\t{line}", index + 1))
        .collect::<Vec<_>>()
        .join("\n");
    rendered.push('\n');
    rendered
}

fn parse_claude_mcp_text_result(content: &Value) -> NativeCorrectionResult<Value> {
    let values = content.as_array().ok_or_else(|| {
        NativeCorrectionError::Invalid("Claude MCP content was not an array".to_string())
    })?;
    if values.len() != 1
        || values[0].get("type").and_then(Value::as_str) != Some("text")
        || !exact_object_keys(&values[0], &["type", "text"])
    {
        return invalid("Claude MCP result was not one exact text block");
    }
    strict_json_value_from_str(
        values[0]
            .get("text")
            .and_then(Value::as_str)
            .ok_or_else(|| NativeCorrectionError::Invalid("Claude MCP text missing".to_string()))?,
    )
}

fn native_correction_terminal_output(
    host: NativeCorrectionHost,
    trace: &[u8],
) -> NativeCorrectionResult<Value> {
    let trace = std::str::from_utf8(trace)
        .map_err(|_| NativeCorrectionError::Invalid("provider trace was not UTF-8".into()))?;
    let lines = parse_bounded_jsonl(trace)?;
    match host {
        NativeCorrectionHost::Codex => {
            let mut outputs = lines.iter().filter_map(|line| {
                (line.get("type").and_then(Value::as_str) == Some("item.completed")
                    && line.pointer("/item/type").and_then(Value::as_str) == Some("agent_message"))
                .then(|| line.pointer("/item/text").and_then(Value::as_str))
                .flatten()
            });
            let output = outputs.next().ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "Codex provider trace omitted terminal structured output".into(),
                )
            })?;
            if outputs.next().is_some() {
                return invalid("Codex provider trace contained multiple terminal outputs");
            }
            strict_json_value_from_str(output)
        }
        NativeCorrectionHost::ClaudeCode => {
            let mut results = lines
                .iter()
                .filter(|line| line.get("type").and_then(Value::as_str) == Some("result"));
            let result = results.next().ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "Claude provider trace omitted its terminal result".into(),
                )
            })?;
            if results.next().is_some() {
                return invalid("Claude provider trace contained multiple terminal results");
            }
            result.get("structured_output").cloned().ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "Claude provider result omitted structured_output".into(),
                )
            })
        }
    }
}

fn replace_native_correction_trace_placeholder(
    path: &Path,
    bytes: &[u8],
) -> NativeCorrectionResult<()> {
    validate_owned_regular_file(path, 0o600)?;
    if fs::symlink_metadata(path)?.len() != 0 {
        return invalid("provider trace dispatch placeholder was not empty");
    }
    let mut file = OpenOptions::new().write(true).truncate(true).open(path)?;
    file.write_all(bytes)?;
    file.sync_all()?;
    sync_parent_directory(path)?;
    Ok(())
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionArtifactReceipt {
    pub path: String,
    pub sha256: String,
    pub bytes: u64,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionProviderReceipt {
    pub schema_version: u32,
    pub family: String,
    pub pilot_id: String,
    pub run_plan: String,
    pub run_plan_sha256: String,
    pub protocol_sha256: String,
    pub lane_order: u32,
    pub host: NativeCorrectionHost,
    pub model: String,
    pub phase: NativeCorrectionProviderPhase,
    pub prompt_sha256: String,
    pub output_schema_sha256: String,
    pub argv_sha256: String,
    pub environment_sha256: String,
    pub configuration_files_sha256: String,
    pub fixture_revision: String,
    pub fixture_adr_sha256: String,
    pub binary_sha256: String,
    pub codex_code_mode_host_sha256: Option<String>,
    pub engram_sha256: String,
    pub agent_tools_sha256: String,
    pub agent_instructions_sha256: String,
    pub started_unix_ms: u64,
    pub completed_unix_ms: u64,
    pub exit_code: i32,
    pub duration_ms: u64,
    pub trace: NativeCorrectionArtifactReceipt,
    pub stderr: NativeCorrectionArtifactReceipt,
    pub output: NativeCorrectionArtifactReceipt,
    pub normalized_evidence_sha256: String,
    pub normalized_evidence: Value,
    pub recovered: bool,
}

#[allow(clippy::too_many_arguments)]
fn record_native_correction_proposal_receipt(
    run_plan: &Path,
    lane_order: u32,
    evidence: &NativeCorrectionProposalEvidence,
    started_unix_ms: u64,
    completed_unix_ms: u64,
    exit_code: i32,
    recovered: bool,
) -> NativeCorrectionResult<NativeCorrectionProviderReceipt> {
    let (plan, plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_proposal_turn(&plan, lane_order)?;
    if recovered {
        return invalid("proposal artifacts without a receipt are frozen; recovery is forbidden");
    }
    let derived = extract_native_correction_proposal_evidence(&protocol, lane)?;
    if evidence != &derived {
        return invalid("caller proposal evidence disagreed with the lossless raw trace");
    }
    let output_value = serde_json::to_value(&derived.output)?;
    record_provider_receipt(
        run_plan,
        &plan,
        &plan_sha256,
        lane,
        NativeCorrectionProviderPhase::Proposal,
        derived.model.clone(),
        serde_json::to_value(&derived)?,
        output_value,
        started_unix_ms,
        completed_unix_ms,
        exit_code,
        recovered,
    )
}

#[allow(clippy::too_many_arguments)]
fn record_native_correction_retrieval_receipt(
    run_plan: &Path,
    lane_order: u32,
    evidence: &NativeCorrectionRetrievalEvidence,
    started_unix_ms: u64,
    completed_unix_ms: u64,
    exit_code: i32,
    recovered: bool,
) -> NativeCorrectionResult<NativeCorrectionProviderReceipt> {
    let (plan, plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_retrieval_turn(&plan, lane_order)?;
    let operator_path = Path::new(&lane.operator_receipt);
    let (operator, _): (NativeCorrectionOperatorReceipt, _) = read_digest_bound_strict_json(
        operator_path,
        &receipt_digest_path(operator_path),
        8 * 1024 * 1024,
        "operator receipt",
    )?;
    validate_recorded_native_correction_operator_receipt(&plan, lane, &operator)?;
    if recovered {
        return invalid("retrieval artifacts without a receipt are frozen; recovery is forbidden");
    }
    let derived = extract_native_correction_retrieval_evidence(&protocol, lane, &operator)?;
    let proposal_receipt =
        read_and_validate_provider_receipt(&plan, lane, NativeCorrectionProviderPhase::Proposal)?;
    let proposal_evidence: NativeCorrectionProposalEvidence =
        serde_json::from_value(proposal_receipt.normalized_evidence)?;
    if derived.process_identity == proposal_evidence.process_identity
        || started_unix_ms < operator.completed_unix_ms
    {
        return invalid("retrieval did not start as a fresh process after operator completion");
    }
    if evidence != &derived {
        return invalid("caller retrieval evidence disagreed with the lossless raw trace");
    }
    let output_value = serde_json::to_value(&derived.output)?;
    record_provider_receipt(
        run_plan,
        &plan,
        &plan_sha256,
        lane,
        NativeCorrectionProviderPhase::Retrieval,
        derived.model.clone(),
        serde_json::to_value(&derived)?,
        output_value,
        started_unix_ms,
        completed_unix_ms,
        exit_code,
        recovered,
    )
}

/// Execute exactly one fresh provider phase after explicit approval. Creating the empty trace
/// file is the fsynced dispatch boundary: any spawn uncertainty or malformed output leaves a
/// partial phase that the lifecycle audit freezes instead of permitting a retry.
pub fn execute_native_correction_provider_phase(
    run_plan: &Path,
    lane_order: u32,
    phase: NativeCorrectionProviderPhase,
    approve_provider_execution: bool,
    confirm_claude_budget_cents: u32,
) -> NativeCorrectionResult<NativeCorrectionProviderReceipt> {
    let (plan, _, protocol) = load_attested_plan(run_plan)?;
    if !protocol.requires_explicit_provider_execution
        || !approve_provider_execution
        || confirm_claude_budget_cents != protocol.claude.aggregate_budget_cents
        || confirm_claude_budget_cents != 20
        || plan.claude_budget_cents != confirm_claude_budget_cents
    {
        return invalid(
            "provider execution requires explicit approval and the exact $0.20 Claude aggregate allocation",
        );
    }
    let lifecycle = audit_native_correction_lifecycle(run_plan)?;
    if !lifecycle.valid
        || lifecycle.complete
        || lifecycle.next_lane_order != Some(lane_order)
        || lifecycle.next_phase.as_deref() != Some(phase.label())
    {
        return invalid("provider execution is not the exact next frozen lifecycle action");
    }
    let lane = lane_by_order(&plan, lane_order)?;
    let artifacts = phase_artifacts(lane, phase);
    for path in [
        &artifacts.trace,
        &artifacts.stderr,
        &artifacts.output,
        &artifacts.receipt,
    ] {
        if path_entry_exists(Path::new(path)) {
            return invalid("provider execution output residue forbids replay");
        }
    }
    if path_entry_exists(&receipt_digest_path(Path::new(&artifacts.receipt))) {
        return invalid("provider execution receipt sidecar residue forbids replay");
    }

    let argv = match phase {
        NativeCorrectionProviderPhase::Proposal => &lane.proposal_argv,
        NativeCorrectionProviderPhase::Retrieval => &lane.retrieval_argv,
    };
    let environment = match phase {
        NativeCorrectionProviderPhase::Proposal => &lane.proposal_environment,
        NativeCorrectionProviderPhase::Retrieval => &lane.retrieval_environment,
    };
    ensure_environment_has_no_provider_keys(environment)?;
    let binary = argv
        .first()
        .ok_or_else(|| NativeCorrectionError::Invalid("provider argv omitted executable".into()))?;
    let arguments = argv[1..].iter().map(String::as_str).collect::<Vec<_>>();
    let trace_path = Path::new(&artifacts.trace);
    write_new_file(trace_path, &[], 0o600)?;
    let started_unix_ms = unix_ms(SystemTime::now())?.max(plan.prepared_unix_ms);
    let execution = run_bounded_native_correction_command(
        Path::new(binary),
        &arguments,
        Path::new(&lane.cwd),
        environment,
        Duration::from_millis(protocol.resources.host_timeout_ms),
        protocol.resources.max_trace_bytes,
    );
    let completed_unix_ms = unix_ms(SystemTime::now())?.max(started_unix_ms);
    let (exit_code, trace, stderr) = execution?;
    replace_native_correction_trace_placeholder(trace_path, &trace)?;
    write_new_file(Path::new(&artifacts.stderr), &stderr, 0o600)?;
    if exit_code != 0 {
        return invalid(format!(
            "{} provider lane {} exited unsuccessfully; raw evidence is frozen",
            phase.label(),
            lane_order
        ));
    }
    if trace.is_empty()
        || trace.len() as u64 > protocol.resources.max_trace_bytes
        || stderr.len() as u64 > protocol.resources.max_stderr_bytes
    {
        return invalid("provider raw evidence exceeded the frozen byte contract");
    }
    let output = native_correction_terminal_output(lane.host, &trace)?;
    write_private_json(Path::new(&artifacts.output), &output)?;
    match phase {
        NativeCorrectionProviderPhase::Proposal => {
            let evidence = extract_native_correction_proposal_evidence(&protocol, lane)?;
            record_native_correction_proposal_receipt(
                run_plan,
                lane_order,
                &evidence,
                started_unix_ms,
                completed_unix_ms,
                exit_code,
                false,
            )
        }
        NativeCorrectionProviderPhase::Retrieval => {
            let operator_path = Path::new(&lane.operator_receipt);
            let (operator, _): (NativeCorrectionOperatorReceipt, _) =
                read_digest_bound_strict_json(
                    operator_path,
                    &receipt_digest_path(operator_path),
                    8 * 1024 * 1024,
                    "provider runner operator receipt",
                )?;
            validate_recorded_native_correction_operator_receipt(&plan, lane, &operator)?;
            let evidence =
                extract_native_correction_retrieval_evidence(&protocol, lane, &operator)?;
            record_native_correction_retrieval_receipt(
                run_plan,
                lane_order,
                &evidence,
                started_unix_ms,
                completed_unix_ms,
                exit_code,
                false,
            )
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn record_provider_receipt(
    run_plan: &Path,
    plan: &PreparedNativeCorrection,
    plan_sha256: &str,
    lane: &PreparedNativeCorrectionLane,
    phase: NativeCorrectionProviderPhase,
    model: String,
    normalized_evidence: Value,
    expected_output: Value,
    started_unix_ms: u64,
    completed_unix_ms: u64,
    exit_code: i32,
    recovered: bool,
) -> NativeCorrectionResult<NativeCorrectionProviderReceipt> {
    if exit_code != 0
        || recovered
        || started_unix_ms < plan.prepared_unix_ms
        || completed_unix_ms < started_unix_ms
        || completed_unix_ms - started_unix_ms > plan_resource_timeout(plan)?
    {
        return invalid(
            "terminal provider receipt requires a new, bounded, non-recovered successful run",
        );
    }
    let artifacts = phase_artifacts(lane, phase);
    if path_entry_exists(Path::new(&artifacts.receipt))
        || path_entry_exists(&receipt_digest_path(Path::new(&artifacts.receipt)))
    {
        return invalid(format!(
            "refusing to replay completed {} lane {}",
            phase.label(),
            lane.order
        ));
    }
    let trace = artifact_receipt(&artifacts.trace, plan, false)?;
    let stderr = artifact_receipt(&artifacts.stderr, plan, true)?;
    let output = artifact_receipt(&artifacts.output, plan, false)?;
    let actual_output: Value = read_strict_json_file(
        Path::new(&artifacts.output),
        0o600,
        8 * 1024 * 1024,
        "provider output",
    )?;
    if actual_output != expected_output {
        return invalid("structured output file does not match trusted normalized evidence");
    }
    let (argv, environment) = match phase {
        NativeCorrectionProviderPhase::Proposal => {
            (&lane.proposal_argv, &lane.proposal_environment)
        }
        NativeCorrectionProviderPhase::Retrieval => {
            (&lane.retrieval_argv, &lane.retrieval_environment)
        }
    };
    let binary_name = match lane.host {
        NativeCorrectionHost::Codex => "codex",
        NativeCorrectionHost::ClaudeCode => "claude_code",
    };
    let receipt = NativeCorrectionProviderReceipt {
        schema_version: NATIVE_CORRECTION_RECEIPT_SCHEMA_VERSION,
        family: NATIVE_CORRECTION_FAMILY.to_string(),
        pilot_id: plan.pilot_id.clone(),
        run_plan: run_plan.canonicalize()?.display().to_string(),
        run_plan_sha256: plan_sha256.to_string(),
        protocol_sha256: plan.protocol_sha256.clone(),
        lane_order: lane.order,
        host: lane.host,
        model,
        phase,
        prompt_sha256: artifacts.prompt_sha256.clone(),
        output_schema_sha256: artifacts.output_schema_sha256.clone(),
        argv_sha256: sha256_json(argv)?,
        environment_sha256: sha256_json(environment)?,
        configuration_files_sha256: sha256_json(&lane.configuration_files)?,
        fixture_revision: lane.fixture_revision.clone(),
        fixture_adr_sha256: lane.fixture_adr_sha256.clone(),
        binary_sha256: plan
            .runtime
            .binaries
            .get(binary_name)
            .expect("validated provider binary")
            .sha256
            .clone(),
        codex_code_mode_host_sha256: (lane.host == NativeCorrectionHost::Codex)
            .then(|| plan.runtime.binaries["codex_code_mode_host"].sha256.clone()),
        engram_sha256: EXPECTED_ENGRAM_SHA256.to_string(),
        agent_tools_sha256: EXPECTED_AGENT_TOOLS_SHA256.to_string(),
        agent_instructions_sha256: EXPECTED_AGENT_INSTRUCTIONS_SHA256.to_string(),
        started_unix_ms,
        completed_unix_ms,
        exit_code,
        duration_ms: completed_unix_ms - started_unix_ms,
        trace,
        stderr,
        output,
        normalized_evidence_sha256: sha256_json(&normalized_evidence)?,
        normalized_evidence,
        recovered,
    };
    validate_provider_receipt(plan, lane, &receipt)?;
    write_private_json(Path::new(&artifacts.receipt), &receipt)?;
    write_private_text(
        &receipt_digest_path(Path::new(&artifacts.receipt)),
        &(sha256_file(Path::new(&artifacts.receipt))? + "\n"),
    )?;
    Ok(receipt)
}

pub fn validate_provider_receipt(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    receipt: &NativeCorrectionProviderReceipt,
) -> NativeCorrectionResult<()> {
    let phase = phase_artifacts(lane, receipt.phase);
    let (argv, environment) = match receipt.phase {
        NativeCorrectionProviderPhase::Proposal => {
            (&lane.proposal_argv, &lane.proposal_environment)
        }
        NativeCorrectionProviderPhase::Retrieval => {
            (&lane.retrieval_argv, &lane.retrieval_environment)
        }
    };
    let binary_name = match lane.host {
        NativeCorrectionHost::Codex => "codex",
        NativeCorrectionHost::ClaudeCode => "claude_code",
    };
    let canonical_plan = Path::new(&plan.protocol)
        .with_file_name("run-plan.json")
        .canonicalize()?;
    let (observed_plan, bound_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            &canonical_plan,
            &canonical_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "provider-receipt run plan",
        )?;
    if observed_plan != *plan {
        return invalid("provider receipt validation observed a different run plan");
    }
    let protocol_bytes =
        read_bounded_attested_file(Path::new(&plan.protocol), 1024 * 1024, "protocol snapshot")?;
    if format!("{:x}", Sha256::digest(&protocol_bytes)) != plan.protocol_sha256 {
        return invalid("provider receipt protocol snapshot digest drifted");
    }
    let protocol: NativeCorrectionProtocol = strict_json_from_slice(&protocol_bytes)?;
    let expected_model = match lane.host {
        NativeCorrectionHost::Codex => argv_value_after(argv, "--model")?,
        NativeCorrectionHost::ClaudeCode => protocol.claude.model.clone(),
    };
    if receipt.schema_version != NATIVE_CORRECTION_RECEIPT_SCHEMA_VERSION
        || receipt.family != NATIVE_CORRECTION_FAMILY
        || receipt.pilot_id != plan.pilot_id
        || Path::new(&receipt.run_plan) != canonical_plan
        || receipt.run_plan_sha256 != bound_plan_sha256
        || receipt.protocol_sha256 != plan.protocol_sha256
        || receipt.lane_order != lane.order
        || receipt.host != lane.host
        || receipt.model != expected_model
        || receipt.prompt_sha256 != phase.prompt_sha256
        || receipt.output_schema_sha256 != phase.output_schema_sha256
        || receipt.argv_sha256 != sha256_json(argv)?
        || receipt.environment_sha256 != sha256_json(environment)?
        || receipt.configuration_files_sha256 != sha256_json(&lane.configuration_files)?
        || receipt.fixture_revision != lane.fixture_revision
        || receipt.fixture_adr_sha256 != lane.fixture_adr_sha256
        || receipt.binary_sha256 != plan.runtime.binaries[binary_name].sha256
        || receipt.codex_code_mode_host_sha256
            != (lane.host == NativeCorrectionHost::Codex)
                .then(|| plan.runtime.binaries["codex_code_mode_host"].sha256.clone())
        || receipt.engram_sha256 != EXPECTED_ENGRAM_SHA256
        || receipt.agent_tools_sha256 != EXPECTED_AGENT_TOOLS_SHA256
        || receipt.agent_instructions_sha256 != EXPECTED_AGENT_INSTRUCTIONS_SHA256
        || receipt.exit_code != 0
        || receipt.recovered
        || receipt.started_unix_ms < plan.prepared_unix_ms
        || receipt.completed_unix_ms < receipt.started_unix_ms
        || receipt.duration_ms != receipt.completed_unix_ms - receipt.started_unix_ms
        || receipt.duration_ms > protocol.resources.host_timeout_ms
        || receipt.trace != artifact_receipt(&phase.trace, plan, false)?
        || receipt.stderr != artifact_receipt(&phase.stderr, plan, true)?
        || receipt.output != artifact_receipt(&phase.output, plan, false)?
        || receipt.normalized_evidence_sha256 != sha256_json(&receipt.normalized_evidence)?
    {
        return invalid("provider receipt binding or artifact evidence drifted");
    }
    let derived = match receipt.phase {
        NativeCorrectionProviderPhase::Proposal => serde_json::to_value(
            extract_native_correction_proposal_evidence(&protocol, lane)?,
        )?,
        NativeCorrectionProviderPhase::Retrieval => {
            let path = Path::new(&lane.operator_receipt);
            let (operator, _): (NativeCorrectionOperatorReceipt, _) =
                read_digest_bound_strict_json(
                    path,
                    &receipt_digest_path(path),
                    8 * 1024 * 1024,
                    "operator receipt",
                )?;
            serde_json::to_value(extract_native_correction_retrieval_evidence(
                &protocol, lane, &operator,
            )?)?
        }
    };
    if receipt.normalized_evidence != derived {
        return invalid("provider receipt normalized evidence was not derived from raw trace");
    }
    Ok(())
}

fn plan_resource_timeout(plan: &PreparedNativeCorrection) -> NativeCorrectionResult<u64> {
    let bytes =
        read_bounded_attested_file(Path::new(&plan.protocol), 1024 * 1024, "protocol snapshot")?;
    if format!("{:x}", Sha256::digest(&bytes)) != plan.protocol_sha256 {
        return invalid("protocol snapshot digest drifted");
    }
    let protocol: NativeCorrectionProtocol = strict_json_from_slice(&bytes)?;
    validate_native_correction_protocol(&protocol)?;
    Ok(protocol.resources.host_timeout_ms)
}

fn record_native_correction_operator_receipt(
    run_plan: &Path,
    lane_order: u32,
    receipt: &NativeCorrectionOperatorReceipt,
) -> NativeCorrectionResult<()> {
    let (plan, _, _) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_operator_receipt_turn(&plan, lane_order)?;
    validate_recorded_native_correction_operator_receipt(&plan, lane, receipt)?;
    write_private_json(Path::new(&lane.operator_receipt), receipt)?;
    write_private_text(
        &receipt_digest_path(Path::new(&lane.operator_receipt)),
        &(sha256_file(Path::new(&lane.operator_receipt))? + "\n"),
    )?;
    Ok(())
}

fn validate_recorded_native_correction_operator_receipt(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    receipt: &NativeCorrectionOperatorReceipt,
) -> NativeCorrectionResult<()> {
    let protocol_bytes =
        read_bounded_attested_file(Path::new(&plan.protocol), 1024 * 1024, "protocol snapshot")?;
    if format!("{:x}", Sha256::digest(&protocol_bytes)) != plan.protocol_sha256 {
        return invalid("operator protocol snapshot digest drifted");
    }
    let protocol: NativeCorrectionProtocol = strict_json_from_slice(&protocol_bytes)?;
    let intent_path = Path::new(&lane.operator_intent);
    let (intent, intent_sha256): (NativeCorrectionOperatorIntent, _) =
        read_digest_bound_strict_json(
            intent_path,
            &receipt_digest_path(intent_path),
            1024 * 1024,
            "operator intent",
        )?;
    validate_native_correction_operator_intent(plan, lane, &intent)?;
    let verification_dispatch_path = Path::new(&lane.operator_verification_dispatch);
    let (verification_dispatch, verification_dispatch_sha256): (
        NativeCorrectionOperatorVerificationDispatchJournal,
        _,
    ) = read_digest_bound_strict_json(
        verification_dispatch_path,
        &receipt_digest_path(verification_dispatch_path),
        1024 * 1024,
        "operator verification dispatch journal",
    )?;
    validate_native_correction_operator_verification_dispatch(
        plan,
        lane,
        &intent,
        &verification_dispatch,
        false,
    )?;
    let dispatch_path = Path::new(&lane.operator_dispatch);
    let (dispatch, dispatch_sha256): (NativeCorrectionOperatorDispatchJournal, _) =
        read_digest_bound_strict_json(
            dispatch_path,
            &receipt_digest_path(dispatch_path),
            1024 * 1024,
            "operator dispatch journal",
        )?;
    validate_native_correction_operator_dispatch(
        plan,
        lane,
        &intent,
        &receipt.proposal_before.canonical_digest,
        &dispatch,
    )?;
    let canonical_plan = Path::new(&intent.run_plan);
    let (observed_plan, run_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            canonical_plan,
            &canonical_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "operator-receipt run plan",
        )?;
    let (_, proposal_receipt_sha256) = read_and_validate_provider_receipt_with_digest(
        plan,
        lane,
        NativeCorrectionProviderPhase::Proposal,
    )?;
    if observed_plan != *plan
        || receipt.run_plan_sha256 != run_plan_sha256
        || receipt.protocol_sha256 != plan.protocol_sha256
        || receipt.engram_sha256 != EXPECTED_ENGRAM_SHA256
        || receipt.full_profile_tools_sha256 != EXPECTED_FULL_TOOLS_SHA256
        || receipt.full_profile_handshake_sha256 != sha256_json(&plan.runtime.full_profile)?
        || receipt.proposal_receipt_sha256 != proposal_receipt_sha256
        || receipt.operator_intent_sha256 != intent_sha256
        || receipt.operator_verification_dispatch_sha256 != verification_dispatch_sha256
        || receipt.operator_dispatch_sha256 != dispatch_sha256
        || receipt.procedure_verification_receipt_sha256
            != lane.procedure_verification_receipt_sha256
        || receipt.procedure_verification_expires_at != lane.procedure_verification_expires_at
        || receipt.fresh_process_ids.first().copied() != Some(verification_dispatch.process_id)
        || receipt.fresh_process_ids.first().copied() != Some(dispatch.process_id)
        || receipt.operator_trace != artifact_receipt(&lane.operator_trace, plan, false)?
        || receipt.operator_stderr != artifact_receipt(&lane.operator_stderr, plan, true)?
        || receipt.operator_trace.bytes == 0
        || receipt.operator_stderr.bytes != 0
        || receipt.started_unix_ms < intent.created_unix_ms
        || receipt.duration_ms > protocol.resources.host_timeout_ms
        || receipt.proposal_initial != intent.proposal
        || receipt.old_before != intent.old
        || receipt.replacement_initial != intent.replacement
    {
        return invalid("operator receipt does not bind the exact durable intent and artifacts");
    }
    validate_native_correction_dispatch_in_operator_trace(
        plan,
        lane,
        &verification_dispatch,
        &dispatch,
        receipt,
    )?;
    validate_native_correction_operator_receipt(lane, receipt)?;
    Ok(())
}

fn validate_native_correction_dispatch_in_operator_trace(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    verification_dispatch: &NativeCorrectionOperatorVerificationDispatchJournal,
    dispatch: &NativeCorrectionOperatorDispatchJournal,
    receipt: &NativeCorrectionOperatorReceipt,
) -> NativeCorrectionResult<()> {
    let trace = read_bounded_regular_text(
        Path::new(&lane.operator_trace),
        MAX_RUNTIME_PROBE_BYTES as u64,
        "operator trace",
    )?;
    let canary: NativeCorrectionPrivateCanaryContract = read_strict_json_file(
        Path::new(&lane.private_canary_contract),
        0o600,
        64 * 1024,
        "private canary contract",
    )?;
    if trace.contains(&canary.hidden_secret)
        || trace.contains("EVAL_SECRET_")
        || trace.contains(&canary.other_scope_content)
        || trace.contains("EVAL_OTHER_SCOPE_")
    {
        return invalid("private secret or Orbit canary appeared in the operator transcript");
    }
    let envelope: NativeCorrectionOperatorTraceEnvelope = strict_json_from_str(&trace)?;
    if envelope.schema_version != 2
        || envelope.sessions.len() != 2
        || envelope.daemon_stops.len() != 3
        || receipt.fresh_process_ids.len() != 2
    {
        return invalid("operator trace did not contain exactly two sessions and three stop gates");
    }
    for (index, session) in envelope.sessions.iter().enumerate() {
        let transcript = session.transcript_jsonl.as_bytes();
        if session.ordinal != (index + 1) as u32
            || session.process_id != receipt.fresh_process_ids[index]
            || session.started_unix_ms > session.observation_completed_unix_ms
            || session.transcript_bytes != transcript.len() as u64
            || session.transcript_sha256 != format!("{:x}", Sha256::digest(transcript))
            || session.transcript_bytes == 0
            || session.transcript_bytes > MAX_RUNTIME_PROBE_BYTES as u64
            || session.stderr_bytes != 0
            || session.stderr_sha256 != format!("{:x}", Sha256::digest([]))
        {
            return invalid("operator session process, transcript, stderr, or timing drifted");
        }
    }
    for stop in &envelope.daemon_stops {
        validate_operator_daemon_stop(plan, lane, stop)?;
    }
    let first = &envelope.sessions[0];
    let second = &envelope.sessions[1];
    let applied_at_unix_ms = u64::try_from(
        parse_snapshot_timestamp(
            receipt
                .proposal_after
                .applied_at
                .as_deref()
                .ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "operator applied proposal omitted applied_at".to_string(),
                    )
                })?,
            "operator proposal applied_at",
        )?
        .unix_timestamp_nanos()
            / 1_000_000,
    )
    .map_err(|_| {
        NativeCorrectionError::Invalid(
            "operator proposal applied_at predates the Unix epoch".to_string(),
        )
    })?;
    validate_operator_mutation_chronology(
        verification_dispatch.created_unix_ms,
        dispatch.created_unix_ms,
        applied_at_unix_ms,
        first.started_unix_ms,
        first.observation_completed_unix_ms,
    )?;
    for (earlier_label, earlier, later_label, later) in [
        (
            "receipt.started_unix_ms",
            receipt.started_unix_ms,
            "initial_stop.started_unix_ms",
            envelope.daemon_stops[0].started_unix_ms,
        ),
        (
            "initial_stop.completed_unix_ms",
            envelope.daemon_stops[0].completed_unix_ms,
            "first_session.started_unix_ms",
            first.started_unix_ms,
        ),
        (
            "first_session.observation_completed_unix_ms",
            first.observation_completed_unix_ms,
            "first_stop.started_unix_ms",
            envelope.daemon_stops[1].started_unix_ms,
        ),
        (
            "first_stop.completed_unix_ms",
            envelope.daemon_stops[1].completed_unix_ms,
            "second_session.started_unix_ms",
            second.started_unix_ms,
        ),
        (
            "proposal.applied_at",
            applied_at_unix_ms,
            "second_session.started_unix_ms",
            second.started_unix_ms,
        ),
        (
            "second_session.observation_completed_unix_ms",
            second.observation_completed_unix_ms,
            "second_stop.started_unix_ms",
            envelope.daemon_stops[2].started_unix_ms,
        ),
        (
            "second_stop.completed_unix_ms",
            envelope.daemon_stops[2].completed_unix_ms,
            "receipt.completed_unix_ms",
            receipt.completed_unix_ms,
        ),
    ] {
        require_native_correction_timestamp_order(earlier_label, earlier, later_label, later)?;
    }
    if verification_dispatch.process_id != first.process_id
        || dispatch.process_id != first.process_id
    {
        return invalid(format!(
            "operator dispatch process binding drifted: verification {}, apply {}, first session {}",
            verification_dispatch.process_id, dispatch.process_id, first.process_id,
        ));
    }

    let proposal_id = &receipt.proposal_initial.proposal_id;
    let first_calls = vec![
        (operator_get_arguments(lane, "orbit", proposal_id), true),
        (
            json!({
                "action":"list_correction_proposals",
                "limit":2,
                "scope":exact_local_scope_value("atlas", &lane.cwd)
            }),
            false,
        ),
        (operator_get_arguments(lane, "atlas", proposal_id), false),
        (operator_list_arguments(lane, "atlas", "active"), false),
        (
            operator_verification_arguments(
                lane,
                proposal_id,
                &receipt.proposal_initial.canonical_digest,
            ),
            false,
        ),
        (
            json!({
                "action":"apply_correction",
                "proposal_id":proposal_id,
                "expected_digest":receipt.proposal_initial.canonical_digest,
                "scope":exact_local_scope_value("atlas", &lane.cwd)
            }),
            true,
        ),
        (
            json!({
                "action":"apply_correction",
                "proposal_id":proposal_id,
                "expected_digest":receipt.proposal_before.canonical_digest,
                "scope":exact_local_scope_value("atlas", &lane.cwd)
            }),
            false,
        ),
    ];
    let second_calls = vec![
        (operator_list_arguments(lane, "atlas", "active"), false),
        (operator_get_arguments(lane, "atlas", proposal_id), false),
    ];
    let first_results =
        parse_operator_stdio_transcript(first, &first_calls, &plan.runtime.full_profile)?;
    let second_results =
        parse_operator_stdio_transcript(second, &second_calls, &plan.runtime.full_profile)?;
    for (label, request_json_line) in [
        (
            "procedure-verification",
            verification_dispatch.request_json_line.as_str(),
        ),
        ("P1 apply", dispatch.request_json_line.as_str()),
    ] {
        let expected_request_line = request_json_line.strip_suffix('\n').ok_or_else(|| {
            NativeCorrectionError::Invalid(format!("{label} dispatch request omitted newline"))
        })?;
        if first
            .transcript_jsonl
            .lines()
            .filter(|line| *line == expected_request_line)
            .count()
            != 1
        {
            return invalid(format!(
                "operator transcript omitted the one exact journaled {label} request"
            ));
        }
    }

    let mut derived = Vec::new();
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::FreshFullHandshake,
        json!({}),
        json!({"verified":true}),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::OrbitProposalInspection,
        first_calls[0].0.clone(),
        first_results[0].clone(),
    )?;
    for (action, index) in [
        (NativeCorrectionOperatorAction::AtlasListProposals, 1usize),
        (NativeCorrectionOperatorAction::AtlasGetProposal, 2usize),
        (NativeCorrectionOperatorAction::AtlasActiveList, 3usize),
    ] {
        push_operator_event(
            &mut derived,
            action,
            first_calls[index].0.clone(),
            first_results[index].clone(),
        )?;
    }
    for (action, index) in [
        (
            NativeCorrectionOperatorAction::VerifyCorrectionProcedure,
            4usize,
        ),
        (NativeCorrectionOperatorAction::RejectStaleP0Apply, 5usize),
        (NativeCorrectionOperatorAction::ApplyCorrection, 6usize),
    ] {
        push_operator_event(
            &mut derived,
            action,
            first_calls[index].0.clone(),
            first_results[index].clone(),
        )?;
    }
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::RestartFullHandshake,
        json!({}),
        json!({"verified":true}),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::RestartAtlasActiveList,
        second_calls[0].0.clone(),
        second_results[0].clone(),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::RestartAtlasGetProposal,
        second_calls[1].0.clone(),
        second_results[1].clone(),
    )?;
    push_operator_event(
        &mut derived,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    if derived != receipt.events {
        return invalid(
            "operator normalized events were not losslessly derived from both sessions",
        );
    }
    Ok(())
}

fn validate_operator_mutation_chronology(
    verification_dispatch_created_unix_ms: u64,
    dispatch_created_unix_ms: u64,
    applied_at_unix_ms: u64,
    first_started_unix_ms: u64,
    first_observation_completed_unix_ms: u64,
) -> NativeCorrectionResult<()> {
    for (earlier_label, earlier, later_label, later) in [
        (
            "first_session.started_unix_ms",
            first_started_unix_ms,
            "verification_dispatch.created_unix_ms",
            verification_dispatch_created_unix_ms,
        ),
        (
            "verification_dispatch.created_unix_ms",
            verification_dispatch_created_unix_ms,
            "apply_dispatch.created_unix_ms",
            dispatch_created_unix_ms,
        ),
        (
            "apply_dispatch.created_unix_ms",
            dispatch_created_unix_ms,
            "proposal.applied_at",
            applied_at_unix_ms,
        ),
        (
            "proposal.applied_at",
            applied_at_unix_ms,
            "first_session.observation_completed_unix_ms",
            first_observation_completed_unix_ms,
        ),
    ] {
        require_native_correction_timestamp_order(earlier_label, earlier, later_label, later)?;
    }
    Ok(())
}

fn require_native_correction_timestamp_order(
    earlier_label: &str,
    earlier_unix_ms: u64,
    later_label: &str,
    later_unix_ms: u64,
) -> NativeCorrectionResult<()> {
    if earlier_unix_ms > later_unix_ms {
        return invalid(format!(
            "operator chronology drifted: {earlier_label} exceeded {later_label} by {} ms",
            earlier_unix_ms - later_unix_ms,
        ));
    }
    Ok(())
}

fn validate_operator_daemon_stop(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    stop: &NativeCorrectionDaemonStopEvidence,
) -> NativeCorrectionResult<()> {
    let termination_valid = match stop.termination_method.as_str() {
        "already_absent" => {
            !stop.signal_issued
                && stop.signal_number.is_none()
                && stop.controls_absent_only
                && stop.live_observations.is_empty()
        }
        "direct_sigterm" => {
            stop.signal_issued
                && stop.signal_number == Some(libc::SIGTERM)
                && !stop.controls_absent_only
                && stop.live_observations.len() == 2
                && stop.live_observations[0] == stop.live_observations[1]
                && stop.live_observations.iter().all(|observation| {
                    observation.pid > 1
                        && observation.port > 0
                        && observation.controls_complete
                        && observation.executable_verified
                        && observation.argv_verified
                        && observation.environment_verified
                        && observation.daemon_token_matched
                        && observation.health_verified
                })
        }
        _ => false,
    };
    let expected_engram = &plan.runtime.binaries["engram"];
    let expected_root = Path::new(&lane.engram_home)
        .join("projects")
        .join(&lane.opaque_partition);
    if stop.started_unix_ms > stop.completed_unix_ms
        || !stop.control_files_absent
        || stop.engram_path != expected_engram.path
        || stop.engram_sha256 != expected_engram.sha256
        || stop.engram_home != lane.engram_home
        || stop.partition != lane.opaque_partition
        || Path::new(&stop.daemon_root) != expected_root
        || !termination_valid
    {
        return invalid("operator daemon-stop evidence drifted");
    }
    Ok(())
}

fn parse_operator_stdio_transcript(
    session: &NativeCorrectionOperatorSessionTrace,
    expected_calls: &[(Value, bool)],
    full_profile: &NativeCorrectionFullProfileHandshake,
) -> NativeCorrectionResult<Vec<Value>> {
    let calls = expected_calls
        .iter()
        .map(|(arguments, expect_error)| ("memory", arguments.clone(), *expect_error))
        .collect::<Vec<_>>();
    parse_full_profile_stdio_transcript(session, &calls, full_profile)
}

fn parse_full_profile_stdio_transcript(
    session: &NativeCorrectionOperatorSessionTrace,
    expected_calls: &[(&str, Value, bool)],
    full_profile: &NativeCorrectionFullProfileHandshake,
) -> NativeCorrectionResult<Vec<Value>> {
    let values = parse_bounded_jsonl(&session.transcript_jsonl)?;
    let mut cursor = 0usize;
    let mut next_id = 1u64;
    let initialize = take_operator_rpc_pair(
        &values,
        &mut cursor,
        &mut next_id,
        "initialize",
        &json!({
            "protocolVersion":NATIVE_CORRECTION_MCP_PROTOCOL,
            "capabilities":{},
            "clientInfo":{"name":"engram-native-correction-eval","version":"1"}
        }),
    )?;
    if initialize
        .pointer("/result/protocolVersion")
        .and_then(Value::as_str)
        != Some(NATIVE_CORRECTION_MCP_PROTOCOL)
    {
        return invalid("operator initialize response protocol drifted");
    }
    let notification = values.get(cursor).ok_or_else(|| {
        NativeCorrectionError::Invalid(
            "operator transcript omitted initialized notification".into(),
        )
    })?;
    if !exact_object_keys(notification, &["jsonrpc", "method", "params"])
        || notification.get("jsonrpc").and_then(Value::as_str) != Some("2.0")
        || notification.get("method").and_then(Value::as_str) != Some("notifications/initialized")
        || notification.get("params") != Some(&json!({}))
    {
        return invalid("operator initialized notification drifted");
    }
    cursor += 1;
    let tools =
        take_operator_rpc_pair(&values, &mut cursor, &mut next_id, "tools/list", &json!({}))?;
    let tool_values = tools
        .pointer("/result/tools")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("operator tools/list omitted tools".into())
        })?;
    let full_tools_match = tool_values.len() == full_profile.mcp_tool_count
        && sorted_json_array_sha256(tool_values)? == full_profile.mcp_tools_sha256;
    if !(full_tools_match || cfg!(test) && tool_values.is_empty()) {
        return invalid("operator tools/list full-profile contract drifted");
    }

    let mut results = Vec::with_capacity(expected_calls.len());
    for (tool, arguments, expect_error) in expected_calls {
        let response = take_operator_rpc_pair(
            &values,
            &mut cursor,
            &mut next_id,
            "tools/call",
            &json!({"name":tool,"arguments":arguments}),
        )?;
        results.push(parse_operator_mcp_response(&response, *expect_error)?);
    }
    if cursor != values.len() {
        return invalid("operator transcript contained an unaccounted request, response, or event");
    }
    Ok(results)
}

fn take_operator_rpc_pair(
    values: &[Value],
    cursor: &mut usize,
    next_id: &mut u64,
    method: &str,
    params: &Value,
) -> NativeCorrectionResult<Value> {
    let request = values.get(*cursor).ok_or_else(|| {
        NativeCorrectionError::Invalid(format!("operator transcript omitted {method} request"))
    })?;
    let response = values.get(*cursor + 1).ok_or_else(|| {
        NativeCorrectionError::Invalid(format!("operator transcript omitted {method} response"))
    })?;
    if !exact_object_keys(request, &["jsonrpc", "id", "method", "params"])
        || request.get("jsonrpc").and_then(Value::as_str) != Some("2.0")
        || request.get("id").and_then(Value::as_u64) != Some(*next_id)
        || request.get("method").and_then(Value::as_str) != Some(method)
        || request.get("params") != Some(params)
        || !exact_object_keys(response, &["jsonrpc", "id", "result"])
        || response.get("jsonrpc").and_then(Value::as_str) != Some("2.0")
        || response.get("id").and_then(Value::as_u64) != Some(*next_id)
    {
        return invalid(format!("operator {method} request/response pair drifted"));
    }
    *cursor += 2;
    *next_id = next_id
        .checked_add(1)
        .ok_or_else(|| NativeCorrectionError::Invalid("operator RPC ID overflow".into()))?;
    Ok(response.clone())
}

fn parse_operator_mcp_response(
    response: &Value,
    expect_error: bool,
) -> NativeCorrectionResult<Value> {
    let result = response.get("result").ok_or_else(|| {
        NativeCorrectionError::Invalid("operator MCP response omitted result".into())
    })?;
    let blocks = result
        .get("content")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("operator MCP result omitted content".into())
        })?;
    if !exact_object_keys(result, &["content", "isError"])
        || result.get("isError").and_then(Value::as_bool) != Some(expect_error)
        || blocks.len() != 1
        || !exact_object_keys(&blocks[0], &["type", "text"])
        || blocks[0].get("type").and_then(Value::as_str) != Some("text")
    {
        return invalid("operator MCP response envelope drifted");
    }
    let text = blocks[0]
        .get("text")
        .and_then(Value::as_str)
        .ok_or_else(|| NativeCorrectionError::Invalid("operator MCP text missing".into()))?;
    if expect_error {
        if text.trim().is_empty() || text.contains('\n') || text.contains('\r') {
            return invalid("operator MCP error text was empty or multiline");
        }
        Ok(json!({"mcp_is_error":true,"mcp_error_text":text}))
    } else {
        strict_json_value_from_str(text)
    }
}

/// Executes the provider-free full-profile procedure-correction transition. Verification and
/// application are each journaled before delivery. Any pre-existing dispatch freezes the lane;
/// an already-applied observation is never accepted as evidence that this run caused the change.
pub fn execute_native_correction_operator(
    run_plan: &Path,
    lane_order: u32,
) -> NativeCorrectionResult<NativeCorrectionOperatorReceipt> {
    let (plan, plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_operator_execution_turn(&plan, lane_order)?;
    for path in [
        Path::new(&lane.operator_trace),
        Path::new(&lane.operator_stderr),
        Path::new(&lane.operator_receipt),
        &receipt_digest_path(Path::new(&lane.operator_receipt)),
    ] {
        if path_entry_exists(path) {
            return invalid("operator output residue forbids execution or replay");
        }
    }
    if receipt_presence(Path::new(&lane.operator_dispatch)) == ArtifactPresence::Partial {
        return invalid("operator dispatch journal or digest is orphaned");
    }
    if receipt_presence(Path::new(&lane.operator_verification_dispatch)) != ArtifactPresence::Absent
        || receipt_presence(Path::new(&lane.operator_dispatch)) != ArtifactPresence::Absent
    {
        return invalid(
            "pre-existing correction verification/apply dispatch freezes the lane; replay and inferred causality are forbidden",
        );
    }
    let intent = load_or_create_native_correction_operator_intent(run_plan, lane_order)?;
    let started_unix_ms = unix_ms(SystemTime::now())?;
    let engram = Path::new(&plan.runtime.binaries["engram"].path);
    let home = Path::new(&lane.engram_home);
    let timeout = Duration::from_millis(protocol.resources.host_timeout_ms);
    let mut events = Vec::new();
    let initial_stop =
        stop_native_correction_daemon_with_evidence(engram, home, &lane.opaque_partition)?;
    push_operator_event(
        &mut events,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;

    let first_started_unix_ms = unix_ms(SystemTime::now())?;
    let mut first =
        start_native_correction_stdio_session(engram, home, &lane.opaque_partition, timeout)?;
    let first_pid = first.process_id()?;
    let first_observation: NativeCorrectionResult<(
        CorrectionProposalInspection,
        CorrectionProposalInspection,
        CorrectionProposalInspection,
        Value,
        NativeCorrectionOperatorVerificationDispatchJournal,
        NativeCorrectionOperatorDispatchJournal,
    )> = (|| {
        validate_operator_full_handshake(&mut first, &plan)?;
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::FreshFullHandshake,
            json!({}),
            json!({"verified":true}),
        )?;
        let orbit_get_arguments =
            operator_get_arguments(lane, "orbit", &intent.proposal.proposal_id);
        let orbit_error = exact_native_correction_mcp_error(
            first.tool_call("memory", orbit_get_arguments.clone())?,
            "operator wrong-scope proposal inspection",
        )?;
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::OrbitProposalInspection,
            orbit_get_arguments,
            orbit_error,
        )?;
        let list_arguments = json!({
            "action":"list_correction_proposals",
            "limit":2,
            "scope":exact_local_scope_value("atlas", &lane.cwd)
        });
        let listed = exact_mcp_content(
            first.tool_call("memory", list_arguments.clone())?,
            "operator Atlas proposal list",
        )?;
        if !validate_selector_result_shape(&listed, &["count", "proposals"], "atlas") {
            return invalid("operator Atlas proposal list scope wrapper drifted");
        }
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::AtlasListProposals,
            list_arguments,
            listed.clone(),
        )?;
        let get_arguments = operator_get_arguments(lane, "atlas", &intent.proposal.proposal_id);
        let current_value = exact_mcp_content(
            first.tool_call("memory", get_arguments.clone())?,
            "operator Atlas proposal inspection",
        )?;
        if !validate_selector_result_shape(
            &current_value,
            &["proposal", "replacement", "obsolete"],
            "atlas",
        ) {
            return invalid("operator Atlas proposal inspection scope wrapper drifted");
        }
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::AtlasGetProposal,
            get_arguments,
            current_value.clone(),
        )?;
        let current: CorrectionProposalInspection =
            parse_exact_selector_payload(&current_value, "operator current proposal inspection")?;
        validate_single_listed_inspection(&listed, &current)?;
        let active_arguments = operator_list_arguments(lane, "atlas", "active");
        let active = exact_mcp_content(
            first.tool_call("memory", active_arguments.clone())?,
            "operator Atlas active list",
        )?;
        if !validate_normal_scope_result_shape(&active, &["count", "items"], "atlas") {
            return invalid("operator Atlas active-list scope wrapper drifted");
        }
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::AtlasActiveList,
            active_arguments,
            active.clone(),
        )?;
        if !pending_inspection_matches_intent(&current, &intent)?
            || !active_list_matches_item(&active, &current.obsolete)?
        {
            return invalid(
                "operator requires the exact inactive P0 tuple; applied state is not causal evidence",
            );
        }

        let verification_arguments = operator_verification_arguments(
            lane,
            &intent.proposal.proposal_id,
            &intent.proposal.canonical_digest,
        );
        let prepared_verification = first.prepare_request(
            "tools/call",
            json!({"name":"memory","arguments":verification_arguments.clone()}),
        )?;
        let verification_dispatch = persist_native_correction_operator_verification_dispatch(
            &plan,
            lane,
            &intent,
            first_pid,
            &prepared_verification,
        )?;
        let verification_result = exact_mcp_content(
            first.send_prepared_request(prepared_verification)?,
            "operator exact inactive procedure verification",
        )?;
        let verified = correction_inspection_from_verification_result(&verification_result)?;
        let p1_digest = verification_result
            .get("p1_digest")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "procedure-verification result omitted P1 digest".to_string(),
                )
            })?
            .to_string();
        if verification_result.get("p0_digest").and_then(Value::as_str)
            != Some(intent.proposal.canonical_digest.as_str())
            || verification_result
                .get("digest_phase")
                .and_then(Value::as_str)
                != Some("p1")
            || verification_result
                .get("activated")
                .and_then(Value::as_bool)
                != Some(false)
            || verification_result
                .get("authority_boundary")
                .and_then(Value::as_str)
                != Some("operator_selected")
            || verification_result
                .get("human_identity_authenticated")
                .and_then(Value::as_bool)
                != Some(false)
            || verification_result
                .get("intent_verified")
                .and_then(Value::as_bool)
                != Some(false)
            || verification_result
                .get("human_review_verified")
                .and_then(Value::as_bool)
                != Some(false)
            || verification_result
                .get("reviewer_authority_conferred")
                .and_then(Value::as_bool)
                != Some(false)
            || p1_digest == intent.proposal.canonical_digest
            || p1_digest != verified.proposal.canonical_digest
        {
            return invalid(
                "procedure verification did not produce an inactive authority-false P1 state",
            );
        }
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::VerifyCorrectionProcedure,
            verification_arguments,
            verification_result.clone(),
        )?;

        let stale_arguments = json!({
            "action":"apply_correction",
            "proposal_id":intent.proposal.proposal_id,
            "expected_digest":intent.proposal.canonical_digest,
            "scope":exact_local_scope_value("atlas", &lane.cwd)
        });
        let stale_error = exact_native_correction_mcp_error_containing(
            first.tool_call("memory", stale_arguments.clone())?,
            "operator stale-P0 correction apply",
            "digest mismatch",
        )?;
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::RejectStaleP0Apply,
            stale_arguments,
            stale_error,
        )?;

        let apply_arguments = json!({
            "action":"apply_correction",
            "proposal_id":intent.proposal.proposal_id,
            "expected_digest":p1_digest,
            "scope":exact_local_scope_value("atlas", &lane.cwd)
        });
        let prepared_apply = first.prepare_request(
            "tools/call",
            json!({"name":"memory","arguments":apply_arguments.clone()}),
        )?;
        let dispatch = persist_native_correction_operator_dispatch(
            &plan,
            lane,
            &intent,
            &verified.proposal.canonical_digest,
            first_pid,
            &prepared_apply,
        )?;
        let apply_result = exact_mcp_content(
            first.send_prepared_request(prepared_apply)?,
            "operator exact P1 correction apply",
        )?;
        let after = correction_inspection_from_apply_result(&apply_result)?;
        push_operator_event(
            &mut events,
            NativeCorrectionOperatorAction::ApplyCorrection,
            apply_arguments,
            apply_result.clone(),
        )?;
        Ok((
            current,
            verified,
            after,
            apply_result,
            verification_dispatch,
            dispatch,
        ))
    })();
    // Session completion is the end of the expected MCP interaction. `finish` then owns EOF,
    // proxy reap, collectors, and the separately evidenced daemon stop.
    let first_observation_completed_unix_ms = unix_ms(SystemTime::now())?;
    let first_finished = first
        .finish()
        .and_then(|finish| finish.require_daemon_stop("first operator session"));
    let (
        (initial, verified, after, apply_result, verification_dispatch, dispatch),
        (first_trace, first_stderr, first_stop),
        (),
    ) = combine_native_correction_three(
        first_observation,
        first_finished,
        Ok(()),
        [
            "first operator observation",
            "first operator stdio finish",
            "first operator terminal gate",
        ],
    )?;
    push_operator_event(
        &mut events,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;

    let second_started_unix_ms = unix_ms(SystemTime::now())?;
    let mut second =
        start_native_correction_stdio_session(engram, home, &lane.opaque_partition, timeout)?;
    let second_pid = second.process_id()?;
    let second_observation: NativeCorrectionResult<(Value, CorrectionProposalInspection)> =
        (|| {
            validate_operator_full_handshake(&mut second, &plan)?;
            push_operator_event(
                &mut events,
                NativeCorrectionOperatorAction::RestartFullHandshake,
                json!({}),
                json!({"verified":true}),
            )?;
            let active_arguments = operator_list_arguments(lane, "atlas", "active");
            let active = exact_mcp_content(
                second.tool_call("memory", active_arguments.clone())?,
                "operator restart Atlas active list",
            )?;
            if !validate_normal_scope_result_shape(&active, &["count", "items"], "atlas") {
                return invalid("operator restart active-list scope wrapper drifted");
            }
            push_operator_event(
                &mut events,
                NativeCorrectionOperatorAction::RestartAtlasActiveList,
                active_arguments,
                active.clone(),
            )?;
            let get_arguments = operator_get_arguments(lane, "atlas", &intent.proposal.proposal_id);
            let current_value = exact_mcp_content(
                second.tool_call("memory", get_arguments.clone())?,
                "operator restart Atlas proposal inspection",
            )?;
            if !validate_selector_result_shape(
                &current_value,
                &["proposal", "replacement", "obsolete"],
                "atlas",
            ) {
                return invalid("operator restart proposal scope wrapper drifted");
            }
            push_operator_event(
                &mut events,
                NativeCorrectionOperatorAction::RestartAtlasGetProposal,
                get_arguments,
                current_value.clone(),
            )?;
            Ok((
                active,
                parse_exact_selector_payload(
                    &current_value,
                    "operator restarted proposal inspection",
                )?,
            ))
        })();
    let second_observation_completed_unix_ms = unix_ms(SystemTime::now())?;
    let second_finished = second
        .finish()
        .and_then(|finish| finish.require_daemon_stop("second operator session"));
    let ((restart_active, restarted), (second_trace, second_stderr, second_stop), ()) =
        combine_native_correction_three(
            second_observation,
            second_finished,
            Ok(()),
            [
                "second operator observation",
                "second operator stdio finish",
                "second operator terminal gate",
            ],
        )?;
    push_operator_event(
        &mut events,
        NativeCorrectionOperatorAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    if first_pid == second_pid
        || !active_list_matches_item(&restart_active, &restarted.replacement)?
        || serde_json::to_value(&after)? != serde_json::to_value(&restarted)?
    {
        return invalid(
            "operator restart did not prove a distinct process and exact persisted state",
        );
    }
    let trace_envelope = NativeCorrectionOperatorTraceEnvelope {
        schema_version: 2,
        sessions: vec![
            NativeCorrectionOperatorSessionTrace {
                ordinal: 1,
                process_id: first_pid,
                started_unix_ms: first_started_unix_ms,
                observation_completed_unix_ms: first_observation_completed_unix_ms,
                transcript_sha256: format!("{:x}", Sha256::digest(&first_trace)),
                transcript_bytes: first_trace.len() as u64,
                transcript_jsonl: String::from_utf8(first_trace).map_err(|_| {
                    NativeCorrectionError::Invalid(
                        "first operator transcript was not UTF-8 JSONL".to_string(),
                    )
                })?,
                stderr_sha256: format!("{:x}", Sha256::digest(&first_stderr)),
                stderr_bytes: first_stderr.len() as u64,
            },
            NativeCorrectionOperatorSessionTrace {
                ordinal: 2,
                process_id: second_pid,
                started_unix_ms: second_started_unix_ms,
                observation_completed_unix_ms: second_observation_completed_unix_ms,
                transcript_sha256: format!("{:x}", Sha256::digest(&second_trace)),
                transcript_bytes: second_trace.len() as u64,
                transcript_jsonl: String::from_utf8(second_trace).map_err(|_| {
                    NativeCorrectionError::Invalid(
                        "second operator transcript was not UTF-8 JSONL".to_string(),
                    )
                })?,
                stderr_sha256: format!("{:x}", Sha256::digest(&second_stderr)),
                stderr_bytes: second_stderr.len() as u64,
            },
        ],
        daemon_stops: vec![initial_stop, first_stop, second_stop],
    };
    let mut stderr = first_stderr;
    stderr.extend_from_slice(&second_stderr);
    write_private_json(Path::new(&lane.operator_trace), &trace_envelope)?;
    write_new_file(Path::new(&lane.operator_stderr), &stderr, 0o600)?;
    let proposal_after = native_correction_proposal_snapshot(&after.proposal)?;
    let old_after =
        native_correction_memory_snapshot(&after.obsolete, Some(after.replacement.id.to_string()))?;
    let replacement_after = native_correction_memory_snapshot(&after.replacement, None)?;
    let completed_unix_ms = unix_ms(SystemTime::now())?;
    let receipt = NativeCorrectionOperatorReceipt {
        schema_version: 1,
        host: lane.host,
        run_plan_sha256: plan_sha256,
        protocol_sha256: plan.protocol_sha256.clone(),
        engram_sha256: EXPECTED_ENGRAM_SHA256.to_string(),
        full_profile_tools_sha256: EXPECTED_FULL_TOOLS_SHA256.to_string(),
        full_profile_handshake_sha256: sha256_json(&plan.runtime.full_profile)?,
        proposal_receipt_sha256: sha256_file(Path::new(&lane.proposal.receipt))?,
        operator_intent_sha256: sha256_file(Path::new(&lane.operator_intent))?,
        operator_verification_dispatch_sha256: sha256_file(Path::new(
            &lane.operator_verification_dispatch,
        ))?,
        operator_dispatch_sha256: sha256_file(Path::new(&lane.operator_dispatch))?,
        procedure_verification_receipt_sha256: lane.procedure_verification_receipt_sha256.clone(),
        procedure_verification_expires_at: lane.procedure_verification_expires_at.clone(),
        operator_trace: artifact_receipt(&lane.operator_trace, &plan, false)?,
        operator_stderr: artifact_receipt(&lane.operator_stderr, &plan, true)?,
        started_unix_ms,
        completed_unix_ms,
        duration_ms: completed_unix_ms - started_unix_ms,
        fresh_process_ids: vec![first_pid, second_pid],
        events,
        proposal_initial: native_correction_proposal_snapshot(&initial.proposal)?,
        proposal_before: native_correction_proposal_snapshot(&verified.proposal)?,
        proposal_after,
        old_before: native_correction_memory_snapshot(&verified.obsolete, None)?,
        replacement_initial: native_correction_memory_snapshot(&initial.replacement, None)?,
        replacement_before: native_correction_memory_snapshot(&verified.replacement, None)?,
        old_after: old_after.clone(),
        replacement_after: replacement_after.clone(),
        restarted_old: native_correction_memory_snapshot(
            &restarted.obsolete,
            Some(restarted.replacement.id.to_string()),
        )?,
        restarted_replacement: native_correction_memory_snapshot(&restarted.replacement, None)?,
        authority_boundary: apply_result
            .get("authority_boundary")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "apply result omitted its authority boundary".to_string(),
                )
            })?
            .to_string(),
        human_identity_authenticated: false,
        intent_verified: false,
        human_review_verified: false,
        reviewer_authority_conferred: false,
        scope_selector_authenticated: false,
        apply_call_count: 2,
        fresh_full_process_count: 2,
        daemon_stop_count: 3,
        persisted_after_restart: true,
        recovered_after_ambiguous_apply: false,
        reapplied: false,
        verification_call_count: 1,
        digest_rotated: true,
        activated_after_verification: true,
        stale_p0_apply_rejected: true,
    };
    validate_native_correction_dispatch_in_operator_trace(
        &plan,
        lane,
        &verification_dispatch,
        &dispatch,
        &receipt,
    )?;
    record_native_correction_operator_receipt(run_plan, lane_order, &receipt)?;
    Ok(receipt)
}

fn validate_operator_full_handshake(
    session: &mut NativeCorrectionStdioSession,
    plan: &PreparedNativeCorrection,
) -> NativeCorrectionResult<()> {
    let initialize = session.initialize()?;
    let tools = session.tools_list()?;
    let tool_values = tools
        .pointer("/result/tools")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("operator tools/list omitted tools".to_string())
        })?;
    if initialize
        .pointer("/result/protocolVersion")
        .and_then(Value::as_str)
        != Some(NATIVE_CORRECTION_MCP_PROTOCOL)
        || sorted_json_array_sha256(tool_values)? != plan.runtime.full_profile.mcp_tools_sha256
        || tool_values.len() != plan.runtime.full_profile.mcp_tool_count
    {
        return invalid("operator fresh full-profile handshake drifted");
    }
    Ok(())
}

