fn exact_native_correction_mcp_error(
    response: NativeCorrectionMcpResponse,
    label: &str,
) -> NativeCorrectionResult<Value> {
    exact_native_correction_mcp_error_containing(
        response,
        label,
        "outside the resolved correction authorization boundary",
    )
}

fn exact_native_correction_mcp_error_containing(
    response: NativeCorrectionMcpResponse,
    label: &str,
    expected_fragment: &str,
) -> NativeCorrectionResult<Value> {
    if response.content.is_some()
        || response
            .raw
            .pointer("/result/isError")
            .and_then(Value::as_bool)
            != Some(true)
    {
        return invalid(format!("Engram {label} was not an MCP error"));
    }
    let blocks = response
        .raw
        .pointer("/result/content")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("Engram {label} omitted content")))?;
    if blocks.len() != 1 || blocks[0].get("type").and_then(Value::as_str) != Some("text") {
        return invalid(format!(
            "Engram {label} returned a non-exact error envelope"
        ));
    }
    let text = blocks[0]
        .get("text")
        .and_then(Value::as_str)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("Engram {label} omitted text")))?;
    if !text.starts_with("invalid state:") || !text.contains(expected_fragment) {
        return invalid(format!("Engram {label} returned an unexpected error"));
    }
    Ok(json!({"mcp_is_error":true,"mcp_error_text":text}))
}

fn correction_inspection_from_verification_result(
    result: &Value,
) -> NativeCorrectionResult<CorrectionProposalInspection> {
    if !validate_selector_result_shape(
        result,
        &[
            "proposal",
            "replacement",
            "obsolete",
            "p0_digest",
            "p1_digest",
            "digest_phase",
            "activated",
            "authority_boundary",
            "human_identity_authenticated",
            "intent_verified",
            "human_review_verified",
            "reviewer_authority_conferred",
        ],
        "atlas",
    ) {
        return invalid("procedure-verification result scope wrapper drifted");
    }
    Ok(CorrectionProposalInspection {
        proposal: parse_exact_domain(
            result.get("proposal").ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "procedure-verification result omitted proposal".to_string(),
                )
            })?,
            "operator verified proposal",
        )?,
        replacement: parse_exact_domain(
            result.get("replacement").ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "procedure-verification result omitted replacement".to_string(),
                )
            })?,
            "operator verified replacement",
        )?,
        obsolete: parse_exact_domain(
            result.get("obsolete").ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "procedure-verification result omitted obsolete".to_string(),
                )
            })?,
            "operator verified obsolete",
        )?,
    })
}

fn validate_single_listed_inspection(
    listed: &Value,
    current: &CorrectionProposalInspection,
) -> NativeCorrectionResult<()> {
    if !validate_selector_result_shape(listed, &["count", "proposals"], "atlas") {
        return invalid("proposal list scope wrapper drifted");
    }
    let values = listed
        .get("proposals")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("proposal list omitted proposals".to_string())
        })?;
    if listed.get("count").and_then(Value::as_u64) != Some(1)
        || values.len() != 1
        || values[0] != serde_json::to_value(current)?
    {
        return invalid("proposal list/get surfaces disagreed");
    }
    Ok(())
}

fn active_list_matches_item(listed: &Value, expected: &MemoryItem) -> NativeCorrectionResult<bool> {
    if !validate_normal_scope_result_shape(listed, &["count", "items"], "atlas") {
        return invalid("active-list scope wrapper drifted");
    }
    let values = listed
        .get("items")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid("active list omitted items".to_string()))?;
    Ok(listed.get("count").and_then(Value::as_u64) == Some(1)
        && values.len() == 1
        && values[0] == serde_json::to_value(expected)?)
}

fn pending_inspection_matches_intent(
    current: &CorrectionProposalInspection,
    intent: &NativeCorrectionOperatorIntent,
) -> NativeCorrectionResult<bool> {
    Ok(
        native_correction_proposal_snapshot(&current.proposal)? == intent.proposal
            && native_correction_memory_snapshot(&current.obsolete, None)? == intent.old
            && native_correction_memory_snapshot(&current.replacement, None)? == intent.replacement,
    )
}

fn correction_inspection_from_apply_result(
    result: &Value,
) -> NativeCorrectionResult<CorrectionProposalInspection> {
    if !validate_selector_result_shape(
        result,
        &[
            "proposal",
            "item",
            "corrected_item",
            "authority_boundary",
            "human_identity_authenticated",
            "intent_verified",
            "reviewer_authority_conferred",
        ],
        "atlas",
    ) {
        return invalid("apply result scope wrapper drifted");
    }
    Ok(CorrectionProposalInspection {
        proposal: parse_exact_domain(
            result.get("proposal").ok_or_else(|| {
                NativeCorrectionError::Invalid("apply result omitted proposal".to_string())
            })?,
            "operator applied proposal",
        )?,
        replacement: parse_exact_domain(
            result.get("item").ok_or_else(|| {
                NativeCorrectionError::Invalid("apply result omitted replacement".to_string())
            })?,
            "operator applied replacement",
        )?,
        obsolete: parse_exact_domain(
            result.get("corrected_item").ok_or_else(|| {
                NativeCorrectionError::Invalid("apply result omitted obsolete item".to_string())
            })?,
            "operator applied obsolete memory",
        )?,
    })
}

fn push_operator_event(
    events: &mut Vec<NativeCorrectionOperatorEvent>,
    action: NativeCorrectionOperatorAction,
    arguments: Value,
    result: Value,
) -> NativeCorrectionResult<()> {
    events.push(NativeCorrectionOperatorEvent {
        ordinal: u32::try_from(events.len() + 1)
            .map_err(|_| NativeCorrectionError::Invalid("operator ordinal overflow".to_string()))?,
        action,
        arguments,
        result_bytes: serde_json::to_vec(&result)?.len() as u64,
        result,
    });
    Ok(())
}

