fn native_correction_cleanup_paths(
    lane: &PreparedNativeCorrectionLane,
) -> NativeCorrectionResult<NativeCorrectionCleanupPaths> {
    let root = Path::new(&lane.operator_receipt).parent().ok_or_else(|| {
        NativeCorrectionError::Invalid("operator receipt has no lane root".to_string())
    })?;
    validate_absolute_normal_path(root, "cleanup lane root")?;
    Ok(NativeCorrectionCleanupPaths {
        intent: root.join("cleanup-intent.json"),
        trace: root.join("cleanup-trace.json"),
        stderr: root.join("cleanup-stderr.txt"),
        receipt: root.join("cleanup-receipt.json"),
        vault: root.join("cleanup-vault"),
    })
}

