fn parse_exact_normal_scope_payload<T>(value: &Value, label: &str) -> NativeCorrectionResult<T>
where
    T: DeserializeOwned + Serialize,
{
    let mut payload = value.clone();
    let object = payload
        .as_object_mut()
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} was not an object")))?;
    for key in NORMAL_SCOPE_RESULT_KEYS {
        if object.remove(key).is_none() {
            return invalid(format!("{label} omitted scope field {key}"));
        }
    }
    parse_exact_domain(&payload, label)
}

fn exact_native_correction_mcp_error_text(
    response: NativeCorrectionMcpResponse,
    label: &str,
    expected_text: &str,
) -> NativeCorrectionResult<Value> {
    if response.content.is_some()
        || response
            .raw
            .pointer("/result/isError")
            .and_then(Value::as_bool)
            != Some(true)
    {
        return invalid(format!("Engram {label} was not an MCP error"));
    }
    let blocks = response
        .raw
        .pointer("/result/content")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("Engram {label} omitted content")))?;
    if blocks.len() != 1
        || !exact_object_keys(&blocks[0], &["type", "text"])
        || blocks[0].get("type").and_then(Value::as_str) != Some("text")
        || blocks[0].get("text").and_then(Value::as_str) != Some(expected_text)
    {
        return invalid(format!("Engram {label} returned an unexpected error"));
    }
    Ok(json!({"mcp_is_error":true,"mcp_error_text":expected_text}))
}

fn validate_cleanup_abstention(
    lane: &PreparedNativeCorrectionLane,
    value: &Value,
    label: &str,
) -> NativeCorrectionResult<ProcedureMatchReport> {
    let report: ProcedureMatchReport = parse_exact_normal_scope_payload(value, label)?;
    if !validate_normal_scope_result_shape(
        value,
        &[
            "query",
            "identity",
            "resolution",
            "procedures",
            "diagnostics",
            "abstained",
            "message",
            "required_condition_keys",
            "next_actions",
            "current_checkout_root",
            "execution_guidance",
        ],
        "atlas",
    ) && !validate_normal_scope_result_shape(
        value,
        &[
            "query",
            "identity",
            "resolution",
            "procedures",
            "diagnostics",
            "abstained",
            "message",
            "required_condition_keys",
            "next_actions",
            "suggested_operation_evidence",
            "current_checkout_root",
            "execution_guidance",
        ],
        "atlas",
    ) {
        return invalid(format!(
            "{label} scope wrapper or closed-world keys drifted"
        ));
    }
    if report.query != EXPECTED_PROCEDURE_TASK
        || !report.abstained
        || !report.procedures.is_empty()
        || !report.diagnostics.is_empty()
        || report.current_checkout_root.as_deref() != Some(lane.cwd.as_str())
        || report
            .suggested_operation_evidence
            .as_ref()
            .is_some_and(|candidate| candidate.authorizes_procedure_execution)
    {
        return invalid(format!(
            "{label} did not prove exact archived/forgotten procedure abstention"
        ));
    }
    Ok(report)
}

fn validate_cleanup_scoped_result_shape(
    value: &Value,
    payload: &[&str],
    surface: &str,
    project: Option<&str>,
) -> bool {
    let local = project.is_some();
    exact_object_keys_with(value, payload, &NORMAL_SCOPE_RESULT_KEYS)
        && value
            .get("authorization_scope_enforced")
            .and_then(Value::as_bool)
            == Some(local)
        && value.get("scope_enforced_layers")
            == Some(&json!(if local {
                vec![surface]
            } else {
                Vec::<&str>::new()
            }))
        && value.get("relevance_mode").and_then(Value::as_str)
            == Some(if local { "local" } else { "global" })
        && value.get("resolved_project") == Some(&project.map_or(Value::Null, |value| json!(value)))
        && value.get("resolved_task").is_some_and(Value::is_null)
        && value.get("omitted_layers") == Some(&json!([]))
        && value.get("warnings")
            == Some(&json!([if local {
                format!("Local mode enforced a directly resolved {surface} boundary.")
            } else {
                format!(
                    "Global mode explicitly accessed {surface} records across all projects; results may belong to unrelated projects."
                )
            }]))
}

fn cleanup_result_excludes(value: &Value, forbidden: &[&str]) -> NativeCorrectionResult<()> {
    let encoded = serde_json::to_string(value)?;
    if forbidden.iter().any(|needle| encoded.contains(needle)) {
        return invalid("forgotten correction data remained in a post-restart projection");
    }
    Ok(())
}

fn validate_cleanup_predelete_derived_graph(
    value: &Value,
    intent: &NativeCorrectionCleanupIntent,
) -> NativeCorrectionResult<()> {
    if !validate_cleanup_scoped_result_shape(value, &["nodes", "edges"], "graph", None) {
        return invalid("cleanup pre-delete derived graph scope wrapper drifted");
    }
    let nodes = value
        .get("nodes")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid("cleanup graph omitted nodes".into()))?;
    let edges = value
        .get("edges")
        .and_then(Value::as_array)
        .ok_or_else(|| NativeCorrectionError::Invalid("cleanup graph omitted edges".into()))?;
    let obsolete = format!("memory:{}", intent.obsolete_id);
    let replacement = format!("memory:{}", intent.replacement_id);
    let commit = format!("commit:{}", intent.projection_commit_id);
    let node_count = |expected: &str| {
        nodes
            .iter()
            .filter(|node| node.get("id").and_then(Value::as_str) == Some(expected))
            .count()
    };
    let edge_count = |from: &str, to: &str, relation: &str| {
        edges
            .iter()
            .filter(|edge| {
                edge.get("from").and_then(Value::as_str) == Some(from)
                    && edge.get("to").and_then(Value::as_str) == Some(to)
                    && edge.get("relation").and_then(Value::as_str) == Some(relation)
            })
            .count()
    };
    if node_count(&obsolete) != 1
        || node_count(&replacement) != 1
        || node_count(&commit) != 1
        || edge_count(&replacement, &obsolete, "supersedes") != 1
        || edge_count(&commit, &obsolete, "added") != 1
    {
        return invalid(
            "cleanup pre-delete derived graph did not contain each seeded node and edge exactly once",
        );
    }
    Ok(())
}

fn validate_cleanup_restart_derived_graph(value: &Value) -> NativeCorrectionResult<()> {
    if !validate_cleanup_scoped_result_shape(value, &["nodes", "edges"], "graph", None)
        || value.get("nodes") != Some(&json!([]))
        || value.get("edges") != Some(&json!([]))
    {
        return invalid("cleanup restart derived graph around forgotten ID was not empty");
    }
    Ok(())
}

fn validate_cleanup_archived_item(
    _lane: &PreparedNativeCorrectionLane,
    expected: &NativeCorrectionMemorySnapshot,
    archived: &MemoryItem,
    earliest_unix_ms: u64,
) -> NativeCorrectionResult<()> {
    let actual = native_correction_memory_snapshot(archived, None)?;
    let archive = archived.archive.as_ref().ok_or_else(|| {
        NativeCorrectionError::Invalid("archived replacement omitted metadata".to_string())
    })?;
    let archived_at_unix_ms = u64::try_from(archive.archived_at.unix_timestamp_nanos() / 1_000_000)
        .map_err(|_| NativeCorrectionError::Invalid("archive timestamp predates epoch".into()))?;
    let mut normalized = actual.clone();
    normalized.status = NativeCorrectionMemoryStatus::Active;
    normalized.updated_at = expected.updated_at.clone();
    normalized.archive = None;
    normalized.canonical_item_sha256 = expected.canonical_item_sha256.clone();
    if normalized != *expected
        || actual.id != expected.id
        || actual.status != NativeCorrectionMemoryStatus::Archived
        || archive.reason != CLEANUP_ARCHIVE_REASON
        || archive.archived_by.as_deref() != Some(CLEANUP_ARCHIVED_BY)
        || archived_at_unix_ms < earliest_unix_ms
        || archived.updated_at != archive.archived_at
    {
        return invalid("archive did not preserve the exact replacement while suppressing it");
    }
    Ok(())
}

fn parse_cleanup_forget_result(
    value: &Value,
    expected_id: &str,
    expected_reason: &str,
) -> NativeCorrectionResult<NativeCorrectionForgetResult> {
    let result: NativeCorrectionForgetResult = parse_exact_domain(value, "cleanup forget result")?;
    if result.id != expected_id
        || result.reason != expected_reason
        || !result.deleted
        || !result.canonical_store_purged
        || result.internal_purge.id.to_string() != expected_id
        || !result.internal_purge.deleted
        || result.internal_purge.cleanup_resumed
        || !result.internal_purge.projection_counts_complete
        || result.vault_refresh.is_null()
        || result.warnings
            != vec![
                "External copies outside the selected generated vault must be deleted separately."
                    .to_string(),
            ]
    {
        return invalid("cleanup forget result lost exact-ID, purge, or fresh-call evidence");
    }
    Ok(result)
}

fn validate_cleanup_vault_refresh(
    value: &Value,
    expected_root: &str,
    expected_memory_items: u64,
    expected_commits: u64,
    expected_removed_id: Option<&str>,
) -> bool {
    let removed = value.get("files_removed").and_then(Value::as_array);
    exact_object_keys(
        value,
        &[
            "root",
            "files_written",
            "files_skipped",
            "files_removed",
            "memory_item_count",
            "knowledge_commit_count",
            "repository_count",
            "entity_count",
            "project_count",
        ],
    ) && value.get("root").and_then(Value::as_str) == Some(expected_root)
        && value
            .get("files_written")
            .and_then(Value::as_array)
            .is_some_and(|files| !files.is_empty())
        && value.get("files_skipped") == Some(&json!([]))
        && value.get("memory_item_count").and_then(Value::as_u64) == Some(expected_memory_items)
        && value.get("knowledge_commit_count").and_then(Value::as_u64) == Some(expected_commits)
        && value.get("repository_count").and_then(Value::as_u64) == Some(1)
        && value.get("entity_count").and_then(Value::as_u64) == Some(0)
        && value.get("project_count").and_then(Value::as_u64) == Some(2)
        && match expected_removed_id {
            None => removed.is_some_and(Vec::is_empty),
            Some(id) => removed.is_some_and(|files| {
                files.len() == 1
                    && files[0]
                        .as_str()
                        .is_some_and(|path| path.starts_with("memory/items/") && path.contains(id))
            }),
        }
}

fn scan_native_correction_cleanup_vault(
    path: &Path,
    forbidden: &[&str],
    allowed_other_scope: Option<(&str, &str)>,
) -> NativeCorrectionResult<(Vec<NativeCorrectionCleanupVaultFile>, u64)> {
    validate_absolute_normal_path(path, "cleanup vault")?;
    if path_has_symlink_component(path)? || !path.is_dir() || path.canonicalize()? != path {
        return invalid("cleanup vault was absent, symlinked, or non-canonical");
    }
    let mut pending = vec![path.to_path_buf()];
    let mut files = Vec::new();
    let mut total_bytes = 0u64;
    let mut other_scope_exact_count = 0usize;
    let mut other_scope_marker_count = 0usize;
    while let Some(directory) = pending.pop() {
        let mut entries = fs::read_dir(&directory)?.collect::<Result<Vec<_>, _>>()?;
        entries.sort_by_key(|entry| entry.file_name());
        for entry in entries.into_iter().rev() {
            let entry_path = entry.path();
            let metadata = fs::symlink_metadata(&entry_path)?;
            if metadata.file_type().is_symlink() {
                return invalid("cleanup vault contained a symlink");
            }
            if metadata.is_dir() {
                pending.push(entry_path);
                continue;
            }
            if !metadata.is_file() {
                return invalid("cleanup vault contained a non-regular entry");
            }
            let bytes = read_bounded_attested_file(
                &entry_path,
                4 * 1024 * 1024,
                "cleanup vault projection",
            )?;
            let text = std::str::from_utf8(&bytes).map_err(|_| {
                NativeCorrectionError::Invalid("cleanup vault projection was not UTF-8".to_string())
            })?;
            let relative = entry_path.strip_prefix(path).map_err(|_| {
                NativeCorrectionError::Invalid("cleanup vault file escaped its root".to_string())
            })?;
            let relative = relative.to_str().ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "cleanup vault relative path was not UTF-8".to_string(),
                )
            })?;
            if forbidden
                .iter()
                .any(|needle| relative.contains(needle) || text.contains(needle))
            {
                return invalid("forgotten correction data remained in the generated vault");
            }
            if let Some((allowed_path, allowed_content)) = allowed_other_scope {
                let exact_count = relative.matches(allowed_content).count()
                    + text.matches(allowed_content).count();
                let marker_count = relative.matches("EVAL_OTHER_SCOPE_").count()
                    + text.matches("EVAL_OTHER_SCOPE_").count();
                if (exact_count != 0 || marker_count != 0)
                    && (relative != allowed_path || exact_count != 1 || marker_count != 1)
                {
                    return invalid(
                        "other-scope canary escaped its exact generated-vault item projection",
                    );
                }
                other_scope_exact_count += exact_count;
                other_scope_marker_count += marker_count;
            } else if relative.contains("EVAL_OTHER_SCOPE_") || text.contains("EVAL_OTHER_SCOPE_") {
                return invalid("other-scope canary appeared in an unallowlisted generated vault");
            }
            total_bytes = total_bytes.checked_add(bytes.len() as u64).ok_or_else(|| {
                NativeCorrectionError::Invalid("cleanup vault size overflowed".to_string())
            })?;
            if files.len() >= 256 || total_bytes > 4 * 1024 * 1024 {
                return invalid("cleanup vault exceeded its bounded projection scan");
            }
            files.push(NativeCorrectionCleanupVaultFile {
                relative_path: relative.to_string(),
                sha256: format!("{:x}", Sha256::digest(&bytes)),
                bytes: bytes.len() as u64,
            });
        }
    }
    files.sort_by(|left, right| left.relative_path.cmp(&right.relative_path));
    if allowed_other_scope.is_some()
        && (other_scope_exact_count != 1 || other_scope_marker_count != 1)
    {
        return invalid(
            "generated vault omitted or duplicated the exact surviving other-scope projection",
        );
    }
    Ok((files, total_bytes))
}

fn cleanup_presence(
    lane: &PreparedNativeCorrectionLane,
) -> NativeCorrectionResult<ArtifactPresence> {
    let paths = native_correction_cleanup_paths(lane)?;
    let intent = receipt_presence(&paths.intent);
    let receipt = receipt_presence(&paths.receipt);
    let trace = path_entry_exists(&paths.trace);
    let stderr = path_entry_exists(&paths.stderr);
    let vault = path_entry_exists(&paths.vault);
    Ok(match (intent, trace, stderr, receipt, vault) {
        (ArtifactPresence::Absent, false, false, ArtifactPresence::Absent, false) => {
            ArtifactPresence::Absent
        }
        (ArtifactPresence::Complete, true, true, ArtifactPresence::Complete, true) => {
            ArtifactPresence::Complete
        }
        _ => ArtifactPresence::Partial,
    })
}

fn require_cleanup_turn(
    plan: &PreparedNativeCorrection,
    lane_order: u32,
    allow_current_intent: bool,
) -> NativeCorrectionResult<()> {
    if plan.lanes.iter().any(|lane| {
        phase_presence(&lane.proposal) != ArtifactPresence::Complete
            || operator_presence(lane) != ArtifactPresence::Complete
            || phase_presence(&lane.retrieval) != ArtifactPresence::Complete
    }) {
        return invalid("cleanup requires every proposal, operator, and retrieval receipt");
    }
    for lane in &plan.lanes {
        let cleanup = cleanup_presence(lane)?;
        if lane.order < lane_order && cleanup != ArtifactPresence::Complete {
            return invalid("cleanup lanes must complete in frozen order");
        }
        if lane.order == lane_order
            && allow_current_intent
            && cleanup == ArtifactPresence::Partial
            && cleanup_has_only_intent(lane)?
        {
            continue;
        }
        if lane.order >= lane_order && cleanup != ArtifactPresence::Absent {
            return invalid("refusing cleanup replay, residue, or out-of-order execution");
        }
    }
    Ok(())
}

fn cleanup_has_only_intent(lane: &PreparedNativeCorrectionLane) -> NativeCorrectionResult<bool> {
    let paths = native_correction_cleanup_paths(lane)?;
    Ok(
        receipt_presence(&paths.intent) == ArtifactPresence::Complete
            && !path_entry_exists(&paths.trace)
            && !path_entry_exists(&paths.stderr)
            && receipt_presence(&paths.receipt) == ArtifactPresence::Absent
            && !path_entry_exists(&paths.vault),
    )
}

fn validate_native_correction_cleanup_intent(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionCleanupIntent,
) -> NativeCorrectionResult<()> {
    let paths = native_correction_cleanup_paths(lane)?;
    let expected_plan = Path::new(&plan.protocol)
        .with_file_name("run-plan.json")
        .canonicalize()?;
    let (observed_plan, run_plan_sha256): (PreparedNativeCorrection, _) =
        read_digest_bound_strict_json(
            &expected_plan,
            &expected_plan.with_file_name("run-plan.sha256"),
            4 * 1024 * 1024,
            "cleanup-intent run plan",
        )?;
    let (operator, operator_receipt_sha256): (NativeCorrectionOperatorReceipt, _) =
        read_digest_bound_strict_json(
            Path::new(&lane.operator_receipt),
            &receipt_digest_path(Path::new(&lane.operator_receipt)),
            8 * 1024 * 1024,
            "cleanup-intent operator receipt",
        )?;
    validate_recorded_native_correction_operator_receipt(plan, lane, &operator)?;
    let (retrieval, retrieval_receipt_sha256) = read_and_validate_provider_receipt_with_digest(
        plan,
        lane,
        NativeCorrectionProviderPhase::Retrieval,
    )?;
    let seed = load_lane_seed_receipt(lane)?;
    let vault = canonical_string_allow_missing(&paths.vault)?;
    if observed_plan != *plan
        || intent.schema_version != 1
        || intent.family != NATIVE_CORRECTION_FAMILY
        || intent.pilot_id != plan.pilot_id
        || intent.run_plan != expected_plan.display().to_string()
        || intent.run_plan_sha256 != run_plan_sha256
        || intent.lane_order != lane.order
        || intent.host != lane.host
        || intent.operator_receipt_sha256 != operator_receipt_sha256
        || intent.retrieval_receipt_sha256 != retrieval_receipt_sha256
        || intent.proposal_id != operator.proposal_after.proposal_id
        || intent.obsolete_id != operator.old_after.id
        || intent.replacement_id != operator.replacement_after.id
        || intent.other_scope_id != lane.other_scope_id
        || intent.other_scope_id != seed.other_scope.id
        || intent.projection_commit_id != seed.projection_commit_id
        || intent.projection_trace_id != seed.projection_trace_id
        || intent.projection_feedback_id != seed.projection_feedback_id
        || intent.tag != lane.tag
        || intent.cwd != lane.cwd
        || intent.vault_path != vault
        || intent.archive_arguments != cleanup_archive_arguments(intent)
        || intent.procedure_match_arguments != cleanup_procedure_match_arguments(lane)
        || intent.forget_replacement_arguments
            != cleanup_forget_arguments(
                &intent.replacement_id,
                CLEANUP_FORGET_REPLACEMENT_REASON,
                &vault,
            )
        || intent.forget_obsolete_arguments
            != cleanup_forget_arguments(&intent.obsolete_id, CLEANUP_FORGET_OBSOLETE_REASON, &vault)
        || intent.created_unix_ms < retrieval.completed_unix_ms
    {
        return invalid("cleanup intent lost its exact receipts, IDs, scope, or mutation tuple");
    }
    Ok(())
}

pub fn create_native_correction_cleanup_intent(
    run_plan: &Path,
    lane_order: u32,
) -> NativeCorrectionResult<NativeCorrectionCleanupIntent> {
    let (plan, run_plan_sha256, _) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    require_cleanup_turn(&plan, lane_order, false)?;
    let paths = native_correction_cleanup_paths(lane)?;
    for path in [
        &paths.intent,
        &receipt_digest_path(&paths.intent),
        &paths.trace,
        &paths.stderr,
        &paths.receipt,
        &receipt_digest_path(&paths.receipt),
        &paths.vault,
    ] {
        if path_entry_exists(path) {
            return invalid("cleanup output residue forbids intent creation or replay");
        }
    }
    let (operator, operator_receipt_sha256): (NativeCorrectionOperatorReceipt, _) =
        read_digest_bound_strict_json(
            Path::new(&lane.operator_receipt),
            &receipt_digest_path(Path::new(&lane.operator_receipt)),
            8 * 1024 * 1024,
            "cleanup operator receipt",
        )?;
    validate_recorded_native_correction_operator_receipt(&plan, lane, &operator)?;
    let (retrieval, retrieval_receipt_sha256) = read_and_validate_provider_receipt_with_digest(
        &plan,
        lane,
        NativeCorrectionProviderPhase::Retrieval,
    )?;
    let seed = load_lane_seed_receipt(lane)?;
    let vault = canonical_string_allow_missing(&paths.vault)?;
    let mut intent = NativeCorrectionCleanupIntent {
        schema_version: 1,
        family: NATIVE_CORRECTION_FAMILY.to_string(),
        pilot_id: plan.pilot_id.clone(),
        run_plan: run_plan.canonicalize()?.display().to_string(),
        run_plan_sha256,
        lane_order,
        host: lane.host,
        operator_receipt_sha256,
        retrieval_receipt_sha256,
        proposal_id: operator.proposal_after.proposal_id.clone(),
        obsolete_id: operator.old_after.id.clone(),
        replacement_id: operator.replacement_after.id.clone(),
        other_scope_id: seed.other_scope.id,
        projection_commit_id: seed.projection_commit_id,
        projection_trace_id: seed.projection_trace_id,
        projection_feedback_id: seed.projection_feedback_id,
        tag: lane.tag.clone(),
        cwd: lane.cwd.clone(),
        vault_path: vault.clone(),
        archive_arguments: Value::Null,
        procedure_match_arguments: cleanup_procedure_match_arguments(lane),
        forget_replacement_arguments: Value::Null,
        forget_obsolete_arguments: Value::Null,
        created_unix_ms: unix_ms(SystemTime::now())?.max(retrieval.completed_unix_ms),
    };
    intent.archive_arguments = cleanup_archive_arguments(&intent);
    intent.forget_replacement_arguments = cleanup_forget_arguments(
        &intent.replacement_id,
        CLEANUP_FORGET_REPLACEMENT_REASON,
        &vault,
    );
    intent.forget_obsolete_arguments =
        cleanup_forget_arguments(&intent.obsolete_id, CLEANUP_FORGET_OBSOLETE_REASON, &vault);
    validate_native_correction_cleanup_intent(&plan, lane, &intent)?;
    write_private_json(&paths.intent, &intent)?;
    write_private_text(
        &receipt_digest_path(&paths.intent),
        &(sha256_file(&paths.intent)? + "\n"),
    )?;
    Ok(intent)
}

fn load_or_create_native_correction_cleanup_intent(
    run_plan: &Path,
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
) -> NativeCorrectionResult<NativeCorrectionCleanupIntent> {
    require_cleanup_turn(plan, lane.order, true)?;
    let paths = native_correction_cleanup_paths(lane)?;
    match receipt_presence(&paths.intent) {
        ArtifactPresence::Absent => create_native_correction_cleanup_intent(run_plan, lane.order),
        ArtifactPresence::Complete if cleanup_has_only_intent(lane)? => {
            let (intent, _): (NativeCorrectionCleanupIntent, _) = read_digest_bound_strict_json(
                &paths.intent,
                &receipt_digest_path(&paths.intent),
                8 * 1024 * 1024,
                "cleanup intent",
            )?;
            validate_native_correction_cleanup_intent(plan, lane, &intent)?;
            Ok(intent)
        }
        ArtifactPresence::Complete | ArtifactPresence::Partial => {
            invalid("cleanup intent or output residue forbids execution")
        }
    }
}

/// Irreversibly removes only the two isolated correction fixture records after both fresh-host
/// retrieval receipts exist. The exact archive/forget tuple is durably recorded before the first
/// mutation; any residue freezes the lane, so a retry can never masquerade as causal evidence.
pub fn execute_native_correction_cleanup(
    run_plan: &Path,
    lane_order: u32,
) -> NativeCorrectionResult<NativeCorrectionCleanupReceipt> {
    let (plan, run_plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let lane = lane_by_order(&plan, lane_order)?;
    let paths = native_correction_cleanup_paths(lane)?;
    let intent = load_or_create_native_correction_cleanup_intent(run_plan, &plan, lane)?;
    let (operator, _): (NativeCorrectionOperatorReceipt, _) = read_digest_bound_strict_json(
        Path::new(&lane.operator_receipt),
        &receipt_digest_path(Path::new(&lane.operator_receipt)),
        8 * 1024 * 1024,
        "cleanup operator receipt",
    )?;
    let started_unix_ms = unix_ms(SystemTime::now())?.max(intent.created_unix_ms);
    let engram = Path::new(&plan.runtime.binaries["engram"].path);
    let home = Path::new(&lane.engram_home);
    let timeout = Duration::from_millis(protocol.resources.host_timeout_ms);
    let mut events = Vec::new();
    let initial_stop =
        stop_native_correction_daemon_with_evidence(engram, home, &lane.opaque_partition)?;
    push_cleanup_event(
        &mut events,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;

    let first_started_unix_ms = unix_ms(SystemTime::now())?;
    let mut first =
        start_native_correction_stdio_session(engram, home, &lane.opaque_partition, timeout)?;
    let first_pid = first.process_id()?;
    let first_observation: NativeCorrectionResult<(
        MemoryItem,
        MemoryForgetReport,
        MemoryForgetReport,
    )> = (|| {
        validate_operator_full_handshake(&mut first, &plan)?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::FreshFullHandshake,
            json!({}),
            json!({"verified":true}),
        )?;

        let memory_reference_arguments = cleanup_other_scope_get_arguments(lane, &intent);
        let memory_reference = exact_mcp_content(
            first.tool_call("memory", memory_reference_arguments.clone())?,
            "cleanup pre-delete surviving-memory reference",
        )?;
        let memory_reference_text = serde_json::to_string(&memory_reference)?;
        if !validate_normal_scope_result_shape(&memory_reference, &["item"], "orbit")
            || memory_reference.pointer("/item/id").and_then(Value::as_str)
                != Some(intent.other_scope_id.as_str())
            || memory_reference_text.matches(&intent.obsolete_id).count() != 1
        {
            return invalid(
                "cleanup pre-delete surviving-memory reference count was not exactly one",
            );
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::PredeleteMemoryReference,
            memory_reference_arguments,
            memory_reference,
        )?;

        let graph_arguments = cleanup_derived_graph_arguments(&intent);
        let graph = exact_mcp_content(
            first.tool_call("graph", graph_arguments.clone())?,
            "cleanup pre-delete derived graph",
        )?;
        validate_cleanup_predelete_derived_graph(&graph, &intent)?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::PredeleteDerivedGraph,
            graph_arguments,
            graph,
        )?;

        let log_arguments = cleanup_commit_log_arguments();
        let log = exact_mcp_content(
            first.tool_call("memory", log_arguments.clone())?,
            "cleanup pre-delete knowledge-commit projection",
        )?;
        let commit_matches = log.get("commits").and_then(Value::as_array).map(|commits| {
            commits
                .iter()
                .filter(|commit| {
                    commit.get("id").and_then(Value::as_str)
                        == Some(intent.projection_commit_id.as_str())
                })
                .count()
        });
        if !validate_cleanup_scoped_result_shape(&log, &["count", "commits"], "memory_admin", None)
            || commit_matches != Some(1)
            || serde_json::to_string(&log)?
                .matches(&intent.obsolete_id)
                .count()
                != 1
        {
            return invalid("cleanup pre-delete knowledge-commit projection count was not one");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::PredeleteCommitReference,
            log_arguments,
            log,
        )?;

        let trace_arguments = cleanup_trace_get_arguments(lane, &intent);
        let trace_result = exact_mcp_content(
            first.tool_call("telemetry", trace_arguments.clone())?,
            "cleanup pre-delete retrieval-trace projection",
        )?;
        if !validate_cleanup_scoped_result_shape(
            &trace_result,
            &["trace"],
            "telemetry",
            Some("atlas"),
        ) || trace_result.pointer("/trace/id").and_then(Value::as_str)
            != Some(intent.projection_trace_id.as_str())
            || trace_result
                .pointer("/trace/returned_memory_ids/0")
                .and_then(Value::as_str)
                != Some(intent.obsolete_id.as_str())
            || trace_result
                .pointer("/trace/returned_memory_ids")
                .and_then(Value::as_array)
                .map(Vec::len)
                != Some(1)
            || serde_json::to_string(&trace_result)?
                .matches(&intent.obsolete_id)
                .count()
                != 1
        {
            return invalid("cleanup pre-delete retrieval-trace projection count was not one");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::PredeleteRetrievalTrace,
            trace_arguments,
            trace_result,
        )?;

        let feedback_arguments = cleanup_feedback_list_arguments(lane, &intent);
        let feedback = exact_mcp_content(
            first.tool_call("telemetry", feedback_arguments.clone())?,
            "cleanup pre-delete feedback projection",
        )?;
        if !validate_cleanup_scoped_result_shape(
            &feedback,
            &["count", "feedback"],
            "telemetry",
            Some("atlas"),
        ) || feedback.get("count").and_then(Value::as_u64) != Some(1)
            || feedback.pointer("/feedback/0/id").and_then(Value::as_str)
                != Some(intent.projection_feedback_id.as_str())
            || feedback
                .pointer("/feedback/0/used_memory_ids/0")
                .and_then(Value::as_str)
                != Some(intent.obsolete_id.as_str())
            || feedback
                .pointer("/feedback/0/used_memory_ids")
                .and_then(Value::as_array)
                .map(Vec::len)
                != Some(1)
            || feedback
                .pointer("/feedback/0/trace_id")
                .and_then(Value::as_str)
                != Some(intent.projection_trace_id.as_str())
            || serde_json::to_string(&feedback)?
                .matches(&intent.obsolete_id)
                .count()
                != 1
        {
            return invalid("cleanup pre-delete feedback projection count was not one");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::PredeleteFeedback,
            feedback_arguments,
            feedback,
        )?;

        let archive_value = exact_mcp_content(
            first.tool_call("memory", intent.archive_arguments.clone())?,
            "cleanup archive replacement",
        )?;
        if !exact_object_keys(&archive_value, &["item"]) {
            return invalid("cleanup archive response keys drifted");
        }
        let archived: MemoryItem = parse_exact_domain(
            archive_value.get("item").ok_or_else(|| {
                NativeCorrectionError::Invalid("cleanup archive omitted item".to_string())
            })?,
            "cleanup archived replacement",
        )?;
        validate_cleanup_archived_item(
            lane,
            &operator.replacement_after,
            &archived,
            intent.created_unix_ms,
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::ArchiveReplacement,
            intent.archive_arguments.clone(),
            archive_value,
        )?;

        let archived_match = exact_mcp_content(
            first.tool_call("memory", intent.procedure_match_arguments.clone())?,
            "cleanup archived procedure match",
        )?;
        validate_cleanup_abstention(lane, &archived_match, "cleanup archived procedure match")?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::ArchivedProcedureMatchAbstention,
            intent.procedure_match_arguments.clone(),
            archived_match,
        )?;

        let replacement_forget_value = exact_mcp_content(
            first.tool_call("memory", intent.forget_replacement_arguments.clone())?,
            "cleanup exact replacement forget",
        )?;
        let replacement_forget = parse_cleanup_forget_result(
            &replacement_forget_value,
            &intent.replacement_id,
            CLEANUP_FORGET_REPLACEMENT_REASON,
        )?
        .internal_purge;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::ForgetReplacement,
            intent.forget_replacement_arguments.clone(),
            replacement_forget_value,
        )?;

        let obsolete_forget_value = exact_mcp_content(
            first.tool_call("memory", intent.forget_obsolete_arguments.clone())?,
            "cleanup exact obsolete forget",
        )?;
        let obsolete_forget = parse_cleanup_forget_result(
            &obsolete_forget_value,
            &intent.obsolete_id,
            CLEANUP_FORGET_OBSOLETE_REASON,
        )?
        .internal_purge;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::ForgetObsolete,
            intent.forget_obsolete_arguments.clone(),
            obsolete_forget_value,
        )?;
        Ok((archived, replacement_forget, obsolete_forget))
    })();
    let first_observation_completed_unix_ms = unix_ms(SystemTime::now())?;
    let first_finished = first
        .finish()
        .and_then(|finish| finish.require_daemon_stop("cleanup mutation session"));
    let (
        (archived, replacement_forget, obsolete_forget),
        (first_trace, first_stderr, first_stop),
        (),
    ) = combine_native_correction_three(
        first_observation,
        first_finished,
        Ok(()),
        [
            "cleanup mutation observation",
            "cleanup mutation stdio finish",
            "cleanup mutation terminal gate",
        ],
    )?;
    push_cleanup_event(
        &mut events,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;

    let second_started_unix_ms = unix_ms(SystemTime::now())?;
    let mut second =
        start_native_correction_stdio_session(engram, home, &lane.opaque_partition, timeout)?;
    let second_pid = second.process_id()?;
    let second_observation: NativeCorrectionResult<()> = (|| {
        validate_operator_full_handshake(&mut second, &plan)?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartFullHandshake,
            json!({}),
            json!({"verified":true}),
        )?;
        let replacement_get = cleanup_get_arguments(lane, &intent.replacement_id);
        let replacement_absent = exact_native_correction_mcp_error_text(
            second.tool_call("memory", replacement_get.clone())?,
            "cleanup restart replacement get",
            &format!("Memory item not found: {}", intent.replacement_id),
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartReplacementGetAbsent,
            replacement_get,
            replacement_absent,
        )?;
        let obsolete_get = cleanup_get_arguments(lane, &intent.obsolete_id);
        let obsolete_absent = exact_native_correction_mcp_error_text(
            second.tool_call("memory", obsolete_get.clone())?,
            "cleanup restart obsolete get",
            &format!("Memory item not found: {}", intent.obsolete_id),
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartObsoleteGetAbsent,
            obsolete_get,
            obsolete_absent,
        )?;
        let proposal_get = operator_get_arguments(lane, "atlas", &intent.proposal_id);
        let proposal_absent = exact_native_correction_mcp_error_text(
            second.tool_call("memory", proposal_get.clone())?,
            "cleanup restart proposal get",
            &format!(
                "not found: correction proposal {} not found",
                intent.proposal_id
            ),
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartProposalGetAbsent,
            proposal_get,
            proposal_absent,
        )?;
        let restart_match = exact_mcp_content(
            second.tool_call("memory", intent.procedure_match_arguments.clone())?,
            "cleanup restart procedure match",
        )?;
        validate_cleanup_abstention(lane, &restart_match, "cleanup restart procedure match")?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartProcedureMatchAbstention,
            intent.procedure_match_arguments.clone(),
            restart_match,
        )?;
        let active_arguments = operator_list_arguments(lane, "atlas", "active");
        let active = exact_mcp_content(
            second.tool_call("memory", active_arguments.clone())?,
            "cleanup restart active list",
        )?;
        if !validate_normal_scope_result_shape(&active, &["count", "items"], "atlas")
            || active.get("count").and_then(Value::as_u64) != Some(0)
            || active.get("items") != Some(&json!([]))
        {
            return invalid("cleanup restart active list was not exactly empty");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartActiveListEmpty,
            active_arguments,
            active,
        )?;

        let other_arguments = cleanup_other_scope_get_arguments(lane, &intent);
        let other = exact_mcp_content(
            second.tool_call("memory", other_arguments.clone())?,
            "cleanup restart memory-reference check",
        )?;
        if !validate_normal_scope_result_shape(&other, &["item"], "orbit")
            || other.pointer("/item/id").and_then(Value::as_str)
                != Some(intent.other_scope_id.as_str())
        {
            return invalid("cleanup restart memory-reference item drifted");
        }
        cleanup_result_excludes(
            &other,
            &[
                &intent.obsolete_id,
                &intent.replacement_id,
                EXPECTED_REPLACEMENT_CONTENT,
            ],
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartMemoryReferenceAbsent,
            other_arguments,
            other,
        )?;

        let graph_arguments = cleanup_derived_graph_arguments(&intent);
        let graph = exact_mcp_content(
            second.tool_call("graph", graph_arguments.clone())?,
            "cleanup restart derived-graph check",
        )?;
        validate_cleanup_restart_derived_graph(&graph)?;
        cleanup_result_excludes(
            &graph,
            &[
                &intent.obsolete_id,
                &intent.replacement_id,
                EXPECTED_REPLACEMENT_CONTENT,
            ],
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartDerivedGraphAbsent,
            graph_arguments,
            graph,
        )?;

        let log_arguments = cleanup_commit_log_arguments();
        let log = exact_mcp_content(
            second.tool_call("memory", log_arguments.clone())?,
            "cleanup restart knowledge-commit check",
        )?;
        if !validate_cleanup_scoped_result_shape(&log, &["count", "commits"], "memory_admin", None)
            || !log
                .get("commits")
                .and_then(Value::as_array)
                .is_some_and(|commits| {
                    commits.iter().any(|commit| {
                        commit.get("id").and_then(Value::as_str)
                            == Some(intent.projection_commit_id.as_str())
                    })
                })
        {
            return invalid("cleanup restart knowledge-commit projection was not exercised");
        }
        cleanup_result_excludes(
            &log,
            &[
                &intent.obsolete_id,
                &intent.replacement_id,
                EXPECTED_REPLACEMENT_CONTENT,
            ],
        )?;
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartCommitReferenceRedacted,
            log_arguments,
            log,
        )?;

        let trace_arguments = cleanup_trace_get_arguments(lane, &intent);
        let trace_result = exact_mcp_content(
            second.tool_call("telemetry", trace_arguments.clone())?,
            "cleanup restart retrieval-trace check",
        )?;
        if !validate_cleanup_scoped_result_shape(
            &trace_result,
            &["trace"],
            "telemetry",
            Some("atlas"),
        ) || !trace_result.get("trace").is_some_and(Value::is_null)
        {
            return invalid("cleanup restart retrieval trace was not absent");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartRetrievalTraceAbsent,
            trace_arguments,
            trace_result,
        )?;

        let feedback_arguments = cleanup_feedback_list_arguments(lane, &intent);
        let feedback = exact_mcp_content(
            second.tool_call("telemetry", feedback_arguments.clone())?,
            "cleanup restart feedback check",
        )?;
        if !validate_cleanup_scoped_result_shape(
            &feedback,
            &["count", "feedback"],
            "telemetry",
            Some("atlas"),
        ) || feedback.get("count").and_then(Value::as_u64) != Some(0)
            || feedback.get("feedback") != Some(&json!([]))
        {
            return invalid("cleanup restart feedback projection was not absent");
        }
        push_cleanup_event(
            &mut events,
            NativeCorrectionCleanupAction::RestartFeedbackAbsent,
            feedback_arguments,
            feedback,
        )?;
        Ok(())
    })();
    let second_observation_completed_unix_ms = unix_ms(SystemTime::now())?;
    let second_finished = second
        .finish()
        .and_then(|finish| finish.require_daemon_stop("cleanup restart session"));
    let ((), (second_trace, second_stderr, second_stop), ()) = combine_native_correction_three(
        second_observation,
        second_finished,
        Ok(()),
        [
            "cleanup restart observation",
            "cleanup restart stdio finish",
            "cleanup restart terminal gate",
        ],
    )?;
    push_cleanup_event(
        &mut events,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    if first_pid == second_pid {
        return invalid("cleanup restart reused the mutation process identity");
    }

    let trace = NativeCorrectionCleanupTraceEnvelope {
        schema_version: 1,
        sessions: vec![
            NativeCorrectionOperatorSessionTrace {
                ordinal: 1,
                process_id: first_pid,
                started_unix_ms: first_started_unix_ms,
                observation_completed_unix_ms: first_observation_completed_unix_ms,
                transcript_sha256: format!("{:x}", Sha256::digest(&first_trace)),
                transcript_bytes: first_trace.len() as u64,
                transcript_jsonl: String::from_utf8(first_trace).map_err(|_| {
                    NativeCorrectionError::Invalid(
                        "cleanup mutation transcript was not UTF-8".to_string(),
                    )
                })?,
                stderr_sha256: format!("{:x}", Sha256::digest(&first_stderr)),
                stderr_bytes: first_stderr.len() as u64,
            },
            NativeCorrectionOperatorSessionTrace {
                ordinal: 2,
                process_id: second_pid,
                started_unix_ms: second_started_unix_ms,
                observation_completed_unix_ms: second_observation_completed_unix_ms,
                transcript_sha256: format!("{:x}", Sha256::digest(&second_trace)),
                transcript_bytes: second_trace.len() as u64,
                transcript_jsonl: String::from_utf8(second_trace).map_err(|_| {
                    NativeCorrectionError::Invalid(
                        "cleanup restart transcript was not UTF-8".to_string(),
                    )
                })?,
                stderr_sha256: format!("{:x}", Sha256::digest(&second_stderr)),
                stderr_bytes: second_stderr.len() as u64,
            },
        ],
        daemon_stops: vec![initial_stop, first_stop, second_stop],
    };
    let mut stderr = first_stderr;
    stderr.extend_from_slice(&second_stderr);
    write_private_json(&paths.trace, &trace)?;
    write_new_file(&paths.stderr, &stderr, 0o600)?;
    let canary: NativeCorrectionPrivateCanaryContract = read_strict_json_file(
        Path::new(&lane.private_canary_contract),
        0o600,
        64 * 1024,
        "cleanup private canary contract",
    )?;
    let other_scope_vault_path = format!(
        "memory/items/{}-orbit-queue-backend.md",
        intent.other_scope_id
    );
    let (vault_files, vault_bytes) = scan_native_correction_cleanup_vault(
        &paths.vault,
        &[
            &intent.obsolete_id,
            &intent.replacement_id,
            &canary.old_content,
            EXPECTED_REPLACEMENT_CONTENT,
            &canary.hidden_secret,
            "EVAL_SECRET_",
        ],
        Some((&other_scope_vault_path, &canary.other_scope_content)),
    )?;
    let completed_unix_ms = unix_ms(SystemTime::now())?.max(started_unix_ms);
    let receipt = NativeCorrectionCleanupReceipt {
        schema_version: 1,
        host: lane.host,
        run_plan_sha256,
        protocol_sha256: plan.protocol_sha256.clone(),
        engram_sha256: EXPECTED_ENGRAM_SHA256.to_string(),
        full_profile_tools_sha256: EXPECTED_FULL_TOOLS_SHA256.to_string(),
        full_profile_handshake_sha256: sha256_json(&plan.runtime.full_profile)?,
        operator_receipt_sha256: intent.operator_receipt_sha256.clone(),
        retrieval_receipt_sha256: intent.retrieval_receipt_sha256.clone(),
        cleanup_intent_sha256: sha256_file(&paths.intent)?,
        cleanup_trace: artifact_receipt(
            paths.trace.to_str().ok_or_else(|| {
                NativeCorrectionError::Invalid("cleanup trace path was not UTF-8".into())
            })?,
            &plan,
            false,
        )?,
        cleanup_stderr: artifact_receipt(
            paths.stderr.to_str().ok_or_else(|| {
                NativeCorrectionError::Invalid("cleanup stderr path was not UTF-8".into())
            })?,
            &plan,
            true,
        )?,
        started_unix_ms,
        completed_unix_ms,
        duration_ms: completed_unix_ms - started_unix_ms,
        fresh_process_ids: vec![first_pid, second_pid],
        events,
        archived_replacement: archived,
        replacement_forget,
        obsolete_forget,
        vault_path: intent.vault_path.clone(),
        vault_files,
        vault_bytes,
        archive_suppressed_retrieval: true,
        restart_abstained: true,
        replacement_absent_after_restart: true,
        obsolete_absent_after_restart: true,
        proposal_absent_after_restart: true,
        active_list_empty_after_restart: true,
        memory_reference_absent_after_restart: true,
        derived_graph_absent_after_restart: true,
        commit_reference_redacted_after_restart: true,
        retrieval_trace_absent_after_restart: true,
        feedback_absent_after_restart: true,
        projections_preregistered: true,
        predelete_projection_counts_verified: true,
        bounded_projection_absence: true,
        engram_owned_projection_scope: CLEANUP_ENGRAM_OWNED_PROJECTION_SCOPE.to_string(),
        excluded_projection_scope: CLEANUP_EXCLUDED_PROJECTION_SCOPE.to_string(),
        preserved_evaluator_operator_transcripts_outside_engram_owned_scope: true,
        human_identity_authenticated: false,
        intent_verified: false,
        human_review_verified: false,
        reviewer_authority_conferred: false,
        scope_selector_authenticated: false,
        archive_call_count: 1,
        forget_call_count: 2,
        fresh_full_process_count: 2,
        daemon_stop_count: 3,
        retry_used_as_causal_evidence: false,
    };
    validate_recorded_native_correction_cleanup_receipt(&plan, lane, &receipt)?;
    write_private_json(&paths.receipt, &receipt)?;
    write_private_text(
        &receipt_digest_path(&paths.receipt),
        &(sha256_file(&paths.receipt)? + "\n"),
    )?;
    Ok(receipt)
}

fn validate_cleanup_error_event(event: &NativeCorrectionCleanupEvent, expected: &str) -> bool {
    exact_object_keys(&event.result, &["mcp_is_error", "mcp_error_text"])
        && event.result.get("mcp_is_error").and_then(Value::as_bool) == Some(true)
        && event.result.get("mcp_error_text").and_then(Value::as_str) == Some(expected)
}

fn validate_cleanup_canary_locations(
    canary: &NativeCorrectionPrivateCanaryContract,
    values: &[&Value],
    allowed_other_scope_indexes: &[usize],
    label: &str,
) -> NativeCorrectionResult<()> {
    let allowed = allowed_other_scope_indexes
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    if allowed.len() != allowed_other_scope_indexes.len()
        || allowed.iter().any(|index| *index >= values.len())
    {
        return invalid(format!("{label} has an invalid internal canary allowlist"));
    }
    for (index, value) in values.iter().enumerate() {
        let encoded = serde_json::to_string(value)?;
        if encoded.contains(&canary.hidden_secret) || encoded.contains("EVAL_SECRET_") {
            return invalid(format!(
                "private secret appeared in {label} at index {index}"
            ));
        }
        let expected_count = usize::from(allowed.contains(&index));
        if encoded.matches(&canary.other_scope_content).count() != expected_count
            || encoded.matches("EVAL_OTHER_SCOPE_").count() != expected_count
        {
            return invalid(format!(
                "other-scope canary appeared outside the exact {label} allowlist at index {index}"
            ));
        }
    }
    Ok(())
}

fn validate_native_correction_cleanup_receipt(
    lane: &PreparedNativeCorrectionLane,
    operator: &NativeCorrectionOperatorReceipt,
    intent: &NativeCorrectionCleanupIntent,
    receipt: &NativeCorrectionCleanupReceipt,
) -> NativeCorrectionResult<()> {
    let expected_actions = [
        NativeCorrectionCleanupAction::StopLaneDaemon,
        NativeCorrectionCleanupAction::FreshFullHandshake,
        NativeCorrectionCleanupAction::PredeleteMemoryReference,
        NativeCorrectionCleanupAction::PredeleteDerivedGraph,
        NativeCorrectionCleanupAction::PredeleteCommitReference,
        NativeCorrectionCleanupAction::PredeleteRetrievalTrace,
        NativeCorrectionCleanupAction::PredeleteFeedback,
        NativeCorrectionCleanupAction::ArchiveReplacement,
        NativeCorrectionCleanupAction::ArchivedProcedureMatchAbstention,
        NativeCorrectionCleanupAction::ForgetReplacement,
        NativeCorrectionCleanupAction::ForgetObsolete,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        NativeCorrectionCleanupAction::RestartFullHandshake,
        NativeCorrectionCleanupAction::RestartReplacementGetAbsent,
        NativeCorrectionCleanupAction::RestartObsoleteGetAbsent,
        NativeCorrectionCleanupAction::RestartProposalGetAbsent,
        NativeCorrectionCleanupAction::RestartProcedureMatchAbstention,
        NativeCorrectionCleanupAction::RestartActiveListEmpty,
        NativeCorrectionCleanupAction::RestartMemoryReferenceAbsent,
        NativeCorrectionCleanupAction::RestartDerivedGraphAbsent,
        NativeCorrectionCleanupAction::RestartCommitReferenceRedacted,
        NativeCorrectionCleanupAction::RestartRetrievalTraceAbsent,
        NativeCorrectionCleanupAction::RestartFeedbackAbsent,
        NativeCorrectionCleanupAction::StopLaneDaemon,
    ];
    if receipt.schema_version != 1
        || receipt.host != lane.host
        || receipt.events.len() != expected_actions.len()
        || receipt.events.iter().zip(expected_actions).enumerate().any(
            |(index, (event, expected))| {
                event.ordinal != (index + 1) as u32
                    || event.action != expected
                    || event.result_bytes
                        != serde_json::to_vec(&event.result).unwrap_or_default().len() as u64
                    || event.result_bytes > 16 * 1024
            },
        )
        || receipt
            .events
            .iter()
            .map(|event| event.result_bytes)
            .sum::<u64>()
            > 64 * 1024
        || receipt.started_unix_ms < intent.created_unix_ms
        || receipt.completed_unix_ms < receipt.started_unix_ms
        || receipt.duration_ms != receipt.completed_unix_ms - receipt.started_unix_ms
        || receipt.fresh_process_ids.len() != 2
        || receipt.fresh_process_ids[0] == 0
        || receipt.fresh_process_ids[1] == 0
        || receipt.fresh_process_ids[0] == receipt.fresh_process_ids[1]
        || !looks_like_sha256(&receipt.run_plan_sha256)
        || !looks_like_sha256(&receipt.protocol_sha256)
        || !looks_like_sha256(&receipt.engram_sha256)
        || !looks_like_sha256(&receipt.full_profile_tools_sha256)
        || !looks_like_sha256(&receipt.full_profile_handshake_sha256)
        || !looks_like_sha256(&receipt.operator_receipt_sha256)
        || !looks_like_sha256(&receipt.retrieval_receipt_sha256)
        || !looks_like_sha256(&receipt.cleanup_intent_sha256)
        || receipt.vault_path != intent.vault_path
        || receipt.archive_call_count != 1
        || receipt.forget_call_count != 2
        || receipt.fresh_full_process_count != 2
        || receipt.daemon_stop_count != 3
        || !receipt.archive_suppressed_retrieval
        || !receipt.restart_abstained
        || !receipt.replacement_absent_after_restart
        || !receipt.obsolete_absent_after_restart
        || !receipt.proposal_absent_after_restart
        || !receipt.active_list_empty_after_restart
        || !receipt.memory_reference_absent_after_restart
        || !receipt.derived_graph_absent_after_restart
        || !receipt.commit_reference_redacted_after_restart
        || !receipt.retrieval_trace_absent_after_restart
        || !receipt.feedback_absent_after_restart
        || !receipt.projections_preregistered
        || !receipt.predelete_projection_counts_verified
        || !receipt.bounded_projection_absence
        || receipt.engram_owned_projection_scope != CLEANUP_ENGRAM_OWNED_PROJECTION_SCOPE
        || receipt.excluded_projection_scope != CLEANUP_EXCLUDED_PROJECTION_SCOPE
        || !receipt.preserved_evaluator_operator_transcripts_outside_engram_owned_scope
        || receipt.human_identity_authenticated
        || receipt.intent_verified
        || receipt.human_review_verified
        || receipt.reviewer_authority_conferred
        || receipt.scope_selector_authenticated
        || receipt.retry_used_as_causal_evidence
    {
        return invalid(
            "cleanup receipt counts, hashes, chronology, or authority boundary drifted",
        );
    }
    let canary: NativeCorrectionPrivateCanaryContract = read_strict_json_file(
        Path::new(&lane.private_canary_contract),
        0o600,
        64 * 1024,
        "cleanup private canary contract",
    )?;
    let event_arguments = receipt
        .events
        .iter()
        .map(|event| &event.arguments)
        .collect::<Vec<_>>();
    let event_results = receipt
        .events
        .iter()
        .map(|event| &event.result)
        .collect::<Vec<_>>();
    validate_cleanup_canary_locations(&canary, &event_arguments, &[], "cleanup arguments")?;
    validate_cleanup_canary_locations(&canary, &event_results, &[2, 18], "cleanup event results")?;
    for (index, expected_result) in [
        (0usize, json!({"stopped":true})),
        (1usize, json!({"verified":true})),
        (11usize, json!({"stopped":true})),
        (12usize, json!({"verified":true})),
        (23usize, json!({"stopped":true})),
    ] {
        if receipt.events[index].arguments != json!({})
            || receipt.events[index].result != expected_result
        {
            return invalid("cleanup stop/handshake event drifted");
        }
    }
    if receipt.events[2].arguments != cleanup_other_scope_get_arguments(lane, intent)
        || receipt.events[3].arguments != cleanup_derived_graph_arguments(intent)
        || receipt.events[4].arguments != cleanup_commit_log_arguments()
        || receipt.events[5].arguments != cleanup_trace_get_arguments(lane, intent)
        || receipt.events[6].arguments != cleanup_feedback_list_arguments(lane, intent)
        || receipt.events[7].arguments != intent.archive_arguments
        || !exact_object_keys(&receipt.events[7].result, &["item"])
        || receipt.events[8].arguments != intent.procedure_match_arguments
        || receipt.events[9].arguments != intent.forget_replacement_arguments
        || receipt.events[10].arguments != intent.forget_obsolete_arguments
        || receipt.events[13].arguments != cleanup_get_arguments(lane, &intent.replacement_id)
        || receipt.events[14].arguments != cleanup_get_arguments(lane, &intent.obsolete_id)
        || receipt.events[15].arguments
            != operator_get_arguments(lane, "atlas", &intent.proposal_id)
        || receipt.events[16].arguments != intent.procedure_match_arguments
        || receipt.events[17].arguments != operator_list_arguments(lane, "atlas", "active")
        || receipt.events[18].arguments != cleanup_other_scope_get_arguments(lane, intent)
        || receipt.events[19].arguments != cleanup_derived_graph_arguments(intent)
        || receipt.events[20].arguments != cleanup_commit_log_arguments()
        || receipt.events[21].arguments != cleanup_trace_get_arguments(lane, intent)
        || receipt.events[22].arguments != cleanup_feedback_list_arguments(lane, intent)
    {
        return invalid("cleanup action arguments drifted from the fsynced exact tuple");
    }
    let archived: MemoryItem = parse_exact_domain(
        receipt.events[7]
            .result
            .get("item")
            .ok_or_else(|| NativeCorrectionError::Invalid("cleanup archive item missing".into()))?,
        "cleanup receipt archived replacement",
    )?;
    validate_cleanup_archived_item(
        lane,
        &operator.replacement_after,
        &archived,
        intent.created_unix_ms,
    )?;
    if serde_json::to_value(&archived)? != serde_json::to_value(&receipt.archived_replacement)? {
        return invalid("cleanup archived replacement receipt drifted from its event");
    }
    validate_cleanup_abstention(
        lane,
        &receipt.events[8].result,
        "cleanup archived abstention",
    )?;
    validate_cleanup_abstention(
        lane,
        &receipt.events[16].result,
        "cleanup restart abstention",
    )?;
    let predelete_memory_reference = serde_json::to_string(&receipt.events[2].result)?;
    validate_cleanup_predelete_derived_graph(&receipt.events[3].result, intent)?;
    let predelete_commit_matches = receipt.events[4]
        .result
        .get("commits")
        .and_then(Value::as_array)
        .map(|commits| {
            commits
                .iter()
                .filter(|commit| {
                    commit.get("id").and_then(Value::as_str)
                        == Some(intent.projection_commit_id.as_str())
                })
                .count()
        });
    let predelete_commit_text = serde_json::to_string(&receipt.events[4].result)?;
    let predelete_trace_text = serde_json::to_string(&receipt.events[5].result)?;
    let predelete_feedback_text = serde_json::to_string(&receipt.events[6].result)?;
    if !validate_normal_scope_result_shape(&receipt.events[2].result, &["item"], "orbit")
        || receipt.events[2]
            .result
            .pointer("/item/id")
            .and_then(Value::as_str)
            != Some(intent.other_scope_id.as_str())
        || predelete_memory_reference
            .matches(&intent.obsolete_id)
            .count()
            != 1
        || predelete_memory_reference.contains(&intent.replacement_id)
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[4].result,
            &["count", "commits"],
            "memory_admin",
            None,
        )
        || predelete_commit_matches != Some(1)
        || predelete_commit_text.matches(&intent.obsolete_id).count() != 1
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[5].result,
            &["trace"],
            "telemetry",
            Some("atlas"),
        )
        || receipt.events[5]
            .result
            .pointer("/trace/id")
            .and_then(Value::as_str)
            != Some(intent.projection_trace_id.as_str())
        || receipt.events[5]
            .result
            .pointer("/trace/returned_memory_ids")
            .and_then(Value::as_array)
            != Some(&vec![json!(intent.obsolete_id)])
        || predelete_trace_text.matches(&intent.obsolete_id).count() != 1
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[6].result,
            &["count", "feedback"],
            "telemetry",
            Some("atlas"),
        )
        || receipt.events[6]
            .result
            .get("count")
            .and_then(Value::as_u64)
            != Some(1)
        || receipt.events[6]
            .result
            .get("feedback")
            .and_then(Value::as_array)
            .map(Vec::len)
            != Some(1)
        || receipt.events[6]
            .result
            .pointer("/feedback/0/id")
            .and_then(Value::as_str)
            != Some(intent.projection_feedback_id.as_str())
        || receipt.events[6]
            .result
            .pointer("/feedback/0/trace_id")
            .and_then(Value::as_str)
            != Some(intent.projection_trace_id.as_str())
        || receipt.events[6]
            .result
            .pointer("/feedback/0/used_memory_ids")
            .and_then(Value::as_array)
            != Some(&vec![json!(intent.obsolete_id)])
        || predelete_feedback_text.matches(&intent.obsolete_id).count() != 1
    {
        return invalid(
            "cleanup pre-delete evidence did not prove exactly one seeded memory, graph, commit, trace, and feedback reference",
        );
    }
    let replacement_forget = parse_cleanup_forget_result(
        &receipt.events[9].result,
        &intent.replacement_id,
        CLEANUP_FORGET_REPLACEMENT_REASON,
    )?;
    let obsolete_forget = parse_cleanup_forget_result(
        &receipt.events[10].result,
        &intent.obsolete_id,
        CLEANUP_FORGET_OBSOLETE_REASON,
    )?;
    if replacement_forget.internal_purge != receipt.replacement_forget
        || obsolete_forget.internal_purge != receipt.obsolete_forget
        || replacement_forget
            .internal_purge
            .correction_proposals_deleted
            != 1
        || replacement_forget.internal_purge.commits_redacted != 0
        || replacement_forget.internal_purge.traces_deleted != 0
        || replacement_forget.internal_purge.feedback_deleted != 0
        || replacement_forget.internal_purge.memory_items_updated != 0
        || replacement_forget
            .internal_purge
            .proposal_replacements_deleted
            != 0
        || replacement_forget
            .internal_purge
            .proposal_obsoletes_unlocked
            != 0
        || obsolete_forget.internal_purge.correction_proposals_deleted != 0
        || obsolete_forget.internal_purge.commits_redacted != 1
        || obsolete_forget.internal_purge.traces_deleted != 1
        || obsolete_forget.internal_purge.feedback_deleted != 1
        || obsolete_forget.internal_purge.memory_items_updated != 1
        || obsolete_forget.internal_purge.proposal_replacements_deleted != 0
        || obsolete_forget.internal_purge.proposal_obsoletes_unlocked != 0
        || !validate_cleanup_vault_refresh(
            &replacement_forget.vault_refresh,
            &intent.vault_path,
            2,
            1,
            None,
        )
        || !validate_cleanup_vault_refresh(
            &obsolete_forget.vault_refresh,
            &intent.vault_path,
            1,
            1,
            Some(&intent.obsolete_id),
        )
    {
        return invalid(
            "cleanup forget reports did not prove both IDs and proposal projection purge",
        );
    }
    let refreshed_vault_files = obsolete_forget
        .vault_refresh
        .get("files_written")
        .and_then(Value::as_array)
        .and_then(|files| {
            files
                .iter()
                .map(Value::as_str)
                .collect::<Option<BTreeSet<_>>>()
        })
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "cleanup final vault refresh omitted its exact file inventory".into(),
            )
        })?;
    let scanned_vault_files = receipt
        .vault_files
        .iter()
        .map(|file| file.relative_path.as_str())
        .collect::<BTreeSet<_>>();
    if refreshed_vault_files != scanned_vault_files {
        return invalid("cleanup final vault refresh and bounded scan disagreed");
    }
    if !validate_cleanup_error_event(
        &receipt.events[13],
        &format!("Memory item not found: {}", intent.replacement_id),
    ) || !validate_cleanup_error_event(
        &receipt.events[14],
        &format!("Memory item not found: {}", intent.obsolete_id),
    ) || !validate_cleanup_error_event(
        &receipt.events[15],
        &format!(
            "not found: correction proposal {} not found",
            intent.proposal_id
        ),
    ) {
        return invalid("cleanup restart did not prove exact item/proposal absence");
    }
    if !validate_normal_scope_result_shape(&receipt.events[17].result, &["count", "items"], "atlas")
        || receipt.events[17]
            .result
            .get("count")
            .and_then(Value::as_u64)
            != Some(0)
        || receipt.events[17].result.get("items") != Some(&json!([]))
    {
        return invalid("cleanup restart active list was not exactly empty");
    }
    let forbidden = [
        intent.obsolete_id.as_str(),
        intent.replacement_id.as_str(),
        operator.old_after.content.as_str(),
        EXPECTED_REPLACEMENT_CONTENT,
    ];
    if !validate_normal_scope_result_shape(&receipt.events[18].result, &["item"], "orbit")
        || receipt.events[18]
            .result
            .pointer("/item/id")
            .and_then(Value::as_str)
            != Some(intent.other_scope_id.as_str())
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[20].result,
            &["count", "commits"],
            "memory_admin",
            None,
        )
        || receipt.events[20]
            .result
            .get("commits")
            .and_then(Value::as_array)
            .map(|commits| {
                commits
                    .iter()
                    .filter(|commit| {
                        commit.get("id").and_then(Value::as_str)
                            == Some(intent.projection_commit_id.as_str())
                    })
                    .count()
            })
            != Some(1)
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[21].result,
            &["trace"],
            "telemetry",
            Some("atlas"),
        )
        || !receipt.events[21]
            .result
            .get("trace")
            .is_some_and(Value::is_null)
        || !validate_cleanup_scoped_result_shape(
            &receipt.events[22].result,
            &["count", "feedback"],
            "telemetry",
            Some("atlas"),
        )
        || receipt.events[22]
            .result
            .get("count")
            .and_then(Value::as_u64)
            != Some(0)
        || receipt.events[22].result.get("feedback") != Some(&json!([]))
    {
        return invalid("cleanup did not prove every preregistered projection absent or redacted");
    }
    validate_cleanup_restart_derived_graph(&receipt.events[19].result)?;
    for index in 18..=22 {
        cleanup_result_excludes(&receipt.events[index].result, &forbidden)?;
    }
    let mut previous = "";
    let mut sum = 0u64;
    for file in &receipt.vault_files {
        if file.relative_path.is_empty()
            || file.relative_path.as_str() <= previous
            || !looks_like_sha256(&file.sha256)
        {
            return invalid("cleanup vault inventory was not sorted and digest-bound");
        }
        previous = &file.relative_path;
        sum = sum.checked_add(file.bytes).ok_or_else(|| {
            NativeCorrectionError::Invalid("cleanup vault receipt size overflowed".into())
        })?;
    }
    if sum != receipt.vault_bytes || sum > 4 * 1024 * 1024 || receipt.vault_files.len() > 256 {
        return invalid("cleanup vault receipt exceeded or misstated its bounded scan");
    }
    Ok(())
}

fn validate_native_correction_cleanup_trace(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    intent: &NativeCorrectionCleanupIntent,
    receipt: &NativeCorrectionCleanupReceipt,
) -> NativeCorrectionResult<()> {
    let paths = native_correction_cleanup_paths(lane)?;
    let trace_text = read_bounded_regular_text(
        &paths.trace,
        MAX_RUNTIME_PROBE_BYTES as u64,
        "cleanup trace",
    )?;
    let canary: NativeCorrectionPrivateCanaryContract = read_strict_json_file(
        Path::new(&lane.private_canary_contract),
        0o600,
        64 * 1024,
        "cleanup private canary contract",
    )?;
    if trace_text.contains(&canary.hidden_secret) || trace_text.contains("EVAL_SECRET_") {
        return invalid("private secret appeared in cleanup evidence");
    }
    let envelope: NativeCorrectionCleanupTraceEnvelope = strict_json_from_str(&trace_text)?;
    if envelope.schema_version != 1
        || envelope.sessions.len() != 2
        || envelope.daemon_stops.len() != 3
        || receipt.fresh_process_ids.len() != 2
    {
        return invalid("cleanup trace did not contain exactly two sessions and three stop gates");
    }
    for (index, session) in envelope.sessions.iter().enumerate() {
        let transcript = session.transcript_jsonl.as_bytes();
        if session.ordinal != (index + 1) as u32
            || session.process_id != receipt.fresh_process_ids[index]
            || session.started_unix_ms > session.observation_completed_unix_ms
            || session.transcript_bytes != transcript.len() as u64
            || session.transcript_sha256 != format!("{:x}", Sha256::digest(transcript))
            || session.transcript_bytes == 0
            || session.transcript_bytes > MAX_RUNTIME_PROBE_BYTES as u64
            || session.stderr_bytes != 0
            || session.stderr_sha256 != format!("{:x}", Sha256::digest([]))
        {
            return invalid("cleanup session process, transcript, stderr, or timing drifted");
        }
    }
    for stop in &envelope.daemon_stops {
        validate_operator_daemon_stop(plan, lane, stop)?;
    }
    let first = &envelope.sessions[0];
    let second = &envelope.sessions[1];
    for (earlier_label, earlier, later_label, later) in [
        (
            "cleanup_intent.created_unix_ms",
            intent.created_unix_ms,
            "cleanup_first.started_unix_ms",
            first.started_unix_ms,
        ),
        (
            "cleanup_first.observation_completed_unix_ms",
            first.observation_completed_unix_ms,
            "cleanup_first_stop.started_unix_ms",
            envelope.daemon_stops[1].started_unix_ms,
        ),
        (
            "cleanup_first_stop.completed_unix_ms",
            envelope.daemon_stops[1].completed_unix_ms,
            "cleanup_second.started_unix_ms",
            second.started_unix_ms,
        ),
        (
            "cleanup_second.observation_completed_unix_ms",
            second.observation_completed_unix_ms,
            "cleanup_second_stop.started_unix_ms",
            envelope.daemon_stops[2].started_unix_ms,
        ),
        (
            "cleanup_second_stop.completed_unix_ms",
            envelope.daemon_stops[2].completed_unix_ms,
            "cleanup_receipt.completed_unix_ms",
            receipt.completed_unix_ms,
        ),
    ] {
        require_native_correction_timestamp_order(earlier_label, earlier, later_label, later)?;
    }
    let first_calls = vec![
        (
            "memory",
            cleanup_other_scope_get_arguments(lane, intent),
            false,
        ),
        ("graph", cleanup_derived_graph_arguments(intent), false),
        ("memory", cleanup_commit_log_arguments(), false),
        (
            "telemetry",
            cleanup_trace_get_arguments(lane, intent),
            false,
        ),
        (
            "telemetry",
            cleanup_feedback_list_arguments(lane, intent),
            false,
        ),
        ("memory", intent.archive_arguments.clone(), false),
        ("memory", intent.procedure_match_arguments.clone(), false),
        ("memory", intent.forget_replacement_arguments.clone(), false),
        ("memory", intent.forget_obsolete_arguments.clone(), false),
    ];
    let second_calls = vec![
        (
            "memory",
            cleanup_get_arguments(lane, &intent.replacement_id),
            true,
        ),
        (
            "memory",
            cleanup_get_arguments(lane, &intent.obsolete_id),
            true,
        ),
        (
            "memory",
            operator_get_arguments(lane, "atlas", &intent.proposal_id),
            true,
        ),
        ("memory", intent.procedure_match_arguments.clone(), false),
        (
            "memory",
            operator_list_arguments(lane, "atlas", "active"),
            false,
        ),
        (
            "memory",
            cleanup_other_scope_get_arguments(lane, intent),
            false,
        ),
        ("graph", cleanup_derived_graph_arguments(intent), false),
        ("memory", cleanup_commit_log_arguments(), false),
        (
            "telemetry",
            cleanup_trace_get_arguments(lane, intent),
            false,
        ),
        (
            "telemetry",
            cleanup_feedback_list_arguments(lane, intent),
            false,
        ),
    ];
    let first_results =
        parse_full_profile_stdio_transcript(first, &first_calls, &plan.runtime.full_profile)?;
    let second_results =
        parse_full_profile_stdio_transcript(second, &second_calls, &plan.runtime.full_profile)?;
    if trace_text.matches(&canary.other_scope_content).count() != 2
        || trace_text.matches("EVAL_OTHER_SCOPE_").count() != 2
    {
        return invalid(
            "cleanup trace did not contain exactly the two trusted-evaluator other-scope observations",
        );
    }
    let first_result_refs = first_results.iter().collect::<Vec<_>>();
    let second_result_refs = second_results.iter().collect::<Vec<_>>();
    validate_cleanup_canary_locations(
        &canary,
        &first_result_refs,
        &[0],
        "cleanup first-session results",
    )?;
    validate_cleanup_canary_locations(
        &canary,
        &second_result_refs,
        &[5],
        "cleanup restart-session results",
    )?;
    let mut derived = Vec::new();
    push_cleanup_event(
        &mut derived,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    push_cleanup_event(
        &mut derived,
        NativeCorrectionCleanupAction::FreshFullHandshake,
        json!({}),
        json!({"verified":true}),
    )?;
    for (action, index) in [
        (
            NativeCorrectionCleanupAction::PredeleteMemoryReference,
            0usize,
        ),
        (NativeCorrectionCleanupAction::PredeleteDerivedGraph, 1usize),
        (
            NativeCorrectionCleanupAction::PredeleteCommitReference,
            2usize,
        ),
        (
            NativeCorrectionCleanupAction::PredeleteRetrievalTrace,
            3usize,
        ),
        (NativeCorrectionCleanupAction::PredeleteFeedback, 4usize),
        (NativeCorrectionCleanupAction::ArchiveReplacement, 5usize),
        (
            NativeCorrectionCleanupAction::ArchivedProcedureMatchAbstention,
            6usize,
        ),
        (NativeCorrectionCleanupAction::ForgetReplacement, 7usize),
        (NativeCorrectionCleanupAction::ForgetObsolete, 8usize),
    ] {
        push_cleanup_event(
            &mut derived,
            action,
            first_calls[index].1.clone(),
            first_results[index].clone(),
        )?;
    }
    push_cleanup_event(
        &mut derived,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    push_cleanup_event(
        &mut derived,
        NativeCorrectionCleanupAction::RestartFullHandshake,
        json!({}),
        json!({"verified":true}),
    )?;
    for (action, index) in [
        (
            NativeCorrectionCleanupAction::RestartReplacementGetAbsent,
            0usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartObsoleteGetAbsent,
            1usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartProposalGetAbsent,
            2usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartProcedureMatchAbstention,
            3usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartActiveListEmpty,
            4usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartMemoryReferenceAbsent,
            5usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartDerivedGraphAbsent,
            6usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartCommitReferenceRedacted,
            7usize,
        ),
        (
            NativeCorrectionCleanupAction::RestartRetrievalTraceAbsent,
            8usize,
        ),
        (NativeCorrectionCleanupAction::RestartFeedbackAbsent, 9usize),
    ] {
        push_cleanup_event(
            &mut derived,
            action,
            second_calls[index].1.clone(),
            second_results[index].clone(),
        )?;
    }
    push_cleanup_event(
        &mut derived,
        NativeCorrectionCleanupAction::StopLaneDaemon,
        json!({}),
        json!({"stopped":true}),
    )?;
    if derived != receipt.events {
        return invalid("cleanup normalized events were not losslessly derived from both sessions");
    }
    Ok(())
}

fn validate_recorded_native_correction_cleanup_receipt(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    receipt: &NativeCorrectionCleanupReceipt,
) -> NativeCorrectionResult<()> {
    let paths = native_correction_cleanup_paths(lane)?;
    let (intent, intent_sha256): (NativeCorrectionCleanupIntent, _) =
        read_digest_bound_strict_json(
            &paths.intent,
            &receipt_digest_path(&paths.intent),
            1024 * 1024,
            "cleanup intent",
        )?;
    validate_native_correction_cleanup_intent(plan, lane, &intent)?;
    let (operator, operator_sha256): (NativeCorrectionOperatorReceipt, _) =
        read_digest_bound_strict_json(
            Path::new(&lane.operator_receipt),
            &receipt_digest_path(Path::new(&lane.operator_receipt)),
            8 * 1024 * 1024,
            "cleanup operator receipt",
        )?;
    validate_recorded_native_correction_operator_receipt(plan, lane, &operator)?;
    let (retrieval, retrieval_sha256) = read_and_validate_provider_receipt_with_digest(
        plan,
        lane,
        NativeCorrectionProviderPhase::Retrieval,
    )?;
    let protocol: NativeCorrectionProtocol = read_strict_json_file(
        Path::new(&plan.protocol),
        0o600,
        1024 * 1024,
        "cleanup protocol",
    )?;
    let canary: NativeCorrectionPrivateCanaryContract = read_strict_json_file(
        Path::new(&lane.private_canary_contract),
        0o600,
        64 * 1024,
        "cleanup private canary contract",
    )?;
    let other_scope_vault_path = format!(
        "memory/items/{}-orbit-queue-backend.md",
        intent.other_scope_id
    );
    let (vault_files, vault_bytes) = scan_native_correction_cleanup_vault(
        &paths.vault,
        &[
            &intent.obsolete_id,
            &intent.replacement_id,
            &canary.old_content,
            EXPECTED_REPLACEMENT_CONTENT,
            &canary.hidden_secret,
            "EVAL_SECRET_",
        ],
        Some((&other_scope_vault_path, &canary.other_scope_content)),
    )?;
    if receipt.run_plan_sha256 != intent.run_plan_sha256
        || receipt.protocol_sha256 != plan.protocol_sha256
        || receipt.engram_sha256 != EXPECTED_ENGRAM_SHA256
        || receipt.full_profile_tools_sha256 != EXPECTED_FULL_TOOLS_SHA256
        || receipt.full_profile_handshake_sha256 != sha256_json(&plan.runtime.full_profile)?
        || receipt.operator_receipt_sha256 != operator_sha256
        || receipt.retrieval_receipt_sha256 != retrieval_sha256
        || receipt.cleanup_intent_sha256 != intent_sha256
        || receipt.cleanup_trace
            != artifact_receipt(
                paths.trace.to_str().ok_or_else(|| {
                    NativeCorrectionError::Invalid("cleanup trace path was not UTF-8".into())
                })?,
                plan,
                false,
            )?
        || receipt.cleanup_stderr
            != artifact_receipt(
                paths.stderr.to_str().ok_or_else(|| {
                    NativeCorrectionError::Invalid("cleanup stderr path was not UTF-8".into())
                })?,
                plan,
                true,
            )?
        || receipt.cleanup_trace.bytes == 0
        || receipt.cleanup_stderr.bytes != 0
        || receipt.started_unix_ms < retrieval.completed_unix_ms
        || receipt.duration_ms > protocol.resources.host_timeout_ms.saturating_mul(2)
        || receipt.vault_files != vault_files
        || receipt.vault_bytes != vault_bytes
    {
        return invalid("cleanup receipt lost its exact source, artifact, or vault binding");
    }
    validate_native_correction_cleanup_trace(plan, lane, &intent, receipt)?;
    validate_native_correction_cleanup_receipt(lane, &operator, &intent, receipt)?;
    Ok(())
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum NativeCorrectionLaneLifecycle {
    AwaitingProposal,
    FrozenIncompleteProposal,
    AwaitingOperator,
    FrozenIncompleteOperator,
    AwaitingRetrieval,
    FrozenIncompleteRetrieval,
    AwaitingCleanup,
    FrozenIncompleteCleanup,
    Complete,
    Invalid,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionLaneBurdenAudit {
    pub lane_order: u32,
    pub host: NativeCorrectionHost,
    pub operator_action_count: u32,
    pub cleanup_action_count: u32,
    pub model_turn_count: u32,
    pub harness_retry_count: u32,
    pub same_phase_replay_count: u32,
    pub provider_internal_retry_count: NativeCorrectionUnavailableCount,
    pub proposal_start_through_cleanup_completion_ms: u64,
    pub active_receipt_duration_ms: u64,
    pub stale_reappearance_count: u32,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionBurdenAudit {
    pub lanes: Vec<NativeCorrectionLaneBurdenAudit>,
    pub operator_action_count: u32,
    pub cleanup_action_count: u32,
    pub model_turn_count: u32,
    pub harness_retry_count: u32,
    pub same_phase_replay_count: u32,
    pub provider_internal_retry_count: NativeCorrectionUnavailableCount,
    pub aggregate_lane_wall_elapsed_ms: u64,
    pub aggregate_active_receipt_duration_ms: u64,
    pub stale_reappearance_count: u32,
    pub within_preregistered_contract: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionLifecycleAudit {
    pub valid: bool,
    pub complete: bool,
    pub provider_calls_completed: u32,
    pub lanes: Vec<(u32, NativeCorrectionLaneLifecycle)>,
    pub next_phase: Option<String>,
    pub next_lane_order: Option<u32>,
    pub burden: Option<NativeCorrectionBurdenAudit>,
    pub failures: Vec<String>,
}

fn native_correction_provider_model_turns(
    receipt: &NativeCorrectionProviderReceipt,
) -> NativeCorrectionResult<u32> {
    let (codex_turn_completed, claude_turns) = match receipt.phase {
        NativeCorrectionProviderPhase::Proposal => {
            let evidence: NativeCorrectionProposalEvidence =
                serde_json::from_value(receipt.normalized_evidence.clone())?;
            (evidence.codex_turn_completed, evidence.claude_turns)
        }
        NativeCorrectionProviderPhase::Retrieval => {
            let evidence: NativeCorrectionRetrievalEvidence =
                serde_json::from_value(receipt.normalized_evidence.clone())?;
            (evidence.codex_turn_completed, evidence.claude_turns)
        }
    };
    match receipt.host {
        NativeCorrectionHost::Codex
            if codex_turn_completed == Some(true) && claude_turns.is_none() =>
        {
            Ok(1)
        }
        NativeCorrectionHost::ClaudeCode if codex_turn_completed.is_none() => claude_turns
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "Claude correction receipt omitted its exact model-turn count".to_string(),
                )
            }),
        _ => invalid("correction receipt model-turn evidence contradicted its host"),
    }
}

fn native_correction_value_contains_any(value: &Value, needles: &[&str]) -> bool {
    match value {
        Value::String(text) => needles
            .iter()
            .any(|needle| !needle.is_empty() && text.contains(needle)),
        Value::Array(values) => values
            .iter()
            .any(|value| native_correction_value_contains_any(value, needles)),
        Value::Object(values) => values.iter().any(|(key, value)| {
            needles
                .iter()
                .any(|needle| !needle.is_empty() && key.contains(needle))
                || native_correction_value_contains_any(value, needles)
        }),
        Value::Null | Value::Bool(_) | Value::Number(_) => false,
    }
}

fn native_correction_value_contains_any_except_root_keys(
    value: &Value,
    needles: &[&str],
    ignored_root_keys: &[&str],
) -> bool {
    let Value::Object(values) = value else {
        return native_correction_value_contains_any(value, needles);
    };
    values.iter().any(|(key, value)| {
        !ignored_root_keys.contains(&key.as_str())
            && (needles
                .iter()
                .any(|needle| !needle.is_empty() && key.contains(needle))
                || native_correction_value_contains_any(value, needles))
    })
}

fn native_correction_active_list_contains_any(
    value: &Value,
    needles: &[&str],
) -> NativeCorrectionResult<bool> {
    let items = value
        .get("items")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "correction burden active-list projection omitted its items array".to_string(),
            )
        })?;
    for item in items {
        let object = item.as_object().ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "correction burden active-list item was not an object".to_string(),
            )
        })?;
        for field in ["id", "title", "content", "tags", "procedure"] {
            if object
                .get(field)
                .is_some_and(|value| native_correction_value_contains_any(value, needles))
            {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

fn native_correction_stale_material(
    memory: &NativeCorrectionMemorySnapshot,
) -> NativeCorrectionResult<Vec<String>> {
    let mut material = BTreeSet::from([
        memory.id.clone(),
        memory.title.clone(),
        memory.content.clone(),
    ]);
    material.extend(memory.tags.iter().cloned());
    if let Some(value) = &memory.procedure {
        let procedure: ProcedureCard = serde_json::from_value(value.clone())?;
        material.insert(procedure.task);
        material.extend(procedure.commands);
        material.extend(procedure.failure_signatures);
        material.insert(procedure.verification.command);
        material.insert(procedure.verification.expected_output_contains);
        if let Some(evidence_path) = procedure.verification.evidence_path {
            material.insert(evidence_path);
        }
        if let Some(evidence_sha256) = procedure.verification.evidence_sha256 {
            material.insert(evidence_sha256);
        }
        for prerequisite in procedure.prerequisites {
            material.insert(prerequisite.key);
            material.insert(prerequisite.expected);
            if let Some(ProcedurePrerequisiteSource::Toml {
                relative_path,
                key_path,
            }) = prerequisite.source
            {
                material.insert(relative_path);
                material.extend(key_path);
            }
        }
    }
    material.retain(|value| !value.is_empty());
    Ok(material.into_iter().collect())
}

fn native_correction_stale_reappearance_count(
    lane: &PreparedNativeCorrectionLane,
    operator: &NativeCorrectionOperatorReceipt,
    retrieval: &NativeCorrectionProviderReceipt,
    cleanup: &NativeCorrectionCleanupReceipt,
) -> NativeCorrectionResult<u32> {
    let operator_results = operator
        .events
        .iter()
        .filter(|event| event.action == NativeCorrectionOperatorAction::RestartAtlasActiveList)
        .map(|event| &event.result)
        .collect::<Vec<_>>();
    let retrieval_evidence: NativeCorrectionRetrievalEvidence =
        serde_json::from_value(retrieval.normalized_evidence.clone())?;
    let retrieval_results = retrieval_evidence
        .events
        .iter()
        .filter(|event| event.kind == NativeCorrectionObservedEventKind::ActiveList)
        .map(|event| &event.result)
        .collect::<Vec<_>>();
    let cleanup_results = cleanup
        .events
        .iter()
        .filter(|event| {
            matches!(
                event.action,
                NativeCorrectionCleanupAction::RestartProcedureMatchAbstention
                    | NativeCorrectionCleanupAction::RestartActiveListEmpty
                    | NativeCorrectionCleanupAction::RestartMemoryReferenceAbsent
                    | NativeCorrectionCleanupAction::RestartDerivedGraphAbsent
                    | NativeCorrectionCleanupAction::RestartCommitReferenceRedacted
                    | NativeCorrectionCleanupAction::RestartRetrievalTraceAbsent
                    | NativeCorrectionCleanupAction::RestartFeedbackAbsent
            )
        })
        .map(|event| (event.action, &event.result))
        .collect::<Vec<_>>();
    if operator_results.len() != 1 || retrieval_results.len() != 1 || cleanup_results.len() != 7 {
        return invalid("correction burden omitted a preregistered post-boundary projection");
    }

    let mut obsolete_material = native_correction_stale_material(&operator.old_after)?;
    if !obsolete_material
        .iter()
        .any(|value| value == &lane.obsolete_id)
    {
        return invalid("correction stale-material set omitted the obsolete ID");
    }
    let replacement_material = native_correction_stale_material(&operator.replacement_after)?;
    let replacement_material_set = replacement_material.iter().collect::<BTreeSet<_>>();
    obsolete_material.retain(|value| !replacement_material_set.contains(value));
    let mut forgotten_material = obsolete_material.clone();
    forgotten_material.extend(replacement_material);
    forgotten_material.retain(|value| value != &lane.tag);
    forgotten_material.sort();
    forgotten_material.dedup();
    let obsolete_needles = obsolete_material
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let forgotten_needles = forgotten_material
        .iter()
        .map(String::as_str)
        .collect::<Vec<_>>();
    let mut total = 0u32;
    for result in operator_results.iter().chain(retrieval_results.iter()) {
        total = total
            .checked_add(u32::from(native_correction_active_list_contains_any(
                result,
                &obsolete_needles,
            )?))
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "correction stale-reappearance count overflowed".to_string(),
                )
            })?;
    }
    for (action, result) in cleanup_results {
        let ignored_root_keys = if matches!(
            action,
            NativeCorrectionCleanupAction::RestartProcedureMatchAbstention
        ) {
            &["query"][..]
        } else {
            &[][..]
        };
        total = total
            .checked_add(u32::from(
                native_correction_value_contains_any_except_root_keys(
                    result,
                    &forgotten_needles,
                    ignored_root_keys,
                ),
            ))
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "correction stale-reappearance count overflowed".to_string(),
                )
            })?;
    }
    Ok(total)
}

fn derive_native_correction_lane_burden(
    lane: &PreparedNativeCorrectionLane,
    proposal: &NativeCorrectionProviderReceipt,
    operator: &NativeCorrectionOperatorReceipt,
    retrieval: &NativeCorrectionProviderReceipt,
    cleanup: &NativeCorrectionCleanupReceipt,
) -> NativeCorrectionResult<NativeCorrectionLaneBurdenAudit> {
    if proposal.lane_order != lane.order
        || proposal.host != lane.host
        || proposal.phase != NativeCorrectionProviderPhase::Proposal
        || operator.host != lane.host
        || retrieval.lane_order != lane.order
        || retrieval.host != lane.host
        || retrieval.phase != NativeCorrectionProviderPhase::Retrieval
        || cleanup.host != lane.host
    {
        return invalid("correction burden receipt identity drifted");
    }
    for (earlier_label, earlier, later_label, later) in [
        (
            "proposal.completed_unix_ms",
            proposal.completed_unix_ms,
            "operator.started_unix_ms",
            operator.started_unix_ms,
        ),
        (
            "operator.completed_unix_ms",
            operator.completed_unix_ms,
            "retrieval.started_unix_ms",
            retrieval.started_unix_ms,
        ),
        (
            "retrieval.completed_unix_ms",
            retrieval.completed_unix_ms,
            "cleanup.started_unix_ms",
            cleanup.started_unix_ms,
        ),
    ] {
        require_native_correction_timestamp_order(earlier_label, earlier, later_label, later)?;
    }
    let proposal_start_through_cleanup_completion_ms = cleanup
        .completed_unix_ms
        .checked_sub(proposal.started_unix_ms)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "correction burden wall elapsed time underflowed".to_string(),
            )
        })?;
    let active_receipt_duration_ms = [
        proposal.duration_ms,
        operator.duration_ms,
        retrieval.duration_ms,
        cleanup.duration_ms,
    ]
    .into_iter()
    .try_fold(0u64, |total, duration| {
        total.checked_add(duration).ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "correction active receipt duration overflowed".to_string(),
            )
        })
    })?;
    let model_turn_count = native_correction_provider_model_turns(proposal)?
        .checked_add(native_correction_provider_model_turns(retrieval)?)
        .ok_or_else(|| {
            NativeCorrectionError::Invalid("correction model-turn count overflowed".to_string())
        })?;
    let harness_retry_count = [
        proposal.recovered,
        retrieval.recovered,
        operator.recovered_after_ambiguous_apply,
        cleanup.retry_used_as_causal_evidence,
    ]
    .into_iter()
    .map(u32::from)
    .sum();
    Ok(NativeCorrectionLaneBurdenAudit {
        lane_order: lane.order,
        host: lane.host,
        operator_action_count: u32::try_from(operator.events.len()).map_err(|_| {
            NativeCorrectionError::Invalid("operator action count overflowed".to_string())
        })?,
        cleanup_action_count: u32::try_from(cleanup.events.len()).map_err(|_| {
            NativeCorrectionError::Invalid("cleanup action count overflowed".to_string())
        })?,
        model_turn_count,
        harness_retry_count,
        same_phase_replay_count: u32::from(operator.reapplied),
        provider_internal_retry_count: NativeCorrectionUnavailableCount::Unavailable,
        proposal_start_through_cleanup_completion_ms,
        active_receipt_duration_ms,
        stale_reappearance_count: native_correction_stale_reappearance_count(
            lane, operator, retrieval, cleanup,
        )?,
    })
}

fn aggregate_native_correction_burden(
    protocol: &NativeCorrectionProtocol,
    lanes: Vec<NativeCorrectionLaneBurdenAudit>,
) -> NativeCorrectionResult<NativeCorrectionBurdenAudit> {
    let mut operator_action_count = 0u32;
    let mut cleanup_action_count = 0u32;
    let mut model_turn_count = 0u32;
    let mut harness_retry_count = 0u32;
    let mut same_phase_replay_count = 0u32;
    let mut aggregate_lane_wall_elapsed_ms = 0u64;
    let mut aggregate_active_receipt_duration_ms = 0u64;
    let mut stale_reappearance_count = 0u32;
    for lane in &lanes {
        operator_action_count = operator_action_count
            .checked_add(lane.operator_action_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("operator action aggregate overflowed".to_string())
            })?;
        cleanup_action_count = cleanup_action_count
            .checked_add(lane.cleanup_action_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("cleanup action aggregate overflowed".to_string())
            })?;
        model_turn_count = model_turn_count
            .checked_add(lane.model_turn_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("model-turn aggregate overflowed".to_string())
            })?;
        harness_retry_count = harness_retry_count
            .checked_add(lane.harness_retry_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("harness retry aggregate overflowed".to_string())
            })?;
        same_phase_replay_count = same_phase_replay_count
            .checked_add(lane.same_phase_replay_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("same-phase replay aggregate overflowed".to_string())
            })?;
        aggregate_lane_wall_elapsed_ms = aggregate_lane_wall_elapsed_ms
            .checked_add(lane.proposal_start_through_cleanup_completion_ms)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid("lane wall elapsed aggregate overflowed".to_string())
            })?;
        aggregate_active_receipt_duration_ms = aggregate_active_receipt_duration_ms
            .checked_add(lane.active_receipt_duration_ms)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "active receipt duration aggregate overflowed".to_string(),
                )
            })?;
        stale_reappearance_count = stale_reappearance_count
            .checked_add(lane.stale_reappearance_count)
            .ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "stale-reappearance aggregate overflowed".to_string(),
                )
            })?;
    }
    let expected_lane_count = protocol.lanes.len();
    let within_preregistered_contract = lanes.len() == expected_lane_count
        && lanes
            .iter()
            .zip(&protocol.lanes)
            .all(|(observed, expected)| {
                observed.lane_order == expected.order
                    && observed.host == expected.host
                    && observed.operator_action_count == protocol.burden.operator_actions_per_lane
                    && observed.cleanup_action_count == protocol.burden.cleanup_actions_per_lane
                    && observed.provider_internal_retry_count
                        == NativeCorrectionUnavailableCount::Unavailable
            })
        && model_turn_count <= protocol.burden.max_model_turns_total
        && harness_retry_count == protocol.burden.required_harness_retry_count
        && same_phase_replay_count == protocol.burden.required_same_phase_replay_count
        && aggregate_active_receipt_duration_ms <= protocol.burden.max_active_elapsed_ms_total
        && stale_reappearance_count == protocol.burden.required_stale_reappearance_count;
    Ok(NativeCorrectionBurdenAudit {
        lanes,
        operator_action_count,
        cleanup_action_count,
        model_turn_count,
        harness_retry_count,
        same_phase_replay_count,
        provider_internal_retry_count: NativeCorrectionUnavailableCount::Unavailable,
        aggregate_lane_wall_elapsed_ms,
        aggregate_active_receipt_duration_ms,
        stale_reappearance_count,
        within_preregistered_contract,
    })
}

pub fn audit_native_correction_lifecycle(
    run_plan: &Path,
) -> NativeCorrectionResult<NativeCorrectionLifecycleAudit> {
    let (plan, plan_sha256, protocol) = load_attested_plan(run_plan)?;
    let mut failures = Vec::new();
    let mut states = Vec::new();
    let mut lane_burdens = Vec::new();
    let mut completed_calls = 0u32;
    for lane in &plan.lanes {
        let proposal = phase_presence(&lane.proposal);
        let operator = operator_presence(lane);
        let retrieval = phase_presence(&lane.retrieval);
        let cleanup = cleanup_presence(lane)?;
        let state = match (proposal, operator, retrieval, cleanup) {
            (
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
            ) => NativeCorrectionLaneLifecycle::AwaitingProposal,
            (ArtifactPresence::Partial, _, _, _) => {
                NativeCorrectionLaneLifecycle::FrozenIncompleteProposal
            }
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
            ) => NativeCorrectionLaneLifecycle::AwaitingOperator,
            (ArtifactPresence::Complete, ArtifactPresence::Partial, _, _) => {
                NativeCorrectionLaneLifecycle::FrozenIncompleteOperator
            }
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Absent,
                ArtifactPresence::Absent,
            ) => NativeCorrectionLaneLifecycle::AwaitingRetrieval,
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Partial,
                _,
            ) => NativeCorrectionLaneLifecycle::FrozenIncompleteRetrieval,
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Absent,
            ) => NativeCorrectionLaneLifecycle::AwaitingCleanup,
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Partial,
            ) => NativeCorrectionLaneLifecycle::FrozenIncompleteCleanup,
            (
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
                ArtifactPresence::Complete,
            ) => NativeCorrectionLaneLifecycle::Complete,
            _ => NativeCorrectionLaneLifecycle::Invalid,
        };
        if state == NativeCorrectionLaneLifecycle::Invalid {
            failures.push(format!("lane {} has out-of-order artifacts", lane.order));
        }
        let proposal_receipt = if matches!(proposal, ArtifactPresence::Complete) {
            match read_and_validate_provider_receipt(
                &plan,
                lane,
                NativeCorrectionProviderPhase::Proposal,
            ) {
                Ok(receipt) => {
                    completed_calls += 1;
                    Some(receipt)
                }
                Err(error) => {
                    failures.push(format!("lane {} proposal: {error}", lane.order));
                    None
                }
            }
        } else {
            None
        };
        let operator_receipt = if matches!(operator, ArtifactPresence::Complete) {
            let validated = (|| -> NativeCorrectionResult<NativeCorrectionOperatorReceipt> {
                let path = Path::new(&lane.operator_receipt);
                let (receipt, _): (NativeCorrectionOperatorReceipt, _) =
                    read_digest_bound_strict_json(
                        path,
                        &receipt_digest_path(path),
                        8 * 1024 * 1024,
                        "operator receipt",
                    )?;
                if receipt.run_plan_sha256 != plan_sha256 {
                    return invalid("operator lost run-plan binding");
                }
                validate_recorded_native_correction_operator_receipt(&plan, lane, &receipt)?;
                Ok(receipt)
            })();
            match validated {
                Ok(receipt) => Some(receipt),
                Err(error) => {
                    failures.push(format!("lane {} operator: {error}", lane.order));
                    None
                }
            }
        } else {
            None
        };
        let intent = match receipt_presence(Path::new(&lane.operator_intent)) {
            ArtifactPresence::Complete => {
                let validated = (|| -> NativeCorrectionResult<NativeCorrectionOperatorIntent> {
                    let path = Path::new(&lane.operator_intent);
                    let (intent, _): (NativeCorrectionOperatorIntent, _) =
                        read_digest_bound_strict_json(
                            path,
                            &receipt_digest_path(path),
                            1024 * 1024,
                            "operator intent",
                        )?;
                    validate_native_correction_operator_intent(&plan, lane, &intent)?;
                    Ok(intent)
                })();
                match validated {
                    Ok(intent) => Some(intent),
                    Err(error) => {
                        failures.push(format!("lane {} operator intent: {error}", lane.order));
                        None
                    }
                }
            }
            ArtifactPresence::Partial => {
                failures.push(format!(
                    "lane {} operator intent or digest is orphaned",
                    lane.order
                ));
                None
            }
            ArtifactPresence::Absent => None,
        };
        match receipt_presence(Path::new(&lane.operator_dispatch)) {
            ArtifactPresence::Complete => {
                if let (Some(intent), Some(operator_receipt)) =
                    (intent.as_ref(), operator_receipt.as_ref())
                {
                    if let Err(error) = load_native_correction_operator_dispatch(
                        &plan,
                        lane,
                        intent,
                        &operator_receipt.proposal_before.canonical_digest,
                    ) {
                        failures.push(format!("lane {} operator dispatch: {error}", lane.order));
                    }
                } else if intent.is_none() {
                    failures.push(format!(
                        "lane {} operator dispatch has no valid durable intent",
                        lane.order
                    ));
                }
            }
            ArtifactPresence::Partial => failures.push(format!(
                "lane {} operator dispatch or digest is orphaned",
                lane.order
            )),
            ArtifactPresence::Absent => {}
        }
        let retrieval_receipt = if matches!(retrieval, ArtifactPresence::Complete) {
            match read_and_validate_provider_receipt(
                &plan,
                lane,
                NativeCorrectionProviderPhase::Retrieval,
            ) {
                Ok(receipt) => {
                    completed_calls += 1;
                    Some(receipt)
                }
                Err(error) => {
                    failures.push(format!("lane {} retrieval: {error}", lane.order));
                    None
                }
            }
        } else {
            None
        };
        let cleanup_receipt = if matches!(cleanup, ArtifactPresence::Complete) {
            let validated = (|| -> NativeCorrectionResult<NativeCorrectionCleanupReceipt> {
                let paths = native_correction_cleanup_paths(lane)?;
                let (receipt, _): (NativeCorrectionCleanupReceipt, _) =
                    read_digest_bound_strict_json(
                        &paths.receipt,
                        &receipt_digest_path(&paths.receipt),
                        8 * 1024 * 1024,
                        "cleanup receipt",
                    )?;
                validate_recorded_native_correction_cleanup_receipt(&plan, lane, &receipt)?;
                Ok(receipt)
            })();
            match validated {
                Ok(receipt) => Some(receipt),
                Err(error) => {
                    failures.push(format!("lane {} cleanup: {error}", lane.order));
                    None
                }
            }
        } else {
            None
        };
        if let (Some(proposal_receipt), Some(operator_receipt), Some(retrieval_receipt)) = (
            proposal_receipt.as_ref(),
            operator_receipt.as_ref(),
            retrieval_receipt.as_ref(),
        ) {
            let proposal_evidence: NativeCorrectionProposalEvidence =
                serde_json::from_value(proposal_receipt.normalized_evidence.clone())?;
            let retrieval_evidence: NativeCorrectionRetrievalEvidence =
                serde_json::from_value(retrieval_receipt.normalized_evidence.clone())?;
            if proposal_evidence.process_identity == retrieval_evidence.process_identity
                || proposal_receipt.completed_unix_ms > operator_receipt.started_unix_ms
                || operator_receipt.completed_unix_ms > retrieval_receipt.started_unix_ms
            {
                failures.push(format!(
                    "lane {} did not prove distinct chronological provider/operator processes",
                    lane.order
                ));
            }
        }
        if let (Some(retrieval_receipt), Some(cleanup_receipt)) =
            (retrieval_receipt.as_ref(), cleanup_receipt.as_ref())
        {
            if retrieval_receipt.completed_unix_ms > cleanup_receipt.started_unix_ms {
                failures.push(format!(
                    "lane {} cleanup predates fresh-provider retrieval",
                    lane.order
                ));
            }
        }
        if let (
            Some(proposal_receipt),
            Some(operator_receipt),
            Some(retrieval_receipt),
            Some(cleanup_receipt),
        ) = (
            proposal_receipt.as_ref(),
            operator_receipt.as_ref(),
            retrieval_receipt.as_ref(),
            cleanup_receipt.as_ref(),
        ) {
            match derive_native_correction_lane_burden(
                lane,
                proposal_receipt,
                operator_receipt,
                retrieval_receipt,
                cleanup_receipt,
            ) {
                Ok(burden) => lane_burdens.push(burden),
                Err(error) => failures.push(format!("lane {} burden: {error}", lane.order)),
            }
        }
        states.push((lane.order, state));
    }
    let frozen = states.iter().any(|(_, state)| {
        matches!(
            state,
            NativeCorrectionLaneLifecycle::FrozenIncompleteProposal
                | NativeCorrectionLaneLifecycle::FrozenIncompleteOperator
                | NativeCorrectionLaneLifecycle::FrozenIncompleteRetrieval
                | NativeCorrectionLaneLifecycle::FrozenIncompleteCleanup
                | NativeCorrectionLaneLifecycle::Invalid
        )
    });
    let (next_phase, next_lane_order) = if frozen {
        (None, None)
    } else if let Some((order, _)) = states
        .iter()
        .find(|(_, state)| *state == NativeCorrectionLaneLifecycle::AwaitingProposal)
    {
        (Some("proposal".to_string()), Some(*order))
    } else if let Some((order, _)) = states
        .iter()
        .find(|(_, state)| *state == NativeCorrectionLaneLifecycle::AwaitingOperator)
    {
        // Operator may begin only after both proposal provider calls completed.
        if states.iter().all(|(_, state)| {
            matches!(
                state,
                NativeCorrectionLaneLifecycle::AwaitingOperator
                    | NativeCorrectionLaneLifecycle::AwaitingRetrieval
                    | NativeCorrectionLaneLifecycle::AwaitingCleanup
                    | NativeCorrectionLaneLifecycle::Complete
            )
        }) {
            (Some("operator".to_string()), Some(*order))
        } else {
            (None, None)
        }
    } else if let Some((order, _)) = states
        .iter()
        .find(|(_, state)| *state == NativeCorrectionLaneLifecycle::AwaitingRetrieval)
    {
        if states.iter().all(|(_, state)| {
            matches!(
                state,
                NativeCorrectionLaneLifecycle::AwaitingRetrieval
                    | NativeCorrectionLaneLifecycle::AwaitingCleanup
                    | NativeCorrectionLaneLifecycle::Complete
            )
        }) {
            (Some("retrieval".to_string()), Some(*order))
        } else {
            (None, None)
        }
    } else if let Some((order, _)) = states
        .iter()
        .find(|(_, state)| *state == NativeCorrectionLaneLifecycle::AwaitingCleanup)
    {
        if states.iter().all(|(_, state)| {
            matches!(
                state,
                NativeCorrectionLaneLifecycle::AwaitingCleanup
                    | NativeCorrectionLaneLifecycle::Complete
            )
        }) {
            (Some("cleanup".to_string()), Some(*order))
        } else {
            (None, None)
        }
    } else {
        (None, None)
    };
    let burden = if lane_burdens.len() == plan.lanes.len() {
        match aggregate_native_correction_burden(&protocol, lane_burdens) {
            Ok(burden) => {
                if !burden.within_preregistered_contract {
                    failures.push(
                        "correction burden exceeded its preregistered exact contract".to_string(),
                    );
                }
                Some(burden)
            }
            Err(error) => {
                failures.push(format!("correction burden aggregate: {error}"));
                None
            }
        }
    } else {
        None
    };
    let complete = states
        .iter()
        .all(|(_, state)| *state == NativeCorrectionLaneLifecycle::Complete)
        && burden
            .as_ref()
            .is_some_and(|burden| burden.within_preregistered_contract)
        && failures.is_empty()
        && !frozen;
    Ok(NativeCorrectionLifecycleAudit {
        valid: failures.is_empty() && !frozen,
        complete,
        provider_calls_completed: completed_calls,
        lanes: states,
        next_phase,
        next_lane_order,
        burden,
        failures,
    })
}

fn read_and_validate_provider_receipt(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    phase: NativeCorrectionProviderPhase,
) -> NativeCorrectionResult<NativeCorrectionProviderReceipt> {
    read_and_validate_provider_receipt_with_digest(plan, lane, phase).map(|(receipt, _)| receipt)
}

fn read_and_validate_provider_receipt_with_digest(
    plan: &PreparedNativeCorrection,
    lane: &PreparedNativeCorrectionLane,
    phase: NativeCorrectionProviderPhase,
) -> NativeCorrectionResult<(NativeCorrectionProviderReceipt, String)> {
    let path = Path::new(&phase_artifacts(lane, phase).receipt);
    let (receipt, digest): (NativeCorrectionProviderReceipt, _) = read_digest_bound_strict_json(
        path,
        &receipt_digest_path(path),
        8 * 1024 * 1024,
        "provider receipt",
    )?;
    if receipt.phase != phase {
        return invalid("provider receipt phase did not match its frozen artifact path");
    }
    validate_provider_receipt(plan, lane, &receipt)?;
    Ok((receipt, digest))
}

fn require_proposal_turn(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<()> {
    for lane in &plan.lanes {
        let presence = phase_presence(&lane.proposal);
        if lane.order < order && presence != ArtifactPresence::Complete {
            return invalid("proposal lanes must complete in frozen order");
        }
        if lane.order == order && !phase_outputs_ready_for_receipt(&lane.proposal) {
            return invalid("proposal raw outputs are incomplete, out of order, or replayed");
        }
        if lane.order > order && presence != ArtifactPresence::Absent {
            return invalid("refusing proposal replay or out-of-order artifact");
        }
        if operator_presence(lane) != ArtifactPresence::Absent
            || phase_presence(&lane.retrieval) != ArtifactPresence::Absent
            || cleanup_presence(lane)? != ArtifactPresence::Absent
        {
            return invalid(
                "operator/retrieval/cleanup artifact exists before proposal phase completed",
            );
        }
    }
    Ok(())
}

fn require_operator_turn(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<()> {
    if plan
        .lanes
        .iter()
        .any(|lane| phase_presence(&lane.proposal) != ArtifactPresence::Complete)
    {
        return invalid("operator phase requires both proposal receipts");
    }
    for lane in &plan.lanes {
        let operator = operator_presence(lane);
        if lane.order < order && operator != ArtifactPresence::Complete {
            return invalid("operator lanes must complete in frozen order");
        }
        if lane.order >= order && operator != ArtifactPresence::Absent {
            return invalid("refusing operator replay or out-of-order artifact");
        }
        if phase_presence(&lane.retrieval) != ArtifactPresence::Absent {
            return invalid("retrieval artifact exists before operator phase completed");
        }
        if cleanup_presence(lane)? != ArtifactPresence::Absent {
            return invalid("cleanup artifact exists before operator phase completed");
        }
    }
    Ok(())
}

/// Execution may resume only at the exact target lane when a complete intent, or a complete
/// intent plus dispatch WAL, is present and every externally visible operator output is absent.
/// The lifecycle audit deliberately classifies either state as frozen/ambiguous; this narrower
/// execution gate is the sole path that may inspect server state to decide whether the fsynced
/// tuple is still pending or was already applied.
fn require_operator_execution_turn(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<()> {
    if plan
        .lanes
        .iter()
        .any(|lane| phase_presence(&lane.proposal) != ArtifactPresence::Complete)
    {
        return invalid("operator phase requires both proposal receipts");
    }
    for lane in &plan.lanes {
        if phase_presence(&lane.retrieval) != ArtifactPresence::Absent {
            return invalid("retrieval artifact exists before operator phase completed");
        }
        if cleanup_presence(lane)? != ArtifactPresence::Absent {
            return invalid("cleanup artifact exists before operator phase completed");
        }
        if lane.order < order {
            if operator_presence(lane) != ArtifactPresence::Complete {
                return invalid("operator lanes must complete in frozen order");
            }
            continue;
        }
        if lane.order > order {
            if operator_presence(lane) != ArtifactPresence::Absent {
                return invalid("future operator lane contains residue");
            }
            continue;
        }

        let intent = receipt_presence(Path::new(&lane.operator_intent));
        let verification_dispatch =
            receipt_presence(Path::new(&lane.operator_verification_dispatch));
        let dispatch = receipt_presence(Path::new(&lane.operator_dispatch));
        let receipt = receipt_presence(Path::new(&lane.operator_receipt));
        let trace = path_entry_exists(Path::new(&lane.operator_trace));
        let stderr = path_entry_exists(Path::new(&lane.operator_stderr));
        let resumable = matches!(
            intent,
            ArtifactPresence::Absent | ArtifactPresence::Complete
        ) && matches!(
            verification_dispatch,
            ArtifactPresence::Absent | ArtifactPresence::Complete
        ) && matches!(
            dispatch,
            ArtifactPresence::Absent | ArtifactPresence::Complete
        ) && !(intent == ArtifactPresence::Absent
            && (verification_dispatch != ArtifactPresence::Absent
                || dispatch != ArtifactPresence::Absent))
            && !(verification_dispatch == ArtifactPresence::Absent
                && dispatch != ArtifactPresence::Absent)
            && !trace
            && !stderr
            && receipt == ArtifactPresence::Absent;
        if !resumable {
            return invalid("target operator lane contains non-resumable or orphaned residue");
        }
    }
    Ok(())
}

fn require_operator_receipt_turn(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<()> {
    for lane in &plan.lanes {
        if lane.order < order && operator_presence(lane) != ArtifactPresence::Complete {
            return invalid("operator receipts must complete in frozen order");
        }
        if lane.order > order && operator_presence(lane) != ArtifactPresence::Absent {
            return invalid("future operator lane contains residue");
        }
        if phase_presence(&lane.retrieval) != ArtifactPresence::Absent {
            return invalid("retrieval artifact exists before operator receipt");
        }
        if cleanup_presence(lane)? != ArtifactPresence::Absent {
            return invalid("cleanup artifact exists before operator receipt");
        }
        if lane.order == order {
            let ready = receipt_presence(Path::new(&lane.operator_intent))
                == ArtifactPresence::Complete
                && receipt_presence(Path::new(&lane.operator_verification_dispatch))
                    == ArtifactPresence::Complete
                && receipt_presence(Path::new(&lane.operator_dispatch))
                    == ArtifactPresence::Complete
                && path_entry_exists(Path::new(&lane.operator_trace))
                && path_entry_exists(Path::new(&lane.operator_stderr))
                && receipt_presence(Path::new(&lane.operator_receipt)) == ArtifactPresence::Absent;
            if !ready {
                return invalid("target operator receipt inputs are incomplete or replayed");
            }
        }
    }
    Ok(())
}

fn require_retrieval_turn(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<()> {
    if plan.lanes.iter().any(|lane| {
        phase_presence(&lane.proposal) != ArtifactPresence::Complete
            || receipt_presence(Path::new(&lane.operator_receipt)) != ArtifactPresence::Complete
    }) {
        return invalid("retrieval phase requires both operator receipts");
    }
    for lane in &plan.lanes {
        let retrieval = phase_presence(&lane.retrieval);
        if cleanup_presence(lane)? != ArtifactPresence::Absent {
            return invalid("cleanup artifact exists before retrieval phase completed");
        }
        if lane.order < order && retrieval != ArtifactPresence::Complete {
            return invalid("retrieval lanes must complete in frozen order");
        }
        if lane.order == order && !phase_outputs_ready_for_receipt(&lane.retrieval) {
            return invalid("retrieval raw outputs are incomplete, out of order, or replayed");
        }
        if lane.order > order && retrieval != ArtifactPresence::Absent {
            return invalid("refusing retrieval replay or out-of-order artifact");
        }
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ArtifactPresence {
    Absent,
    Partial,
    Complete,
}

fn phase_presence(phase: &NativeCorrectionPhaseArtifacts) -> ArtifactPresence {
    let trace = path_entry_exists(Path::new(&phase.trace));
    let stderr = path_entry_exists(Path::new(&phase.stderr));
    let output = path_entry_exists(Path::new(&phase.output));
    let receipt = path_entry_exists(Path::new(&phase.receipt));
    let sidecar = path_entry_exists(&receipt_digest_path(Path::new(&phase.receipt)));
    match (trace, stderr, output, receipt, sidecar) {
        (false, false, false, false, false) => ArtifactPresence::Absent,
        (true, true, true, true, true) => ArtifactPresence::Complete,
        _ => ArtifactPresence::Partial,
    }
}

fn phase_outputs_ready_for_receipt(phase: &NativeCorrectionPhaseArtifacts) -> bool {
    path_entry_exists(Path::new(&phase.trace))
        && path_entry_exists(Path::new(&phase.stderr))
        && path_entry_exists(Path::new(&phase.output))
        && !path_entry_exists(Path::new(&phase.receipt))
        && !path_entry_exists(&receipt_digest_path(Path::new(&phase.receipt)))
}

fn receipt_presence(path: &Path) -> ArtifactPresence {
    match (
        path_entry_exists(path),
        path_entry_exists(&receipt_digest_path(path)),
    ) {
        (false, false) => ArtifactPresence::Absent,
        (true, true) => ArtifactPresence::Complete,
        _ => ArtifactPresence::Partial,
    }
}

fn operator_presence(lane: &PreparedNativeCorrectionLane) -> ArtifactPresence {
    let intent = receipt_presence(Path::new(&lane.operator_intent));
    let verification_dispatch = receipt_presence(Path::new(&lane.operator_verification_dispatch));
    let dispatch = receipt_presence(Path::new(&lane.operator_dispatch));
    let receipt = receipt_presence(Path::new(&lane.operator_receipt));
    let trace = path_entry_exists(Path::new(&lane.operator_trace));
    let stderr = path_entry_exists(Path::new(&lane.operator_stderr));
    match (
        intent,
        verification_dispatch,
        dispatch,
        trace,
        stderr,
        receipt,
    ) {
        (
            ArtifactPresence::Absent,
            ArtifactPresence::Absent,
            ArtifactPresence::Absent,
            false,
            false,
            ArtifactPresence::Absent,
        ) => ArtifactPresence::Absent,
        (
            ArtifactPresence::Complete,
            ArtifactPresence::Complete,
            ArtifactPresence::Complete,
            true,
            true,
            ArtifactPresence::Complete,
        ) => ArtifactPresence::Complete,
        _ => ArtifactPresence::Partial,
    }
}

fn path_entry_exists(path: &Path) -> bool {
    match fs::symlink_metadata(path) {
        Ok(_) => true,
        Err(error) => error.kind() != std::io::ErrorKind::NotFound,
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionAuthProvisioningReport {
    pub provider_free: bool,
    pub destination_count: u32,
    pub owner_only: bool,
    pub no_overwrite: bool,
    pub source_content_reported: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct NativeCorrectionAuthReadinessReport {
    pub provider_free: bool,
    pub codex_cache_count: u32,
    pub codex_chatgpt_login: bool,
    pub claude_profile_count: u32,
    pub claude_subscription_login: bool,
    pub api_key_mode: bool,
    pub raw_credential_content_reported: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeCorrectionClaudeAuthStatus {
    logged_in: bool,
    auth_method: String,
    api_provider: String,
    exit_code: i32,
    stdout_sha256: String,
    stderr_sha256: String,
    output_bytes: u64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeCorrectionCodexAuthStatus {
    chatgpt_login: bool,
    api_key_mode: bool,
    exit_code: i32,
    stdout_sha256: String,
    stderr_sha256: String,
    output_bytes: u64,
}

trait NativeCorrectionAuthBackend {
    fn codex_status(
        &mut self,
        codex: &Path,
        cwd: &Path,
        environment: &BTreeMap<String, String>,
    ) -> NativeCorrectionResult<NativeCorrectionCodexAuthStatus>;

    fn claude_status(
        &mut self,
        claude: &Path,
        config_dir: &Path,
    ) -> NativeCorrectionResult<NativeCorrectionClaudeAuthStatus>;
}

struct NativeCorrectionCliAuthBackend;

impl NativeCorrectionAuthBackend for NativeCorrectionCliAuthBackend {
    fn codex_status(
        &mut self,
        codex: &Path,
        cwd: &Path,
        environment: &BTreeMap<String, String>,
    ) -> NativeCorrectionResult<NativeCorrectionCodexAuthStatus> {
        let (exit_code, stdout, stderr) = run_bounded_native_correction_command(
            codex,
            &["login", "status"],
            cwd,
            environment,
            Duration::from_secs(5),
            64 * 1024,
        )?;
        let stdout_text = std::str::from_utf8(&stdout).map_err(|_| {
            NativeCorrectionError::Invalid("Codex auth status stdout was not UTF-8".into())
        })?;
        let stderr_text = std::str::from_utf8(&stderr).map_err(|_| {
            NativeCorrectionError::Invalid("Codex auth status stderr was not UTF-8".into())
        })?;
        let messages = [stdout_text.trim(), stderr_text.trim()]
            .into_iter()
            .filter(|message| !message.is_empty())
            .collect::<Vec<_>>();
        Ok(NativeCorrectionCodexAuthStatus {
            chatgpt_login: messages == ["Logged in using ChatGPT"],
            api_key_mode: messages == ["Logged in using an API key"],
            exit_code,
            stdout_sha256: format!("{:x}", Sha256::digest(&stdout)),
            stderr_sha256: format!("{:x}", Sha256::digest(&stderr)),
            output_bytes: stdout.len().saturating_add(stderr.len()) as u64,
        })
    }

    fn claude_status(
        &mut self,
        claude: &Path,
        config_dir: &Path,
    ) -> NativeCorrectionResult<NativeCorrectionClaudeAuthStatus> {
        let environment = BTreeMap::from([
            (
                "CLAUDE_CONFIG_DIR".to_string(),
                canonical_string(config_dir)?,
            ),
            (
                "CLAUDE_CODE_DISABLE_AUTO_MEMORY".to_string(),
                "1".to_string(),
            ),
            ("DISABLE_TELEMETRY".to_string(), "1".to_string()),
            (
                "PATH".to_string(),
                "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
            ),
        ]);
        let (exit_code, stdout, stderr) = run_bounded_native_correction_command(
            claude,
            &["auth", "status", "--json"],
            config_dir,
            &environment,
            Duration::from_secs(5),
            64 * 1024,
        )?;
        let output_bytes = stdout.len().saturating_add(stderr.len()) as u64;
        let value = strict_json_value_from_slice(&stdout)?;
        let object = value.as_object().ok_or_else(|| {
            NativeCorrectionError::Invalid(
                "Claude auth status JSON was not an exact object".to_string(),
            )
        })?;
        if object.keys().map(String::as_str).collect::<BTreeSet<_>>()
            != BTreeSet::from(["apiProvider", "authMethod", "loggedIn"])
        {
            return invalid("Claude auth status JSON shape drifted");
        }
        Ok(NativeCorrectionClaudeAuthStatus {
            logged_in: object.get("loggedIn").and_then(Value::as_bool) == Some(true),
            auth_method: object
                .get("authMethod")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string(),
            api_provider: object
                .get("apiProvider")
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_string(),
            exit_code,
            stdout_sha256: format!("{:x}", Sha256::digest(&stdout)),
            stderr_sha256: format!("{:x}", Sha256::digest(&stderr)),
            output_bytes,
        })
    }
}

fn run_bounded_native_correction_command(
    binary: &Path,
    arguments: &[&str],
    cwd: &Path,
    environment: &BTreeMap<String, String>,
    timeout: Duration,
    byte_limit: u64,
) -> NativeCorrectionResult<(i32, Vec<u8>, Vec<u8>)> {
    run_bounded_native_correction_command_inner(
        binary,
        arguments,
        cwd,
        environment,
        timeout,
        byte_limit,
        |_| {},
    )
}

fn run_bounded_native_correction_command_inner(
    binary: &Path,
    arguments: &[&str],
    cwd: &Path,
    environment: &BTreeMap<String, String>,
    timeout: Duration,
    byte_limit: u64,
    configure_child: impl FnOnce(&mut NativeCorrectionChildGuard),
) -> NativeCorrectionResult<(i32, Vec<u8>, Vec<u8>)> {
    if environment.keys().any(|key| {
        matches!(
            key.as_str(),
            "ANTHROPIC_API_KEY" | "OPENAI_API_KEY" | "CODEX_ACCESS_TOKEN"
        )
    }) {
        return invalid("bounded command environment contains a provider credential key");
    }
    if binary.file_name().and_then(|name| name.to_str()) == Some("engram") {
        validate_native_correction_candidate_bundle(binary)?;
    }
    let (response_deadline, terminal_deadline) = native_correction_deadlines(timeout)?;
    let mut command = Command::new(binary);
    command
        .args(arguments)
        .current_dir(cwd)
        .env_clear()
        .envs(environment)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let mut child = native_correction_spawned_guard(NativeCorrectionChildGuard::spawn(
        command,
        terminal_deadline,
    ))?;
    configure_child(&mut child);
    let stdout = child
        .take_stdout()?
        .ok_or_else(|| NativeCorrectionError::Invalid("bounded command stdout unavailable".into()));
    let stderr = child
        .take_stderr()?
        .ok_or_else(|| NativeCorrectionError::Invalid("bounded command stderr unavailable".into()));
    let (stdout, stderr) = match (stdout, stderr) {
        (Ok(stdout), Ok(stderr)) => (stdout, stderr),
        (stdout, stderr) => {
            let mut failures = Vec::new();
            if let Err(error) = stdout {
                failures.push(error.to_string());
            }
            if let Err(error) = stderr {
                failures.push(error.to_string());
            }
            if let Err(error) = native_correction_cleanup_result(
                child.terminate_group_and_reap_with_status_until(terminal_deadline),
            ) {
                failures.push(format!("bounded command setup cleanup failed: {error}"));
                if let Some(abandonment) =
                    child.abandon_after_cleanup_failure("bounded command setup cleanup")
                {
                    failures.push(abandonment);
                }
            }
            return invalid(failures.join("; "));
        }
    };
    let collect = |reader: Box<dyn Read + Send>| {
        thread::spawn(move || {
            let mut bytes = Vec::new();
            let result = reader.take(byte_limit + 1).read_to_end(&mut bytes);
            (result, bytes)
        })
    };
    let stdout_thread = collect(Box::new(stdout));
    let stderr_thread = collect(Box::new(stderr));
    let completion = loop {
        match child.exited_without_reap(response_deadline) {
            Ok(true) => break Ok(()),
            Ok(false) if Instant::now() < response_deadline => {
                let remaining = response_deadline.saturating_duration_since(Instant::now());
                thread::sleep(remaining.min(Duration::from_millis(10)));
            }
            Ok(false) => break invalid("bounded command exceeded its wall-clock timeout"),
            Err(error) => break Err(error.into()),
        }
    };
    let reaped_status = native_correction_cleanup_result(
        child.terminate_group_and_reap_with_status_until(terminal_deadline),
    );
    let abandonment = reaped_status
        .as_ref()
        .err()
        .and_then(|_| child.abandon_after_cleanup_failure("bounded command cleanup"));
    let stdout_join = join_native_correction_thread_until(
        stdout_thread,
        terminal_deadline,
        "bounded command stdout collector",
    );
    let stderr_join = join_native_correction_thread_until(
        stderr_thread,
        terminal_deadline,
        "bounded command stderr collector",
    );

    let mut failures = Vec::new();
    if let Err(error) = completion {
        failures.push(format!(
            "bounded command completion observation failed: {error}"
        ));
    }
    let status = match reaped_status {
        Ok(status) => Some(status),
        Err(error) => {
            failures.push(format!(
                "bounded command group termination and direct-child reap failed: {error}"
            ));
            None
        }
    };
    if let Some(abandonment) = abandonment {
        failures.push(abandonment);
    }
    let stdout = match stdout_join {
        Ok((result, bytes)) => {
            if let Err(error) = result {
                failures.push(format!("bounded command stdout read failed: {error}"));
            }
            if bytes.len() as u64 > byte_limit {
                failures.push("bounded command stdout exceeded its byte limit".to_string());
            }
            Some(bytes)
        }
        Err(error) => {
            failures.push(error.to_string());
            None
        }
    };
    let stderr = match stderr_join {
        Ok((result, bytes)) => {
            if let Err(error) = result {
                failures.push(format!("bounded command stderr read failed: {error}"));
            }
            if bytes.len() as u64 > byte_limit {
                failures.push("bounded command stderr exceeded its byte limit".to_string());
            }
            Some(bytes)
        }
        Err(error) => {
            failures.push(error.to_string());
            None
        }
    };
    if let (Some(stdout), Some(stderr)) = (&stdout, &stderr) {
        if stdout.len().saturating_add(stderr.len()) as u64 > byte_limit {
            failures.push("bounded command combined output exceeded its byte limit".to_string());
        }
    }
    let code = match status {
        Some(status) => match status.code() {
            Some(code) => Some(code),
            None => {
                failures.push("bounded command exited without a numeric status".to_string());
                None
            }
        },
        None => None,
    };
    if !failures.is_empty() {
        return invalid(failures.join("; "));
    }
    Ok((
        code.expect("failure list proves exit code exists"),
        stdout.expect("failure list proves stdout exists"),
        stderr.expect("failure list proves stderr exists"),
    ))
}

fn preflight_native_correction_auth_destinations(
    plan: &PreparedNativeCorrection,
    protocol: &NativeCorrectionProtocol,
) -> NativeCorrectionResult<()> {
    preflight_native_correction_auth_destinations_allowing(plan, protocol, &BTreeSet::new())
}

fn preflight_native_correction_auth_destinations_allowing(
    plan: &PreparedNativeCorrection,
    protocol: &NativeCorrectionProtocol,
    allowed_existing_auth: &BTreeSet<PathBuf>,
) -> NativeCorrectionResult<()> {
    let run_root = Path::new(&plan.protocol)
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("protocol has no parent".into()))?;
    validate_native_correction_static_plan_metadata(plan, protocol, run_root)?;
    let mut destinations = Vec::new();
    for lane in &plan.lanes {
        if phase_presence(&lane.proposal) != ArtifactPresence::Absent
            || operator_presence(lane) != ArtifactPresence::Absent
            || phase_presence(&lane.retrieval) != ArtifactPresence::Absent
        {
            return invalid("provider/operator/retrieval residue forbids auth provisioning");
        }
        destinations.extend(lane.codex_auth_destinations.iter().map(PathBuf::from));
    }
    if destinations.len() != 2 {
        return invalid("auth provisioner requires exactly two frozen destinations");
    }
    for destination in destinations {
        validate_absolute_normal_path(&destination, "Codex auth destination")?;
        if path_entry_exists(&destination) && !allowed_existing_auth.contains(&destination) {
            return invalid("refusing to overwrite an auth cache destination");
        }
        let parent = destination.parent().ok_or_else(|| {
            NativeCorrectionError::Invalid("auth destination has no parent".into())
        })?;
        validate_existing_path_identity(parent, parent, "Codex auth destination home")?;
        validate_owned_directory(parent, 0o700)?;
    }
    Ok(())
}

/// Copy a bounded Codex ChatGPT file cache to exactly the two prepared homes. The function never
/// returns, logs, or hashes credential bytes. Destinations are `create_new`, regular, single-link,
/// same-owner files under owner-only non-symlink homes. Existing destinations fail closed.
#[cfg(unix)]
pub fn provision_native_correction_codex_auth(
    run_plan: &Path,
    source: &Path,
) -> NativeCorrectionResult<NativeCorrectionAuthProvisioningReport> {
    provision_native_correction_codex_auth_with_hook(run_plan, source, |_, _| Ok(()))
}

#[cfg(unix)]
fn provision_native_correction_codex_auth_with_hook(
    run_plan: &Path,
    source: &Path,
    mut before_create: impl FnMut(usize, &Path) -> NativeCorrectionResult<()>,
) -> NativeCorrectionResult<NativeCorrectionAuthProvisioningReport> {
    provision_native_correction_codex_auth_with_phase_hook(run_plan, source, |phase, path| {
        match phase {
            NativeCorrectionAuthHookPhase::BeforeCreate(index) => before_create(index, path),
            _ => Ok(()),
        }
    })
}

#[cfg(unix)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeCorrectionAuthHookPhase {
    SourceOpened,
    DestinationParentsOpened,
    BeforeCreate(usize),
    AfterOpen(usize),
    AfterCreate(usize),
    BeforeFinalRecheck,
}

#[cfg(unix)]
#[derive(Debug)]
struct NativeCorrectionHeldDirectoryComponent {
    name: std::ffi::CString,
    fd: std::os::fd::OwnedFd,
    device: u64,
    inode: u64,
}

#[cfg(unix)]
#[derive(Debug)]
struct NativeCorrectionHeldDirectory {
    root: std::os::fd::OwnedFd,
    root_device: u64,
    root_inode: u64,
    components: Vec<NativeCorrectionHeldDirectoryComponent>,
}

#[cfg(unix)]
impl NativeCorrectionHeldDirectory {
    fn deepest_fd(&self) -> std::os::fd::RawFd {
        use std::os::fd::AsRawFd;
        self.components
            .last()
            .map(|component| component.fd.as_raw_fd())
            .unwrap_or_else(|| self.root.as_raw_fd())
    }

    fn revalidate(&self, owner_only_final: bool) -> NativeCorrectionResult<()> {
        use std::os::fd::AsRawFd;

        let root = native_correction_fstat(self.root.as_raw_fd())?;
        if root.st_dev as u64 != self.root_device
            || root.st_ino as u64 != self.root_inode
            || root.st_mode & libc::S_IFMT != libc::S_IFDIR
        {
            return invalid("held auth directory root identity drifted");
        }
        let mut parent_fd = self.root.as_raw_fd();
        for component in &self.components {
            let handle = native_correction_fstat(component.fd.as_raw_fd())?;
            let entry =
                native_correction_fstatat(parent_fd, &component.name)?.ok_or_else(|| {
                    NativeCorrectionError::Invalid(
                        "held auth directory component disappeared".to_string(),
                    )
                })?;
            if handle.st_dev as u64 != component.device
                || handle.st_ino as u64 != component.inode
                || entry.st_dev != handle.st_dev
                || entry.st_ino != handle.st_ino
                || handle.st_mode & libc::S_IFMT != libc::S_IFDIR
                || entry.st_mode & libc::S_IFMT != libc::S_IFDIR
            {
                return invalid("held auth directory component identity drifted");
            }
            parent_fd = component.fd.as_raw_fd();
        }
        if owner_only_final {
            let final_meta = native_correction_fstat(self.deepest_fd())?;
            if final_meta.st_uid != unsafe { libc::geteuid() }
                || final_meta.st_mode & 0o7777 != 0o700
            {
                return invalid("auth destination home is not exact owner-only mode 0700");
            }
        }
        Ok(())
    }
}

#[cfg(unix)]
#[derive(Debug)]
struct NativeCorrectionCreatedAuthDestination {
    destination_index: usize,
    device: u64,
    inode: u64,
    file: File,
}

#[cfg(unix)]
fn native_correction_fstat(fd: std::os::fd::RawFd) -> NativeCorrectionResult<libc::stat> {
    let mut metadata = unsafe { std::mem::zeroed::<libc::stat>() };
    // SAFETY: metadata points to writable storage and fd is held open by the caller.
    if unsafe { libc::fstat(fd, &mut metadata) } != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    Ok(metadata)
}

#[cfg(unix)]
fn native_correction_fstatat(
    directory_fd: std::os::fd::RawFd,
    name: &std::ffi::CStr,
) -> NativeCorrectionResult<Option<libc::stat>> {
    let mut metadata = unsafe { std::mem::zeroed::<libc::stat>() };
    // SAFETY: name is NUL-terminated, metadata is writable, and the directory FD is held open.
    if unsafe {
        libc::fstatat(
            directory_fd,
            name.as_ptr(),
            &mut metadata,
            libc::AT_SYMLINK_NOFOLLOW,
        )
    } == 0
    {
        return Ok(Some(metadata));
    }
    let error = std::io::Error::last_os_error();
    if error.kind() == std::io::ErrorKind::NotFound {
        Ok(None)
    } else {
        Err(error.into())
    }
}

#[cfg(unix)]
fn open_native_correction_directory_chain(
    path: &Path,
    owner_only_final: bool,
) -> NativeCorrectionResult<NativeCorrectionHeldDirectory> {
    use std::os::fd::{FromRawFd, OwnedFd};
    use std::os::unix::ffi::OsStrExt;

    validate_absolute_normal_path(path, "auth directory")?;
    let root_name = std::ffi::CString::new("/").expect("root path has no NUL");
    // SAFETY: root_name is a fixed C string. The returned descriptor is uniquely owned below.
    let root_fd = unsafe {
        libc::open(
            root_name.as_ptr(),
            libc::O_RDONLY | libc::O_DIRECTORY | libc::O_CLOEXEC,
        )
    };
    if root_fd < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: open returned a new descriptor and ownership is transferred exactly once.
    let root = unsafe { OwnedFd::from_raw_fd(root_fd) };
    let root_metadata = native_correction_fstat(root_fd)?;
    let mut components = Vec::new();
    let mut parent_fd = root_fd;
    for component in path.components() {
        let Component::RootDir = component else {
            let Component::Normal(name) = component else {
                return invalid("auth directory contained a non-normal component");
            };
            let name = std::ffi::CString::new(name.as_bytes()).map_err(|_| {
                NativeCorrectionError::Invalid("auth directory component contained NUL".into())
            })?;
            // SAFETY: parent_fd remains owned by root or a previously retained component. The
            // component C string is valid and O_NOFOLLOW rejects a symlink component.
            let child_fd = unsafe {
                libc::openat(
                    parent_fd,
                    name.as_ptr(),
                    libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
                )
            };
            if child_fd < 0 {
                return Err(std::io::Error::last_os_error().into());
            }
            // SAFETY: openat returned a new descriptor and ownership is transferred once.
            let fd = unsafe { OwnedFd::from_raw_fd(child_fd) };
            let metadata = native_correction_fstat(child_fd)?;
            if metadata.st_mode & libc::S_IFMT != libc::S_IFDIR {
                return invalid("auth directory component was not a directory");
            }
            components.push(NativeCorrectionHeldDirectoryComponent {
                name,
                fd,
                device: metadata.st_dev as u64,
                inode: metadata.st_ino as u64,
            });
            parent_fd = child_fd;
            continue;
        };
    }
    let held = NativeCorrectionHeldDirectory {
        root,
        root_device: root_metadata.st_dev as u64,
        root_inode: root_metadata.st_ino as u64,
        components,
    };
    held.revalidate(owner_only_final)?;
    Ok(held)
}

#[cfg(unix)]
fn native_correction_auth_leaf(path: &Path) -> NativeCorrectionResult<std::ffi::CString> {
    use std::os::unix::ffi::OsStrExt;
    let name = path.file_name().ok_or_else(|| {
        NativeCorrectionError::Invalid("auth path omitted a final filename".into())
    })?;
    std::ffi::CString::new(name.as_bytes())
        .map_err(|_| NativeCorrectionError::Invalid("auth filename contained NUL".into()))
}

#[cfg(unix)]
fn provision_native_correction_codex_auth_with_phase_hook(
    run_plan: &Path,
    source: &Path,
    mut hook: impl FnMut(NativeCorrectionAuthHookPhase, &Path) -> NativeCorrectionResult<()>,
) -> NativeCorrectionResult<NativeCorrectionAuthProvisioningReport> {
    use std::os::fd::{AsRawFd, FromRawFd};

    let (plan, _, protocol) = load_attested_plan(run_plan)?;
    preflight_native_correction_auth_destinations(&plan, &protocol)?;
    let codex_lane = plan
        .lanes
        .iter()
        .find(|lane| lane.host == NativeCorrectionHost::Codex)
        .ok_or_else(|| NativeCorrectionError::Invalid("Codex lane is missing".to_string()))?;
    if codex_lane.codex_auth_destinations.len() != 2 {
        return invalid("auth provisioner requires exactly two frozen destinations");
    }
    let expected_uid = unsafe { libc::geteuid() };
    validate_absolute_normal_path(source, "auth source")?;
    let destinations = codex_lane
        .codex_auth_destinations
        .iter()
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    let destination_parents = destinations
        .iter()
        .map(|destination| {
            open_native_correction_directory_chain(
                destination.parent().ok_or_else(|| {
                    NativeCorrectionError::Invalid("auth destination has no parent".into())
                })?,
                true,
            )
        })
        .collect::<NativeCorrectionResult<Vec<_>>>()?;
    let destination_names = destinations
        .iter()
        .map(|path| native_correction_auth_leaf(path))
        .collect::<NativeCorrectionResult<Vec<_>>>()?;
    for (parent, name) in destination_parents.iter().zip(&destination_names) {
        parent.revalidate(true)?;
        if native_correction_fstatat(parent.deepest_fd(), name)?.is_some() {
            return invalid("refusing to overwrite an auth cache destination");
        }
    }

    let source_parent_path = source.parent().ok_or_else(|| {
        NativeCorrectionError::Invalid("auth source has no parent directory".into())
    })?;
    let source_parent = open_native_correction_directory_chain(source_parent_path, false)?;
    let source_name = native_correction_auth_leaf(source)?;
    // SAFETY: the held parent FD is stable, source_name is valid, and O_NOFOLLOW rejects a leaf
    // symlink. The returned descriptor is transferred exactly once to File.
    let source_fd = unsafe {
        libc::openat(
            source_parent.deepest_fd(),
            source_name.as_ptr(),
            libc::O_RDONLY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
        )
    };
    if source_fd < 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: openat returned a new descriptor and ownership is transferred once.
    let mut source_file = unsafe { File::from_raw_fd(source_fd) };
    let source_stat = native_correction_fstat(source_fd)?;
    if source_stat.st_mode & libc::S_IFMT != libc::S_IFREG
        || source_stat.st_uid != expected_uid
        || source_stat.st_nlink != 1
        || source_stat.st_size <= 0
        || source_stat.st_size as u64 > MAX_AUTH_CACHE_BYTES
        || source_stat.st_mode & 0o7177 != 0
    {
        return invalid(
            "auth source must be bounded, owner-only, same-owner, regular, and single-link",
        );
    }
    let source_entry = native_correction_fstatat(source_parent.deepest_fd(), &source_name)?
        .ok_or_else(|| NativeCorrectionError::Invalid("auth source disappeared".into()))?;
    if source_entry.st_dev != source_stat.st_dev || source_entry.st_ino != source_stat.st_ino {
        return invalid("auth source pathname did not match its opened inode");
    }
    hook(NativeCorrectionAuthHookPhase::SourceOpened, source)?;
    let mut bytes = Zeroizing::new(Vec::with_capacity(source_stat.st_size as usize));
    Read::take(&mut source_file, MAX_AUTH_CACHE_BYTES + 1).read_to_end(&mut bytes)?;
    let source_after = native_correction_fstat(source_fd)?;
    source_parent.revalidate(false)?;
    let source_entry_after = native_correction_fstatat(source_parent.deepest_fd(), &source_name)?
        .ok_or_else(|| {
        NativeCorrectionError::Invalid("auth source disappeared after read".into())
    })?;
    if source_stat.st_dev != source_after.st_dev
        || source_stat.st_ino != source_after.st_ino
        || source_stat.st_size != source_after.st_size
        || source_stat.st_mtime != source_after.st_mtime
        || source_stat.st_mtime_nsec != source_after.st_mtime_nsec
        || source_after.st_dev != source_entry_after.st_dev
        || source_after.st_ino != source_entry_after.st_ino
        || bytes.len() as i64 != source_stat.st_size
    {
        return invalid("auth source identity changed during its bounded opaque read");
    }

    hook(
        NativeCorrectionAuthHookPhase::DestinationParentsOpened,
        &destinations[0],
    )?;
    preflight_native_correction_auth_destinations(&plan, &protocol)?;
    for (parent, name) in destination_parents.iter().zip(&destination_names) {
        parent.revalidate(true)?;
        if native_correction_fstatat(parent.deepest_fd(), name)?.is_some() {
            return invalid("refusing to overwrite an auth cache destination");
        }
    }

    let mut created: Vec<NativeCorrectionCreatedAuthDestination> = Vec::new();
    for (index, ((destination, parent), name)) in destinations
        .iter()
        .zip(destination_parents.iter())
        .zip(destination_names.iter())
        .enumerate()
    {
        if let Err(primary) = hook(
            NativeCorrectionAuthHookPhase::BeforeCreate(index),
            destination,
        ) {
            let cleanup = rollback_native_correction_auth_destinations(
                &destination_parents,
                &destination_names,
                &mut created,
            );
            return combine_native_correction_cleanup(
                Err(primary),
                cleanup,
                "auth destination rollback",
            );
        }
        let mut created_current = None;
        let result = (|| -> NativeCorrectionResult<()> {
            preflight_native_correction_auth_destinations_allowing(
                &plan,
                &protocol,
                &created
                    .iter()
                    .map(|existing| destinations[existing.destination_index].clone())
                    .collect(),
            )?;
            for (candidate_index, (candidate_parent, candidate_name)) in destination_parents
                .iter()
                .zip(&destination_names)
                .enumerate()
            {
                candidate_parent.revalidate(true)?;
                let observed =
                    native_correction_fstatat(candidate_parent.deepest_fd(), candidate_name)?;
                if candidate_index >= created.len() && observed.is_some() {
                    return invalid("refusing to overwrite an auth cache destination");
                }
                if let Some(existing) = created.get(candidate_index) {
                    let observed = observed.ok_or_else(|| {
                        NativeCorrectionError::Invalid(
                            "a previously created auth destination disappeared".into(),
                        )
                    })?;
                    if observed.st_dev as u64 != existing.device
                        || observed.st_ino as u64 != existing.inode
                    {
                        return invalid("a previously created auth destination was replaced");
                    }
                }
            }
            // SAFETY: the held parent FD and leaf name are stable. O_EXCL and O_NOFOLLOW make the
            // final create non-overwriting and non-symlink-following.
            let fd = unsafe {
                libc::openat(
                    parent.deepest_fd(),
                    name.as_ptr(),
                    libc::O_RDWR
                        | libc::O_CREAT
                        | libc::O_EXCL
                        | libc::O_NOFOLLOW
                        | libc::O_CLOEXEC,
                    0o600,
                )
            };
            if fd < 0 {
                return Err(std::io::Error::last_os_error().into());
            }
            // SAFETY: openat returned a new descriptor and ownership is transferred once.
            let file = unsafe { File::from_raw_fd(fd) };
            let handle = native_correction_fstat(fd)?;
            created_current = Some(NativeCorrectionCreatedAuthDestination {
                destination_index: index,
                device: handle.st_dev as u64,
                inode: handle.st_ino as u64,
                file,
            });
            hook(NativeCorrectionAuthHookPhase::AfterOpen(index), destination)?;
            let file = &mut created_current
                .as_mut()
                .expect("created destination was just recorded")
                .file;
            file.write_all(&bytes)?;
            file.sync_all()?;
            let written_handle = native_correction_fstat(fd)?;
            let entry = native_correction_fstatat(parent.deepest_fd(), name)?.ok_or_else(|| {
                NativeCorrectionError::Invalid("written auth cache disappeared".into())
            })?;
            if written_handle.st_mode & libc::S_IFMT != libc::S_IFREG
                || written_handle.st_dev != entry.st_dev
                || written_handle.st_ino != entry.st_ino
                || written_handle.st_uid != expected_uid
                || written_handle.st_nlink != 1
                || written_handle.st_mode & 0o7777 != 0o600
                || written_handle.st_size != source_stat.st_size
            {
                return invalid("written auth cache failed owner/link/size validation");
            }
            // SAFETY: fsync operates only on the retained destination directory descriptor.
            if unsafe { libc::fsync(parent.deepest_fd()) } != 0 {
                return Err(std::io::Error::last_os_error().into());
            }
            Ok(())
        })();
        match result {
            Ok(()) => created.push(
                created_current
                    .take()
                    .expect("successful auth create recorded its inode"),
            ),
            Err(error) => {
                if let Some(created_destination) = created_current.take() {
                    created.push(created_destination);
                }
                let cleanup = rollback_native_correction_auth_destinations(
                    &destination_parents,
                    &destination_names,
                    &mut created,
                );
                return combine_native_correction_cleanup(
                    Err(error),
                    cleanup,
                    "auth destination rollback",
                );
            }
        }
        if let Err(primary) = hook(
            NativeCorrectionAuthHookPhase::AfterCreate(index),
            destination,
        ) {
            let cleanup = rollback_native_correction_auth_destinations(
                &destination_parents,
                &destination_names,
                &mut created,
            );
            return combine_native_correction_cleanup(
                Err(primary),
                cleanup,
                "auth destination rollback",
            );
        }
    }
    let final_check = (|| -> NativeCorrectionResult<()> {
        hook(
            NativeCorrectionAuthHookPhase::BeforeFinalRecheck,
            &destinations[0],
        )?;
        for (index, ((parent, name), created_destination)) in destination_parents
            .iter()
            .zip(&destination_names)
            .zip(&created)
            .enumerate()
        {
            parent.revalidate(true)?;
            if created_destination.destination_index != index {
                return invalid("auth destination creation order drifted");
            }
            let handle = native_correction_fstat(created_destination.file.as_raw_fd())?;
            let entry = native_correction_fstatat(parent.deepest_fd(), name)?.ok_or_else(|| {
                NativeCorrectionError::Invalid(
                    "auth destination disappeared before final check".into(),
                )
            })?;
            if handle.st_dev as u64 != created_destination.device
                || handle.st_ino as u64 != created_destination.inode
                || entry.st_dev != handle.st_dev
                || entry.st_ino != handle.st_ino
                || handle.st_size != source_stat.st_size
                || handle.st_mode & 0o7777 != 0o600
                || handle.st_uid != expected_uid
                || handle.st_nlink != 1
            {
                return invalid("auth destination final inode binding drifted");
            }
            verify_native_correction_auth_destination_bytes(
                &created_destination.file,
                bytes.as_slice(),
            )?;
        }
        Ok(())
    })();
    if let Err(primary) = final_check {
        let cleanup = rollback_native_correction_auth_destinations(
            &destination_parents,
            &destination_names,
            &mut created,
        );
        return combine_native_correction_cleanup(
            Err(primary),
            cleanup,
            "auth destination rollback",
        );
    }
    Ok(NativeCorrectionAuthProvisioningReport {
        provider_free: true,
        destination_count: 2,
        owner_only: true,
        no_overwrite: true,
        source_content_reported: false,
    })
}

#[cfg(unix)]
fn verify_native_correction_auth_destination_bytes(
    file: &File,
    expected: &[u8],
) -> NativeCorrectionResult<()> {
    use std::os::unix::fs::FileExt;

    let mut observed = Zeroizing::new(vec![0_u8; expected.len()]);
    let mut offset = 0usize;
    while offset < observed.len() {
        let read = file.read_at(&mut observed[offset..], offset as u64)?;
        if read == 0 {
            return invalid("auth destination became shorter during final opaque verification");
        }
        offset = offset.checked_add(read).ok_or_else(|| {
            NativeCorrectionError::Invalid("auth destination read offset overflowed".into())
        })?;
    }
    let mut extra = [0_u8; 1];
    if file.read_at(&mut extra, expected.len() as u64)? != 0 {
        return invalid("auth destination became longer during final opaque verification");
    }
    if observed.as_slice() != expected {
        return invalid("auth destination content drifted before final opaque verification");
    }
    Ok(())
}

#[cfg(unix)]
#[allow(clippy::unnecessary_cast)] // libc::dev_t is target-dependent across Unix platforms.
fn rollback_native_correction_auth_destinations(
    parents: &[NativeCorrectionHeldDirectory],
    names: &[std::ffi::CString],
    created: &mut [NativeCorrectionCreatedAuthDestination],
) -> NativeCorrectionResult<()> {
    let mut failures = Vec::new();
    for destination in created.iter_mut().rev() {
        let parent = &parents[destination.destination_index];
        let name = &names[destination.destination_index];
        if let Err(error) = destination
            .file
            .set_len(0)
            .and_then(|()| destination.file.sync_all())
        {
            failures.push(format!(
                "cannot erase a partially copied auth inode before rollback: {error}"
            ));
        }
        match native_correction_fstatat(parent.deepest_fd(), name) {
            Ok(Some(entry))
                if entry.st_dev as u64 == destination.device
                    && entry.st_ino == destination.inode =>
            {
                // SAFETY: the entry was re-bound to the exact evaluator-created inode through the
                // still-held parent FD. No replacement path is ever unlinked.
                if unsafe { libc::unlinkat(parent.deepest_fd(), name.as_ptr(), 0) } != 0 {
                    failures.push(format!(
                        "cannot unlink an inode-bound auth destination: {}",
                        std::io::Error::last_os_error()
                    ));
                }
            }
            Ok(None) => {}
            Ok(Some(_)) => failures.push(
                "auth destination entry was replaced; refusing to delete the replacement; manual quarantine required"
                    .to_string(),
            ),
            Err(error) => failures.push(format!(
                "cannot inspect auth destination during rollback: {error}"
            )),
        }
        // SAFETY: fsync is restricted to the retained destination directory descriptor.
        if unsafe { libc::fsync(parent.deepest_fd()) } != 0 {
            failures.push(format!(
                "cannot sync an auth destination parent: {}",
                std::io::Error::last_os_error()
            ));
        }
        match native_correction_fstatat(parent.deepest_fd(), name) {
            Ok(None) => {}
            Ok(Some(entry))
                if entry.st_dev as u64 != destination.device
                    || entry.st_ino != destination.inode =>
            {
                failures.push(
                    "a replacement auth entry remains quarantined after rollback".to_string(),
                );
            }
            Ok(Some(_)) => failures
                .push("an evaluator-created auth destination remained after rollback".to_string()),
            Err(error) => failures.push(format!(
                "cannot verify auth destination absence after rollback: {error}"
            )),
        }
        if let Err(error) = parent.revalidate(true) {
            failures.push(format!(
                "auth destination parent drifted during rollback: {error}"
            ));
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        invalid(failures.join("; "))
    }
}

#[cfg(not(unix))]
pub fn provision_native_correction_codex_auth(
    _run_plan: &Path,
    _source: &Path,
) -> NativeCorrectionResult<NativeCorrectionAuthProvisioningReport> {
    invalid("owner-only Codex auth provisioning requires Unix permission semantics")
}

pub fn check_native_correction_auth_ready(
    run_plan: &Path,
) -> NativeCorrectionResult<NativeCorrectionAuthReadinessReport> {
    check_native_correction_auth_ready_with_backend(run_plan, &mut NativeCorrectionCliAuthBackend)
}

fn check_native_correction_auth_ready_with_backend(
    run_plan: &Path,
    auth: &mut impl NativeCorrectionAuthBackend,
) -> NativeCorrectionResult<NativeCorrectionAuthReadinessReport> {
    let (plan, _, _) = load_attested_plan(run_plan)?;
    let destinations = plan
        .lanes
        .iter()
        .filter(|lane| lane.host == NativeCorrectionHost::Codex)
        .flat_map(|lane| lane.codex_auth_destinations.iter())
        .collect::<Vec<_>>();
    if destinations.len() != 2 {
        return invalid("prepared plan does not contain exactly two Codex auth destinations");
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        let expected_uid = unsafe { libc::geteuid() };
        for destination in destinations {
            let path = Path::new(destination);
            let meta = fs::symlink_metadata(path)?;
            if meta.file_type().is_symlink()
                || !meta.is_file()
                || meta.uid() != expected_uid
                || meta.nlink() != 1
                || meta.permissions().mode() & 0o077 != 0
                || meta.len() == 0
                || meta.len() > MAX_AUTH_CACHE_BYTES
            {
                return invalid("one Codex auth cache is not a bounded owner-only regular file");
            }
        }
    }
    #[cfg(not(unix))]
    return invalid("Codex auth readiness requires Unix permission semantics");
    let codex = Path::new(&plan.runtime.binaries["codex"].path);
    let codex_lane = plan
        .lanes
        .iter()
        .find(|lane| lane.host == NativeCorrectionHost::Codex)
        .ok_or_else(|| NativeCorrectionError::Invalid("Codex lane is missing".into()))?;
    let codex_homes = [
        codex_lane.codex_proposal_home.as_deref(),
        codex_lane.codex_retrieval_home.as_deref(),
    ];
    let codex_environments = [
        &codex_lane.proposal_environment,
        &codex_lane.retrieval_environment,
    ];
    let mut codex_status_count = 0u32;
    for (home, frozen_environment) in codex_homes.into_iter().zip(codex_environments) {
        let home =
            Path::new(home.ok_or_else(|| {
                NativeCorrectionError::Invalid("Codex auth home is missing".into())
            })?);
        validate_owned_directory(home, 0o700)?;
        let mut environment = frozen_environment.clone();
        if environment.get("CODEX_HOME").map(String::as_str) != home.to_str()
            || environment.keys().any(|key| {
                matches!(
                    key.as_str(),
                    "ANTHROPIC_API_KEY" | "OPENAI_API_KEY" | "CODEX_ACCESS_TOKEN"
                )
            })
        {
            return invalid("Codex auth status environment drifted or contained a provider key");
        }
        environment.insert(
            "PATH".to_string(),
            "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
        );
        let status = auth.codex_status(codex, Path::new(&codex_lane.cwd), &environment)?;
        if status.exit_code != 0
            || !status.chatgpt_login
            || status.api_key_mode
            || !looks_like_sha256(&status.stdout_sha256)
            || !looks_like_sha256(&status.stderr_sha256)
            || status.output_bytes > 64 * 1024
        {
            return invalid("Codex isolated cache is not ready with ChatGPT login");
        }
        codex_status_count = codex_status_count.saturating_add(1);
    }
    if codex_status_count != 2 {
        return invalid("Codex auth readiness did not attest exactly two isolated caches");
    }
    let claude = Path::new(&plan.runtime.binaries["claude_code"].path);
    let claude_lane = plan
        .lanes
        .iter()
        .find(|lane| lane.host == NativeCorrectionHost::ClaudeCode)
        .ok_or_else(|| NativeCorrectionError::Invalid("Claude lane is missing".into()))?;
    let config_dirs = [
        claude_lane.claude_proposal_config_dir.as_deref(),
        claude_lane.claude_retrieval_config_dir.as_deref(),
    ];
    let mut statuses = Vec::with_capacity(2);
    for config in config_dirs {
        let config = Path::new(config.ok_or_else(|| {
            NativeCorrectionError::Invalid("Claude auth config directory is missing".into())
        })?);
        validate_owned_directory(config, 0o700)?;
        let status = auth.claude_status(claude, config)?;
        if status.exit_code != 0
            || !status.logged_in
            || status.auth_method != "claude.ai"
            || status.api_provider != "firstParty"
            || !looks_like_sha256(&status.stdout_sha256)
            || !looks_like_sha256(&status.stderr_sha256)
            || status.output_bytes > 64 * 1024
        {
            return invalid("Claude isolated profile is not ready with subscription login");
        }
        statuses.push(status);
    }
    Ok(NativeCorrectionAuthReadinessReport {
        provider_free: true,
        codex_cache_count: 2,
        codex_chatgpt_login: true,
        claude_profile_count: statuses.len() as u32,
        claude_subscription_login: true,
        api_key_mode: false,
        raw_credential_content_reported: false,
    })
}

fn load_attested_plan(
    run_plan: &Path,
) -> NativeCorrectionResult<(PreparedNativeCorrection, String, NativeCorrectionProtocol)> {
    let run_plan = preflight_run_plan_path(run_plan)?;
    let (plan, plan_sha256): (PreparedNativeCorrection, _) = read_digest_bound_strict_json(
        &run_plan,
        &run_plan.with_file_name("run-plan.sha256"),
        4 * 1024 * 1024,
        "run plan",
    )?;
    if plan.schema_version != NATIVE_CORRECTION_PLAN_SCHEMA_VERSION
        || plan.family != NATIVE_CORRECTION_FAMILY
        || plan.execution_approved
        || plan.provider_calls_total != 4
        || plan.lanes.len() != 2
    {
        return invalid("run-plan header drifted");
    }
    validate_runtime_path_metadata(&plan.runtime)?;
    let run_root = run_plan
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("run-plan has no parent".to_string()))?;
    let expected_protocol_path = run_root.join("protocol.snapshot.json");
    let protocol_path = Path::new(&plan.protocol);
    validate_existing_path_identity(protocol_path, &expected_protocol_path, "protocol snapshot")?;
    validate_owned_regular_file(protocol_path, 0o600)?;
    let protocol_metadata = fs::symlink_metadata(protocol_path)?;
    if protocol_metadata.len() == 0 || protocol_metadata.len() > 1024 * 1024 {
        return invalid("protocol snapshot exceeded its frozen byte boundary");
    }
    let protocol_bytes =
        read_bounded_attested_file(protocol_path, 1024 * 1024, "protocol snapshot")?;
    if format!("{:x}", Sha256::digest(&protocol_bytes)) != plan.protocol_sha256 {
        return invalid("run-plan protocol binding drifted");
    }
    let protocol: NativeCorrectionProtocol = strict_json_from_slice(&protocol_bytes)?;
    validate_native_correction_protocol(&protocol)?;
    if protocol.pilot_id != plan.pilot_id {
        return invalid("run-plan pilot ID differs from protocol snapshot");
    }
    validate_native_correction_static_plan_metadata(&plan, &protocol, run_root)?;
    validate_native_correction_runtime(&plan.runtime)?;
    validate_native_correction_static_plan_content(&plan, &protocol, run_root)?;
    Ok((plan, plan_sha256, protocol))
}

fn lane_by_order(
    plan: &PreparedNativeCorrection,
    order: u32,
) -> NativeCorrectionResult<&PreparedNativeCorrectionLane> {
    plan.lanes
        .iter()
        .find(|lane| lane.order == order)
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("unknown lane order {order}")))
}

fn phase_artifacts(
    lane: &PreparedNativeCorrectionLane,
    phase: NativeCorrectionProviderPhase,
) -> &NativeCorrectionPhaseArtifacts {
    match phase {
        NativeCorrectionProviderPhase::Proposal => &lane.proposal,
        NativeCorrectionProviderPhase::Retrieval => &lane.retrieval,
    }
}

fn artifact_receipt(
    path: &str,
    plan: &PreparedNativeCorrection,
    stderr: bool,
) -> NativeCorrectionResult<NativeCorrectionArtifactReceipt> {
    let path = Path::new(path);
    let metadata = fs::symlink_metadata(path)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return invalid(format!(
            "artifact is not a regular non-symlink file: {}",
            path.display()
        ));
    }
    validate_owned_regular_file(path, 0o600)?;
    let max = if stderr { 1024 * 1024 } else { 8 * 1024 * 1024 };
    if metadata.len() > max {
        return invalid(format!(
            "artifact exceeds frozen byte budget: {}",
            path.display()
        ));
    }
    let root = Path::new(&plan.protocol)
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("plan protocol has no parent".to_string()))?;
    if !path.starts_with(root) {
        return invalid("artifact escaped prepared output root");
    }
    Ok(NativeCorrectionArtifactReceipt {
        path: path.display().to_string(),
        sha256: sha256_file(path)?,
        bytes: metadata.len(),
    })
}

fn receipt_digest_path(path: &Path) -> PathBuf {
    path.with_extension("sha256")
}

fn validate_receipt_digest(path: &Path) -> NativeCorrectionResult<()> {
    validate_receipt_digest_named(path, &receipt_digest_path(path))
}

fn validate_receipt_digest_named(path: &Path, sidecar: &Path) -> NativeCorrectionResult<()> {
    read_digest_bound_bytes(path, sidecar, 8 * 1024 * 1024, "receipt")?;
    Ok(())
}

fn read_digest_bound_strict_json<T: DeserializeOwned>(
    path: &Path,
    sidecar: &Path,
    max_bytes: u64,
    label: &str,
) -> NativeCorrectionResult<(T, String)> {
    let (bytes, digest) = read_digest_bound_bytes(path, sidecar, max_bytes, label)?;
    Ok((strict_json_from_slice(&bytes)?, digest))
}

fn read_digest_bound_bytes(
    path: &Path,
    sidecar: &Path,
    max_bytes: u64,
    label: &str,
) -> NativeCorrectionResult<(Vec<u8>, String)> {
    validate_absolute_normal_path(path, "receipt primary")?;
    validate_absolute_normal_path(sidecar, "receipt digest sidecar")?;
    if path.parent() != sidecar.parent() {
        return invalid("receipt primary and digest sidecar escaped one directory");
    }
    validate_existing_path_identity(path, path, "receipt primary")?;
    validate_existing_path_identity(sidecar, sidecar, "receipt digest sidecar")?;
    validate_owned_regular_file(path, 0o600)?;
    validate_owned_regular_file(sidecar, 0o600)?;
    let primary_len = fs::symlink_metadata(path)?.len();
    if primary_len == 0 || primary_len > max_bytes {
        return invalid(format!(
            "{label} primary exceeded its conservative byte boundary"
        ));
    }
    let sidecar_metadata = fs::symlink_metadata(sidecar)?;
    if sidecar_metadata.len() != 65 {
        return invalid("receipt digest sidecar must be exactly SHA-256 plus newline");
    }
    let sidecar_bytes = read_bounded_attested_file(sidecar, 65, "receipt digest sidecar")?;
    let sidecar_text = std::str::from_utf8(&sidecar_bytes)
        .map_err(|_| NativeCorrectionError::Invalid("receipt digest was not UTF-8".into()))?;
    let expected = sidecar_text.strip_suffix('\n').ok_or_else(|| {
        NativeCorrectionError::Invalid("receipt digest omitted its exact newline".into())
    })?;
    let primary_bytes = read_bounded_attested_file(path, max_bytes, label)?;
    let actual = format!("{:x}", Sha256::digest(&primary_bytes));
    if !looks_like_sha256(expected) || actual != expected {
        return invalid(format!("digest sidecar mismatch for {}", path.display()));
    }
    Ok((primary_bytes, actual))
}

fn create_new_private_dir(path: &Path) -> NativeCorrectionResult<()> {
    fs::create_dir(path)?;
    set_private_directory_mode(path)
}

fn create_private_dir_all(path: &Path) -> NativeCorrectionResult<()> {
    fs::create_dir_all(path)?;
    set_private_directory_mode(path)
}

fn set_private_directory_mode(path: &Path) -> NativeCorrectionResult<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(path, fs::Permissions::from_mode(0o700))?;
    }
    Ok(())
}

fn write_new_file(path: &Path, bytes: &[u8], unix_mode: u32) -> NativeCorrectionResult<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut options = OpenOptions::new();
    options.create_new(true).write(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(unix_mode);
    }
    let mut file = options.open(path)?;
    file.write_all(bytes)?;
    file.sync_all()?;
    sync_parent_directory(path)?;
    Ok(())
}

fn sync_parent_directory(path: &Path) -> NativeCorrectionResult<()> {
    #[cfg(unix)]
    {
        let parent = path
            .parent()
            .ok_or_else(|| NativeCorrectionError::Invalid("path has no parent".to_string()))?;
        File::open(parent)?.sync_all()?;
    }
    Ok(())
}

fn write_private_json(path: &Path, value: &impl Serialize) -> NativeCorrectionResult<()> {
    let mut bytes = serde_json::to_vec_pretty(value)?;
    bytes.push(b'\n');
    write_new_file(path, &bytes, 0o600)
}

fn write_private_text(path: &Path, value: &str) -> NativeCorrectionResult<()> {
    write_new_file(path, value.as_bytes(), 0o600)
}

fn read_bounded_attested_file(
    path: &Path,
    max_bytes: u64,
    label: &str,
) -> NativeCorrectionResult<Vec<u8>> {
    let path_metadata = fs::symlink_metadata(path)?;
    if path_metadata.file_type().is_symlink()
        || !path_metadata.is_file()
        || path_metadata.len() > max_bytes
    {
        return invalid(format!("{label} was unsafe or exceeded its byte boundary"));
    }
    let mut options = OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
    }
    let mut file = options.open(path)?;
    let opened_metadata = file.metadata()?;
    if !opened_metadata.is_file()
        || opened_metadata.len() != path_metadata.len()
        || opened_metadata.len() > max_bytes
    {
        return invalid(format!("{label} changed before its bounded read"));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if opened_metadata.dev() != path_metadata.dev()
            || opened_metadata.ino() != path_metadata.ino()
        {
            return invalid(format!("{label} identity changed before its bounded read"));
        }
    }
    let expected_len = usize::try_from(opened_metadata.len())
        .map_err(|_| NativeCorrectionError::Invalid(format!("{label} length overflowed")))?;
    let mut bytes = vec![0u8; expected_len];
    file.read_exact(&mut bytes)?;
    let mut trailing = [0u8; 1];
    if file.read(&mut trailing)? != 0 {
        return invalid(format!("{label} grew during its bounded read"));
    }
    let final_handle_metadata = file.metadata()?;
    let final_path_metadata = fs::symlink_metadata(path)?;
    if final_handle_metadata.len() != opened_metadata.len()
        || final_path_metadata.len() != opened_metadata.len()
        || final_path_metadata.file_type().is_symlink()
        || !final_path_metadata.is_file()
    {
        return invalid(format!("{label} metadata changed during its bounded read"));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if final_handle_metadata.dev() != path_metadata.dev()
            || final_handle_metadata.ino() != path_metadata.ino()
            || final_path_metadata.dev() != path_metadata.dev()
            || final_path_metadata.ino() != path_metadata.ino()
        {
            return invalid(format!("{label} identity changed during its bounded read"));
        }
    }
    Ok(bytes)
}

fn sha256_file(path: &Path) -> NativeCorrectionResult<String> {
    const MAX_HASH_BYTES: u64 = 512 * 1024 * 1024;
    let path_metadata = fs::symlink_metadata(path)?;
    if path_metadata.file_type().is_symlink()
        || !path_metadata.is_file()
        || path_metadata.len() > MAX_HASH_BYTES
    {
        return invalid(format!(
            "refusing to hash an unsafe or unbounded file: {}",
            path.display()
        ));
    }
    let mut options = OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC);
    }
    let mut file = options.open(path)?;
    let opened_metadata = file.metadata()?;
    if !opened_metadata.is_file()
        || opened_metadata.len() != path_metadata.len()
        || opened_metadata.len() > MAX_HASH_BYTES
    {
        return invalid(format!(
            "file changed before its bounded hash was opened: {}",
            path.display()
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if opened_metadata.dev() != path_metadata.dev()
            || opened_metadata.ino() != path_metadata.ino()
        {
            return invalid(format!(
                "file identity changed before its bounded hash was opened: {}",
                path.display()
            ));
        }
    }
    let mut digest = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    let expected_len = opened_metadata.len();
    let mut remaining = expected_len;
    while remaining != 0 {
        let request = usize::try_from(remaining.min(buffer.len() as u64))
            .expect("bounded buffer request fits usize");
        let read = file.read(&mut buffer[..request])?;
        if read == 0 {
            return invalid(format!(
                "file shrank during its bounded hash: {}",
                path.display()
            ));
        }
        digest.update(&buffer[..read]);
        remaining -= read as u64;
    }
    if file.read(&mut buffer[..1])? != 0 {
        return invalid(format!(
            "file grew during its bounded hash: {}",
            path.display()
        ));
    }
    let final_handle_metadata = file.metadata()?;
    let final_path_metadata = fs::symlink_metadata(path)?;
    if final_handle_metadata.len() != expected_len
        || final_path_metadata.len() != expected_len
        || final_path_metadata.file_type().is_symlink()
        || !final_path_metadata.is_file()
    {
        return invalid(format!(
            "file metadata changed during its bounded hash: {}",
            path.display()
        ));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        if final_handle_metadata.dev() != path_metadata.dev()
            || final_handle_metadata.ino() != path_metadata.ino()
            || final_path_metadata.dev() != path_metadata.dev()
            || final_path_metadata.ino() != path_metadata.ino()
        {
            return invalid(format!(
                "file identity changed during its bounded hash: {}",
                path.display()
            ));
        }
    }
    Ok(format!("{:x}", digest.finalize()))
}

fn sha256_json(value: &impl Serialize) -> NativeCorrectionResult<String> {
    Ok(format!("{:x}", Sha256::digest(serde_json::to_vec(value)?)))
}

fn canonical_string(path: &Path) -> NativeCorrectionResult<String> {
    Ok(path.canonicalize()?.display().to_string())
}

fn canonical_string_allow_missing(path: &Path) -> NativeCorrectionResult<String> {
    let parent = path
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid("path has no parent".to_string()))?
        .canonicalize()?;
    let name = path
        .file_name()
        .ok_or_else(|| NativeCorrectionError::Invalid("path has no file name".to_string()))?;
    Ok(parent.join(name).display().to_string())
}

fn validate_absolute_normal_path(path: &Path, label: &str) -> NativeCorrectionResult<()> {
    validate_native_correction_path_spelling(path, label)?;
    let mut components = path.components();
    if !matches!(components.next(), Some(Component::RootDir)) {
        return invalid(format!(
            "{label} must be an absolute lexically-normal Unix path"
        ));
    }
    let mut rebuilt = PathBuf::from("/");
    for component in components {
        let Component::Normal(value) = component else {
            return invalid(format!(
                "{label} must be an absolute lexically-normal Unix path"
            ));
        };
        rebuilt.push(value);
    }
    if rebuilt.as_os_str() != path.as_os_str() {
        return invalid(format!(
            "{label} must be an absolute lexically-normal Unix path"
        ));
    }
    Ok(())
}

fn validate_relative_normal_path(path: &Path, label: &str) -> NativeCorrectionResult<()> {
    validate_native_correction_path_spelling(path, label)?;
    if path.as_os_str().is_empty() {
        return invalid(format!(
            "{label} must contain only non-empty normal relative path components"
        ));
    }
    let mut rebuilt = PathBuf::new();
    for component in path.components() {
        let Component::Normal(value) = component else {
            return invalid(format!(
                "{label} must contain only non-empty normal relative path components"
            ));
        };
        rebuilt.push(value);
    }
    if rebuilt.as_os_str() != path.as_os_str() {
        return invalid(format!(
            "{label} must contain only non-empty normal relative path components"
        ));
    }
    Ok(())
}

fn validate_native_correction_path_spelling(
    path: &Path,
    label: &str,
) -> NativeCorrectionResult<()> {
    let spelling = path.to_str().ok_or_else(|| {
        NativeCorrectionError::Invalid(format!("{label} must use UTF-8 path spelling"))
    })?;
    if spelling.is_empty()
        || !spelling
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'/' | b'.' | b'_' | b'-'))
    {
        return invalid(format!(
            "{label} contained a byte outside the frozen evaluation path alphabet"
        ));
    }
    Ok(())
}

fn validate_existing_path_identity(
    path: &Path,
    expected: &Path,
    label: &str,
) -> NativeCorrectionResult<()> {
    validate_absolute_normal_path(path, label)?;
    validate_absolute_normal_path(expected, label)?;
    if path != expected {
        return invalid(format!("{label} escaped its frozen path"));
    }
    if path_has_symlink_component(path)? || path.canonicalize()? != expected {
        return invalid(format!("{label} was symlinked or non-canonical"));
    }
    Ok(())
}

fn validate_missing_or_owned_regular_path(
    path: &Path,
    expected: &Path,
    expected_mode: u32,
    label: &str,
) -> NativeCorrectionResult<()> {
    validate_absolute_normal_path(path, label)?;
    validate_absolute_normal_path(expected, label)?;
    if path != expected {
        return invalid(format!("{label} escaped its frozen path"));
    }
    let parent = path
        .parent()
        .ok_or_else(|| NativeCorrectionError::Invalid(format!("{label} has no parent")))?;
    if path_has_symlink_component(parent)? || parent.canonicalize()? != parent {
        return invalid(format!("{label} parent was symlinked or non-canonical"));
    }
    match fs::symlink_metadata(path) {
        Ok(_) => {
            validate_owned_regular_file(path, expected_mode)?;
            if path.canonicalize()? != path {
                return invalid(format!("{label} was non-canonical"));
            }
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error.into()),
    }
    Ok(())
}

fn read_strict_json_file<T: DeserializeOwned>(
    path: &Path,
    expected_mode: u32,
    max_bytes: u64,
    label: &str,
) -> NativeCorrectionResult<T> {
    validate_owned_regular_file_size(path, expected_mode, 1, max_bytes, label)?;
    strict_json_from_slice(&read_bounded_attested_file(path, max_bytes, label)?)
}

fn validate_owned_regular_file_size(
    path: &Path,
    expected_mode: u32,
    min_bytes: u64,
    max_bytes: u64,
    label: &str,
) -> NativeCorrectionResult<()> {
    validate_owned_regular_file(path, expected_mode)?;
    let bytes = fs::symlink_metadata(path)?.len();
    if bytes < min_bytes || bytes > max_bytes {
        return invalid(format!("{label} exceeded its frozen byte boundary"));
    }
    Ok(())
}

fn directory_entry_names(path: &Path, label: &str) -> NativeCorrectionResult<BTreeSet<String>> {
    validate_owned_directory(path, 0o700)?;
    let mut names = BTreeSet::new();
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let name = entry.file_name().into_string().map_err(|_| {
            NativeCorrectionError::Invalid(format!("{label} contained a non-UTF-8 entry"))
        })?;
        if !names.insert(name) {
            return invalid(format!("{label} contained a duplicate entry name"));
        }
    }
    Ok(names)
}

fn require_exact_directory_entries(
    path: &Path,
    expected: &BTreeSet<String>,
    label: &str,
) -> NativeCorrectionResult<()> {
    if directory_entry_names(path, label)? != *expected {
        return invalid(format!("{label} contained unaccounted filesystem residue"));
    }
    Ok(())
}

fn validate_owned_directory(path: &Path, expected_mode: u32) -> NativeCorrectionResult<()> {
    let metadata = fs::symlink_metadata(path)?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return invalid(format!("expected owned directory: {}", path.display()));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        if metadata.uid() != unsafe { libc::geteuid() }
            || metadata.permissions().mode() & 0o7777 != expected_mode
        {
            return invalid(format!(
                "directory ownership or mode drifted: {}",
                path.display()
            ));
        }
    }
    Ok(())
}

fn validate_owned_regular_file(path: &Path, expected_mode: u32) -> NativeCorrectionResult<()> {
    let metadata = fs::symlink_metadata(path)?;
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return invalid(format!("expected owned regular file: {}", path.display()));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::{MetadataExt, PermissionsExt};
        if metadata.uid() != unsafe { libc::geteuid() }
            || metadata.nlink() != 1
            || metadata.permissions().mode() & 0o7777 != expected_mode
        {
            return invalid(format!(
                "file ownership, link count, or mode drifted: {}",
                path.display()
            ));
        }
    }
    Ok(())
}

fn path_has_symlink_component(path: &Path) -> NativeCorrectionResult<bool> {
    let mut current = PathBuf::new();
    for component in path.components() {
        match component {
            Component::Prefix(prefix) => current.push(prefix.as_os_str()),
            Component::RootDir => current.push(Path::new("/")),
            Component::CurDir => continue,
            Component::ParentDir => return Ok(true),
            Component::Normal(part) => current.push(part),
        }
        if fs::symlink_metadata(&current)?.file_type().is_symlink() {
            return Ok(true);
        }
    }
    Ok(false)
}

fn opaque_digest(value: &str, chars: usize) -> String {
    format!("{:x}", Sha256::digest(value.as_bytes()))[..chars].to_string()
}

fn json_string(value: &str) -> NativeCorrectionResult<String> {
    Ok(serde_json::to_string(value)?)
}

fn unix_ms(time: SystemTime) -> NativeCorrectionResult<u64> {
    let value = time
        .duration_since(UNIX_EPOCH)
        .map_err(|error| {
            NativeCorrectionError::Invalid(format!("time predates Unix epoch: {error}"))
        })?
        .as_millis();
    u64::try_from(value)
        .map_err(|_| NativeCorrectionError::Invalid("timestamp overflow".to_string()))
}

fn looks_like_sha256(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn looks_like_uuid(value: &str) -> bool {
    value.len() == 36
        && value.bytes().enumerate().all(|(index, byte)| match index {
            8 | 13 | 18 | 23 => byte == b'-',
            _ => byte.is_ascii_hexdigit(),
        })
}

fn invalid<T>(message: impl Into<String>) -> NativeCorrectionResult<T> {
    Err(NativeCorrectionError::Invalid(message.into()))
}

