    #[derive(Default)]
    struct FakeSeedBackend {
        corrupt_identity: bool,
        leak_replacement: bool,
        corrupt_scope_wrapper: bool,
    }

    impl NativeCorrectionSeedBackend for FakeSeedBackend {
        fn seed_lane(
            &mut self,
            request: &NativeCorrectionSeedRequest,
        ) -> NativeCorrectionResult<NativeCorrectionSeedOutcome> {
            let (old_id, other_id) = match request.host {
                NativeCorrectionHost::Codex => (CODEX_OLD, CODEX_OTHER),
                NativeCorrectionHost::ClaudeCode => (CLAUDE_OLD, CLAUDE_OTHER),
            };
            let item = |id: &str, project: &str, title: &str, content: &str| {
                native_correction_memory_snapshot(
                    &seeded_item(id, project, title, content, &request.tag),
                    None,
                )
                .unwrap()
            };
            let mut receipt = NativeCorrectionSeedReceipt {
                schema_version: 1,
                host: request.host,
                request_sha256: sha256_json(request)?,
                full_profile_handshake_sha256: sha256_json(&runtime().full_profile)?,
                fresh_process: true,
                daemon_stopped: true,
                identity: NativeCorrectionIdentitySnapshot {
                    repository_id: "99999999-9999-4999-8999-999999999999".to_string(),
                    normalized_remote: "github.com/acme/atlas".to_string(),
                    checkout_id: "88888888-8888-4888-8888-888888888888".to_string(),
                    checkout_root: request.orient_cwd.clone(),
                    head_sha: "0123456789abcdef0123456789abcdef01234567".to_string(),
                    project_name: request.project_name.clone(),
                    project_status: if self.corrupt_identity {
                        "requires_confirmation".to_string()
                    } else {
                        "authorized".to_string()
                    },
                    resolution_source: "explicit_project".to_string(),
                    project_linked: !self.corrupt_identity,
                    requires_confirmation: self.corrupt_identity,
                },
                old: item(old_id, "atlas", &request.old_title, &request.old_content),
                other_scope: item(
                    other_id,
                    "orbit",
                    &request.other_title,
                    &request.other_content,
                ),
                active_atlas_ids: vec![old_id.to_string()],
                active_orbit_ids: vec![other_id.to_string()],
                all_memory_ids: vec![old_id.to_string(), other_id.to_string()],
                replacement_count: u32::from(self.leak_replacement),
                proposal_count: 0,
                projection_commit_id: PROJECTION_COMMIT_ID.to_string(),
                projection_trace_id: PROJECTION_TRACE_ID.to_string(),
                projection_feedback_id: PROJECTION_FEEDBACK_ID.to_string(),
                stdio_call_count: 16,
                stdio_transcript_sha256: String::new(),
                stdio_transcript_bytes: 0,
                stdio_stderr_sha256: format!("{:x}", Sha256::digest([])),
                stdio_stderr_bytes: 0,
                reviewer_authority_conferred: false,
                intent_verified: false,
                scope_selector_authenticated: false,
            };
            let transcript = fake_seed_transcript(request, &receipt, self.corrupt_scope_wrapper);
            receipt.stdio_transcript_sha256 = format!("{:x}", Sha256::digest(&transcript));
            receipt.stdio_transcript_bytes = transcript.len() as u64;
            Ok(NativeCorrectionSeedOutcome {
                receipt,
                transcript,
                stderr: Vec::new(),
            })
        }
    }

    fn fake_seed_transcript(
        request: &NativeCorrectionSeedRequest,
        receipt: &NativeCorrectionSeedReceipt,
        corrupt_scope_wrapper: bool,
    ) -> Vec<u8> {
        let old = seeded_item(
            &receipt.old.id,
            "atlas",
            &request.old_title,
            &request.old_content,
            &request.tag,
        );
        let mut old_candidate = old.clone();
        old_candidate.status = MemoryStatus::NeedsReview;
        old_candidate.evidence.pop();
        let other = seeded_item(
            &receipt.other_scope.id,
            "orbit",
            &request.other_title,
            &request.other_content,
            &request.tag,
        );
        let repository_id = &receipt.identity.repository_id;
        let mut proposal_list = selector_result(
            json!({"count":receipt.proposal_count,"proposals":[]}),
            "atlas",
        );
        if corrupt_scope_wrapper {
            proposal_list["scope_selector_authenticated"] = json!(true);
        }
        let calls = vec![
            (
                "work_project",
                json!({"action":"create","name":"atlas","description":"native correction fixture"}),
                json!({"name":"atlas","status":"active"}),
            ),
            (
                "work_project",
                json!({"action":"create","name":"orbit","description":"native correction scope canary"}),
                json!({"name":"orbit","status":"active"}),
            ),
            (
                "repo",
                json!({"action":"detect","cwd":request.orient_cwd}),
                json!({"detection":{"context":{"repository":{"id":repository_id,"remote_url":request.repository_remote},"checkout":{"id":receipt.identity.checkout_id,"repository_id":repository_id,"local_path":request.orient_cwd,"head_sha":receipt.identity.head_sha}}}}),
            ),
            (
                "repo",
                json!({"action":"link_project","repository_id":repository_id,"project_name":"atlas","role":"primary"}),
                json!({"link":{"project_name":"atlas","repository_id":repository_id}}),
            ),
            (
                "memory",
                seed_procedure_arguments(
                    "atlas",
                    &request.old_title,
                    &request.old_content,
                    &request.tag,
                ),
                json!({"item":old_candidate}),
            ),
            (
                "memory",
                json!({
                    "action":"promote",
                    "id":receipt.old.id,
                    "reviewer":"engram-eval-seed",
                    "rationale":"Activate the isolated obsolete procedure fixture; this label is not verified reviewer authority."
                }),
                json!({"item":old}),
            ),
            (
                "memory",
                seed_decision_arguments(
                    "orbit",
                    &request.other_title,
                    &request.other_content,
                    &request.tag,
                    &receipt.old.id,
                ),
                json!({"item":other}),
            ),
            (
                "memory",
                seed_projection_commit_arguments(&old),
                json!({"commit":{"id":receipt.projection_commit_id}}),
            ),
            (
                "telemetry",
                seed_projection_trace_arguments(&old),
                json!({"trace":{"id":receipt.projection_trace_id}}),
            ),
            (
                "telemetry",
                seed_projection_feedback_arguments(&old, &receipt.projection_trace_id),
                json!({"feedback":{"id":receipt.projection_feedback_id},"warnings":[]}),
            ),
            (
                "orient",
                json!({"project":"atlas","cwd":request.orient_cwd,"agent":"engram_eval","response_shape":"lean"}),
                test_orient_result(
                    &request.orient_cwd,
                    "engram_eval",
                    &receipt.identity,
                    &receipt.old,
                ),
            ),
            (
                "memory",
                exact_memory_list_arguments("atlas", request, "active"),
                normal_scope_result(json!({"count":1,"items":[old]}), "atlas"),
            ),
            (
                "memory",
                exact_memory_list_arguments("orbit", request, "active"),
                normal_scope_result(json!({"count":1,"items":[other]}), "orbit"),
            ),
            (
                "memory",
                json!({"action":"list","status_filter":"active","tags":[request.tag],"limit":3,"scope":{"relevance_mode":"global"}}),
                global_scope_result(json!({"count":2,"items":[old,other]})),
            ),
            (
                "memory",
                exact_memory_list_arguments("atlas", request, "needs_review"),
                normal_scope_result(
                    json!({"count":receipt.replacement_count,"items":[]}),
                    "atlas",
                ),
            ),
            (
                "memory",
                json!({"action":"list_correction_proposals","limit":2,"scope":exact_local_scope_value("atlas", &request.orient_cwd)}),
                proposal_list,
            ),
        ];
        let mut lines = Vec::new();
        test_stdio_pair(
            &mut lines,
            1,
            "initialize",
            json!({"protocolVersion":NATIVE_CORRECTION_MCP_PROTOCOL,"capabilities":{},"clientInfo":{"name":"engram-native-correction-eval","version":"1"}}),
            json!({"protocolVersion":NATIVE_CORRECTION_MCP_PROTOCOL}),
        );
        lines.push(json!({"jsonrpc":"2.0","method":"notifications/initialized","params":{}}));
        test_stdio_pair(&mut lines, 2, "tools/list", json!({}), json!({"tools":[]}));
        for (index, (tool, arguments, result)) in calls.into_iter().enumerate() {
            test_stdio_pair(
                &mut lines,
                index as u64 + 3,
                "tools/call",
                json!({"name":tool,"arguments":arguments}),
                json!({"content":[{"type":"text","text":serde_json::to_string(&result).unwrap()}],"isError":false}),
            );
        }
        (lines
            .into_iter()
            .map(|line| serde_json::to_string(&line).unwrap())
            .collect::<Vec<_>>()
            .join("\n")
            + "\n")
            .into_bytes()
    }

    struct PreparedTest {
        _root: TempDir,
        run_plan: PathBuf,
        protocol: NativeCorrectionProtocol,
        plan: PreparedNativeCorrection,
    }

    fn canonical_tempdir() -> TempDir {
        tempfile::Builder::new()
            .prefix("engram-native-correction-test-")
            .tempdir_in(std::env::temp_dir().canonicalize().unwrap())
            .unwrap()
    }

    fn prepare() -> PreparedTest {
        let root = canonical_tempdir();
        let protocol = protocol();
        let protocol_path = root.path().join("protocol.json");
        fs::write(
            &protocol_path,
            serde_json::to_string_pretty(&protocol).unwrap() + "\n",
        )
        .unwrap();
        let output = root.path().join("run");
        let plan = prepare_native_correction_with_backend(
            &protocol_path,
            &output,
            runtime(),
            &mut FakeSeedBackend::default(),
        )
        .unwrap();
        PreparedTest {
            _root: root,
            run_plan: PathBuf::from(&plan.protocol).with_file_name("run-plan.json"),
            protocol,
            plan,
        }
    }

    fn rewrite_frozen_plan(path: &Path, plan: &PreparedNativeCorrection) {
        fs::write(path, serde_json::to_vec_pretty(plan).unwrap()).unwrap();
        fs::write(
            path.with_file_name("run-plan.sha256"),
            sha256_file(path).unwrap() + "\n",
        )
        .unwrap();
    }

    #[test]
    fn protocol_is_exactly_two_hosts_four_calls_and_twenty_cents() {
        validate_native_correction_protocol(&protocol()).unwrap();
        let mut invalid_protocol = protocol();
        invalid_protocol.resources.provider_calls = 5;
        assert!(validate_native_correction_protocol(&invalid_protocol).is_err());
        invalid_protocol = protocol();
        invalid_protocol.lanes.swap(0, 1);
        assert!(validate_native_correction_protocol(&invalid_protocol).is_err());
        invalid_protocol = protocol();
        invalid_protocol.claude.aggregate_budget_cents = 21;
        assert!(validate_native_correction_protocol(&invalid_protocol).is_err());
    }

    #[test]
    fn burden_protocol_is_strict_complete_and_rejects_every_field_mutation() {
        let exact = serde_json::to_value(protocol()).unwrap();
        let burden = exact.get("burden").and_then(Value::as_object).unwrap();
        let keys = burden.keys().cloned().collect::<Vec<_>>();
        assert_eq!(keys.len(), 16);

        for key in &keys {
            let mut missing = exact.clone();
            missing
                .get_mut("burden")
                .and_then(Value::as_object_mut)
                .unwrap()
                .remove(key);
            assert!(serde_json::from_value::<NativeCorrectionProtocol>(missing).is_err());

            let mut mutated = exact.clone();
            let value = mutated
                .get_mut("burden")
                .and_then(Value::as_object_mut)
                .unwrap()
                .get_mut(key)
                .unwrap();
            match value {
                Value::String(text) => text.push_str("_drift"),
                Value::Number(number) => {
                    let next = number.as_u64().unwrap().checked_add(1).unwrap();
                    *value = json!(next);
                }
                _ => panic!("unexpected burden field type for {key}"),
            }
            let rejected = serde_json::from_value::<NativeCorrectionProtocol>(mutated)
                .map_or(true, |protocol| {
                    validate_native_correction_protocol(&protocol).is_err()
                });
            assert!(rejected, "accepted mutated burden field {key}");
        }

        let mut unknown = exact;
        unknown
            .get_mut("burden")
            .and_then(Value::as_object_mut)
            .unwrap()
            .insert("self_reported_total".to_string(), json!(0));
        assert!(serde_json::from_value::<NativeCorrectionProtocol>(unknown).is_err());
    }

    #[test]
    fn protocol_file_validation_is_bounded_and_rejects_duplicate_keys() {
        let root = tempfile::tempdir().unwrap();
        let root = root.path().canonicalize().unwrap();
        let path = root.join("protocol.json");
        let expected = protocol();
        write_private_json(&path, &expected).unwrap();
        assert_eq!(
            validate_native_correction_protocol_file(&path).unwrap(),
            expected
        );

        let duplicate =
            serde_json::to_string(&protocol())
                .unwrap()
                .replacen('{', "{\"schema_version\":1,", 1);
        fs::write(&path, duplicate).unwrap();
        let error = validate_native_correction_protocol_file(&path).unwrap_err();
        assert!(error.to_string().contains("duplicate JSON object key"));
    }

