    #[test]
    fn terminal_output_is_derived_once_from_each_raw_host_trace() {
        let output = json!({"activated":false});
        let codex = format!(
            "{}\n{}\n",
            json!({"type":"item.completed","item":{"id":"terminal","type":"agent_message","text":serde_json::to_string(&output).unwrap()}}),
            json!({"type":"turn.completed","usage":{}})
        );
        assert_eq!(
            native_correction_terminal_output(NativeCorrectionHost::Codex, codex.as_bytes())
                .unwrap(),
            output
        );
        let duplicate = format!("{codex}{}\n", codex.lines().next().unwrap());
        assert!(native_correction_terminal_output(
            NativeCorrectionHost::Codex,
            duplicate.as_bytes()
        )
        .is_err());

        let claude = format!(
            "{}\n{}\n",
            json!({"type":"system","subtype":"init"}),
            json!({"type":"result","structured_output":output})
        );
        assert_eq!(
            native_correction_terminal_output(NativeCorrectionHost::ClaudeCode, claude.as_bytes())
                .unwrap(),
            output
        );
    }

