    #[test]
    fn empty_state_and_codex_stderr_are_exact_and_fail_closed() {
        assert!(require_exact_empty_collection(
            &json!({"count":0,"items":[]}),
            "items",
            "initial items"
        )
        .is_ok());
        assert!(require_exact_empty_collection(
            &json!({"count":0,"items":[{"id":"hidden"}]}),
            "items",
            "initial items"
        )
        .is_err());
        assert!(require_exact_empty_collection(
            &json!({"count":1,"proposals":[]}),
            "proposals",
            "initial proposals"
        )
        .is_err());

        let prepared = prepare();
        let lane = &prepared.plan.lanes[0];
        let timestamp = "2026-09-05T12:00:00Z";
        let plugin = Path::new(lane.codex_proposal_home.as_deref().unwrap())
            .join("skills/example/.codex-plugin/plugin.json");
        let valid = format!(
            "Reading additional input from stdin...\n{timestamp}  WARN codex_skills::interface: ignoring interface.icon_small: icon path must not contain '..'\n{timestamp}  WARN codex_core_plugins::manifest: ignoring interface.defaultPrompt: prompt must be at most 128 characters path=file://{}\n{timestamp}  WARN codex_core::tasks: task 10000000-0000-4000-8000-000000000001 didn't complete gracefully after 100ms\n",
            plugin.display()
        );
        validate_provider_stderr(lane, &valid).unwrap();

        let suffix = format!(
            "Reading additional input from stdin...\n{timestamp}  WARN codex_skills::interface: ignoring interface.icon_small: icon path must not contain '..' authentication failed\n"
        );
        assert!(validate_provider_stderr(lane, &suffix).is_err());
        let malformed_timestamp = "Reading additional input from stdin...\nnot-a-time  WARN codex_rollout::list: state db discrepancy during find_thread_path_by_id_str_in_subdir: falling_back\n";
        assert!(validate_provider_stderr(lane, malformed_timestamp).is_err());
        let credential = format!(
            "Reading additional input from stdin...\n{timestamp}  WARN token refresh completed\n"
        );
        assert!(validate_provider_stderr(lane, &credential).is_err());

        let home = Path::new(lane.codex_proposal_home.as_deref().unwrap());
        for invalid_path in [
            home.join("skills/../escape/.codex-plugin/plugin.json"),
            home.join("skills/./escape/.codex-plugin/plugin.json"),
            PathBuf::from("/tmp/outside/.codex-plugin/plugin.json"),
        ] {
            let warning = format!(
                "Reading additional input from stdin...\n{timestamp}  WARN codex_core_plugins::manifest: ignoring interface.defaultPrompt: prompt must be at most 128 characters path=file://{}\n",
                invalid_path.display()
            );
            assert!(validate_provider_stderr(lane, &warning).is_err());
        }
        assert!(validate_relative_normal_path(Path::new("../escape"), "warning path").is_err());
        assert!(validate_relative_normal_path(Path::new("/rooted"), "warning path").is_err());
        assert!(validate_relative_normal_path(Path::new("a//b"), "warning path").is_err());
    }

