    #[test]
    fn operator_intent_is_create_new_digest_bound_and_audited_before_apply() {
        let prepared = prepare();
        for lane in &prepared.plan.lanes {
            let evidence = proposal_evidence(&prepared.protocol, lane);
            write_proposal_provider_artifacts(lane, &evidence);
            record_native_correction_proposal_receipt(
                &prepared.run_plan,
                lane.order,
                &evidence,
                prepared.plan.prepared_unix_ms + u64::from(lane.order),
                prepared.plan.prepared_unix_ms + u64::from(lane.order) + 1,
                0,
                false,
            )
            .unwrap();
        }
        let lane = &prepared.plan.lanes[0];
        create_native_correction_operator_intent(&prepared.run_plan, lane.order).unwrap();
        assert!(create_native_correction_operator_intent(&prepared.run_plan, lane.order).is_err());
        let audit = audit_native_correction_lifecycle(&prepared.run_plan).unwrap();
        assert!(!audit.valid, "intent-only state must be frozen");
        assert_eq!(
            audit.lanes[0].1,
            NativeCorrectionLaneLifecycle::FrozenIncompleteOperator
        );

        let mut intent: NativeCorrectionOperatorIntent =
            serde_json::from_reader(File::open(&lane.operator_intent).unwrap()).unwrap();
        intent.proposal.canonical_digest = "0".repeat(64);
        fs::write(
            &lane.operator_intent,
            serde_json::to_vec_pretty(&intent).unwrap(),
        )
        .unwrap();
        fs::write(
            receipt_digest_path(Path::new(&lane.operator_intent)),
            sha256_file(Path::new(&lane.operator_intent)).unwrap() + "\n",
        )
        .unwrap();
        let audit = audit_native_correction_lifecycle(&prepared.run_plan).unwrap();
        assert!(!audit.valid);
        assert!(audit
            .failures
            .iter()
            .any(|failure| failure.contains("operator intent")));
    }

