    fn refresh_cleanup_event_bytes(receipt: &mut NativeCorrectionCleanupReceipt, index: usize) {
        receipt.events[index].result_bytes = serde_json::to_vec(&receipt.events[index].result)
            .unwrap()
            .len() as u64;
    }

    #[test]
    fn cleanup_requires_exact_predelete_counts_two_forgets_restart_and_no_authority_claims() {
        let prepared = prepare();
        write_complete_precleanup_lifecycle(&prepared);
        let lane = &prepared.plan.lanes[0];
        let base = write_test_cleanup_receipt(&prepared, lane);
        let paths = native_correction_cleanup_paths(lane).unwrap();
        let intent: NativeCorrectionCleanupIntent =
            serde_json::from_reader(File::open(&paths.intent).unwrap()).unwrap();
        let operator: NativeCorrectionOperatorReceipt =
            serde_json::from_reader(File::open(&lane.operator_receipt).unwrap()).unwrap();
        validate_native_correction_cleanup_receipt(lane, &operator, &intent, &base).unwrap();

        for mutate in 0..26 {
            let mut invalid = base.clone();
            match mutate {
                0 => {
                    invalid.events[2].result["item"]["evidence"] = json!([]);
                    refresh_cleanup_event_bytes(&mut invalid, 2);
                }
                1 => {
                    invalid.events[3].result["nodes"] = json!([]);
                    refresh_cleanup_event_bytes(&mut invalid, 3);
                }
                2 => {
                    invalid.events[3].result["edges"] = json!([]);
                    refresh_cleanup_event_bytes(&mut invalid, 3);
                }
                3 => {
                    invalid.events[4].result["commits"] = json!([]);
                    refresh_cleanup_event_bytes(&mut invalid, 4);
                }
                4 => {
                    invalid.events[5].result["trace"]["returned_memory_ids"] = json!([]);
                    refresh_cleanup_event_bytes(&mut invalid, 5);
                }
                5 => {
                    invalid.events[6].result["count"] = json!(0);
                    refresh_cleanup_event_bytes(&mut invalid, 6);
                }
                6 => invalid.predelete_projection_counts_verified = false,
                7 => {
                    invalid.events[8].result["abstained"] = json!(false);
                    refresh_cleanup_event_bytes(&mut invalid, 8);
                }
                8 => {
                    invalid.events[9].result["id"] = json!(CODEX_OTHER);
                    invalid.events[9].result["internal_purge"]["id"] = json!(CODEX_OTHER);
                    refresh_cleanup_event_bytes(&mut invalid, 9);
                }
                9 => {
                    invalid.replacement_forget.traces_deleted = 1;
                    invalid.events[9].result["internal_purge"]["traces_deleted"] = json!(1);
                    refresh_cleanup_event_bytes(&mut invalid, 9);
                }
                10 => {
                    invalid.events[13].result["mcp_error_text"] =
                        json!(format!("Memory item not found: {}", intent.obsolete_id));
                    refresh_cleanup_event_bytes(&mut invalid, 13);
                }
                11 => invalid.fresh_process_ids[1] = invalid.fresh_process_ids[0],
                12 => invalid.human_identity_authenticated = true,
                13 => {
                    invalid.events.remove(10);
                }
                14 => {
                    invalid.events[15].result["mcp_error_text"] = json!("not found: different");
                    refresh_cleanup_event_bytes(&mut invalid, 15);
                }
                15 => {
                    invalid.events[18].result["item"]["evidence"] =
                        json!([{"kind":"observation","target":intent.obsolete_id}]);
                    refresh_cleanup_event_bytes(&mut invalid, 18);
                }
                16 => {
                    invalid.events[19].result["nodes"] = json!([{
                        "id":format!("memory:{}", intent.obsolete_id),
                        "kind":"memory",
                        "label":"forgotten"
                    }]);
                    refresh_cleanup_event_bytes(&mut invalid, 19);
                }
                17 => {
                    invalid.events[20].result["commits"][0]["changes"] =
                        json!([{"item_id":intent.obsolete_id}]);
                    refresh_cleanup_event_bytes(&mut invalid, 20);
                }
                18 => {
                    invalid.events[21].result["trace"] = json!({"id":intent.projection_trace_id});
                    refresh_cleanup_event_bytes(&mut invalid, 21);
                }
                19 => {
                    invalid.events[22].result["count"] = json!(1);
                    invalid.events[22].result["feedback"] =
                        json!([{"id":intent.projection_feedback_id}]);
                    refresh_cleanup_event_bytes(&mut invalid, 22);
                }
                20 => {
                    invalid.commit_reference_redacted_after_restart = false;
                }
                21 => invalid.memory_reference_absent_after_restart = false,
                22 => invalid.derived_graph_absent_after_restart = false,
                23 => invalid.excluded_projection_scope = "forensic erasure".to_string(),
                24 => {
                    invalid.preserved_evaluator_operator_transcripts_outside_engram_owned_scope =
                        false;
                }
                25 => invalid.retry_used_as_causal_evidence = true,
                _ => unreachable!(),
            }
            assert!(
                validate_native_correction_cleanup_receipt(lane, &operator, &intent, &invalid)
                    .is_err(),
                "accepted cleanup mutation {mutate}"
            );
        }
    }

    #[test]
    fn cleanup_trace_structurally_allowlists_only_two_other_scope_observations() {
        let prepared = prepare();
        write_complete_precleanup_lifecycle(&prepared);
        let lane = &prepared.plan.lanes[0];
        let receipt = write_test_cleanup_receipt(&prepared, lane);
        let paths = native_correction_cleanup_paths(lane).unwrap();
        let intent: NativeCorrectionCleanupIntent =
            serde_json::from_reader(File::open(&paths.intent).unwrap()).unwrap();
        let canary: NativeCorrectionPrivateCanaryContract =
            serde_json::from_reader(File::open(&lane.private_canary_contract).unwrap()).unwrap();
        let original: NativeCorrectionCleanupTraceEnvelope =
            serde_json::from_reader(File::open(&paths.trace).unwrap()).unwrap();
        validate_native_correction_cleanup_trace(&prepared.plan, lane, &intent, &receipt).unwrap();

        let mut wrong_location = original.clone();
        wrong_location.sessions[0].transcript_jsonl = wrong_location.sessions[0]
            .transcript_jsonl
            .replacen(
                &canary.other_scope_content,
                "Orbit-only queue guidance without the evaluator marker.",
                1,
            )
            .replacen(
                "native-correction cleanup projection seed",
                &canary.other_scope_content,
                1,
            );
        wrong_location.sessions[0].transcript_bytes =
            wrong_location.sessions[0].transcript_jsonl.len() as u64;
        wrong_location.sessions[0].transcript_sha256 = format!(
            "{:x}",
            Sha256::digest(wrong_location.sessions[0].transcript_jsonl.as_bytes())
        );
        fs::write(
            &paths.trace,
            serde_json::to_vec_pretty(&wrong_location).unwrap(),
        )
        .unwrap();
        let error =
            validate_native_correction_cleanup_trace(&prepared.plan, lane, &intent, &receipt)
                .unwrap_err();
        assert!(error.to_string().contains("other-scope canary"));

        let mut extra_count = original.clone();
        extra_count.sessions[0].transcript_jsonl =
            extra_count.sessions[0].transcript_jsonl.replacen(
                "native-correction cleanup projection seed",
                &format!(
                    "native-correction cleanup projection seed {}",
                    canary.other_scope_content
                ),
                1,
            );
        extra_count.sessions[0].transcript_bytes =
            extra_count.sessions[0].transcript_jsonl.len() as u64;
        extra_count.sessions[0].transcript_sha256 = format!(
            "{:x}",
            Sha256::digest(extra_count.sessions[0].transcript_jsonl.as_bytes())
        );
        fs::write(
            &paths.trace,
            serde_json::to_vec_pretty(&extra_count).unwrap(),
        )
        .unwrap();
        let error =
            validate_native_correction_cleanup_trace(&prepared.plan, lane, &intent, &receipt)
                .unwrap_err();
        assert!(error
            .to_string()
            .contains("two trusted-evaluator other-scope observations"));

        let mut secret = original;
        secret.sessions[0].transcript_jsonl = secret.sessions[0].transcript_jsonl.replacen(
            "native-correction cleanup projection seed",
            &canary.hidden_secret,
            1,
        );
        secret.sessions[0].transcript_bytes = secret.sessions[0].transcript_jsonl.len() as u64;
        secret.sessions[0].transcript_sha256 = format!(
            "{:x}",
            Sha256::digest(secret.sessions[0].transcript_jsonl.as_bytes())
        );
        fs::write(&paths.trace, serde_json::to_vec_pretty(&secret).unwrap()).unwrap();
        let error =
            validate_native_correction_cleanup_trace(&prepared.plan, lane, &intent, &receipt)
                .unwrap_err();
        assert!(error.to_string().contains("private secret"));
    }

