    #[cfg(unix)]
    #[test]
    fn persistent_cleanup_failures_return_bounded_and_aggregate_production_evidence() {
        use std::os::unix::process::CommandExt;

        let working_directory = canonical_tempdir();

        fn kill_and_reap_test_group(process_group_id: i32) {
            // SAFETY: every ID passed here is captured from a process group created by this test.
            let result = unsafe { libc::kill(-process_group_id, libc::SIGKILL) };
            if result != 0 {
                let errno = std::io::Error::last_os_error().raw_os_error();
                assert!(matches!(errno, Some(libc::ESRCH) | Some(libc::EPERM)));
            }
            let mut status = 0;
            loop {
                // SAFETY: waitpid targets only the direct child created by this test.
                let waited = unsafe { libc::waitpid(process_group_id, &mut status, 0) };
                if waited == process_group_id {
                    break;
                }
                let errno = std::io::Error::last_os_error().raw_os_error();
                if errno == Some(libc::ECHILD) {
                    break;
                }
                assert_eq!(errno, Some(libc::EINTR));
            }
        }

        let mut unrelated_command = Command::new("/bin/sleep");
        unrelated_command.arg("30").process_group(0);
        let unrelated_child = unrelated_command.spawn().unwrap();
        let unrelated_pid = i32::try_from(unrelated_child.id()).unwrap();
        let mut unrelated_guard = NativeCorrectionChildGuard::adopt_spawned_group_for_test(
            unrelated_child,
            Instant::now() + Duration::from_secs(2),
        )
        .unwrap();

        let mut stdio_command = Command::new("/bin/sh");
        stdio_command
            .args(["-c", "sleep 30 & wait"])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let stdio_child = stdio_command.spawn().unwrap();
        let stdio_pid = i32::try_from(stdio_child.id()).unwrap();
        let mut session = NativeCorrectionStdioSession::from_spawned_child(
            stdio_child,
            Duration::from_millis(120),
            None,
        )
        .unwrap();
        session
            .child
            .inject_cleanup_fault(NativeCorrectionCleanupFault::PersistentSignalEperm);
        let started = Instant::now();
        let stdio_result = session.finish();
        let elapsed = started.elapsed();
        // SAFETY: signal zero only checks the still-owned target and unrelated test processes.
        assert_eq!(unsafe { libc::kill(stdio_pid, 0) }, 0);
        assert_eq!(unsafe { libc::kill(unrelated_pid, 0) }, 0);
        kill_and_reap_test_group(stdio_pid);
        assert!(unrelated_guard.try_wait_for_test().unwrap().is_none());
        native_correction_cleanup_result(
            unrelated_guard.terminate_group_and_reap_with_status_until(
                Instant::now() + Duration::from_secs(2),
            ),
        )
        .unwrap();
        let stdio_error = stdio_result.unwrap_err().to_string();
        assert!(elapsed < Duration::from_millis(600));
        assert!(stdio_error.contains("did not exit after EOF"));
        assert!(stdio_error.contains("errno Some(1)"));
        assert!(stdio_error.contains("abandoned evaluator-owned PID"));
        assert!(stdio_error.contains("stdout collector"));
        assert!(stdio_error.contains("stderr collector"));

        for fault in [
            NativeCorrectionCleanupFault::PersistentEnumeration,
            NativeCorrectionCleanupFault::PersistentSignalEperm,
        ] {
            let mut captured_pid = None;
            let started = Instant::now();
            let result = run_bounded_native_correction_command_inner(
                Path::new("/bin/sh"),
                &["-c", "sleep 30 & wait"],
                working_directory.path(),
                &BTreeMap::new(),
                Duration::from_millis(120),
                1024,
                |child| {
                    captured_pid = child
                        .process_id()
                        .ok()
                        .and_then(|process_id| i32::try_from(process_id).ok());
                    child.inject_cleanup_fault(fault);
                },
            );
            let elapsed = started.elapsed();
            let captured_pid = captured_pid.unwrap();
            let error = result.unwrap_err().to_string();
            assert!(elapsed < Duration::from_millis(600));
            assert!(error.contains("wall-clock timeout"));
            assert!(error.contains("abandoned evaluator-owned PID"));
            match fault {
                NativeCorrectionCleanupFault::PersistentEnumeration => {
                    assert!(error.contains("enumeration failure"));
                    let deadline = Instant::now() + Duration::from_millis(500);
                    let mut status = 0;
                    loop {
                        // SAFETY: waitpid targets only the WNOWAIT-reserved direct child whose
                        // exact test group received the production cleanup SIGKILL.
                        let waited =
                            unsafe { libc::waitpid(captured_pid, &mut status, libc::WNOHANG) };
                        if waited == captured_pid {
                            break;
                        }
                        assert_eq!(waited, 0);
                        assert!(
                            Instant::now() < deadline,
                            "cleanup SIGKILL was not observed"
                        );
                        thread::sleep(Duration::from_millis(5));
                    }
                    assert!(libc::WIFSIGNALED(status));
                    assert_eq!(libc::WTERMSIG(status), libc::SIGKILL);
                }
                NativeCorrectionCleanupFault::PersistentSignalEperm => {
                    assert!(error.contains("errno Some(1)"));
                    assert!(error.contains("stdout collector"));
                    assert!(error.contains("stderr collector"));
                    // SAFETY: the injected EPERM path must not signal its still-owned group.
                    assert_eq!(unsafe { libc::kill(captured_pid, 0) }, 0);
                    kill_and_reap_test_group(captured_pid);
                }
            }
        }

        let mut captured_pid = None;
        let triple = run_bounded_native_correction_command_inner(
            Path::new("/bin/sh"),
            &[
                "-c",
                "printf '0123456789abcdef'; printf 'fedcba9876543210' >&2",
            ],
            working_directory.path(),
            &BTreeMap::new(),
            Duration::from_secs(1),
            8,
            |child| {
                captured_pid = child
                    .process_id()
                    .ok()
                    .and_then(|process_id| i32::try_from(process_id).ok());
                child.inject_cleanup_fault(NativeCorrectionCleanupFault::PersistentEnumeration);
            },
        );
        kill_and_reap_test_group(captured_pid.unwrap());
        let error = triple.unwrap_err().to_string();
        assert!(error.contains("enumeration failure"));
        assert!(error.contains("stdout exceeded"));
        assert!(error.contains("stderr exceeded"));
        assert!(error.contains("combined output exceeded"));
    }

    #[test]
    fn daemon_health_accepts_only_the_exact_installed_content_length_framing() {
        let pid = 42_424_u32;
        let body = serde_json::to_vec(&json!({
            "status":"ok",
            "service":"engram",
            "version":EXPECTED_ENGRAM_VERSION.trim_start_matches("engram "),
            "build_sha":null,
            "pid":pid,
            "health_schema_version":3,
            "mcp_contract_version":5,
            "mcp_tools_sha256":EXPECTED_FULL_TOOLS_SHA256,
            "mcp_protocol_version":NATIVE_CORRECTION_MCP_PROTOCOL,
            "auth_required":true,
            "storage_status":"ready",
            "storage_ready":true,
            "storage_available_bytes":1000000,
            "storage_required_bytes":1000
        }))
        .unwrap();
        let response = |framing: &str, body: &[u8]| {
            let mut response = framing.as_bytes().to_vec();
            response.extend_from_slice(body);
            response
        };
        let valid_header = format!(
            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\ndate: Sat, 06 Sep 2026 00:00:00 GMT\r\n\r\n",
            body.len()
        );
        validate_native_correction_daemon_health_response(&response(&valid_header, &body), pid)
            .unwrap();

        let duplicate_length = format!(
            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\ncontent-length: {}\r\nconnection: close\r\ndate: Sat, 06 Sep 2026 00:00:00 GMT\r\n\r\n",
            body.len(),
            body.len()
        );
        assert!(validate_native_correction_daemon_health_response(
            &response(&duplicate_length, &body),
            pid,
        )
        .is_err());
        let conflicting_length = format!(
            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ncontent-length: {}\r\ncontent-length: {}\r\nconnection: close\r\ndate: Sat, 06 Sep 2026 00:00:00 GMT\r\n\r\n",
            body.len(),
            body.len() + 1
        );
        assert!(validate_native_correction_daemon_health_response(
            &response(&conflicting_length, &body),
            pid,
        )
        .is_err());
        let transfer_encoding =
            "HTTP/1.1 200 OK\r\ncontent-type: application/json\r\ntransfer-encoding: chunked\r\nconnection: close\r\ndate: Sat, 06 Sep 2026 00:00:00 GMT\r\n\r\n";
        assert!(validate_native_correction_daemon_health_response(
            &response(transfer_encoding, b"0\r\n\r\n"),
            pid,
        )
        .is_err());

        let mut truncated = response(&valid_header, &body);
        truncated.pop();
        assert!(validate_native_correction_daemon_health_response(&truncated, pid).is_err());
        let mut trailing = response(&valid_header, &body);
        trailing.push(b'x');
        assert!(validate_native_correction_daemon_health_response(&trailing, pid).is_err());
        assert!(
            validate_native_correction_daemon_health_response(&vec![b'x'; 64 * 1024 + 1], pid,)
                .is_err()
        );
        assert!(validate_native_correction_daemon_health_response(
            b"HTTP/1.1 200 OK\ncontent-length: 0\n\n",
            pid,
        )
        .is_err());
    }

    #[test]
    fn daemon_process_identity_requires_exact_partition_and_home() {
        let arguments = vec![
            "/frozen/engram".to_string(),
            "serve".to_string(),
            "--http".to_string(),
            "--port".to_string(),
            "8765".to_string(),
            "--project".to_string(),
            "corr-correct".to_string(),
        ];
        #[cfg_attr(not(target_os = "macos"), allow(unused_mut))]
        let mut environment = vec![
            "ENGRAM_HOME=/private/correct".to_string(),
            "DISABLE_TELEMETRY=1".to_string(),
            "PATH=/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
            format!("ENGRAM_DAEMON_TOKEN={}", "a".repeat(64)),
        ];
        #[cfg(target_os = "macos")]
        {
            // SAFETY: geteuid only reads the effective identity of this test process.
            let expected_uid = unsafe { libc::geteuid() };
            environment.push(format!(
                "__CF_USER_TEXT_ENCODING=0x{expected_uid:X}:0x0:0x0"
            ));
        }
        validate_native_correction_daemon_process_surfaces(
            &arguments,
            &environment,
            Path::new("/frozen/engram"),
            Path::new("/private/correct"),
            8765,
            "corr-correct",
            &"a".repeat(64),
        )
        .unwrap();
        assert!(validate_native_correction_daemon_process_surfaces(
            &arguments,
            &environment,
            Path::new("/frozen/engram"),
            Path::new("/private/other"),
            8765,
            "corr-correct",
            &"a".repeat(64),
        )
        .is_err());
        let wrong_partition = validate_native_correction_daemon_process_surfaces(
            &arguments,
            &environment,
            Path::new("/frozen/engram"),
            Path::new("/private/correct"),
            8765,
            "corr-other",
            &"a".repeat(64),
        )
        .unwrap_err()
        .to_string();
        assert!(wrong_partition.contains("argv"));
        let mut ambiguous_arguments = arguments.clone();
        ambiguous_arguments.extend(["--project".to_string(), "corr-correct".to_string()]);
        assert!(validate_native_correction_daemon_process_surfaces(
            &ambiguous_arguments,
            &environment,
            Path::new("/frozen/engram"),
            Path::new("/private/correct"),
            8765,
            "corr-correct",
            &"a".repeat(64),
        )
        .unwrap_err()
        .to_string()
        .contains("argv"));
        let mut injected_environment = environment.clone();
        injected_environment.push("DYLD_INSERT_LIBRARIES=/tmp/injected.dylib".to_string());
        assert!(validate_native_correction_daemon_process_surfaces(
            &arguments,
            &injected_environment,
            Path::new("/frozen/engram"),
            Path::new("/private/correct"),
            8765,
            "corr-correct",
            &"a".repeat(64),
        )
        .is_err());
        #[cfg(target_os = "macos")]
        {
            let mut missing_system_variable = environment.clone();
            missing_system_variable.retain(|entry| !entry.starts_with("__CF_USER_TEXT_ENCODING="));
            assert!(validate_native_correction_daemon_process_surfaces(
                &arguments,
                &missing_system_variable,
                Path::new("/frozen/engram"),
                Path::new("/private/correct"),
                8765,
                "corr-correct",
                &"a".repeat(64),
            )
            .unwrap_err()
            .to_string()
            .contains("environment"));
            let mut wrong_system_variable = environment.clone();
            let entry = wrong_system_variable
                .iter_mut()
                .find(|entry| entry.starts_with("__CF_USER_TEXT_ENCODING="))
                .unwrap();
            *entry = "__CF_USER_TEXT_ENCODING=0x0:0x0:0x0".to_string();
            assert!(validate_native_correction_daemon_process_surfaces(
                &arguments,
                &wrong_system_variable,
                Path::new("/frozen/engram"),
                Path::new("/private/correct"),
                8765,
                "corr-correct",
                &"a".repeat(64),
            )
            .unwrap_err()
            .to_string()
            .contains("environment"));
        }
        assert!(validate_native_correction_daemon_process_surfaces(
            &arguments,
            &environment,
            Path::new("/frozen/engram"),
            Path::new("/private/correct"),
            8765,
            "corr-correct",
            &"b".repeat(64),
        )
        .is_err());

        assert!(validate_native_correction_daemon_control_presence(true, false, false).is_ok());
        assert!(validate_native_correction_daemon_control_presence(true, true, false).is_ok());
        assert!(validate_native_correction_daemon_control_presence(true, true, true).is_ok());
        assert!(validate_native_correction_daemon_control_presence(false, true, false).is_err());
        assert!(validate_native_correction_daemon_control_presence(false, false, true).is_err());
        assert!(validate_native_correction_daemon_control_presence(false, true, true).is_err());
    }

