    #[test]
    fn operator_lists_require_count_and_array_length_one_and_reject_recovery_claims() {
        let prepared = prepare();
        let lane = &prepared.plan.lanes[0];
        let base = operator_receipt(&prepared, lane, &"d".repeat(64));
        let mut invalid = base.clone();
        invalid.events[5].result["count"] = json!(2);
        invalid.events[5].result_bytes =
            serde_json::to_vec(&invalid.events[5].result).unwrap().len() as u64;
        assert!(validate_native_correction_operator_receipt(lane, &invalid).is_err());
        let mut invalid = base;
        invalid.events[11].result["items"] = json!([]);
        invalid.events[11].result_bytes = serde_json::to_vec(&invalid.events[11].result)
            .unwrap()
            .len() as u64;
        assert!(validate_native_correction_operator_receipt(lane, &invalid).is_err());

        let mut recovered = operator_receipt(&prepared, lane, &"d".repeat(64));
        let (proposal, obsolete, replacement) = applied_pair(lane);
        let inspection = CorrectionProposalInspection {
            proposal,
            replacement: replacement.clone(),
            obsolete,
        };
        recovered.events[3].result =
            selector_result(json!({"count":1,"proposals":[inspection.clone()]}), "atlas");
        recovered.events[4].result = selector_result(json!(inspection.clone()), "atlas");
        recovered.events[5].result =
            normal_scope_result(json!({"count":1,"items":[replacement]}), "atlas");
        recovered.events[6].action = NativeCorrectionOperatorAction::RecoverAppliedWithoutReplay;
        recovered.events[6].arguments = json!({
            "action":"recover_applied_without_replay",
            "proposal_id":PROPOSAL_ID,
            "expected_digest":recovered.proposal_before.canonical_digest,
            "scope":scope(lane,"atlas")
        });
        recovered.events[6].result = selector_result(json!(inspection), "atlas");
        recovered.authority_boundary =
            "applied_state_observed_without_dispatch_attribution".to_string();
        recovered.apply_call_count = 0;
        recovered.fresh_process_ids.push(30_000 + lane.order);
        recovered.fresh_full_process_count = 3;
        recovered.recovered_after_ambiguous_apply = true;
        for event in &mut recovered.events {
            event.result_bytes = serde_json::to_vec(&event.result).unwrap().len() as u64;
        }
        assert!(validate_native_correction_operator_receipt(lane, &recovered).is_err());
    }

    #[test]
