    #[cfg(unix)]
    #[test]
    fn bounded_processes_clear_ambient_env_and_reap_same_group_descendants() {
        fn assert_group_absent(process_group_id: i32, label: &str) {
            let deadline = std::time::Instant::now() + Duration::from_secs(2);
            loop {
                // SAFETY: signal 0 only probes the test-created process group.
                let result = unsafe { libc::kill(-process_group_id, 0) };
                if result != 0
                    && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH)
                {
                    return;
                }
                assert!(
                    std::time::Instant::now() < deadline,
                    "{label} process group {process_group_id} survived cleanup"
                );
                thread::sleep(Duration::from_millis(10));
            }
        }

        let root = canonical_tempdir();
        let environment = BTreeMap::from([("EXACT_ALLOWED".to_string(), "present".to_string())]);
        let (status, stdout, stderr) = run_bounded_native_correction_command(
            Path::new("/usr/bin/env"),
            &[],
            root.path(),
            &environment,
            Duration::from_secs(2),
            1024,
        )
        .unwrap();
        assert_eq!(status, 0);
        assert_eq!(stdout, b"EXACT_ALLOWED=present\n");
        assert!(stderr.is_empty());

        let normal_pids = root.path().join("normal-pids");
        let script = "sleep 30 & child=$!; child_pgid=$(/bin/ps -o pgid= -p \"$child\" | /usr/bin/tr -d ' '); printf '%s\\n%s\\n%s\\n' \"$$\" \"$child\" \"$child_pgid\" > \"$1\"; exit 0";
        run_bounded_native_correction_command(
            Path::new("/bin/sh"),
            &["-c", script, "sh", normal_pids.to_str().unwrap()],
            root.path(),
            &BTreeMap::new(),
            Duration::from_secs(2),
            1024,
        )
        .unwrap();
        let normal_values = fs::read_to_string(&normal_pids)
            .unwrap()
            .lines()
            .map(|value| value.parse::<i32>().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(normal_values.len(), 3);
        let normal_group = normal_values[0];
        assert_eq!(normal_values[2], normal_group);
        assert_group_absent(normal_group, "normal-exit");

        let timeout_pids = root.path().join("timeout-pids");
        let script = "sleep 30 & child=$!; child_pgid=$(/bin/ps -o pgid= -p \"$child\" | /usr/bin/tr -d ' '); printf '%s\\n%s\\n%s\\n' \"$$\" \"$child\" \"$child_pgid\" > \"$1\"; wait";
        let timeout_error = run_bounded_native_correction_command(
            Path::new("/bin/sh"),
            &["-c", script, "sh", timeout_pids.to_str().unwrap()],
            root.path(),
            &BTreeMap::new(),
            Duration::from_secs(1),
            1024,
        )
        .unwrap_err();
        assert!(timeout_error.to_string().contains("wall-clock timeout"));
        let timeout_values = fs::read_to_string(&timeout_pids)
            .unwrap()
            .lines()
            .map(|value| value.parse::<i32>().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(timeout_values.len(), 3);
        let timeout_group = timeout_values[0];
        assert_eq!(timeout_values[2], timeout_group);
        assert_group_absent(timeout_group, "timeout");

        use std::os::unix::process::CommandExt;
        let mut command = Command::new("/usr/bin/true");
        command.process_group(0);
        let child = command.spawn().unwrap();
        let process_group_id = i32::try_from(child.id()).unwrap();
        let mut guard = NativeCorrectionChildGuard::adopt_spawned_group_for_test(
            child,
            Instant::now() + Duration::from_secs(2),
        )
        .unwrap();
        let mut status = 0;
        loop {
            // SAFETY: waitpid targets only the test-created direct child.
            let waited = unsafe { libc::waitpid(process_group_id, &mut status, 0) };
            if waited == process_group_id {
                break;
            }
            assert_eq!(
                std::io::Error::last_os_error().raw_os_error(),
                Some(libc::EINTR)
            );
        }
        let error = guard.try_wait_for_test().unwrap_err();
        assert!(matches!(
            error,
            NativeExecutionError::Io(ref error) if error.raw_os_error() == Some(libc::ECHILD)
        ));
        assert!(guard.terminate_group_and_reap().is_err());
        assert_group_absent(process_group_id, "externally-reaped");

        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", "sleep 30 & wait"])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::piped());
        let child = command.spawn().unwrap();
        let process_group_id = i32::try_from(child.id()).unwrap();
        let result =
            NativeCorrectionStdioSession::from_spawned_child(child, Duration::from_secs(1), None);
        assert!(result.is_err());
        assert_group_absent(process_group_id, "constructor-failure");
    }

    #[cfg(unix)]
    #[test]
    fn stdio_finish_drains_trailing_output_and_uses_one_absolute_deadline() {
        use std::os::unix::process::CommandExt;

        let mut trailing = Command::new("/bin/sh");
        trailing
            .args([
                "-c",
                "printf '{\"jsonrpc\":\"2.0\",\"id\":99,\"result\":{}}\\n'",
            ])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let session = NativeCorrectionStdioSession::from_spawned_child(
            trailing.spawn().unwrap(),
            Duration::from_secs(2),
            None,
        )
        .unwrap();
        let error = session.finish().unwrap_err().to_string();
        assert!(error.contains("unaccounted trailing JSONL line"));

        for (script, expected) in [
            ("printf 'unterminated'", "omitted its JSONL newline"),
            ("printf '\\377\\n'", "was not UTF-8"),
        ] {
            let mut invalid = Command::new("/bin/sh");
            invalid
                .args(["-c", script])
                .process_group(0)
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped());
            let session = NativeCorrectionStdioSession::from_spawned_child(
                invalid.spawn().unwrap(),
                Duration::from_secs(2),
                None,
            )
            .unwrap();
            assert!(session.finish().unwrap_err().to_string().contains(expected));
        }

        let mut cumulative = Command::new("/bin/sh");
        cumulative
            .args([
                "-c",
                "IFS= read -r first; sleep 0.05; printf '{\"jsonrpc\":\"2.0\",\"id\":1,\"result\":{}}\\n'; IFS= read -r second; sleep 5; printf '{\"jsonrpc\":\"2.0\",\"id\":2,\"result\":{}}\\n'",
            ])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let mut session = NativeCorrectionStdioSession::from_spawned_child(
            cumulative.spawn().unwrap(),
            Duration::from_secs(2),
            None,
        )
        .unwrap();
        session.request("first", json!({})).unwrap();
        let started = Instant::now();
        assert!(session.request("second", json!({})).is_err());
        assert!(started.elapsed() < Duration::from_secs(2));
    }

    #[cfg(unix)]
    #[test]
    fn non_draining_stdio_stdin_is_bounded_and_cleanup_failures_are_aggregated() {
        use std::os::unix::process::CommandExt;

        fn kill_and_reap_group(process_group_id: i32) {
            // SAFETY: this exact group was created by this test and remains WNOWAIT-reserved.
            let signal = unsafe { libc::kill(-process_group_id, libc::SIGKILL) };
            if signal != 0 {
                assert_eq!(
                    std::io::Error::last_os_error().raw_os_error(),
                    Some(libc::ESRCH)
                );
            }
            let mut status = 0;
            loop {
                // SAFETY: waitpid targets only the direct child created by this test.
                let waited = unsafe { libc::waitpid(process_group_id, &mut status, 0) };
                if waited == process_group_id
                    || (waited < 0
                        && std::io::Error::last_os_error().raw_os_error() == Some(libc::ECHILD))
                {
                    break;
                }
                assert!(waited < 0);
                assert_eq!(
                    std::io::Error::last_os_error().raw_os_error(),
                    Some(libc::EINTR)
                );
            }
        }

        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", "sleep 30 & wait"])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let child = command.spawn().unwrap();
        let process_group_id = i32::try_from(child.id()).unwrap();
        let mut session = NativeCorrectionStdioSession::from_spawned_child(
            child,
            Duration::from_millis(400),
            None,
        )
        .unwrap();
        let started = Instant::now();
        let error = session
            .write_message_bytes(&vec![b'x'; 4 * 1024 * 1024])
            .unwrap_err()
            .to_string();
        assert!(started.elapsed() < Duration::from_secs(2));
        assert!(error.contains("absolute response deadline"));
        assert!(error.contains("after delivering"));
        assert!(session.transcript.is_empty());
        assert!(!session.child.is_armed());
        assert!(session.stdout_thread.is_none());
        assert!(session.stderr_thread.is_none());
        // SAFETY: signal zero only probes the test-owned group after production cleanup.
        assert_eq!(unsafe { libc::kill(-process_group_id, 0) }, -1);
        assert_eq!(
            std::io::Error::last_os_error().raw_os_error(),
            Some(libc::ESRCH)
        );
        let finish_error = session.finish().unwrap_err().to_string();
        assert!(finish_error.contains("safely disarmed terminal failure"));
        assert!(finish_error.contains("absolute response deadline"));

        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", "sleep 30 & wait"])
            .process_group(0)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let child = command.spawn().unwrap();
        let process_group_id = i32::try_from(child.id()).unwrap();
        let mut session = NativeCorrectionStdioSession::from_spawned_child(
            child,
            Duration::from_millis(300),
            None,
        )
        .unwrap();
        session
            .child
            .inject_cleanup_fault(NativeCorrectionCleanupFault::PersistentSignalEperm);
        let started = Instant::now();
        let error = session
            .write_message_bytes(&vec![b'y'; 4 * 1024 * 1024])
            .unwrap_err()
            .to_string();
        assert!(started.elapsed() < Duration::from_secs(2));
        assert!(error.contains("absolute response deadline"));
        assert!(error.contains("errno Some(1)"));
        assert!(error.contains("abandoned evaluator-owned PID"));
        assert!(error.contains("stdout collector"));
        assert!(error.contains("stderr collector"));
        assert!(session.transcript.is_empty());
        assert!(!session.child.is_armed());
        assert!(session.stdout_thread.is_none());
        assert!(session.stderr_thread.is_none());
        kill_and_reap_group(process_group_id);
    }

    #[test]
    fn stdio_start_failure_fallback_consumes_the_original_terminal_deadline() {
        let started = Instant::now();
        let terminal_deadline = started + Duration::from_millis(120);
        let mut observed_deadline = None;
        let error = finish_native_correction_stdio_start_failure(
            NativeCorrectionError::Invalid("injected stdio startup failure".to_string()),
            false,
            terminal_deadline,
            |deadline| {
                observed_deadline = Some(deadline);
                while Instant::now() < deadline {
                    let remaining = deadline.saturating_duration_since(Instant::now());
                    thread::sleep(remaining.min(Duration::from_millis(5)));
                }
                invalid("injected fallback cleanup deadline exhaustion")
            },
        )
        .unwrap_err()
        .to_string();
        assert_eq!(observed_deadline, Some(terminal_deadline));
        assert!(started.elapsed() < Duration::from_millis(350));
        assert!(error.contains("injected stdio startup failure"));
        assert!(error.contains("injected fallback cleanup deadline exhaustion"));
    }

    #[test]
    fn stdio_and_standalone_stop_budgets_preserve_one_absolute_deadline() {
        assert!(require_native_correction_cleanup_before(
            Instant::now(),
            "injected exact deadline boundary"
        )
        .unwrap_err()
        .to_string()
        .contains("injected exact deadline boundary"));
        require_native_correction_cleanup_before(
            Instant::now() + Duration::from_secs(1),
            "unexpected adequate-budget failure",
        )
        .unwrap();

        let (response_deadline, terminal_deadline) =
            native_correction_deadlines(Duration::from_millis(RUNTIME_PROBE_TIMEOUT_MS)).unwrap();
        assert_eq!(
            terminal_deadline.duration_since(response_deadline),
            NATIVE_CORRECTION_CLEANUP_RESERVE_MAX
        );

        let mut adequate_deadline = None;
        let value = run_native_correction_standalone_stop_with_budget(
            Duration::from_millis(200),
            |deadline| {
                adequate_deadline = Some(deadline);
                assert!(Instant::now() < deadline);
                Ok(7u8)
            },
        )
        .unwrap();
        assert_eq!(value, 7);
        assert!(adequate_deadline.is_some());

        let observed = Instant::now();
        let started = observed - Duration::from_millis(31);
        let mut exhausted_deadline = None;
        let error = run_native_correction_standalone_stop_with_budget_from(
            started,
            Duration::from_millis(30),
            |deadline| -> NativeCorrectionResult<()> {
                exhausted_deadline = Some(deadline);
                assert!(Instant::now() >= deadline);
                invalid("injected cleanup observed the elapsed original deadline")
            },
        )
        .unwrap_err()
        .to_string();
        let exhausted_deadline = exhausted_deadline.unwrap();
        assert!(observed >= exhausted_deadline);
        assert!(error.contains("30 ms absolute budget"));
        assert!(error.contains("injected cleanup observed the elapsed original deadline"));
    }

