    #[cfg(unix)]
    #[test]
    fn full_profile_delivery_failure_finishes_without_panic_and_removes_probe_root() {
        use std::os::unix::process::CommandExt;

        let outer = canonical_tempdir();
        let probe_root = outer.path().join("delivery-failure-probe-root");
        create_new_private_dir(&probe_root).unwrap();
        let stdin_closed = probe_root.join("stdin-closed");
        let error = derive_full_profile_handshake_in_root_with_cleanup_and_start(
            Path::new("/synthetic/frozen/engram"),
            &probe_root,
            |path| fs::remove_dir_all(path).map_err(NativeCorrectionError::from),
            |_engram, _home, _partition, _timeout| {
                let mut command = Command::new("/bin/sh");
                command
                    .args([
                        "-c",
                        "exec 0<&-; : > \"$1\"; exec /bin/sleep 30",
                        "sh",
                        stdin_closed.to_str().unwrap(),
                    ])
                    .process_group(0)
                    .stdin(Stdio::piped())
                    .stdout(Stdio::piped())
                    .stderr(Stdio::piped());
                let session = NativeCorrectionStdioSession::from_spawned_child(
                    command.spawn()?,
                    Duration::from_millis(500),
                    None,
                )?;
                let deadline = Instant::now() + Duration::from_secs(2);
                while !stdin_closed.exists() {
                    if Instant::now() >= deadline {
                        return invalid("synthetic child did not close stdin");
                    }
                    thread::sleep(Duration::from_millis(2));
                }
                Ok(session)
            },
        )
        .unwrap_err()
        .to_string();
        assert!(!path_entry_exists(&probe_root));
        assert!(
            error.contains("full-profile handshake observation failed"),
            "unexpected error: {error}"
        );
        assert!(
            error.contains("request delivery failed"),
            "unexpected error: {error}"
        );
        assert!(
            error.contains("safely disarmed terminal failure"),
            "unexpected error: {error}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn production_auth_backend_is_bounded_env_clear_and_exact_for_both_hosts() {
        let root = canonical_tempdir();
        let codex_home = root.path().join("codex-home");
        let claude_config = root.path().join("claude-config");
        create_new_private_dir(&codex_home).unwrap();
        create_new_private_dir(&claude_config).unwrap();
        let codex = root.path().join("codex-auth-status");
        write_new_file(
            &codex,
            br##"#!/bin/sh
if [ "$#" -ne 2 ] || [ "$1" != "login" ] || [ "$2" != "status" ]; then exit 41; fi
if [ -z "$CODEX_HOME" ] || [ -n "$OPENAI_API_KEY" ] || [ -n "$CODEX_ACCESS_TOKEN" ] || [ -n "$ANTHROPIC_API_KEY" ]; then exit 42; fi
printf '%s\n' 'Logged in using ChatGPT'
"##,
            0o700,
        )
        .unwrap();
        let claude = root.path().join("claude-auth-status");
        write_new_file(
            &claude,
            br##"#!/bin/sh
if [ "$#" -ne 3 ] || [ "$1" != "auth" ] || [ "$2" != "status" ] || [ "$3" != "--json" ]; then exit 43; fi
if [ -z "$CLAUDE_CONFIG_DIR" ] || [ -n "$OPENAI_API_KEY" ] || [ -n "$CODEX_ACCESS_TOKEN" ] || [ -n "$ANTHROPIC_API_KEY" ]; then exit 44; fi
printf '%s\n' '{"loggedIn":true,"authMethod":"claude.ai","apiProvider":"firstParty"}'
"##,
            0o700,
        )
        .unwrap();
        let mut backend = NativeCorrectionCliAuthBackend;
        let codex_environment = BTreeMap::from([
            (
                "CODEX_HOME".to_string(),
                canonical_string(&codex_home).unwrap(),
            ),
            (
                "PATH".to_string(),
                "/usr/bin:/bin:/usr/sbin:/sbin".to_string(),
            ),
        ]);
        let codex_status = backend
            .codex_status(&codex, root.path(), &codex_environment)
            .unwrap();
        assert!(codex_status.chatgpt_login);
        assert!(!codex_status.api_key_mode);
        assert_eq!(codex_status.exit_code, 0);
        assert!(looks_like_sha256(&codex_status.stdout_sha256));
        assert!(looks_like_sha256(&codex_status.stderr_sha256));
        assert!(codex_status.output_bytes <= 64 * 1024);

        let claude_status = backend.claude_status(&claude, &claude_config).unwrap();
        assert!(claude_status.logged_in);
        assert_eq!(claude_status.auth_method, "claude.ai");
        assert_eq!(claude_status.api_provider, "firstParty");
        assert_eq!(claude_status.exit_code, 0);
        assert!(looks_like_sha256(&claude_status.stdout_sha256));
        assert!(looks_like_sha256(&claude_status.stderr_sha256));
        assert!(claude_status.output_bytes <= 64 * 1024);

        fs::write(
            &claude,
            b"#!/bin/sh\nprintf '%s\\n' '{\"loggedIn\":true,\"loggedIn\":false,\"authMethod\":\"claude.ai\",\"apiProvider\":\"firstParty\"}'\n",
        )
        .unwrap();
        assert!(backend.claude_status(&claude, &claude_config).is_err());
    }

